class MySqlSessionStore extends session.Store {
  constructor(databasePool) {
    super();
    this.pool = databasePool;
    this.ready = null;
    this.lastCleanup = 0;
  }

  async ensureTable() {
    if (!this.ready) {
      this.ready = this.pool.execute(
        `CREATE TABLE IF NOT EXISTS dalvo_sessions (
          sid VARCHAR(128) NOT NULL PRIMARY KEY,
          data MEDIUMTEXT NOT NULL,
          expires DATETIME NOT NULL,
          updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
          INDEX idx_dalvo_sessions_expires (expires)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
      );
    }
    await this.ready;
  }

  getExpiration(sessionData) {
    const expires = sessionData?.cookie?.expires ? new Date(sessionData.cookie.expires) : null;
    if (expires && !Number.isNaN(expires.getTime())) return expires;
    return new Date(Date.now() + SESSION_MAX_AGE_MS);
  }

  async cleanupExpiredSessions() {
    const now = Date.now();
    if (now - this.lastCleanup < 1000 * 60 * 60) return;
    this.lastCleanup = now;
    await this.pool.execute("DELETE FROM dalvo_sessions WHERE expires <= NOW()");
  }

  get(sid, callback) {
    this.ensureTable()
      .then(() =>
        this.pool.execute(
          "SELECT data FROM dalvo_sessions WHERE sid = ? AND expires > NOW() LIMIT 1",
          [sid]
        )
      )
      .then(([rows]) => {
        if (!rows.length) return callback(null, null);
        try {
          return callback(null, JSON.parse(rows[0].data));
        } catch (error) {
          return callback(error);
        }
      })
      .catch((error) => callback(error));
  }

  set(sid, sessionData, callback) {
    const expires = this.getExpiration(sessionData);
    this.ensureTable()
      .then(() => this.cleanupExpiredSessions())
      .then(() =>
        this.pool.execute(
          `REPLACE INTO dalvo_sessions (sid, data, expires)
           VALUES (?, ?, ?)`,
          [sid, JSON.stringify(sessionData), expires]
        )
      )
      .then(() => callback(null))
      .catch((error) => callback(error));
  }

  destroy(sid, callback) {
    this.ensureTable()
      .then(() => this.pool.execute("DELETE FROM dalvo_sessions WHERE sid = ?", [sid]))
      .then(() => callback(null))
      .catch((error) => callback(error));
  }

  touch(sid, sessionData, callback) {
    const expires = this.getExpiration(sessionData);
    this.ensureTable()
      .then(() =>
        this.pool.execute("UPDATE dalvo_sessions SET expires = ? WHERE sid = ?", [expires, sid])
      )
      .then(() => callback(null))
      .catch((error) => callback(error));
  }
}

