function normalizeBranchLookupKey(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");
}

function resolveOfficialBranchAlias(value) {
  const key = normalizeBranchLookupKey(value);
  if (!key) return null;
  if (["SLP", "SANLUISPOTOSI"].includes(key)) return "SLP";
  if (["QRO", "QUERETARO"].includes(key)) return "QRO";
  if (["GTO", "GUANAJUATO", "CEL", "CELAYA"].includes(key)) return "GTO";
  return null;
}

function branchLabelsEquivalent(left, right) {
  const leftOfficial = resolveOfficialBranchAlias(left);
  const rightOfficial = resolveOfficialBranchAlias(right);
  if (leftOfficial || rightOfficial) return Boolean(leftOfficial && rightOfficial && leftOfficial === rightOfficial);
  return normalizeBranchLookupKey(left) === normalizeBranchLookupKey(right);
}

function resolveFixedExpenseBranch(value) {
  return resolveOfficialBranchAlias(value);
}
