function escapeId(identifier) {
  return `\`${String(identifier).replace(/`/g, "``")}\``;
}

function pickColumn(columns, candidates) {
  const lowered = new Map(columns.map((column) => [column.toLowerCase(), column]));
  for (const candidate of candidates) {
    const match = lowered.get(candidate.toLowerCase());
    if (match) return match;
  }
  return null;
}

function isActive(value) {
  if (value === null || value === undefined) return true;
  if (typeof value === "number") return value === 1;
  if (typeof value === "boolean") return value;

  const normalized = String(value).trim().toLowerCase();
  return ["1", "true", "activo", "active", "habilitado", "enabled", "si", "sí"].includes(
    normalized
  );
}

async function comparePassword(inputPassword, storedPassword) {
  const stored = String(storedPassword || "");
  const input = String(inputPassword || "");

  if (!stored) return false;
  if (stored.startsWith("$2a$") || stored.startsWith("$2b$") || stored.startsWith("$2y$")) {
    return bcrypt.compare(input, stored);
  }

  return false;
}

function loginKey(req, username) {
  return `${req.ip || "local"}:${username.toLowerCase()}`;
}

function checkLoginLimit(req, res, next) {
  const username = String(req.body.username || "").trim();
  const key = loginKey(req, username);
  const now = Date.now();
  const attempt = loginAttempts.get(key);

  if (attempt && attempt.lockedUntil > now) {
    return res.status(429).json({
      ok: false,
      message: "Demasiados intentos. Intenta de nuevo en unos minutos."
    });
  }

  next();
}

function recordLoginFailure(req, username) {
  const key = loginKey(req, username);
  const now = Date.now();
  const current = loginAttempts.get(key);
  const count = current && current.resetAt > now ? current.count + 1 : 1;

  loginAttempts.set(key, {
    count,
    resetAt: now + LOGIN_WINDOW_MS,
    lockedUntil: count >= LOGIN_MAX_ATTEMPTS ? now + LOGIN_WINDOW_MS : 0
  });
}

function clearLoginFailures(req, username) {
  loginAttempts.delete(loginKey(req, username));
}

async function ensureFixedExpensesTable() {
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS gastos_fijos (
      id INT AUTO_INCREMENT PRIMARY KEY,
      proveedor_id INT NULL,
      gasto VARCHAR(180) NOT NULL,
      sucursal VARCHAR(80) NOT NULL,
      recurrencia VARCHAR(30) NOT NULL,
      descripcion_automatica VARCHAR(500) NOT NULL DEFAULT '',
      generacion_automatica TINYINT(1) NOT NULL DEFAULT 0,
      dia_generacion TINYINT UNSIGNED NOT NULL DEFAULT 1,
      fecha_inicio_recurrencia DATE NULL,
      fecha_fin_recurrencia DATE NULL,
      proxima_generacion DATE NULL,
      ultima_generacion DATE NULL,
      estado_registro VARCHAR(30) NOT NULL DEFAULT 'Activo',
      presupuesto DECIMAL(14,2) NOT NULL DEFAULT 0,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      INDEX idx_gastos_fijos_busqueda (gasto, sucursal, recurrencia)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("gastos_fijos", "proveedor_id", "proveedor_id INT NULL");
  await ensureColumn("gastos_fijos", "gasto", "gasto VARCHAR(180) NOT NULL DEFAULT ''");
  await ensureColumn("gastos_fijos", "sucursal", "sucursal VARCHAR(80) NOT NULL DEFAULT 'Querétaro'");
  await ensureColumn("gastos_fijos", "recurrencia", "recurrencia VARCHAR(30) NOT NULL DEFAULT 'mensual'");
  await ensureColumn("gastos_fijos", "descripcion_automatica", "descripcion_automatica VARCHAR(500) NOT NULL DEFAULT ''");
  await ensureColumn("gastos_fijos", "generacion_automatica", "generacion_automatica TINYINT(1) NOT NULL DEFAULT 0");
  await ensureColumn("gastos_fijos", "dia_generacion", "dia_generacion TINYINT UNSIGNED NOT NULL DEFAULT 1");
  await ensureColumn("gastos_fijos", "fecha_inicio_recurrencia", "fecha_inicio_recurrencia DATE NULL");
  await ensureColumn("gastos_fijos", "fecha_fin_recurrencia", "fecha_fin_recurrencia DATE NULL");
  await ensureColumn("gastos_fijos", "proxima_generacion", "proxima_generacion DATE NULL");
  await ensureColumn("gastos_fijos", "ultima_generacion", "ultima_generacion DATE NULL");
  await ensureColumn("gastos_fijos", "estado_registro", "estado_registro VARCHAR(30) NOT NULL DEFAULT 'Activo'");
  await ensureColumn("gastos_fijos", "presupuesto", "presupuesto DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("gastos_fijos", "presupuesto_adicional", "presupuesto_adicional DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn(
    "gastos_fijos",
    "updated_at",
    "updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"
  );
  await ensureColumn("gastos_fijos", "es_catalogo", "es_catalogo TINYINT(1) NOT NULL DEFAULT 1");
  const columns = await getTableColumns("gastos_fijos");
  if (columns.includes("proveedor_id")) {
    await pool.execute("ALTER TABLE gastos_fijos MODIFY proveedor_id INT NULL");
  }
  if (columns.includes("contacto")) {
    await pool.execute("UPDATE gastos_fijos SET gasto = contacto WHERE (gasto IS NULL OR gasto = '') AND contacto <> ''");
  }
  if (columns.includes("area")) {
    await pool.execute("UPDATE gastos_fijos SET sucursal = area WHERE (sucursal IS NULL OR sucursal = '') AND area <> ''");
  }
  const fixedExpenseProviderExpression = columns.includes("servicio_proveedor_id") && columns.includes("proveedor_id")
    ? "COALESCE(gf.servicio_proveedor_id, gf.proveedor_id)"
    : columns.includes("servicio_proveedor_id")
      ? "gf.servicio_proveedor_id"
      : columns.includes("proveedor_id")
        ? "gf.proveedor_id"
        : "";
  if (fixedExpenseProviderExpression) {
    await pool.execute(
      `UPDATE gastos_fijos gf
       LEFT JOIN proveedores p ON p.id = ${fixedExpenseProviderExpression}
       SET gf.presupuesto = COALESCE(NULLIF(p.presupuesto, 0), gf.presupuesto),
           gf.recurrencia = COALESCE(NULLIF(p.recurrencia, ''), gf.recurrencia)
       WHERE (gf.presupuesto = 0 OR gf.recurrencia = '' OR gf.recurrencia IS NULL)`
    );
  }
  try {
    await markLegacyFixedExpenseRowsAsTransactions(columns);
    await syncFixedExpenseCatalogFromProviders();
  } catch (error) {
    logServerError("fixed-expenses-catalog-normalization", error);
  }
}

async function markLegacyFixedExpenseRowsAsTransactions(columns = []) {
  const legacyMarkers = [];
  if (columns.includes("folio")) legacyMarkers.push("COALESCE(folio, '') <> ''");
  if (columns.includes("contacto")) legacyMarkers.push("COALESCE(contacto, '') <> ''");
  if (columns.includes("fecha")) legacyMarkers.push("fecha IS NOT NULL");
  // proveedor_id también se usa en los catálogos automáticos actuales; no identifica por sí solo un movimiento histórico.
  if (columns.includes("servicio_proveedor_id")) legacyMarkers.push("servicio_proveedor_id IS NOT NULL");

  if (!legacyMarkers.length) return;

  await pool.execute(
    `UPDATE gastos_fijos
     SET es_catalogo = 0
     WHERE ${legacyMarkers.map((marker) => `(${marker})`).join(" OR ")}`
  );
}

async function syncFixedExpenseCatalogFromProviders() {
  if (!(await tableExists("proveedores"))) return;

  const providerColumns = await getTableColumns("proveedores");
  if (!providerColumns.includes("tipo") || !providerColumns.includes("empresa")) return;

  const fields = ["empresa"];
  if (providerColumns.includes("direccion")) fields.push("direccion");
  if (providerColumns.includes("recurrencia")) fields.push("recurrencia");
  if (providerColumns.includes("presupuesto")) fields.push("presupuesto");

  const [providers] = await pool.execute(
    `SELECT ${fields.map((field) => escapeId(field)).join(", ")}
     FROM proveedores
     WHERE LOWER(COALESCE(tipo, '')) = 'gastos_fijos'
       AND COALESCE(TRIM(empresa), '') <> ''
     ORDER BY id`
  );

  for (const provider of providers) {
    const expense = {
      gasto: String(provider.empresa || "").trim(),
      sucursal: FIXED_EXPENSE_BRANCHES.includes(String(provider.direccion || "").trim())
        ? String(provider.direccion || "").trim()
        : FIXED_EXPENSE_BRANCHES[0],
      recurrencia: "anual",
      presupuesto: Number(provider.presupuesto || 0)
    };

    if (!expense.gasto) continue;
    if (await findAnyFixedExpenseByName(expense.gasto)) continue;
    if (await findFixedExpenseDuplicate(expense)) continue;

    await pool.execute(
      `INSERT INTO gastos_fijos (proveedor_id, gasto, sucursal, recurrencia, presupuesto, presupuesto_adicional, es_catalogo)
       VALUES (NULL, ?, ?, ?, ?, 0, 1)`,
      [expense.gasto, expense.sucursal, expense.recurrencia, expense.presupuesto]
    );
  }
}

async function findAnyFixedExpenseByName(gasto, connection = pool) {
  if (!String(gasto || "").trim()) return null;
  const [rows] = await connection.execute(
    `SELECT id
     FROM gastos_fijos
     WHERE LOWER(TRIM(gasto)) = LOWER(TRIM(?))
     LIMIT 1`,
    [gasto]
  );
  return rows[0] || null;
}

async function ensureColumn(tableName, columnName, definition) {
  const [rows] = await pool.execute(
    `SELECT COLUMN_NAME
     FROM INFORMATION_SCHEMA.COLUMNS
     WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? AND COLUMN_NAME = ?
     LIMIT 1`,
    [DB_NAME, tableName, columnName]
  );

  if (!rows.length) {
    await pool.execute(`ALTER TABLE ${escapeId(tableName)} ADD COLUMN ${definition}`);
  }
}

