async function ensureAccountsReceivableTables() {
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cuentas_por_cobrar (
      id INT AUTO_INCREMENT PRIMARY KEY,
      cotizacion_cliente_id INT NOT NULL,
      presupuesto_id INT NOT NULL,
      estado VARCHAR(80) NOT NULL DEFAULT 'En proceso',
      pendiente VARCHAR(120) NOT NULL DEFAULT 'En proceso',
      dias_pago INT NOT NULL DEFAULT 30,
      fecha_pago DATE NULL,
      monto DECIMAL(14,2) NOT NULL DEFAULT 0,
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      INDEX idx_cuentas_por_cobrar_cotizacion (cotizacion_cliente_id),
      INDEX idx_cuentas_por_cobrar_presupuesto (presupuesto_id),
      CONSTRAINT fk_cuentas_por_cobrar_cotizacion
        FOREIGN KEY (cotizacion_cliente_id) REFERENCES cotizaciones_cliente(id)
        ON DELETE CASCADE,
      CONSTRAINT fk_cuentas_por_cobrar_presupuesto
        FOREIGN KEY (presupuesto_id) REFERENCES presupuestos(id)
        ON DELETE CASCADE
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("cuentas_por_cobrar", "cotizacion_cliente_id", "cotizacion_cliente_id INT NULL");
  await ensureColumn("cuentas_por_cobrar", "presupuesto_id", "presupuesto_id INT NULL");
  await ensureColumn("cuentas_por_cobrar", "estado", "estado VARCHAR(80) NOT NULL DEFAULT 'En proceso'");
  await ensureColumn("cuentas_por_cobrar", "pendiente", "pendiente VARCHAR(120) NOT NULL DEFAULT 'En proceso'");
  await ensureColumn("cuentas_por_cobrar", "dias_pago", "dias_pago INT NOT NULL DEFAULT 30");
  await ensureColumn("cuentas_por_cobrar", "fecha_pago", "fecha_pago DATE NULL");
  await ensureColumn("cuentas_por_cobrar", "monto", "monto DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("cuentas_por_cobrar", "usuario_id", "usuario_id INT NULL");

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cuentas_por_cobrar_archivos (
      id INT AUTO_INCREMENT PRIMARY KEY,
      cuenta_id INT NOT NULL,
      tipo VARCHAR(80) NOT NULL,
      nombre VARCHAR(260) NOT NULL,
      ruta VARCHAR(360) NOT NULL,
      usuario_id INT NULL,
      facturacion_id INT NULL,
      lote_cobro_archivo_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      INDEX idx_cuentas_por_cobrar_archivos (cuenta_id),
      INDEX idx_cxc_archivos_facturacion (facturacion_id),
      CONSTRAINT fk_cuentas_por_cobrar_archivos_cuenta
        FOREIGN KEY (cuenta_id) REFERENCES cuentas_por_cobrar(id)
        ON DELETE CASCADE
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("cuentas_por_cobrar_archivos", "cuenta_id", "cuenta_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_archivos", "tipo", "tipo VARCHAR(80) NOT NULL DEFAULT ''");
  await ensureColumn("cuentas_por_cobrar_archivos", "nombre", "nombre VARCHAR(260) NOT NULL DEFAULT ''");
  await ensureColumn("cuentas_por_cobrar_archivos", "ruta", "ruta VARCHAR(360) NOT NULL DEFAULT ''");
  await ensureColumn("cuentas_por_cobrar_archivos", "usuario_id", "usuario_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_archivos", "facturacion_id", "facturacion_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_archivos", "lote_cobro_archivo_id", "lote_cobro_archivo_id INT NULL");

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cuentas_por_cobrar_facturacion (
      id INT AUTO_INCREMENT PRIMARY KEY,
      cuenta_id INT NOT NULL,
      monto DECIMAL(14,2) NOT NULL DEFAULT 0,
      estado VARCHAR(30) NOT NULL DEFAULT 'Solicitada',
      observaciones VARCHAR(500) NOT NULL DEFAULT '',
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      INDEX idx_cxc_facturacion_cuenta (cuenta_id),
      INDEX idx_cxc_facturacion_estado (estado)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("cuentas_por_cobrar_facturacion", "cuenta_id", "cuenta_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_facturacion", "monto", "monto DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("cuentas_por_cobrar_facturacion", "estado", "estado VARCHAR(30) NOT NULL DEFAULT 'Solicitada'");
  await ensureColumn("cuentas_por_cobrar_facturacion", "observaciones", "observaciones VARCHAR(500) NOT NULL DEFAULT ''");
  await ensureColumn("cuentas_por_cobrar_facturacion", "usuario_id", "usuario_id INT NULL");

  // Cada comprobante de pago representa un cobro real. Se guarda por separado de
  // la facturación para soportar parcialidades y filtrar los reportes por la fecha
  // y el monto efectivamente cobrados, no por el total completo del proyecto.
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cuentas_por_cobrar_pagos (
      id INT AUTO_INCREMENT PRIMARY KEY,
      cuenta_id INT NOT NULL,
      archivo_id INT NULL,
      facturacion_id INT NULL,
      monto DECIMAL(14,2) NOT NULL DEFAULT 0,
      fecha_pago DATE NULL,
      referencia VARCHAR(260) NOT NULL DEFAULT '',
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_cxc_pagos_archivo (archivo_id),
      INDEX idx_cxc_pagos_cuenta (cuenta_id),
      INDEX idx_cxc_pagos_fecha (fecha_pago),
      INDEX idx_cxc_pagos_facturacion (facturacion_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("cuentas_por_cobrar_pagos", "cuenta_id", "cuenta_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_pagos", "archivo_id", "archivo_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_pagos", "facturacion_id", "facturacion_id INT NULL");
  await ensureColumn("cuentas_por_cobrar_pagos", "monto", "monto DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("cuentas_por_cobrar_pagos", "fecha_pago", "fecha_pago DATE NULL");
  await ensureColumn("cuentas_por_cobrar_pagos", "referencia", "referencia VARCHAR(260) NOT NULL DEFAULT ''");
  await ensureColumn("cuentas_por_cobrar_pagos", "usuario_id", "usuario_id INT NULL");

  await pool.execute(
    `INSERT INTO cuentas_por_cobrar_facturacion (cuenta_id, monto, estado, observaciones, usuario_id)
     SELECT cx.id, GREATEST(COALESCE(cx.monto, 0), 0), 'Facturada', 'Registro previo a parcialidades', cx.usuario_id
     FROM cuentas_por_cobrar cx
     WHERE COALESCE(cx.monto, 0) > 0
       AND EXISTS (
         SELECT 1 FROM cuentas_por_cobrar_archivos a
         WHERE a.cuenta_id = cx.id AND a.tipo = 'Factura'
       )
       AND NOT EXISTS (
         SELECT 1 FROM cuentas_por_cobrar_facturacion f
         WHERE f.cuenta_id = cx.id
       )`
  );

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS lotes_cobro_clientes (
      id INT AUTO_INCREMENT PRIMARY KEY,
      folio VARCHAR(60) NOT NULL,
      estado VARCHAR(30) NOT NULL DEFAULT 'Pendiente',
      empresa VARCHAR(180) NOT NULL DEFAULT '',
      intermediario VARCHAR(180) NOT NULL DEFAULT '',
      referencia_externa VARCHAR(160) NOT NULL DEFAULT '',
      porcentaje_descuento DECIMAL(8,4) NOT NULL DEFAULT 0,
      monto_original DECIMAL(14,2) NOT NULL DEFAULT 0,
      descuento_monto DECIMAL(14,2) NOT NULL DEFAULT 0,
      monto_cobrar DECIMAL(14,2) NOT NULL DEFAULT 0,
      fecha_cobro DATE NULL,
      pdf_ruta VARCHAR(360) NOT NULL DEFAULT '',
      observaciones VARCHAR(500) NOT NULL DEFAULT '',
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_lotes_cobro_clientes_folio (folio),
      INDEX idx_lotes_cobro_clientes_estado (estado),
      INDEX idx_lotes_cobro_clientes_empresa (empresa),
      INDEX idx_lotes_cobro_clientes_fecha (fecha_cobro)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS lotes_cobro_clientes_items (
      id INT AUTO_INCREMENT PRIMARY KEY,
      lote_id INT NOT NULL,
      cuenta_id INT NOT NULL,
      cotizacion_cliente_id INT NOT NULL,
      presupuesto_id INT NOT NULL,
      folio_cotizacion VARCHAR(80) NOT NULL DEFAULT '',
      folio_presupuesto VARCHAR(80) NOT NULL DEFAULT '',
      po_cliente VARCHAR(120) NOT NULL DEFAULT '',
      proyecto VARCHAR(220) NOT NULL DEFAULT '',
      monto_original DECIMAL(14,2) NOT NULL DEFAULT 0,
      porcentaje_descuento DECIMAL(8,4) NOT NULL DEFAULT 0,
      descuento_monto DECIMAL(14,2) NOT NULL DEFAULT 0,
      ajuste_redondeo DECIMAL(14,2) NOT NULL DEFAULT 0,
      monto_cobrar DECIMAL(14,2) NOT NULL DEFAULT 0,
      pago_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      UNIQUE KEY uq_lotes_cobro_item_cuenta (cuenta_id),
      UNIQUE KEY uq_lotes_cobro_item_cotizacion (cotizacion_cliente_id),
      INDEX idx_lotes_cobro_items_lote (lote_id),
      INDEX idx_lotes_cobro_items_presupuesto (presupuesto_id),
      CONSTRAINT fk_lotes_cobro_items_lote FOREIGN KEY (lote_id)
        REFERENCES lotes_cobro_clientes(id) ON DELETE CASCADE,
      CONSTRAINT fk_lotes_cobro_items_cuenta FOREIGN KEY (cuenta_id)
        REFERENCES cuentas_por_cobrar(id) ON DELETE CASCADE
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS lotes_cobro_clientes_archivos (
      id INT AUTO_INCREMENT PRIMARY KEY,
      lote_id INT NOT NULL,
      item_id INT NULL,
      tipo VARCHAR(80) NOT NULL DEFAULT 'Comprobante de pago',
      nombre VARCHAR(260) NOT NULL DEFAULT '',
      ruta VARCHAR(360) NOT NULL DEFAULT '',
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      INDEX idx_lotes_cobro_archivos_lote (lote_id),
      INDEX idx_lotes_cobro_archivos_item (item_id),
      CONSTRAINT fk_lotes_cobro_archivos_lote FOREIGN KEY (lote_id)
        REFERENCES lotes_cobro_clientes(id) ON DELETE CASCADE,
      CONSTRAINT fk_lotes_cobro_archivos_item FOREIGN KEY (item_id)
        REFERENCES lotes_cobro_clientes_items(id) ON DELETE CASCADE
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
}

