function normalizeClientBranchLabel(value) {
  const raw = String(value || "").trim().replace(/\s+/g, " ");
  if (!raw) return "";
  return resolveOfficialBranchAlias(raw) || raw;
}

function normalizePersonAssignmentKey(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

async function ensureClientBranchAndAssignmentTables() {
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS catalogo_ubicaciones (
      id INT AUTO_INCREMENT PRIMARY KEY,
      nombre VARCHAR(160) NOT NULL,
      activo TINYINT(1) NOT NULL DEFAULT 1,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_catalogo_ubicaciones_nombre (nombre),
      INDEX idx_catalogo_ubicaciones_activo (activo)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  for (const branchName of OFFICIAL_BRANCHES) {
    await pool.execute(
      `INSERT INTO catalogo_ubicaciones (nombre, activo) VALUES (?, 1)
       ON DUPLICATE KEY UPDATE activo = 1, nombre = VALUES(nombre)`,
      [branchName]
    );
  }
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cliente_empresas (
      id INT AUTO_INCREMENT PRIMARY KEY,
      nombre VARCHAR(180) NOT NULL,
      rfc VARCHAR(40) NOT NULL DEFAULT '',
      direccion VARCHAR(500) NOT NULL DEFAULT '',
      email VARCHAR(180) NOT NULL DEFAULT '',
      uso_cfdi VARCHAR(120) NOT NULL DEFAULT '',
      valor_venta DECIMAL(12,4) NOT NULL DEFAULT 1.4500,
      condiciones_pago VARCHAR(30) NOT NULL DEFAULT 'contado',
      dias_credito INT NOT NULL DEFAULT 0,
      notas TEXT NULL,
      activo TINYINT(1) NOT NULL DEFAULT 1,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_cliente_empresas_nombre (nombre),
      INDEX idx_cliente_empresas_activo (activo)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  // Al migrar instalaciones existentes, las condiciones iniciales de cada
  // empresa se toman de su registro histórico más antiguo. Un contacto nuevo
  // nunca debe redefinir las condiciones comerciales de toda la empresa.
  await pool.execute(
    `INSERT IGNORE INTO cliente_empresas
      (nombre, rfc, direccion, email, uso_cfdi, valor_venta, condiciones_pago, dias_credito, notas, activo)
     SELECT
       TRIM(c.empresa), COALESCE(c.rfc, ''), COALESCE(c.direccion, ''), COALESCE(c.email, ''),
       COALESCE(c.uso_cfdi, ''), COALESCE(NULLIF(c.valor_venta, 0), 1.45),
       COALESCE(NULLIF(c.condiciones_pago, ''), 'contado'), COALESCE(c.dias_credito, 0), c.notas, 1
     FROM clientes c
     INNER JOIN (
       SELECT MIN(id) AS id
       FROM clientes
       WHERE NULLIF(TRIM(empresa), '') IS NOT NULL
       GROUP BY TRIM(empresa)
     ) first_client ON first_client.id = c.id`
  );
  await pool.execute(
    `INSERT IGNORE INTO cliente_empresas (nombre)
     SELECT DISTINCT TRIM(empresa)
     FROM presupuestos
     WHERE NULLIF(TRIM(empresa), '') IS NOT NULL`
  );
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS cliente_sucursales (
      id INT AUTO_INCREMENT PRIMARY KEY,
      empresa VARCHAR(180) NOT NULL,
      nombre VARCHAR(160) NOT NULL,
      direccion VARCHAR(500) NOT NULL DEFAULT '',
      activo TINYINT(1) NOT NULL DEFAULT 1,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_cliente_sucursales_empresa_nombre (empresa, nombre),
      INDEX idx_cliente_sucursales_empresa (empresa),
      INDEX idx_cliente_sucursales_activo (activo)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await ensureColumn("cliente_sucursales", "ubicacion_id", "ubicacion_id INT NULL");
  await ensureColumn("cliente_sucursales", "empresa_id", "empresa_id INT NULL");
  await ensureColumn("clientes", "empresa_id", "empresa_id INT NULL");
  await ensureColumn("clientes", "sucursal_id", "sucursal_id INT NULL");
  await ensureColumn("presupuestos", "empresa_id", "empresa_id INT NULL");
  await ensureColumn("presupuestos", "sucursal_id", "sucursal_id INT NULL");

  await pool.execute(
    `UPDATE cliente_sucursales s
     INNER JOIN cliente_empresas e
       ON CONVERT(TRIM(e.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET s.empresa_id = e.id
     WHERE s.empresa_id IS NULL OR s.empresa_id <> e.id`
  );
  await pool.execute(
    `UPDATE clientes c
     INNER JOIN cliente_empresas e
       ON CONVERT(TRIM(e.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(c.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET c.empresa_id = e.id
     WHERE c.empresa_id IS NULL OR c.empresa_id <> e.id`
  );
  await pool.execute(
    `UPDATE presupuestos p
     INNER JOIN cliente_empresas e
       ON CONVERT(TRIM(e.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(p.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET p.empresa_id = e.id
     WHERE p.empresa_id IS NULL OR p.empresa_id <> e.id`
  );

  await pool.execute(
    `CREATE TABLE IF NOT EXISTS usuario_asignacion_aliases (
      id INT AUTO_INCREMENT PRIMARY KEY,
      usuario_id INT NOT NULL,
      alias VARCHAR(180) NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      UNIQUE KEY uq_usuario_asignacion_alias (alias),
      INDEX idx_usuario_asignacion_usuario (usuario_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  // Alcance operativo por sucursal. La asignación y los permisos se separan para
  // que un usuario pueda tener, por ejemplo, Presupuestos en Honda pero no CxP.
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS usuarios_sucursales (
      usuario_id INT NOT NULL,
      sucursal_id INT NOT NULL,
      nivel_acceso VARCHAR(20) NOT NULL DEFAULT 'modular',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      PRIMARY KEY (usuario_id, sucursal_id),
      INDEX idx_usuarios_sucursales_sucursal (sucursal_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS usuarios_sucursales_permisos (
      usuario_id INT NOT NULL,
      sucursal_id INT NOT NULL,
      permiso_id INT NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY (usuario_id, sucursal_id, permiso_id),
      INDEX idx_usp_sucursal_permiso (sucursal_id, permiso_id),
      INDEX idx_usp_usuario (usuario_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  // Si ya existían variantes SLP/S.L.P. en el catálogo, consolídalas por empresa
  // antes de volver a sembrar ubicaciones históricas.
  const [slpBranchRows] = await pool.execute(
    `SELECT id, empresa, nombre
     FROM cliente_sucursales
     WHERE UPPER(REPLACE(REPLACE(REPLACE(TRIM(nombre), '.', ''), ' ', ''), '-', '')) = 'SLP'
     ORDER BY empresa, id`
  );
  const slpGroups = new Map();
  for (const row of slpBranchRows) {
    const companyKey = normalizePersonAssignmentKey(row.empresa);
    if (!slpGroups.has(companyKey)) slpGroups.set(companyKey, []);
    slpGroups.get(companyKey).push(row);
  }
  for (const rows of slpGroups.values()) {
    if (!rows.length) continue;
    const canonical = rows.find((row) => String(row.nombre || '').trim().toUpperCase() === 'S.L.P.') || rows[0];
    const duplicateIds = rows.map((row) => Number(row.id)).filter((id) => id && id !== Number(canonical.id));
    for (const duplicateId of duplicateIds) {
      await pool.execute('UPDATE clientes SET sucursal_id = ? WHERE sucursal_id = ?', [canonical.id, duplicateId]);
      await pool.execute('UPDATE presupuestos SET sucursal_id = ? WHERE sucursal_id = ?', [canonical.id, duplicateId]);
      await pool.execute('DELETE FROM cliente_sucursales WHERE id = ?', [duplicateId]);
    }
    await pool.execute('UPDATE cliente_sucursales SET nombre = ? WHERE id = ?', ['SLP', canonical.id]);
  }

  // Canonización mínima solicitada por administración. Las demás ubicaciones se administran
  // desde el catálogo y no se infieren a partir del nombre del contacto.
  await pool.execute(
    `UPDATE clientes
     SET sucursal = 'SLP'
     WHERE UPPER(REPLACE(REPLACE(REPLACE(TRIM(sucursal), '.', ''), ' ', ''), '-', '')) = 'SLP'`
  );
  await pool.execute(
    `UPDATE presupuestos
     SET sucursal = 'SLP'
     WHERE UPPER(REPLACE(REPLACE(REPLACE(TRIM(sucursal), '.', ''), ' ', ''), '-', '')) = 'SLP'`
  );

  await pool.execute(
    `INSERT IGNORE INTO cliente_sucursales (empresa, nombre)
     SELECT DISTINCT TRIM(c.empresa), TRIM(c.sucursal)
     FROM clientes c
     WHERE NULLIF(TRIM(c.empresa), '') IS NOT NULL
       AND NULLIF(TRIM(c.sucursal), '') IS NOT NULL
       AND (
         NULLIF(TRIM(c.nombre), '') IS NULL
         OR CONVERT(TRIM(c.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci <>
            CONVERT(TRIM(c.sucursal) USING utf8mb4) COLLATE utf8mb4_unicode_ci
       )`
  );

  await pool.execute(
    `INSERT IGNORE INTO cliente_sucursales (empresa, nombre)
     SELECT DISTINCT TRIM(p.empresa), TRIM(p.sucursal)
     FROM presupuestos p
     WHERE NULLIF(TRIM(p.empresa), '') IS NOT NULL
       AND NULLIF(TRIM(p.sucursal), '') IS NOT NULL
       AND (
         NULLIF(TRIM(p.cliente_usuario), '') IS NULL
         OR CONVERT(TRIM(p.cliente_usuario) USING utf8mb4) COLLATE utf8mb4_unicode_ci <>
            CONVERT(TRIM(p.sucursal) USING utf8mb4) COLLATE utf8mb4_unicode_ci
       )`
  );

  await pool.execute(
    `INSERT IGNORE INTO catalogo_ubicaciones (nombre, activo)
     SELECT DISTINCT TRIM(s.nombre),
            CASE WHEN UPPER(TRIM(s.nombre)) IN ('GTO','SLP','QRO') THEN 1 ELSE 0 END
     FROM cliente_sucursales s
     WHERE NULLIF(TRIM(s.nombre), '') IS NOT NULL`
  );

  await pool.execute(
    `UPDATE cliente_sucursales s
     INNER JOIN catalogo_ubicaciones u
       ON CONVERT(TRIM(s.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(u.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET s.ubicacion_id = u.id,
         s.nombre = u.nombre
     WHERE s.ubicacion_id IS NULL OR s.ubicacion_id <> u.id`
  );

  // Las sucursales históricas se insertan arriba; enlázalas también con su
  // empresa antes de propagar la asignación a contactos y presupuestos.
  await pool.execute(
    `UPDATE cliente_sucursales s
     INNER JOIN cliente_empresas e
       ON CONVERT(TRIM(e.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET s.empresa_id = e.id
     WHERE s.empresa_id IS NULL OR s.empresa_id <> e.id`
  );

  await pool.execute(
    `UPDATE clientes c
     INNER JOIN cliente_sucursales s
       ON CONVERT(TRIM(c.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND CONVERT(TRIM(c.sucursal) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET c.sucursal_id = s.id,
         c.sucursal = s.nombre
     WHERE c.sucursal_id IS NULL OR c.sucursal_id <> s.id`
  );

  await pool.execute(
    `UPDATE presupuestos p
     INNER JOIN cliente_sucursales s
       ON CONVERT(TRIM(p.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci
      AND CONVERT(TRIM(p.sucursal) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
          CONVERT(TRIM(s.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     SET p.sucursal_id = s.id,
         p.sucursal = s.nombre
     WHERE p.sucursal_id IS NULL OR p.sucursal_id <> s.id`
  );

  if (await tableExists("ordenes_servicio")) {
    // "supervisor" del esquema legado es un trabajador interno, no el contacto del cliente.
    // Corrige registros que fueron heredados previamente al campo cliente_usuario.
    await pool.execute(
      `UPDATE presupuestos p
       INNER JOIN ordenes_servicio os ON os.id = p.id
       LEFT JOIN clientes c ON c.id = COALESCE(NULLIF(os.cliente_id, 0), p.cliente_id)
       LEFT JOIN cliente_sucursales s ON s.id = c.sucursal_id
       SET p.cliente_id = COALESCE(c.id, p.cliente_id),
           p.sucursal_id = COALESCE(c.sucursal_id, p.sucursal_id),
           p.sucursal = COALESCE(NULLIF(s.nombre, ''), NULLIF(c.sucursal, ''), p.sucursal),
           p.cliente_usuario = COALESCE(NULLIF(TRIM(c.nombre), ''), '')
       WHERE NULLIF(TRIM(os.supervisor), '') IS NOT NULL
         AND (
           CONVERT(TRIM(COALESCE(p.cliente_usuario, '')) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
             CONVERT(TRIM(os.supervisor) USING utf8mb4) COLLATE utf8mb4_unicode_ci
           OR CONVERT(TRIM(COALESCE(p.cliente_usuario, '')) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
             CONVERT(TRIM(COALESCE(p.sucursal, '')) USING utf8mb4) COLLATE utf8mb4_unicode_ci
         )`
    );

    // Limpia únicamente contactos huérfanos creados por la migración histórica equivocada
    // (sin datos propios) cuando su nombre era en realidad el supervisor interno del proyecto.
    await pool.execute(
      `DELETE c
       FROM clientes c
       WHERE c.notas = 'Contacto recuperado desde historial de presupuestos'
         AND NULLIF(TRIM(c.telefono), '') IS NULL
         AND NULLIF(TRIM(c.rfc), '') IS NULL
         AND NULLIF(TRIM(c.direccion), '') IS NULL
         AND NULLIF(TRIM(c.email), '') IS NULL
         AND NOT EXISTS (SELECT 1 FROM presupuestos p2 WHERE p2.cliente_id = c.id)
         AND NOT EXISTS (SELECT 1 FROM cliente_archivos ca WHERE ca.cliente_id = c.id)
         AND EXISTS (
           SELECT 1
           FROM ordenes_servicio os2
           WHERE NULLIF(TRIM(os2.supervisor), '') IS NOT NULL
             AND CONVERT(TRIM(os2.supervisor) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
                 CONVERT(TRIM(c.nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci
         )`
    );
  }
}

async function ensureCommissionTables() {
  await pool.execute(
    `CREATE TABLE IF NOT EXISTS comisiones (
      id INT AUTO_INCREMENT PRIMARY KEY,
      presupuesto_id INT NOT NULL,
      supervisor_id INT NULL,
      supervisor_nombre_manual VARCHAR(180) NOT NULL DEFAULT '',
      folio VARCHAR(60) NOT NULL UNIQUE,
      nombre_proyecto VARCHAR(220) NOT NULL DEFAULT '',
      descripcion_proyecto TEXT NULL,
      empresa VARCHAR(180) NOT NULL DEFAULT '',
      monto_proyecto DECIMAL(14,2) NOT NULL DEFAULT 0,
      porcentaje_comision DECIMAL(8,4) NOT NULL DEFAULT 0,
      porcentaje_distribucion DECIMAL(8,4) NOT NULL DEFAULT 100,
      descuento DECIMAL(14,2) NOT NULL DEFAULT 0,
      monto_comision DECIMAL(14,2) NOT NULL DEFAULT 0,
      estatus VARCHAR(60) NOT NULL DEFAULT 'Generada',
      pdf_ruta VARCHAR(360) NOT NULL DEFAULT '',
      usuario_id INT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
      INDEX idx_comisiones_presupuesto (presupuesto_id),
      INDEX idx_comisiones_supervisor (supervisor_id),
      INDEX idx_comisiones_folio (folio)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
  );

  await ensureColumn("comisiones", "presupuesto_id", "presupuesto_id INT NULL");
  await ensureColumn("comisiones", "supervisor_id", "supervisor_id INT NULL");
  // Evita ejecutar un ALTER TABLE en cada apertura del módulo. Además de ser
  // innecesario, ese bloqueo de esquema podía provocar el error 500 cuando
  // varias personas consultaban Comisiones al mismo tiempo.
  try {
    const [supervisorColumn] = await pool.execute(
      `SELECT IS_NULLABLE
       FROM INFORMATION_SCHEMA.COLUMNS
       WHERE TABLE_SCHEMA = ? AND TABLE_NAME = 'comisiones' AND COLUMN_NAME = 'supervisor_id'
       LIMIT 1`,
      [DB_NAME]
    );
    if (supervisorColumn[0]?.IS_NULLABLE === "NO") {
      await pool.execute("ALTER TABLE comisiones MODIFY supervisor_id INT NULL");
    }
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }
  await ensureColumn("comisiones", "supervisor_nombre_manual", "supervisor_nombre_manual VARCHAR(180) NOT NULL DEFAULT ''");
  await ensureColumn("comisiones", "folio", "folio VARCHAR(60) NOT NULL DEFAULT ''");
  await ensureColumn("comisiones", "nombre_proyecto", "nombre_proyecto VARCHAR(220) NOT NULL DEFAULT ''");
  await ensureColumn("comisiones", "descripcion_proyecto", "descripcion_proyecto TEXT NULL");
  await ensureColumn("comisiones", "empresa", "empresa VARCHAR(180) NOT NULL DEFAULT ''");
  await ensureColumn("comisiones", "monto_proyecto", "monto_proyecto DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("comisiones", "porcentaje_comision", "porcentaje_comision DECIMAL(8,4) NOT NULL DEFAULT 0");
  await ensureColumn("comisiones", "porcentaje_distribucion", "porcentaje_distribucion DECIMAL(8,4) NOT NULL DEFAULT 100");
  await ensureColumn("comisiones", "descuento", "descuento DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("comisiones", "monto_comision", "monto_comision DECIMAL(14,2) NOT NULL DEFAULT 0");
  await ensureColumn("comisiones", "estatus", "estatus VARCHAR(60) NOT NULL DEFAULT 'Generada'");
  await ensureColumn("comisiones", "pdf_ruta", "pdf_ruta VARCHAR(360) NOT NULL DEFAULT ''");
  await ensureColumn("comisiones", "usuario_id", "usuario_id INT NULL");
  await ensureColumn(
    "comisiones",
    "created_at",
    "created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP"
  );
  await ensureColumn(
    "comisiones",
    "updated_at",
    "updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"
  );
}

function parseLegacyJsonArray(value) {
  if (!value) return [];
  try {
    const parsed = typeof value === "string" ? JSON.parse(value) : value;
    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed?.items)) return parsed.items;
    if (Array.isArray(parsed?.partidas)) return parsed.partidas;
    if (Array.isArray(parsed?.conceptos)) return parsed.conceptos;
    return [];
  } catch (error) {
    return [];
  }
}

function mapLegacyApprovalStatus(value) {
  const normalized = String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (normalized.includes("aprobad") && !normalized.includes("no")) return "Aprobada";
  if (normalized.includes("rechaz") || normalized.includes("no_aprob") || normalized.includes("no apro")) {
    return "No aprobada";
  }
  if (normalized.includes("cerr")) return "Orden cerrada";
  return "En espera de aprobación";
}

function mapLegacyVersionStatus(value) {
  const normalized = String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (normalized.includes("cancel")) return "Cancelada";
  if (normalized.includes("aprobad")) return "Aprobada";
  if (normalized.includes("rechaz") || normalized.includes("no_aprob") || normalized.includes("no apro")) {
    return "No aprobada";
  }
  return "Pendiente de aprobación";
}

function legacyClientQuoteFolio(budgetFolio, version) {
  const digits = String(budgetFolio || "").match(/(\d{1,6})$/)?.[1] || "0";
  return `CC${String(Number(digits)).padStart(4, "0")}-${Number(version || 1)}`;
}

function legacySupplierOrderFolio(budgetId, version) {
  return `OCP${String(Number(budgetId || 0)).padStart(4, "0")}-${Number(version || 1)}`;
}

function legacyFixedExpenseOrderFolio(ocgfId, version) {
  return `OCGF${String(Number(ocgfId || 0)).padStart(4, "0")}-${Number(version || 1)}`;
}

async function migrateLegacyBudgets() {
  if (!(await tableExists("ordenes_servicio"))) return;

  const [existingRows] = await pool.execute("SELECT id, folio FROM presupuestos");
  const existingIds = new Set(existingRows.map((row) => Number(row.id)));
  const usedFolios = new Set(existingRows.map((row) => String(row.folio || "").toLowerCase()).filter(Boolean));
  const [legacyRows] = await pool.execute(
    `SELECT os.*,
            COALESCE(c.sucursal, '') AS legacy_sucursal,
            COALESCE(c.nombre, '') AS legacy_cliente_usuario,
            COALESCE(c.valor_venta, NULL) AS legacy_valor_venta
     FROM ordenes_servicio os
     LEFT JOIN clientes c ON c.id = os.cliente_id
     WHERE COALESCE(os.eliminado, 0) = 0
     ORDER BY os.id`
  );

  for (const row of legacyRows) {
    if (existingIds.has(Number(row.id))) continue;
    let folio = String(row.dlv || `DLVLEG${row.id}`).trim() || `DLVLEG${row.id}`;
    if (usedFolios.has(folio.toLowerCase())) folio = `${folio}-${row.id}`;
    usedFolios.add(folio.toLowerCase());
    const hasPo = Boolean(row.po_cliente) || Boolean(row.sin_po_cliente);
    const estado = String(row.estado || "").toLowerCase().includes("cerr")
      ? "Cerrada"
      : hasPo
        ? "En proceso"
        : "Abierta";

    await pool.execute(
      `INSERT INTO presupuestos
        (id, cliente_id, empresa, sucursal, cliente_usuario, area, titulo_proyecto, folio, po,
         folio_manual, estado, estatus, usuario_id, sin_garantia, valor_venta_override,
         created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?)`,
      [
        row.id,
        row.cliente_id || null,
        row.empresa || "",
        normalizeClientBranchLabel(row.legacy_sucursal || ""),
        row.legacy_cliente_usuario || "",
        row.area || "",
        row.proyecto || "Presupuesto histórico",
        folio,
        row.po_cliente || (row.sin_po_cliente ? "Sin PO" : ""),
        estado,
        mapLegacyApprovalStatus(row.estatus_aprobacion),
        row.usuario_id || null,
        Number(row.sin_garantia || 0),
        row.legacy_valor_venta || null,
        row.created_at || row.fecha || new Date(),
        row.created_at || row.fecha || new Date()
      ]
    );
    existingIds.add(Number(row.id));
  }

  await pool.execute(
    `UPDATE presupuestos p
     INNER JOIN ordenes_servicio os ON os.id = p.id
     SET p.sucursal = os.nombre_cliente
     WHERE (p.sucursal IS NULL OR p.sucursal = '')
       AND NULLIF(os.nombre_cliente, '') IS NOT NULL`
  );

  await pool.execute(
    `UPDATE presupuestos p
     INNER JOIN ordenes_servicio os ON os.id = p.id
     INNER JOIN clientes c ON c.id = COALESCE(p.cliente_id, os.cliente_id)
     SET p.cliente_usuario = c.nombre
     WHERE (
        p.cliente_usuario IS NULL
        OR p.cliente_usuario = ''
        OR p.cliente_usuario = p.sucursal
        OR CONVERT(TRIM(p.cliente_usuario) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
           CONVERT(TRIM(COALESCE(os.supervisor, '')) USING utf8mb4) COLLATE utf8mb4_unicode_ci
       )
       AND NULLIF(c.nombre, '') IS NOT NULL`
  );

  if (await tableExists("os_equipos")) {
    await pool.execute(
      `INSERT IGNORE INTO presupuesto_costos_equipos
        (id, presupuesto_id, item, cantidad_equipos, cantidad_um, unidad_medida, costo_unitario, flete, subtotal)
       SELECT e.id, e.orden_id, COALESCE(NULLIF(e.item, ''), 'Equipo histórico'),
              COALESCE(e.cantidad, 0), COALESCE(e.dias, 0), COALESCE(e.unidad, ''),
              COALESCE(e.costo_unitario, 0), COALESCE(e.flete, 0), COALESCE(e.subtotal, 0)
       FROM os_equipos e
       INNER JOIN ordenes_servicio os ON os.id = e.orden_id
       INNER JOIN presupuestos p ON p.id = e.orden_id
       WHERE (
          LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci LIKE
            CONCAT(LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci, _utf8mb4'-%' COLLATE utf8mb4_unicode_ci)
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(CONCAT(_utf8mb4'DLVLEG' COLLATE utf8mb4_unicode_ci, os.id))
        )
        AND (COALESCE(e.item, '') NOT IN ('', '0') OR COALESCE(e.subtotal, 0) <> 0)`
    );
  }

  if (await tableExists("os_destajo")) {
    await pool.execute(
      `INSERT IGNORE INTO presupuesto_costos_contratistas
        (id, presupuesto_id, descripcion, cantidad, costo, subtotal)
       SELECT d.id, d.orden_id, COALESCE(NULLIF(d.descripcion, ''), 'Contratista histórico'),
              COALESCE(d.cantidad, 0), COALESCE(d.costo, 0), COALESCE(d.subtotal, 0)
       FROM os_destajo d
       INNER JOIN ordenes_servicio os ON os.id = d.orden_id
       INNER JOIN presupuestos p ON p.id = d.orden_id
       WHERE (
          LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci LIKE
            CONCAT(LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci, _utf8mb4'-%' COLLATE utf8mb4_unicode_ci)
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(CONCAT(_utf8mb4'DLVLEG' COLLATE utf8mb4_unicode_ci, os.id))
        )
        AND (COALESCE(d.descripcion, '') NOT IN ('', '0') OR COALESCE(d.subtotal, 0) <> 0)`
    );
  }

  if (await tableExists("os_mano_obra")) {
    await pool.execute(
      `INSERT IGNORE INTO presupuesto_costos_mano_obra
        (id, presupuesto_id, descripcion, personas, horas, horas_total, costo_hora, comidas, costo_comida, subtotal)
       SELECT m.id, m.orden_id, COALESCE(NULLIF(m.descripcion, ''), 'Mano de obra histórica'),
              COALESCE(m.personas, 0), COALESCE(m.horas, 0), COALESCE(m.horas_totales, 0),
              COALESCE(m.costo_hr, 0), COALESCE(m.comidas, 0), COALESCE(m.costo_comidas, 0),
              COALESCE(m.subtotal, 0)
       FROM os_mano_obra m
       INNER JOIN ordenes_servicio os ON os.id = m.orden_id
       INNER JOIN presupuestos p ON p.id = m.orden_id
       WHERE (
          LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci LIKE
            CONCAT(LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci, _utf8mb4'-%' COLLATE utf8mb4_unicode_ci)
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(CONCAT(_utf8mb4'DLVLEG' COLLATE utf8mb4_unicode_ci, os.id))
        )
        AND (COALESCE(m.descripcion, '') NOT IN ('', '0') OR COALESCE(m.subtotal, 0) <> 0)`
    );
  }

  if (await tableExists("os_materiales")) {
    await pool.execute(
      `INSERT IGNORE INTO presupuesto_costos_materiales
        (id, presupuesto_id, descripcion, cantidad, unidad, costo, subtotal)
       SELECT mt.id, mt.orden_id, COALESCE(NULLIF(mt.descripcion, ''), 'Material histórico'),
              COALESCE(mt.cantidad, 0), COALESCE(mt.unidad, ''), COALESCE(mt.costo, 0),
              COALESCE(mt.subtotal, 0)
       FROM os_materiales mt
       INNER JOIN ordenes_servicio os ON os.id = mt.orden_id
       INNER JOIN presupuestos p ON p.id = mt.orden_id
       WHERE (
          LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci LIKE
            CONCAT(LOWER(TRIM(CONVERT(os.dlv USING utf8mb4))) COLLATE utf8mb4_unicode_ci, _utf8mb4'-%' COLLATE utf8mb4_unicode_ci)
          OR LOWER(TRIM(CONVERT(p.folio USING utf8mb4))) COLLATE utf8mb4_unicode_ci =
            LOWER(CONCAT(_utf8mb4'DLVLEG' COLLATE utf8mb4_unicode_ci, os.id))
        )
        AND (COALESCE(mt.descripcion, '') NOT IN ('', '0') OR COALESCE(mt.subtotal, 0) <> 0)`
    );
  }

  for (const row of legacyRows) {
    const poNumber = String(row.po_cliente || "").trim();
    const sinPo = Number(row.sin_po_cliente || 0) === 1;
    if (!poNumber && !sinPo) continue;
    const [existingPoRows] = await pool.execute(
      "SELECT id FROM presupuesto_po_cliente WHERE presupuesto_id = ? LIMIT 1",
      [row.id]
    );
    if (existingPoRows.length) continue;
    const [currentBudgetRows] = await pool.execute("SELECT po, estatus FROM presupuestos WHERE id = ? LIMIT 1", [
      row.id
    ]);
    const currentBudget = currentBudgetRows[0];
    if (
      currentBudget &&
      !String(currentBudget.po || "").trim() &&
      normalizeWorkflowValue(currentBudget.estatus) === "en espera de po"
    ) {
      continue;
    }
    await pool.execute(
      `INSERT INTO presupuesto_po_cliente
        (presupuesto_id, numero_po, sin_po, nombre, ruta, usuario_id, created_at)
       VALUES (?, ?, ?, '', '', ?, ?)`,
      [
        row.id,
        poNumber || "Sin PO",
        sinPo ? 1 : 0,
        row.usuario_id || null,
        row.created_at || new Date()
      ]
    );
  }

  const transferColumns = await getTableColumns("presupuesto_transferencias");
  if (transferColumns.includes("orden_id") && transferColumns.includes("presupuesto_id")) {
    await pool.execute(
      `UPDATE presupuesto_transferencias
       SET presupuesto_id = orden_id
       WHERE (presupuesto_id IS NULL OR presupuesto_id = 0) AND orden_id IS NOT NULL`
    );
  }

  if (await tableExists("presupuesto_adicional_orden")) {
    await pool.execute(
      `INSERT IGNORE INTO presupuesto_adicionales (id, presupuesto_id, bloque, monto, usuario_id, created_at)
       SELECT pa.id, pa.orden_id, COALESCE(pa.presupuesto, 'materiales'), COALESCE(pa.monto, 0),
              pa.usuario_id, COALESCE(pa.created_at, CURRENT_TIMESTAMP)
       FROM presupuesto_adicional_orden pa
       INNER JOIN presupuestos p ON p.id = pa.orden_id`
    );
  }
}

async function migrateLegacyClientQuotes() {
  if (!(await tableExists("os_cotizaciones_cliente"))) return;
  const [rows] = await pool.execute(
    `SELECT q.*, p.folio AS presupuesto_folio
     FROM os_cotizaciones_cliente q
     INNER JOIN presupuestos p ON p.id = q.orden_id
     ORDER BY q.id`
  );

  for (const row of rows) {
    const [existing] = await pool.execute("SELECT id FROM cotizaciones_cliente WHERE id = ? LIMIT 1", [row.id]);
    if (!existing.length) {
      await pool.execute(
        `INSERT INTO cotizaciones_cliente
          (id, presupuesto_id, tipo, folio, version, estatus, terminos, usuario_id, aprobada_at, pdf_ruta, created_at, updated_at)
         VALUES (?, ?, 'version', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          row.id,
          row.orden_id,
          row.folio || legacyClientQuoteFolio(row.presupuesto_folio, row.version),
          row.version || 1,
          mapLegacyVersionStatus(row.estado) === "Cancelada" ? "Cancelada" : "Aprobada",
          CLIENT_QUOTE_DEFAULT_TERMS,
          row.usuario_id || null,
          mapLegacyVersionStatus(row.estado) === "Cancelada" ? null : row.aprobado_en || row.creado_en || new Date(),
          row.pdf_ruta || "",
          row.creado_en || new Date(),
          row.creado_en || new Date()
        ]
      );
    }

    const [partCount] = await pool.execute(
      "SELECT COUNT(*) AS total FROM cotizacion_cliente_partidas WHERE cotizacion_id = ?",
      [row.id]
    );
    if (Number(partCount[0]?.total || 0) > 0) continue;
    for (const item of parseLegacyJsonArray(row.datos)) {
      const cantidad = Number(item.cantidad || 0);
      const precio = Number(item.precio || item.precio_unitario || 0);
      const descripcion = String(item.descripcion || item.concepto || "").trim();
      if (!descripcion && !cantidad && !precio) continue;
      await pool.execute(
        `INSERT INTO cotizacion_cliente_partidas
          (cotizacion_id, cantidad, unidad_medida, descripcion, precio, subtotal)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [row.id, cantidad, item.um || item.unidad || "U.M.", descripcion || "Partida histórica", precio, cantidad * precio]
      );
    }
  }
}

async function syncLegacyAccountsReceivableData() {
  await ensureAccountsReceivableTables();

  if (await tableExists("os_archivos")) {
    await pool.execute(
      `INSERT INTO cuentas_por_cobrar
        (cotizacion_cliente_id, presupuesto_id, estado, pendiente, dias_pago, fecha_pago, monto, usuario_id, created_at, updated_at)
       SELECT
         q.id,
         p.id,
         'En proceso',
         'En proceso',
         CASE
           WHEN LOWER(COALESCE((
             SELECT c2.condiciones_pago
             FROM clientes c2
             WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
             ORDER BY c2.id DESC
             LIMIT 1
           ), 'contado')) LIKE '%contado%' THEN 0
           ELSE COALESCE((
             SELECT NULLIF(c2.dias_credito, 0)
             FROM clientes c2
             WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
             ORDER BY c2.id DESC
             LIMIT 1
           ), 30)
         END,
         NULL,
         GREATEST(COALESCE(SUM(part.subtotal), 0) - COALESCE(MAX(q.descuento_monto), 0), 0),
         q.usuario_id,
         COALESCE(q.created_at, CURRENT_TIMESTAMP),
         COALESCE(q.updated_at, q.created_at, CURRENT_TIMESTAMP)
       FROM cotizaciones_cliente q
       INNER JOIN presupuestos p ON p.id = q.presupuesto_id
       LEFT JOIN cotizacion_cliente_partidas part ON part.cotizacion_id = q.id
       LEFT JOIN cuentas_por_cobrar cx ON cx.cotizacion_cliente_id = q.id
       WHERE q.tipo = 'version'
         AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
         AND EXISTS (
           SELECT 1
           FROM os_archivos a
           WHERE a.orden_id = p.id
             AND LOWER(TRIM(a.tipo)) IN ('factura', 'comprobante_pago', 'complemento_pago', 'gr', 'track_id', 'track id')
           LIMIT 1
         )
         AND q.id = (
           SELECT q2.id
           FROM cotizaciones_cliente q2
           WHERE q2.presupuesto_id = q.presupuesto_id
             AND q2.tipo = 'version'
             AND LOWER(TRIM(q2.estatus)) LIKE 'aprob%'
           ORDER BY q2.version DESC, q2.id DESC
           LIMIT 1
         )
         AND cx.id IS NULL
       GROUP BY q.id, p.id, p.empresa, q.usuario_id, q.created_at, q.updated_at`
    );

    await pool.execute(
      `INSERT INTO cuentas_por_cobrar_archivos (cuenta_id, tipo, nombre, ruta, usuario_id, created_at)
       SELECT
         cx.id,
         CASE LOWER(TRIM(a.tipo))
           WHEN 'factura' THEN 'Factura'
           WHEN 'comprobante_pago' THEN 'Comprobante de pago'
           WHEN 'complemento_pago' THEN 'Complemento de pago'
           WHEN 'gr' THEN 'GR'
           WHEN 'track_id' THEN 'Track ID'
           WHEN 'track id' THEN 'Track ID'
           ELSE ''
         END,
         a.nombre,
         a.ruta,
         a.usuario_id,
         COALESCE(a.created_at, CURRENT_TIMESTAMP)
       FROM os_archivos a
       INNER JOIN cotizaciones_cliente q
         ON q.presupuesto_id = a.orden_id
        AND q.tipo = 'version'
        AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
        AND q.id = (
          SELECT q2.id
          FROM cotizaciones_cliente q2
          WHERE q2.presupuesto_id = a.orden_id
            AND q2.tipo = 'version'
            AND LOWER(TRIM(q2.estatus)) LIKE 'aprob%'
          ORDER BY q2.version DESC, q2.id DESC
          LIMIT 1
        )
       INNER JOIN cuentas_por_cobrar cx ON cx.cotizacion_cliente_id = q.id
       WHERE LOWER(TRIM(a.tipo)) IN ('factura', 'comprobante_pago', 'complemento_pago', 'gr', 'track_id', 'track id')
         AND NOT EXISTS (
           SELECT 1
           FROM cuentas_por_cobrar_archivos existing
           WHERE existing.cuenta_id = cx.id
             AND existing.ruta COLLATE utf8mb4_unicode_ci = a.ruta COLLATE utf8mb4_unicode_ci
         )`
    );
  }

  const [accountRows] = await pool.execute("SELECT id FROM cuentas_por_cobrar");
  for (const row of accountRows) {
    await refreshAccountsReceivableStatus(row.id);
  }
}

async function migrateLegacySupplierOrders() {
  if (!(await tableExists("oc_proveedor"))) return;
  const legacyOrderColumns = await getTableColumns("oc_proveedor");
  const hasLegacyDocumentStatus = legacyOrderColumns.includes("estatus_documentacion");
  const [rows] = await pool.execute(
    `SELECT o.*
     FROM oc_proveedor o
     INNER JOIN presupuestos p ON p.id = o.orden_id
     ORDER BY o.id`
  );

  for (const row of rows) {
    const [existing] = await pool.execute("SELECT id FROM ocp_proveedor WHERE id = ? LIMIT 1", [row.id]);
    if (!existing.length) {
      await pool.execute(
        `INSERT INTO ocp_proveedor
          (id, presupuesto_id, tipo, folio, version, estatus, retencion_activa, retencion_monto,
           pdf_ruta, estatus_documentacion, usuario_id, created_at, updated_at)
         VALUES (?, ?, 'version', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          row.id,
          row.orden_id,
          row.folio || legacySupplierOrderFolio(row.orden_id, row.version),
          row.version || 1,
          mapLegacyVersionStatus(row.estado),
          Number(row.retencion_impuestos || 0) > 0 ? 1 : 0,
          Number(row.retencion_impuestos || 0),
          row.pdf_ruta || "",
          hasLegacyDocumentStatus ? row.estatus_documentacion || "" : "",
          row.usuario_id || null,
          row.fecha || new Date(),
          row.fecha || new Date()
        ]
      );
    }

    const [partCount] = await pool.execute("SELECT COUNT(*) AS total, COALESCE(SUM(total), 0) AS amount FROM ocp_proveedor_partidas WHERE ocp_id = ?", [
      row.id
    ]);
    if (Number(partCount[0]?.total || 0) > 0 && Number(partCount[0]?.amount || 0) > 0) continue;
    if (Number(partCount[0]?.total || 0) > 0) {
      await pool.execute("DELETE FROM ocp_proveedor_partidas WHERE ocp_id = ?", [row.id]);
    }
    for (const item of parseLegacyJsonArray(row.items)) {
      const cantidad = Number(item.cantidad || 0);
      const precio = Number(item.precio || item.precio_unitario || 0);
      const descripcion = String(item.descripcion || item.concepto || "").trim();
      if (!descripcion && !cantidad && !precio) continue;
      await pool.execute(
        `INSERT INTO ocp_proveedor_partidas
          (ocp_id, presupuesto_bloque, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario, total)
         VALUES (?, ?, NULL, ?, ?, ?, ?, ?)`,
        [
          row.id,
          normalizeBudgetBlock(item.presupuesto || item.bloque || "materiales"),
          item.proveedor || "",
          descripcion || "Partida histórica",
          cantidad,
          precio,
          cantidad * precio
        ]
      );
    }
  }

  if (hasLegacyDocumentStatus) {
    await pool.execute(
      `UPDATE ocp_proveedor n
       INNER JOIN oc_proveedor old ON old.id = n.id
       SET n.estatus_documentacion = COALESCE(old.estatus_documentacion, n.estatus_documentacion)
       WHERE (n.estatus_documentacion IS NULL OR n.estatus_documentacion = '')
         AND COALESCE(old.estatus_documentacion, '') <> ''`
    );
  }

  if (await tableExists("ordenes_pago_proveedor")) {
    await pool.execute(
      `UPDATE ocp_proveedor n
       INNER JOIN ordenes_pago_proveedor op ON op.oc_proveedor_id = n.id
       SET n.estatus_documentacion = 'ocp_pagada'
       WHERE LOWER(TRIM(n.estatus)) LIKE 'aprobad%'`
    );
  }
}

async function migrateLegacyFixedExpenseOrders() {
  if (!(await tableExists("gastos_fijos"))) return;
  const fixedColumns = await getTableColumns("gastos_fijos");
  if (fixedColumns.includes("contacto") || fixedColumns.includes("folio")) {
    await pool.execute(
      `INSERT IGNORE INTO ocgf_compras
        (id, gasto_fijo_id, gasto, sucursal, proveedor_id, proveedor_nombre, descripcion, fecha,
         presupuesto, folio, estado, usuario_id, created_at, updated_at)
       SELECT gf.id, gf.id, COALESCE(NULLIF(gf.gasto, ''), gf.contacto, 'Gasto fijo histórico'),
              COALESCE(NULLIF(gf.sucursal, ''), gf.area, ''),
              gf.proveedor_id, COALESCE(p.empresa, ''),
              COALESCE(gf.contacto, gf.gasto, ''), gf.fecha,
              COALESCE(NULLIF(gf.presupuesto, 0), p.presupuesto, 0),
              COALESCE(gf.folio, CONCAT('OCGF', LPAD(gf.id, 4, '0'))),
              CASE
                WHEN gf.estatus_aprobacion = 'pagada' THEN 'OCGF Pagada'
                WHEN gf.estatus_aprobacion = 'aprobada' THEN 'Aprobada'
                ELSE 'OCGF Generada'
              END,
              gf.usuario_id, COALESCE(gf.created_at, CURRENT_TIMESTAMP), CURRENT_TIMESTAMP
       FROM gastos_fijos gf
       LEFT JOIN proveedores p ON p.id = gf.proveedor_id
       WHERE gf.proveedor_id IS NOT NULL OR COALESCE(gf.folio, '') <> '' OR COALESCE(gf.contacto, '') <> ''`
    );
  }

  if (await tableExists("gf_oc_proveedor")) {
    const [rows] = await pool.execute(
      `SELECT o.*
       FROM gf_oc_proveedor o
       INNER JOIN ocgf_compras g ON g.id = o.gasto_fijo_id
       ORDER BY o.id`
    );
    const orderColumns = await getTableColumns("gf_oc_proveedor");
    const hasLegacyDocumentStatus = orderColumns.includes("estatus_documentacion");
    for (const row of rows) {
      const [existing] = await pool.execute("SELECT id FROM ocgf_ordenes WHERE id = ? LIMIT 1", [row.id]);
      if (!existing.length) {
        const retencion = Number(row.retencion_impuestos || 0);
        await pool.execute(
          `INSERT INTO ocgf_ordenes
            (id, ocgf_id, tipo, folio, version, estatus, retencion_activa, retencion_monto, sin_iva,
             pdf_ruta, estatus_documentacion, usuario_id, created_at, updated_at)
           VALUES (?, ?, 'version', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            row.id,
            row.gasto_fijo_id,
            row.folio || legacyFixedExpenseOrderFolio(row.gasto_fijo_id, row.version),
            row.version || 1,
            mapLegacyVersionStatus(row.estado),
            retencion > 0 ? 1 : 0,
            retencion,
            orderColumns.includes("sin_iva") ? Number(row.sin_iva || 0) : 0,
            row.pdf_ruta || "",
            hasLegacyDocumentStatus ? row.estatus_documentacion || "" : "",
            row.usuario_id || null,
            row.fecha || new Date(),
            row.fecha || new Date()
          ]
        );
      }

      const [partCount] = await pool.execute("SELECT COUNT(*) AS total, COALESCE(SUM(total), 0) AS amount FROM ocgf_orden_partidas WHERE orden_id = ?", [
        row.id
      ]);
      if (Number(partCount[0]?.total || 0) > 0 && Number(partCount[0]?.amount || 0) > 0) continue;
      if (Number(partCount[0]?.total || 0) > 0) {
        await pool.execute("DELETE FROM ocgf_orden_partidas WHERE orden_id = ?", [row.id]);
      }
      const [ocgfRows] = await pool.execute(
        "SELECT proveedor_id, proveedor_nombre FROM ocgf_compras WHERE id = ? LIMIT 1",
        [row.gasto_fijo_id]
      );
      const ocgf = ocgfRows[0] || {};
      for (const item of parseLegacyJsonArray(row.items)) {
        const cantidad = Number(item.cantidad || 0);
        const precio = Number(item.precio || item.precio_unitario || 0);
        const descripcion = String(item.descripcion || item.concepto || "").trim();
        if (!descripcion && !cantidad && !precio) continue;
        await pool.execute(
          `INSERT INTO ocgf_orden_partidas
            (orden_id, presupuesto, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario, total)
           VALUES (?, 'Gastos Fijos', ?, ?, ?, ?, ?, ?)`,
          [
            row.id,
            ocgf.proveedor_id || null,
            ocgf.proveedor_nombre || item.proveedor || "",
            descripcion || "Partida histórica",
            cantidad,
            precio,
            cantidad * precio
          ]
        );
      }
    }

    if (hasLegacyDocumentStatus) {
      await pool.execute(
        `UPDATE ocgf_ordenes n
         INNER JOIN gf_oc_proveedor old ON old.id = n.id
         SET n.estatus_documentacion = COALESCE(old.estatus_documentacion, n.estatus_documentacion)
         WHERE (n.estatus_documentacion IS NULL OR n.estatus_documentacion = '')
           AND COALESCE(old.estatus_documentacion, '') <> ''`
      );
    }
  }

  if (await tableExists("gf_archivos")) {
    await pool.execute(
      `INSERT IGNORE INTO ocgf_archivos (id, ocgf_id, tipo, nombre, ruta, usuario_id, created_at)
       SELECT a.id, a.gasto_fijo_id, a.tipo, a.nombre, a.ruta, a.usuario_id, COALESCE(a.created_at, CURRENT_TIMESTAMP)
       FROM gf_archivos a
       INNER JOIN ocgf_compras g ON g.id = a.gasto_fijo_id`
    );
  }
}

async function migrateLegacyV1Data() {
  try {
    await migrateLegacyBudgets();
    await migrateLegacyClientQuotes();
    await migrateLegacySupplierOrders();
    await migrateLegacyFixedExpenseOrders();
    await syncLegacyAccountsReceivableData();
    await syncLegacyAccountsPayableData();
  } catch (error) {
    logServerError("legacy-v1-migration", error);
  }
}

async function syncLegacyAccountsPayableData() {
  await ensureAccountsPayableTables();

  await pool.execute(
    `INSERT INTO cuentas_por_pagar
      (tipo_origen, ocp_id, presupuesto_id, estado, pendiente, dias_pago, fecha_pago, monto, pagado, usuario_id, created_at, updated_at)
     SELECT
       'OCP',
       o.id,
       o.presupuesto_id,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' THEN 'Pago completo'
         ELSE 'En proceso'
       END,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' THEN 'Sin pendientes'
         ELSE 'Cargar Factura Proveedor'
       END,
       30,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' THEN DATE(o.updated_at)
         ELSE NULL
       END,
       GREATEST(0, COALESCE(SUM(COALESCE(NULLIF(op.monto_pago_aplicado, 0), ROUND(op.total * COALESCE(op.porcentaje_aplicado, 100) / 100, 2))), 0) * 1.16 - IF(COALESCE(o.retencion_activa, 0) = 1, COALESCE(o.retencion_monto, 0), 0)),
       CASE WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' THEN 1 ELSE 0 END,
       o.usuario_id,
       COALESCE(o.created_at, CURRENT_TIMESTAMP),
       COALESCE(o.updated_at, CURRENT_TIMESTAMP)
     FROM ocp_proveedor o
     LEFT JOIN ocp_proveedor_partidas op ON op.ocp_id = o.id
     LEFT JOIN cuentas_por_pagar cp ON cp.ocp_id = o.id AND cp.tipo_origen = 'OCP'
     WHERE o.tipo = 'version'
       AND LOWER(TRIM(o.estatus)) LIKE 'aprobad%'
       AND cp.id IS NULL
     GROUP BY
       o.id, o.presupuesto_id, o.estatus_documentacion, o.retencion_activa, o.retencion_monto,
       o.usuario_id, o.created_at, o.updated_at`
  );

  await pool.execute(
    `UPDATE cuentas_por_pagar cp
     INNER JOIN (
       SELECT
         o.id AS ocp_id,
         COALESCE(SUM(op.total), 0) AS monto_ocp_base,
         COALESCE(SUM(COALESCE(NULLIF(op.monto_pago_aplicado, 0), ROUND(op.total * COALESCE(op.porcentaje_aplicado, 100) / 100, 2))), 0) AS subtotal_programado_pago,
         GROUP_CONCAT(DISTINCT CONCAT(CAST(ROUND(COALESCE(op.porcentaje_aplicado, 100), 2) AS CHAR), '%') ORDER BY COALESCE(op.porcentaje_aplicado, 100) SEPARATOR ', ') AS porcentaje_pago,
         GREATEST(0, COALESCE(SUM(COALESCE(NULLIF(op.monto_pago_aplicado, 0), ROUND(op.total * COALESCE(op.porcentaje_aplicado, 100) / 100, 2))), 0) * 1.16 - IF(COALESCE(o.retencion_activa, 0) = 1, COALESCE(o.retencion_monto, 0), 0)) AS total,
         CASE WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' THEN 1 ELSE 0 END AS legacy_paid
       FROM ocp_proveedor o
       LEFT JOIN ocp_proveedor_partidas op ON op.ocp_id = o.id
       WHERE o.tipo = 'version'
       GROUP BY o.id, o.retencion_activa, o.retencion_monto, o.estatus_documentacion
     ) totals ON totals.ocp_id = cp.ocp_id
     SET cp.monto = totals.total,
         cp.monto_ocp_base = totals.monto_ocp_base,
         cp.porcentaje_pago = COALESCE(totals.porcentaje_pago, '100%'),
         cp.subtotal_programado_pago = totals.subtotal_programado_pago,
         cp.pagado = GREATEST(cp.pagado, totals.legacy_paid),
         cp.estado = CASE WHEN totals.legacy_paid = 1 THEN 'Pago completo' ELSE cp.estado END,
         cp.pendiente = CASE WHEN totals.legacy_paid = 1 THEN 'Sin pendientes' ELSE cp.pendiente END
     WHERE cp.tipo_origen = 'OCP'`
  );

  await pool.execute(
    `INSERT INTO cuentas_por_pagar
      (tipo_origen, ocp_id, ocgf_orden_id, ocgf_id, presupuesto_id, estado, pendiente, dias_pago,
       fecha_pago, monto, pagado, usuario_id, created_at, updated_at)
     SELECT
       'OCGF',
       NULL,
       o.id,
       o.ocgf_id,
       NULL,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' OR g.estado = 'OCGF Pagada' THEN 'Pago completo'
         ELSE 'En proceso'
       END,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' OR g.estado = 'OCGF Pagada' THEN 'Sin pendientes'
         ELSE 'Cargar Factura Proveedor'
       END,
       30,
       CASE
         WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' OR g.estado = 'OCGF Pagada' THEN DATE(o.updated_at)
         ELSE NULL
       END,
       GREATEST(0, COALESCE(SUM(p.total), 0) * IF(COALESCE(o.sin_iva, 0) = 1, 1, 1.16) - IF(COALESCE(o.retencion_activa, 0) = 1, COALESCE(o.retencion_monto, 0), 0)),
       CASE WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' OR g.estado = 'OCGF Pagada' THEN 1 ELSE 0 END,
       o.usuario_id,
       COALESCE(o.created_at, CURRENT_TIMESTAMP),
       COALESCE(o.updated_at, CURRENT_TIMESTAMP)
     FROM ocgf_ordenes o
     INNER JOIN ocgf_compras g ON g.id = o.ocgf_id
     LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
     LEFT JOIN cuentas_por_pagar cp ON cp.ocgf_orden_id = o.id AND cp.tipo_origen = 'OCGF'
     WHERE o.tipo = 'version'
       AND LOWER(TRIM(o.estatus)) LIKE 'aprobad%'
       AND cp.id IS NULL
     GROUP BY
       o.id, o.ocgf_id, o.estatus_documentacion, g.estado, o.sin_iva, o.retencion_activa,
       o.retencion_monto, o.usuario_id, o.created_at, o.updated_at`
  );

  await pool.execute(
    `UPDATE cuentas_por_pagar cp
     INNER JOIN (
       SELECT
         o.id AS order_id,
         GREATEST(0, COALESCE(SUM(p.total), 0) * IF(COALESCE(o.sin_iva, 0) = 1, 1, 1.16) - IF(COALESCE(o.retencion_activa, 0) = 1, COALESCE(o.retencion_monto, 0), 0)) AS total,
         CASE WHEN LOWER(COALESCE(o.estatus_documentacion, '')) LIKE '%pagad%' OR g.estado = 'OCGF Pagada' THEN 1 ELSE 0 END AS legacy_paid
       FROM ocgf_ordenes o
       INNER JOIN ocgf_compras g ON g.id = o.ocgf_id
       LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
       WHERE o.tipo = 'version'
       GROUP BY o.id, o.estatus_documentacion, g.estado, o.sin_iva, o.retencion_activa, o.retencion_monto
     ) totals ON totals.order_id = cp.ocgf_orden_id
     SET cp.monto = CASE WHEN cp.monto IS NULL OR cp.monto = 0 THEN totals.total ELSE cp.monto END,
         cp.pagado = GREATEST(cp.pagado, totals.legacy_paid),
         cp.estado = CASE WHEN totals.legacy_paid = 1 THEN 'Pago completo' ELSE cp.estado END,
         cp.pendiente = CASE WHEN totals.legacy_paid = 1 THEN 'Sin pendientes' ELSE cp.pendiente END
     WHERE cp.tipo_origen = 'OCGF'`
  );

  if (await tableExists("os_archivos")) {
    await pool.execute(
      `INSERT INTO cuentas_por_pagar_archivos (cuenta_id, tipo, nombre, ruta, usuario_id, created_at)
       SELECT
         cp.id,
         CASE
           WHEN LOWER(a.tipo) LIKE '%factura%' THEN 'Factura'
           WHEN LOWER(a.tipo) LIKE '%comprobante%pago%' THEN 'Comprobante de pago'
           WHEN LOWER(a.tipo) LIKE '%complemento%' THEN 'Complemento de pago'
           ELSE ''
         END,
         a.nombre,
         a.ruta,
         a.usuario_id,
         COALESCE(a.created_at, CURRENT_TIMESTAMP)
       FROM os_archivos a
       INNER JOIN ocp_proveedor o
         ON o.presupuesto_id = a.orden_id
        AND (
          (COALESCE(a.oc_proveedor_folio, '') <> '' AND a.oc_proveedor_folio COLLATE utf8mb4_unicode_ci = o.folio COLLATE utf8mb4_unicode_ci)
          OR (a.oc_proveedor_version IS NOT NULL AND a.oc_proveedor_version = o.version)
        )
       INNER JOIN cuentas_por_pagar cp ON cp.ocp_id = o.id AND cp.tipo_origen = 'OCP'
       WHERE (
           LOWER(a.tipo) LIKE '%factura%'
           OR LOWER(a.tipo) LIKE '%comprobante%pago%'
           OR LOWER(a.tipo) LIKE '%complemento%'
         )
         AND NOT EXISTS (
           SELECT 1 FROM cuentas_por_pagar_archivos existing
           WHERE existing.cuenta_id = cp.id AND existing.ruta COLLATE utf8mb4_unicode_ci = a.ruta COLLATE utf8mb4_unicode_ci
         )`
    );
  }

  if (await tableExists("gf_archivos")) {
    await pool.execute(
      `INSERT INTO cuentas_por_pagar_archivos (cuenta_id, tipo, nombre, ruta, usuario_id, created_at)
       SELECT
         cp.id,
         CASE
           WHEN LOWER(a.tipo) LIKE '%factura%' THEN 'Factura'
           WHEN LOWER(a.tipo) LIKE '%comprobante%pago%' THEN 'Comprobante de pago'
           WHEN LOWER(a.tipo) LIKE '%complemento%' THEN 'Complemento de pago'
           ELSE ''
         END,
         a.nombre,
         a.ruta,
         a.usuario_id,
         COALESCE(a.created_at, CURRENT_TIMESTAMP)
       FROM gf_archivos a
       INNER JOIN ocgf_ordenes o
         ON o.ocgf_id = a.gasto_fijo_id
        AND (
          (COALESCE(a.oc_proveedor_folio, '') <> '' AND a.oc_proveedor_folio COLLATE utf8mb4_unicode_ci = o.folio COLLATE utf8mb4_unicode_ci)
          OR (a.oc_proveedor_version IS NOT NULL AND a.oc_proveedor_version = o.version)
        )
       INNER JOIN cuentas_por_pagar cp ON cp.ocgf_orden_id = o.id AND cp.tipo_origen = 'OCGF'
       WHERE (
           LOWER(a.tipo) LIKE '%factura%'
           OR LOWER(a.tipo) LIKE '%comprobante%pago%'
           OR LOWER(a.tipo) LIKE '%complemento%'
         )
         AND NOT EXISTS (
           SELECT 1 FROM cuentas_por_pagar_archivos existing
           WHERE existing.cuenta_id = cp.id AND existing.ruta COLLATE utf8mb4_unicode_ci = a.ruta COLLATE utf8mb4_unicode_ci
         )`
    );
  }

  await pool.execute(
    `UPDATE cuentas_por_pagar cp
     SET cp.estado = 'Factura cargada',
         cp.pendiente = 'Cargar comprobante de pago',
         cp.fecha_pago = COALESCE(cp.fecha_pago, (
           SELECT DATE_ADD(MIN(a.created_at), INTERVAL cp.dias_pago DAY)
           FROM cuentas_por_pagar_archivos a
           WHERE a.cuenta_id = cp.id AND a.tipo = 'Factura'
         ))
     WHERE cp.pagado = 0
       AND EXISTS (SELECT 1 FROM cuentas_por_pagar_archivos a WHERE a.cuenta_id = cp.id AND a.tipo = 'Factura')
       AND NOT EXISTS (SELECT 1 FROM cuentas_por_pagar_archivos a WHERE a.cuenta_id = cp.id AND a.tipo = 'Comprobante de pago')`
  );

  await pool.execute(
    `UPDATE cuentas_por_pagar cp
     SET cp.estado = 'Pago comprobado',
         cp.pendiente = 'Cargar complemento de pago',
         cp.fecha_pago = COALESCE(cp.fecha_pago, CURDATE())
     WHERE cp.pagado = 0
       AND EXISTS (SELECT 1 FROM cuentas_por_pagar_archivos a WHERE a.cuenta_id = cp.id AND a.tipo = 'Comprobante de pago')`
  );
}

async function getAuthTable() {
  if (authTableCache) return authTableCache;

  const [rows] = await pool.execute(
    `SELECT TABLE_NAME, COLUMN_NAME
     FROM INFORMATION_SCHEMA.COLUMNS
     WHERE TABLE_SCHEMA = ?
     ORDER BY TABLE_NAME, ORDINAL_POSITION`,
    [DB_NAME]
  );

  const tables = new Map();
  for (const row of rows) {
    if (!tables.has(row.TABLE_NAME)) tables.set(row.TABLE_NAME, []);
    tables.get(row.TABLE_NAME).push(row.COLUMN_NAME);
  }

  const candidates = [...tables.entries()]
    .map(([table, columns]) => {
      const userColumn = pickColumn(columns, USER_COLUMNS);
      const passwordColumn = pickColumn(columns, PASSWORD_COLUMNS);
      const preferredTableScore = AUTH_TABLES.includes(table.toLowerCase()) ? 20 : 0;

      return {
        table,
        columns,
        userColumn,
        passwordColumn,
        idColumn: pickColumn(columns, ID_COLUMNS),
        nameColumn: pickColumn(columns, NAME_COLUMNS),
        roleColumn: pickColumn(columns, ROLE_COLUMNS),
        activeColumn: pickColumn(columns, ACTIVE_COLUMNS),
        score: preferredTableScore + (userColumn ? 10 : 0) + (passwordColumn ? 10 : 0)
      };
    })
    .filter((candidate) => candidate.userColumn && candidate.passwordColumn)
    .sort((a, b) => b.score - a.score);

  if (!candidates.length) {
    throw new Error(
      "No encontre una tabla de usuarios con columnas de usuario/correo y contrasena/password."
    );
  }

  authTableCache = candidates[0];
  return authTableCache;
}

function publicUser(row, config) {
  const id = config.idColumn ? row[config.idColumn] : row[config.userColumn];
  const name = config.nameColumn ? row[config.nameColumn] : row[config.userColumn];
  const role = config.roleColumn ? row[config.roleColumn] : "Operaciones";

  return {
    id,
    name: name || "Usuario Dalvo",
    username: row[config.userColumn],
    role: role || "Operaciones"
  };
}

async function getSpecialPermissionsForUser(userId) {
  const numericUserId = Number(userId || 0);
  if (!numericUserId) return [];
  const [rows] = await pool.execute(
    `SELECT DISTINCT p.nombre
     FROM usuarios_permisos up
     INNER JOIN permisos p ON p.id = up.permiso_id
     WHERE up.usuario_id = ?
     ORDER BY p.nombre`,
    [numericUserId]
  );
  return rows.map((row) => row.nombre).filter(Boolean);
}

async function getUserBranchAccessData(userId, connection = pool) {
  const numericUserId = Number(userId || 0);
  if (!numericUserId) return { branchIds: [], permissionMap: {} };
  try {
    const [rows] = await connection.execute(
      `SELECT us.sucursal_id, p.nombre AS permiso
       FROM usuarios_sucursales us
       INNER JOIN cliente_sucursales s ON s.id = us.sucursal_id AND s.activo = 1
       LEFT JOIN usuarios_sucursales_permisos usp
         ON usp.usuario_id = us.usuario_id AND usp.sucursal_id = us.sucursal_id
       LEFT JOIN permisos p ON p.id = usp.permiso_id
       WHERE us.usuario_id = ?
       ORDER BY us.sucursal_id, p.nombre`,
      [numericUserId]
    );
    const permissionMap = {};
    for (const row of rows) {
      const branchId = Number(row.sucursal_id || 0);
      if (!branchId) continue;
      if (!permissionMap[branchId]) permissionMap[branchId] = [];
      if (row.permiso && BRANCH_SCOPED_PERMISSION_NAMES.has(row.permiso)) {
        permissionMap[branchId].push(row.permiso);
      }
    }
    for (const branchId of Object.keys(permissionMap)) {
      permissionMap[branchId] = [...new Set(permissionMap[branchId])];
    }
    const branchIds = Object.entries(permissionMap)
      .filter(([, permissions]) => permissions.some((permission) => permission.startsWith("modulo:")))
      .map(([branchId]) => Number(branchId))
      .filter(Boolean);
    return { branchIds, permissionMap };
  } catch (error) {
    if (["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) {
      return { branchIds: [], permissionMap: {} };
    }
    throw error;
  }
}

async function getUserBranchAccessIds(userId, connection = pool) {
  return (await getUserBranchAccessData(userId, connection)).branchIds;
}

function getSessionBranchPermissionMap(user = {}) {
  const source = user?.permisosSucursal && typeof user.permisosSucursal === "object"
    ? user.permisosSucursal
    : {};
  const result = {};
  for (const [branchId, permissions] of Object.entries(source)) {
    const numericBranchId = Number(branchId || 0);
    if (!numericBranchId || !Array.isArray(permissions)) continue;
    result[numericBranchId] = [...new Set(permissions.map(String).filter(Boolean))];
  }
  return result;
}

function getSessionBranchAccessIds(user = {}, permissionName = "") {
  const permissionMap = getSessionBranchPermissionMap(user);
  const requestedPermission = String(permissionName || "").trim();
  return Object.entries(permissionMap)
    .filter(([, permissions]) =>
      requestedPermission
        ? permissions.includes(requestedPermission)
        : permissions.some((permission) => permission.startsWith("modulo:"))
    )
    .map(([branchId]) => Number(branchId))
    .filter(Boolean);
}

function sessionHasBranchPermission(user = {}, branchId, permissionName) {
  const numericBranchId = Number(branchId || 0);
  const normalizedPermission = String(permissionName || "").trim();
  if (!numericBranchId || !normalizedPermission) return false;
  return (getSessionBranchPermissionMap(user)[numericBranchId] || []).includes(normalizedPermission);
}

function sessionHasAnyBranchPermission(user = {}, permissionName) {
  return getSessionBranchAccessIds(user, permissionName).length > 0;
}

function applyBranchScopePermissions(user = {}, permissions = []) {
  const current = Array.isArray(permissions) ? permissions.filter(Boolean) : [];
  const role = String(user?.role || "").trim().toLowerCase();
  if (role !== "supervisor") return [...new Set(current)];
  const branchModules = Object.values(getSessionBranchPermissionMap(user))
    .flat()
    .filter((permission) => permission.startsWith("modulo:"));
  return [...new Set([...current, ...branchModules])];
}

async function hydrateSessionBranchAccess(user = {}) {
  if (!user?.id) return user;
  const access = await getUserBranchAccessData(user.id);
  user.sucursalesAccesoIds = access.branchIds;
  user.permisosSucursal = access.permissionMap;
  user.permisosEspeciales = applyBranchScopePermissions(
    user,
    await getSpecialPermissionsForUser(user.id)
  );
  return user;
}

function sessionHasSpecialPermission(user, permissionName) {
  const permissions = Array.isArray(user?.permisosEspeciales) ? user.permisosEspeciales : [];
  const normalized = String(permissionName || "").toLowerCase();
  return permissions.some((permission) => String(permission || "").toLowerCase() === normalized);
}

function isSuperAdminSession(user) {
  const username = String(user?.username || "").toLowerCase();
  const role = String(user?.role || "").toLowerCase();
  return username === "superadmin" || role === "superadmin";
}

function isCanonicalSuperAdminSession(user) {
  return String(user?.username || "").trim().toLowerCase() === "superadmin";
}

function isEngineerOscarSession(user) {
  return normalizeAccessRole(user?.username || "") === "oscar";
}

function canUseExportsWithSession(user) {
  return isSuperAdminSession(user) || isEngineerOscarSession(user);
}

function canApproveWithSession(user) {
  return isSuperAdminSession(user) || sessionHasSpecialPermission(user, "botones:aprobar");
}

function canDeleteWithSession(user) {
  return isSuperAdminSession(user) || sessionHasSpecialPermission(user, "botones:eliminar");
}

function canDeletePaymentDocumentsWithSession(user) {
  const role = normalizeAccessRole(user?.role);
  return canDeleteWithSession(user) || role === "administracion" || role === "compras";
}

function canRegisterPaymentsWithSession(user) {
  return isSuperAdminSession(user) || sessionHasSpecialPermission(user, "accion:pagar");
}

function canRegisterCollectionsWithSession(user) {
  return isSuperAdminSession(user)
    || sessionHasSpecialPermission(user, "accion:facturar")
    || sessionHasAnyBranchPermission(user, "accion:facturar");
}

function canEditOcgfHeaderWithSession(user) {
  return isSuperAdminSession(user) || sessionHasSpecialPermission(user, "operacion:ocgf:editar-cabecera");
}

async function resolveSessionRole(row, config) {
  if (row?.rol_id) {
    const roleName = await getRoleNameById(row.rol_id);
    if (roleName) return roleName;
  }

  const rawRole = config.roleColumn ? row[config.roleColumn] : "";
  if (rawRole && !Number.isFinite(Number(rawRole))) return rawRole;

  if (rawRole && Number.isFinite(Number(rawRole))) {
    const roleName = await getRoleNameById(Number(rawRole));
    if (roleName) return roleName;
  }

  return "Operaciones";
}

function requireAuth(req, res, next) {
  if (!req.session.user) {
    return res.status(401).json({ ok: false, message: "Sesion no iniciada." });
  }

  return next();
}

function requireApprovePermission(req, res, next) {
  if (!canApproveWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para aprobar." });
  }
  return next();
}

function requireDeletePermission(req, res, next) {
  if (!canDeleteWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para eliminar." });
  }
  return next();
}

function requireCanonicalSuperAdmin(req, res, next) {
  if (!isCanonicalSuperAdminSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "Solo el usuario superadmin puede eliminar presupuestos." });
  }
  return next();
}

function requireExportPermission(req, res, next) {
  if (!canUseExportsWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para acceder a Exportaciones." });
  }
  return next();
}

function requirePaymentPermission(req, res, next) {
  if (!canRegisterPaymentsWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permiso para registrar pagos." });
  }
  return next();
}

function requireCollectionPermission(req, res, next) {
  if (!canRegisterCollectionsWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permiso para registrar cobros." });
  }
  return next();
}

function requireClientDeletePermission(req, res, next) {
  const role = normalizeAccessRole(req.session.user?.role);
  if (!canDeleteWithSession(req.session.user) && role !== "administracion") {
    return res.status(403).json({ ok: false, message: "No tienes permisos para eliminar contactos." });
  }
  return next();
}

function requirePaymentDocumentDeletePermission(req, res, next) {
  if (!canDeletePaymentDocumentsWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para eliminar documentos de pago." });
  }
  return next();
}

function requireSuperAdmin(req, res, next) {
  const username = String(req.session.user?.username || "").toLowerCase();
  const role = String(req.session.user?.role || "").toLowerCase();

  if (username !== "superadmin" && role !== "superadmin") {
    return res.status(403).json({ ok: false, message: "Solo superadmin puede administrar usuarios." });
  }

  return next();
}

function requireSuperAdminOrAdministration(req, res, next) {
  const username = String(req.session.user?.username || "").toLowerCase();
  const role = String(req.session.user?.role || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  if (username !== "superadmin" && role !== "superadmin" && role !== "administracion") {
    return res.status(403).json({ ok: false, message: "No tienes acceso a usuarios." });
  }

  return next();
}


function normalizeRecoveryFolio(value) {
  const text = String(value || "").toUpperCase();
  const match = text.match(/(?:DLV)?(\d{6})/);
  return match ? `DLV${match[1]}` : text.trim();
}

function extractRecoveryProjectFolio(relativePath) {
  const normalized = sanitizeRelativeUploadPath(relativePath).toUpperCase();
  const parts = normalized.split("/");
  for (const part of parts) {
    const exact = part.match(/^(?:DLV)?(\d{6})$/i);
    if (exact) return `DLV${exact[1]}`;
  }
  const loose = normalized.match(/(?:^|[^A-Z0-9])(?:DLV)?(\d{6})(?=$|[^0-9])/i);
  return loose ? `DLV${loose[1]}` : "";
}

function normalizeRecoveryFileName(value) {
  return path.basename(String(value || "").replace(/\\/g, "/")).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9.]+/g, "").trim();
}

function getRecoveryPathMetadata(relativePath) {
  const cleanPath = sanitizeRelativeUploadPath(relativePath || "");
  const normalized = cleanPath.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const fileName = path.basename(normalized);
  const folder = path.dirname(normalized).replace(/\\/g, "/");
  const extension = path.extname(fileName).replace(".", "");
  const baseName = extension ? fileName.slice(0, -(extension.length + 1)) : fileName;
  return { cleanPath, normalized, fileName, folder, extension, baseName };
}

function getRecoveryPairKey(relativePath) {
  const meta = getRecoveryPathMetadata(relativePath);
  return `${meta.folder}::${meta.baseName}`;
}

function inferRecoveryDocumentType(relativePath, options = {}) {
  const meta = getRecoveryPathMetadata(relativePath);
  const { normalized, fileName, folder, extension } = meta;
  const cadExtensions = new Set(["dwg", "dxf", "catpart", "catproduct", "step", "stp", "igs", "iges", "sldprt", "sldasm"]);
  const imageExtensions = new Set(["jpg", "jpeg", "png", "webp", "gif", "bmp", "tif", "tiff"]);
  const hasXmlPair = Boolean(options.hasXmlPair);
  const inPaymentFolder = /(^|\/)(pago|pagos|payment|payments)(\s|_|-)*[0-9a-z-]*/.test(folder);
  const inOcpFolder = /(^|\/)ocp[0-9][0-9a-z._-]*/.test(folder);

  if (cadExtensions.has(extension)) return { type: "Ingeniería / Diseño", module: "Proyecto" };

  if (/\b(pof|po cliente|purchase order|orden cliente)\b/.test(normalized) || /(^|[/_-])po[f0-9]/.test(fileName)) {
    return { type: "PO cliente recuperada", module: "Presupuesto" };
  }

  if (/^oc[_-]?proveedor/.test(fileName) || /^ocp[0-9].*\.pdf$/.test(fileName)) {
    return { type: "OCP proveedor", module: "Compras" };
  }

  if (extension === "xml") return { type: "Factura XML", module: "Cuentas por cobrar / pagar" };
  if (extension === "pdf" && hasXmlPair) return { type: "Factura PDF", module: "Cuentas por cobrar / pagar" };
  if (/\b(factura|invoice)\b/.test(normalized)) return { type: extension === "xml" ? "Factura XML" : "Factura PDF", module: "Cuentas por cobrar / pagar" };

  if (/\b(gr|goods receipt|recepcion|recepción)\b/.test(normalized)) return { type: "GR / Recepción", module: "Proyecto" };

  if (/\b(pago|comprobante|transferencia|spei)\b/.test(normalized)) {
    return { type: "Comprobante de pago", module: "Cuentas por pagar" };
  }

  if (inPaymentFolder && (imageExtensions.has(extension) || extension === "pdf")) {
    return { type: "Soporte de pago", module: "Cuentas por pagar" };
  }

  if (inOcpFolder) return { type: "Soporte OCP proveedor", module: "Compras" };
  if (/\b(cotizacion|cotización|quote|quotation)\b/.test(normalized)) return { type: "Cotización", module: "Presupuesto" };
  return { type: "Documento proyecto", module: "Proyecto" };
}

async function hashFileSha256(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("error", reject);
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

function assertRecoveryPathInsideRoot(relativePath) {
  const absolutePath = path.resolve(__dirname, relativePath);
  if (!absolutePath.startsWith(DOCUMENT_RECOVERY_UPLOAD_DIR)) {
    const error = new Error("Ruta de recuperación inválida.");
    error.statusCode = 400;
    throw error;
  }
  return absolutePath;
}

async function getRecoveryProjectMap() {
  const [rows] = await pool.execute("SELECT id, folio FROM presupuestos ORDER BY id");
  const map = new Map();
  rows.forEach((row) => {
    const folio = normalizeRecoveryFolio(row.folio);
    if (!folio) return;
    map.set(folio, { id: row.id, folio });
    const digits = folio.match(/(\d{6})/)?.[1];
    if (digits) map.set(digits, { id: row.id, folio });
  });
  return map;
}

function resolveDatabaseUploadPath(ruta = "") {
  const normalized = String(ruta || "").replace(/\\/g, "/").replace(/^\/+/, "").trim();
  if (!normalized || normalized.includes("\0")) return null;
  const uploadsRoot = path.resolve(__dirname, "uploads");
  const absolutePath = path.resolve(__dirname, normalized);
  if (absolutePath !== uploadsRoot && !absolutePath.startsWith(`${uploadsRoot}${path.sep}`)) return null;
  return {
    absolutePath,
    relativePath: path.relative(__dirname, absolutePath).replace(/\\/g, "/")
  };
}

function databaseUploadFileExists(ruta = "") {
  const resolved = resolveDatabaseUploadPath(ruta);
  return Boolean(resolved && fs.existsSync(resolved.absolutePath));
}

async function getExistingDocumentRowsByBudget(executor, projectIds) {
  const uniqueIds = [...new Set(projectIds.map(Number).filter(Boolean))];
  if (!uniqueIds.length) return [];
  const placeholders = uniqueIds.map(() => "?").join(",");
  const params = [
    ...uniqueIds,
    ...uniqueIds,
    ...uniqueIds,
    ...uniqueIds,
    ...uniqueIds,
    ...uniqueIds,
    ...uniqueIds
  ];
  const [rows] = await executor.execute(
    `SELECT 'presupuesto_archivos' AS source_table, id AS source_id, presupuesto_id, nombre, ruta, '' AS sha256
       FROM presupuesto_archivos
      WHERE presupuesto_id IN (${placeholders})
     UNION ALL
     SELECT 'presupuesto_po_cliente' AS source_table, id AS source_id, presupuesto_id, nombre, ruta, '' AS sha256
       FROM presupuesto_po_cliente
      WHERE presupuesto_id IN (${placeholders})
        AND (deleted_at IS NULL OR CAST(deleted_at AS CHAR) = '0000-00-00 00:00:00')
     UNION ALL
     SELECT 'proyecto_archivos' AS source_table, id AS source_id, presupuesto_id, nombre_original AS nombre, ruta, sha256
       FROM proyecto_archivos
      WHERE presupuesto_id IN (${placeholders})
        AND estado = 'Activo'
     UNION ALL
     SELECT 'ocp_proveedor_archivos' AS source_table, id AS source_id, presupuesto_id, nombre, ruta, '' AS sha256
       FROM ocp_proveedor_archivos
      WHERE presupuesto_id IN (${placeholders})
     UNION ALL
     SELECT 'cotizaciones_cliente' AS source_table,
            id AS source_id,
            presupuesto_id,
            CASE
              WHEN TRIM(COALESCE(folio, '')) <> '' THEN CONCAT(folio, '.pdf')
              ELSE SUBSTRING_INDEX(REPLACE(pdf_ruta, '\\\\', '/'), '/', -1)
            END AS nombre,
            pdf_ruta AS ruta,
            '' AS sha256
       FROM cotizaciones_cliente
      WHERE presupuesto_id IN (${placeholders})
        AND TRIM(COALESCE(pdf_ruta, '')) <> ''
     UNION ALL
     SELECT 'cuentas_por_pagar_archivos' AS source_table,
            a.id AS source_id,
            cp.presupuesto_id,
            a.nombre,
            a.ruta,
            '' AS sha256
       FROM cuentas_por_pagar_archivos a
       INNER JOIN cuentas_por_pagar cp ON cp.id = a.cuenta_id
      WHERE cp.presupuesto_id IN (${placeholders})
     UNION ALL
     SELECT 'cuentas_por_cobrar_archivos' AS source_table,
            a.id AS source_id,
            cc.presupuesto_id,
            a.nombre,
            a.ruta,
            '' AS sha256
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar cc ON cc.id = a.cuenta_id
      WHERE cc.presupuesto_id IN (${placeholders})`,
    params
  );
  return rows.map((row) => ({
    ...row,
    presupuesto_id: Number(row.presupuesto_id || 0),
    source_id: Number(row.source_id || 0),
    name_key: normalizeRecoveryFileName(row.nombre || row.ruta),
    path_key: normalizeRecoveryFileName(row.ruta),
    physical_exists: databaseUploadFileExists(row.ruta)
  }));
}

function pushRecoveryIndexEntry(map, key, row) {
  if (!key) return;
  if (!map.has(key)) map.set(key, []);
  map.get(key).push(row);
}

function recoveryRowsHavePhysicalFile(rows = []) {
  return rows.some((row) => row.physical_exists);
}

function recoveryRowsMissingPhysicalFile(rows = []) {
  return rows.some((row) => !row.physical_exists && resolveDatabaseUploadPath(row.ruta));
}

function classifyRecoveryMatch(project, bucket, sha256, nameKey) {
  if (!project) return "Proyecto no encontrado";
  const hashRows = bucket?.hashRows?.get(String(sha256 || "")) || [];
  const nameRows = bucket?.nameRows?.get(nameKey) || [];
  const combinedRows = [...hashRows, ...nameRows].filter((row, index, rows) => (
    rows.findIndex((candidate) => candidate.source_table === row.source_table && candidate.source_id === row.source_id) === index
  ));

  if (combinedRows.length && recoveryRowsMissingPhysicalFile(combinedRows)) {
    return "Registrado en SQL, falta archivo físico";
  }

  if (hashRows.length && recoveryRowsHavePhysicalFile(hashRows)) return "Ya registrado por hash";
  if (nameRows.length && recoveryRowsHavePhysicalFile(nameRows)) return "Ya registrado por nombre";

  return "Falta en SQL";
}

async function getExistingDocumentKeysByBudget(projectIds) {
  const uniqueIds = [...new Set(projectIds.map(Number).filter(Boolean))];
  const result = new Map();
  uniqueIds.forEach((id) => result.set(id, { nameRows: new Map(), hashRows: new Map() }));
  if (!uniqueIds.length) return result;

  const rows = await getExistingDocumentRowsByBudget(pool, uniqueIds);
  rows.forEach((row) => {
    const bucket = result.get(Number(row.presupuesto_id));
    if (!bucket) return;
    pushRecoveryIndexEntry(bucket.nameRows, row.name_key, row);
    pushRecoveryIndexEntry(bucket.nameRows, row.path_key, row);
    if (row.sha256) pushRecoveryIndexEntry(bucket.hashRows, String(row.sha256), row);
  });
  return result;
}

function isMissingPhysicalRecoveryStatus(value = "") {
  return String(value || "").toLowerCase().includes("falta archivo físico");
}

async function findMissingPhysicalSqlReference(connection, item) {
  if (!item?.presupuesto_id) return null;
  const rows = await getExistingDocumentRowsByBudget(connection, [item.presupuesto_id]);
  const itemNameKey = normalizeRecoveryFileName(item.relative_path || item.original_name || "");
  const itemBaseNameKey = normalizeRecoveryFileName(item.original_name || item.relative_path || "");
  const itemSha = String(item.sha256 || "");
  const candidates = rows.filter((row) => {
    if (row.physical_exists) return false;
    if (!resolveDatabaseUploadPath(row.ruta)) return false;
    if (itemSha && row.sha256 && row.sha256 === itemSha) return true;
    return row.name_key === itemNameKey || row.path_key === itemNameKey || row.name_key === itemBaseNameKey || row.path_key === itemBaseNameKey;
  });
  candidates.sort((a, b) => {
    const order = { proyecto_archivos: 0, presupuesto_archivos: 1, presupuesto_po_cliente: 2 };
    return (order[a.source_table] ?? 9) - (order[b.source_table] ?? 9);
  });
  return candidates[0] || null;
}

async function createOrUpdateProjectArchiveForRestoredFile(connection, item, sqlReference, userId) {
  const restoredRuta = resolveDatabaseUploadPath(sqlReference.ruta)?.relativePath || sqlReference.ruta;
  if (sqlReference.source_table === "proyecto_archivos") {
    await connection.execute(
      `UPDATE proyecto_archivos
          SET tipo_documento = ?,
              nombre_original = COALESCE(NULLIF(nombre_original, ''), ?),
              extension = ?,
              tamano_bytes = ?,
              sha256 = ?,
              fuente = 'respaldo_restaurado',
              estado = 'Activo',
              deleted_at = NULL,
              deleted_by = NULL
        WHERE id = ?`,
      [
        item.suggested_type || "Documento proyecto",
        item.original_name || path.basename(item.relative_path || restoredRuta),
        item.extension || path.extname(item.original_name || "").replace(".", "").toLowerCase(),
        Number(item.size_bytes || 0),
        item.sha256 || "",
        sqlReference.source_id
      ]
    );
    return sqlReference.source_id;
  }

  const [existingProjectRows] = await connection.execute(
    `SELECT id
       FROM proyecto_archivos
      WHERE presupuesto_id = ?
        AND ruta = ?
        AND estado = 'Activo'
      ORDER BY id DESC
      LIMIT 1`,
    [item.presupuesto_id, restoredRuta]
  );
  if (existingProjectRows.length) {
    await connection.execute(
      `UPDATE proyecto_archivos
          SET tipo_documento = ?, sha256 = ?, tamano_bytes = ?, fuente = 'respaldo_restaurado'
        WHERE id = ?`,
      [item.suggested_type || "Documento proyecto", item.sha256 || "", Number(item.size_bytes || 0), existingProjectRows[0].id]
    );
    return existingProjectRows[0].id;
  }

  const [archivoResult] = await connection.execute(
    `INSERT INTO proyecto_archivos
      (presupuesto_id, folio_proyecto, modulo_origen, tabla_origen, registro_origen_id, tipo_documento, nombre_original, ruta, extension, tamano_bytes, sha256, fuente, estado, usuario_id)
     VALUES (?, ?, 'recuperacion_documental', ?, ?, ?, ?, ?, ?, ?, ?, 'respaldo_restaurado', 'Activo', ?)`,
    [
      item.presupuesto_id,
      normalizeRecoveryFolio(item.folio_proyecto),
      sqlReference.source_table,
      sqlReference.source_id,
      item.suggested_type || "Documento proyecto",
      item.original_name || path.basename(item.relative_path || restoredRuta),
      restoredRuta,
      item.extension || path.extname(item.original_name || "").replace(".", "").toLowerCase(),
      Number(item.size_bytes || 0),
      item.sha256 || "",
      userId || null
    ]
  );
  return archivoResult.insertId;
}

async function restoreMissingPhysicalDocument(connection, item, sourcePath, userId) {
  const sqlReference = await findMissingPhysicalSqlReference(connection, item);
  if (!sqlReference) {
    const error = new Error("El registro existe en SQL, pero no se encontró una ruta física segura para restaurarlo.");
    error.statusCode = 409;
    throw error;
  }

  const resolved = resolveDatabaseUploadPath(sqlReference.ruta);
  if (!resolved) {
    const error = new Error("La ruta registrada en SQL no apunta a uploads/ y requiere revisión manual.");
    error.statusCode = 409;
    throw error;
  }

  fs.mkdirSync(path.dirname(resolved.absolutePath), { recursive: true });
  fs.copyFileSync(sourcePath, resolved.absolutePath);

  if (sqlReference.source_table === "presupuesto_archivos") {
    await connection.execute("UPDATE presupuesto_archivos SET tipo = ?, nombre = ? WHERE id = ?", [
      item.suggested_type || "Documento restaurado",
      item.original_name || sqlReference.nombre || path.basename(resolved.relativePath),
      sqlReference.source_id
    ]);
  }

  if (sqlReference.source_table === "presupuesto_po_cliente") {
    await connection.execute(
      "UPDATE presupuesto_po_cliente SET nombre = COALESCE(NULLIF(nombre, ''), ?), estado_documento = 'Activo', deleted_at = NULL, deleted_by = NULL WHERE id = ?",
      [item.original_name || sqlReference.nombre || path.basename(resolved.relativePath), sqlReference.source_id]
    );
  }

  const archivoId = await createOrUpdateProjectArchiveForRestoredFile(connection, item, sqlReference, userId);
  return { archivoId, restoredPath: resolved.relativePath, sqlReference };
}

function publicRecoveryItem(row) {
  return {
    id: row.id,
    batchId: row.batch_id,
    budgetId: row.presupuesto_id,
    folio: row.folio_proyecto || "",
    originalName: row.original_name || "",
    relativePath: row.relative_path || "",
    extension: row.extension || "",
    sizeBytes: Number(row.size_bytes || 0),
    suggestedType: row.suggested_type || "Documento proyecto",
    suggestedModule: row.suggested_module || "Proyecto",
    matchStatus: row.match_status || "Pendiente de revisión",
    status: row.status || "Pendiente",
    importedArchivoId: row.imported_archivo_id || null,
    createdAt: row.created_at,
    importedAt: row.imported_at
  };
}

async function getDocumentRecoveryPayload(batchId = 0) {
  const [batches] = await pool.execute(
    `SELECT id, nombre_lote, source_name, total_files, matched_projects, imported_files, status, usuario_id, created_at
     FROM document_recovery_batches
     ORDER BY id DESC
     LIMIT 10`
  );
  const selectedBatchId = Number(batchId || batches[0]?.id || 0);
  let items = [];
  if (selectedBatchId) {
    const [itemRows] = await pool.execute(
      `SELECT *
       FROM document_recovery_items
       WHERE batch_id = ?
       ORDER BY FIELD(match_status, 'Registrado en SQL, falta archivo físico', 'Falta en SQL', 'Proyecto no encontrado', 'Ya registrado por nombre', 'Ya registrado por hash'), folio_proyecto, original_name
       LIMIT 1200`,
      [selectedBatchId]
    );
    items = itemRows.map(publicRecoveryItem);
  }
  return { ok: true, batches, selectedBatchId, items };
}

async function refreshDocumentRecoveryClassification(connection, batchId, userId = null) {
  const [items] = await connection.execute(
    `SELECT *
     FROM document_recovery_items
     WHERE batch_id = ?
     FOR UPDATE`,
    [batchId]
  );
  if (!items.length) return { reclassified: 0, updatedFiles: 0, linkedFiles: 0 };

  const xmlPairKeys = new Set(
    items
      .filter((item) => String(item.extension || path.extname(item.relative_path || '').replace('.', '')).toLowerCase() === 'xml')
      .map((item) => getRecoveryPairKey(item.relative_path || item.original_name || ''))
  );

  let reclassified = 0;
  let updatedFiles = 0;
  let linkedFiles = 0;

  for (const item of items) {
    const relativePath = item.relative_path || item.original_name || '';
    const suggestion = inferRecoveryDocumentType(relativePath, { hasXmlPair: xmlPairKeys.has(getRecoveryPairKey(relativePath)) });
    const existingRows = item.presupuesto_id ? await getExistingDocumentRowsByBudget(connection, [item.presupuesto_id]) : [];
    const currentBucket = { nameRows: new Map(), hashRows: new Map() };
    existingRows.forEach((row) => {
      pushRecoveryIndexEntry(currentBucket.nameRows, row.name_key, row);
      pushRecoveryIndexEntry(currentBucket.nameRows, row.path_key, row);
      if (row.sha256) pushRecoveryIndexEntry(currentBucket.hashRows, String(row.sha256), row);
    });
    const nextMatchStatus = classifyRecoveryMatch(
      item.presupuesto_id ? { id: item.presupuesto_id, folio: item.folio_proyecto } : null,
      currentBucket,
      item.sha256,
      normalizeRecoveryFileName(relativePath)
    );
    const typeChanged = suggestion.type !== item.suggested_type || suggestion.module !== item.suggested_module || nextMatchStatus !== item.match_status;

    let archivoId = Number(item.imported_archivo_id || 0) || null;
    let archivoRuta = '';

    if (!archivoId && item.presupuesto_id && item.sha256) {
      const [matchedFiles] = await connection.execute(
        `SELECT id, ruta
         FROM proyecto_archivos
         WHERE presupuesto_id = ?
           AND sha256 = ?
           AND estado = 'Activo'
         ORDER BY id DESC
         LIMIT 1`,
        [item.presupuesto_id, item.sha256]
      );
      if (matchedFiles.length) {
        archivoId = matchedFiles[0].id;
        archivoRuta = matchedFiles[0].ruta || '';
        linkedFiles += 1;
      }
    }

    if (archivoId && !archivoRuta) {
      const [archivoRows] = await connection.execute(
        `SELECT ruta FROM proyecto_archivos WHERE id = ? LIMIT 1`,
        [archivoId]
      );
      archivoRuta = archivoRows[0]?.ruta || '';
    }

    await connection.execute(
      `UPDATE document_recovery_items
       SET suggested_type = ?,
           suggested_module = ?,
           match_status = ?,
           imported_archivo_id = COALESCE(imported_archivo_id, ?)
       WHERE id = ?`,
      [suggestion.type, suggestion.module, nextMatchStatus, archivoId, item.id]
    );
    if (typeChanged) reclassified += 1;

    if (archivoId) {
      await connection.execute(
        `UPDATE proyecto_archivos
         SET tipo_documento = ?
         WHERE id = ?`,
        [suggestion.type, archivoId]
      );
      if (archivoRuta) {
        await connection.execute(
          `UPDATE presupuesto_archivos
           SET tipo = ?
           WHERE presupuesto_id = ?
             AND ruta = ?`,
          [suggestion.type, item.presupuesto_id, archivoRuta]
        );
      }
      updatedFiles += 1;
    }
  }

  await connection.execute(
    `UPDATE document_recovery_batches
     SET status = 'Reclasificado',
         imported_files = (SELECT COUNT(*) FROM document_recovery_items i WHERE i.batch_id = document_recovery_batches.id AND i.status = 'Importado')
     WHERE id = ?`,
    [batchId]
  );

  return { reclassified, updatedFiles, linkedFiles };
}

app.get("/api/document-recovery", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  try {
    res.json(await getDocumentRecoveryPayload(Number(req.query.batchId || 0)));
  } catch (error) {
    logServerError("document-recovery-list", error);
    res.status(500).json({ ok: false, message: "No se pudo cargar la conciliación documental." });
  }
});

app.post("/api/document-recovery/reclassify", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const batchId = Number(req.body.batchId || 0);
  if (!batchId) return res.status(400).json({ ok: false, message: "Selecciona un análisis para actualizar la clasificación." });

  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();
    const result = await refreshDocumentRecoveryClassification(connection, batchId, req.session.user?.id || null);
    await connection.commit();
    res.json({ ok: true, ...result, ...(await getDocumentRecoveryPayload(batchId)) });
  } catch (error) {
    await connection.rollback();
    logServerError("document-recovery-reclassify", error);
    res.status(error.statusCode || 500).json({ ok: false, message: error.message || "No se pudo actualizar la clasificación documental." });
  } finally {
    connection.release();
  }
});

app.post(
  "/api/document-recovery/analyze",
  requireAuth,
  requireSuperAdminOrAdministration,
  uploadDocumentRecoveryFiles.array("files", 3000),
  async (req, res) => {
    const uploadedFiles = Array.isArray(req.files) ? req.files : [];
    if (!uploadedFiles.length) return res.status(400).json({ ok: false, message: "Selecciona una carpeta o archivos para analizar." });

    try {
      const projectMap = await getRecoveryProjectMap();
      const uploadedEntries = uploadedFiles.map((file) => {
        const relativePath = sanitizeRelativeUploadPath(file.originalname || file.filename || file.originalname);
        return { file, relativePath, meta: getRecoveryPathMetadata(relativePath) };
      });
      const xmlPairKeys = new Set(uploadedEntries.filter((entry) => entry.meta.extension === "xml").map((entry) => getRecoveryPairKey(entry.relativePath)));
      const stagedItems = [];
      for (const entry of uploadedEntries) {
        const { file, relativePath } = entry;
        const folio = extractRecoveryProjectFolio(relativePath);
        const project = projectMap.get(folio) || projectMap.get(folio.replace(/^DLV/, "")) || null;
        const sha256 = await hashFileSha256(file.path);
        const suggestion = inferRecoveryDocumentType(relativePath, { hasXmlPair: xmlPairKeys.has(getRecoveryPairKey(relativePath)) });
        stagedItems.push({ file, relativePath, folio, project, sha256, suggestion });
      }

    const existingKeys = await getExistingDocumentKeysByBudget(stagedItems.map((item) => item.project?.id));
    const connection = await pool.getConnection();
    try {
      await connection.beginTransaction();
      const [batchResult] = await connection.execute(
        `INSERT INTO document_recovery_batches (nombre_lote, source_name, total_files, matched_projects, usuario_id)
         VALUES (?, ?, ?, ?, ?)`,
        [
          String(req.body.nombreLote || "Respaldo documental").trim() || "Respaldo documental",
          String(req.body.sourceName || "Carpeta subida desde navegador").trim() || "Carpeta subida desde navegador",
          stagedItems.length,
          new Set(stagedItems.map((item) => item.project?.id).filter(Boolean)).size,
          req.session.user?.id || null
        ]
      );
      const batchId = batchResult.insertId;
      for (const item of stagedItems) {
        const bucket = item.project ? existingKeys.get(Number(item.project.id)) : null;
        const nameKey = normalizeRecoveryFileName(item.relativePath);
        const matchStatus = classifyRecoveryMatch(item.project, bucket, item.sha256, nameKey);
        const stagedPath = path.relative(__dirname, item.file.path).replace(/\\/g, "/");
        await connection.execute(
          `INSERT INTO document_recovery_items
            (batch_id, presupuesto_id, folio_proyecto, original_name, relative_path, staged_path, extension, size_bytes, sha256, suggested_type, suggested_module, match_status, status)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'Pendiente')`,
          [
            batchId,
            item.project?.id || null,
            item.project?.folio || item.folio || "",
            path.basename(item.relativePath),
            item.relativePath,
            stagedPath,
            path.extname(item.relativePath).replace(".", "").toLowerCase(),
            Number(item.file.size || 0),
            item.sha256,
            item.suggestion.type,
            item.suggestion.module,
            matchStatus
          ]
        );
      }
      await connection.commit();
      res.status(201).json(await getDocumentRecoveryPayload(batchId));
    } catch (error) {
      await connection.rollback();
      uploadedFiles.forEach((file) => fs.promises.unlink(file.path).catch(() => {}));
      throw error;
    } finally {
      connection.release();
    }
    } catch (error) {
      uploadedFiles.forEach((file) => fs.promises.unlink(file.path).catch(() => {}));
      logServerError("document-recovery-analyze", error);
      res.status(error.statusCode || 500).json({ ok: false, message: error.message || "No se pudo analizar el respaldo." });
    }
  }
);

app.post("/api/document-recovery/import", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const itemIds = Array.isArray(req.body.itemIds) ? req.body.itemIds.map(Number).filter(Boolean) : [];
  if (!itemIds.length) return res.status(400).json({ ok: false, message: "Selecciona al menos un archivo pendiente." });
  const placeholders = itemIds.map(() => "?").join(",");
  const connection = await pool.getConnection();
  let imported = 0;
  let skipped = 0;
  try {
    await connection.beginTransaction();
    const [items] = await connection.execute(
      `SELECT * FROM document_recovery_items WHERE id IN (${placeholders}) FOR UPDATE`,
      itemIds
    );
    for (const item of items) {
      if (item.status === "Importado") {
        skipped += 1;
        continue;
      }
      if (!item.presupuesto_id || !item.folio_proyecto) {
        await connection.execute("UPDATE document_recovery_items SET status = 'Requiere revisión' WHERE id = ?", [item.id]);
        skipped += 1;
        continue;
      }
      const sourcePath = assertRecoveryPathInsideRoot(item.staged_path);
      if (!fs.existsSync(sourcePath)) {
        await connection.execute("UPDATE document_recovery_items SET status = 'Archivo no encontrado' WHERE id = ?", [item.id]);
        skipped += 1;
        continue;
      }

      if (isMissingPhysicalRecoveryStatus(item.match_status)) {
        try {
          const restored = await restoreMissingPhysicalDocument(connection, item, sourcePath, req.session.user?.id || null);
          await connection.execute(
            `UPDATE document_recovery_items
             SET status = 'Restaurado', imported_archivo_id = ?, imported_at = NOW(), imported_by = ?
             WHERE id = ?`,
            [restored.archivoId, req.session.user?.id || null, item.id]
          );
          await touchBudgetUpdatedAt(item.presupuesto_id, connection);
          imported += 1;
          continue;
        } catch (restoreError) {
          await connection.execute("UPDATE document_recovery_items SET status = 'Requiere revisión' WHERE id = ?", [item.id]);
          skipped += 1;
          continue;
        }
      }

      if (item.match_status !== "Falta en SQL") {
        await connection.execute("UPDATE document_recovery_items SET status = 'Duplicado' WHERE id = ?", [item.id]);
        skipped += 1;
        continue;
      }

      const [duplicateRows] = await connection.execute(
        "SELECT id, ruta FROM proyecto_archivos WHERE presupuesto_id = ? AND sha256 = ? AND estado = 'Activo' LIMIT 1",
        [item.presupuesto_id, item.sha256]
      );
      if (duplicateRows.length && databaseUploadFileExists(duplicateRows[0].ruta)) {
        await connection.execute(
          "UPDATE document_recovery_items SET status = 'Duplicado', imported_archivo_id = ? WHERE id = ?",
          [duplicateRows[0].id, item.id]
        );
        skipped += 1;
        continue;
      }
      const projectFolder = path.join(__dirname, "uploads", normalizeRecoveryFolio(item.folio_proyecto), "recuperados");
      fs.mkdirSync(projectFolder, { recursive: true });
      const safeBase = path.basename(item.original_name || item.relative_path || "archivo").replace(/[^a-zA-Z0-9._-]/g, "_");
      const finalName = `${Date.now()}-${crypto.randomBytes(5).toString("hex")}-${safeBase}`;
      const finalPath = path.join(projectFolder, finalName);
      fs.copyFileSync(sourcePath, finalPath);
      const relativeFinalPath = path.relative(__dirname, finalPath).replace(/\\/g, "/");
      const [archivoResult] = await connection.execute(
        `INSERT INTO proyecto_archivos
          (presupuesto_id, folio_proyecto, modulo_origen, tabla_origen, tipo_documento, nombre_original, ruta, extension, tamano_bytes, sha256, fuente, estado, usuario_id)
         VALUES (?, ?, 'recuperacion_documental', 'document_recovery_items', ?, ?, ?, ?, ?, ?, 'respaldo', 'Activo', ?)`,
        [
          item.presupuesto_id,
          normalizeRecoveryFolio(item.folio_proyecto),
          item.suggested_type || "Documento proyecto",
          item.original_name || path.basename(item.relative_path),
          relativeFinalPath,
          item.extension || path.extname(item.original_name || "").replace(".", "").toLowerCase(),
          Number(item.size_bytes || 0),
          item.sha256 || "",
          req.session.user?.id || null
        ]
      );
      await connection.execute(
        `INSERT INTO presupuesto_archivos (presupuesto_id, tipo, nombre, ruta, usuario_id)
         VALUES (?, ?, ?, ?, ?)`,
        [item.presupuesto_id, item.suggested_type || "Documento recuperado", item.original_name || path.basename(item.relative_path), relativeFinalPath, req.session.user?.id || null]
      );
      await connection.execute(
        `UPDATE document_recovery_items
         SET status = 'Importado', imported_archivo_id = ?, imported_at = NOW(), imported_by = ?
         WHERE id = ?`,
        [archivoResult.insertId, req.session.user?.id || null, item.id]
      );
      await touchBudgetUpdatedAt(item.presupuesto_id, connection);
      imported += 1;
    }
    const affectedBatchIds = [...new Set(items.map((item) => Number(item.batch_id)).filter(Boolean))];
    for (const batchId of affectedBatchIds) {
      await connection.execute(
        `UPDATE document_recovery_batches b
         SET imported_files = (SELECT COUNT(*) FROM document_recovery_items i WHERE i.batch_id = b.id AND i.status = 'Importado'),
             status = 'Parcial / importado'
         WHERE b.id = ?`,
        [batchId]
      );
    }
    await connection.commit();
    res.json({ ok: true, imported, skipped, ...(await getDocumentRecoveryPayload(Number(items[0]?.batch_id || 0))) });
  } catch (error) {
    await connection.rollback();
    logServerError("document-recovery-import", error);
    res.status(error.statusCode || 500).json({ ok: false, message: error.message || "No se pudieron importar los archivos." });
  } finally {
    connection.release();
  }
});

function normalizeAccessRole(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function shouldRestrictToOwnedBudgets(user = {}) {
  const safeUser = user || {};
  const username = String(safeUser.username || "").toLowerCase();
  const role = normalizeAccessRole(safeUser.role);
  return username !== "superadmin" && role === "supervisor";
}

function canManageCommissions(user = {}) {
  const username = String(user.username || "").toLowerCase();
  const role = normalizeAccessRole(user.role);
  return (
    username === "superadmin" ||
    role === "superadmin" ||
    sessionHasSpecialPermission(user, "modulo:comisiones") ||
    sessionHasSpecialPermission(user, "accion:generar-comisiones")
  );
}

function canApproveCommissions(user = {}) {
  return canApproveWithSession(user);
}

function canManageClientPo(user = {}) {
  const username = String(user.username || "").toLowerCase();
  const role = normalizeAccessRole(user.role);
  return username === "superadmin" || role === "superadmin" || role === "administracion" || role === "compras";
}

async function requireClientPoManager(req, res, next) {
  if (canManageClientPo(req.session.user || {})) return next();
  try {
    const budgetId = Number(req.params.id || 0);
    if (!budgetId) {
      return res.status(403).json({ ok: false, message: "No tienes acceso para administrar la PO del cliente." });
    }
    const isBilling = String(req.path || req.originalUrl || "").includes("/bill");
    const isDelete = String(req.method || "").toUpperCase() === "DELETE";
    const modulePermission = isBilling ? "modulo:cuentas-cobrar" : "modulo:presupuesto";
    const operationPermission = isBilling
      ? "accion:facturar"
      : isDelete
        ? "accion:eliminar-archivos"
        : "accion:subir-archivos";
    if (await canAccessBudget(req.session.user, budgetId, modulePermission, operationPermission)) return next();
    return res.status(403).json({ ok: false, message: "No tienes acceso para administrar la PO del cliente." });
  } catch (error) {
    logServerError("client-po-manager-access", error);
    return res.status(500).json({ ok: false, message: "No se pudo validar el permiso de la sucursal." });
  }
}

function appendBudgetOwnerCondition(conditions, values, user, alias = "p", modulePermission = "modulo:presupuesto") {
  if (!shouldRestrictToOwnedBudgets(user)) return;
  const userId = Number(user?.id || 0);
  const branchIds = getSessionBranchAccessIds(user, modulePermission);
  const accessParts = [];
  if (userId) {
    accessParts.push(`${alias}.usuario_id = ?`);
    values.push(userId);
  }
  if (branchIds.length) {
    accessParts.push(`${alias}.sucursal_id IN (${branchIds.map(() => "?").join(",")})`);
    values.push(...branchIds);
  }
  conditions.push(accessParts.length ? `(${accessParts.join(" OR ")})` : "1 = 0");
}

function getRequestOperationPermission(req = {}) {
  const method = String(req.method || "GET").toUpperCase();
  if (["GET", "HEAD", "OPTIONS"].includes(method)) return "";
  if (method === "DELETE") return "botones:eliminar";
  if (["POST", "PUT", "PATCH"].includes(method)) return "accion:editar";
  return "";
}

async function getBudgetAccessRow(budgetId, connection = pool) {
  const numericBudgetId = Number(budgetId || 0);
  if (!numericBudgetId) return null;
  const [rows] = await connection.execute(
    `SELECT id, usuario_id, sucursal_id
     FROM presupuestos
     WHERE id = ?
     LIMIT 1`,
    [numericBudgetId]
  );
  return rows[0] || null;
}

async function canAccessBudget(
  user,
  budgetId,
  modulePermission = "modulo:presupuesto",
  operationPermission = ""
) {
  if (!shouldRestrictToOwnedBudgets(user)) return true;
  const row = await getBudgetAccessRow(budgetId);
  if (!row) return false;
  const userId = Number(user?.id || 0);
  if (userId && Number(row.usuario_id || 0) === userId) return true;
  const branchId = Number(row.sucursal_id || 0);
  if (!sessionHasBranchPermission(user, branchId, modulePermission)) return false;
  if (operationPermission && !sessionHasBranchPermission(user, branchId, operationPermission)) return false;
  return true;
}

async function requireBudgetAccess(req, res, next) {
  const budgetId = Number(req.params.id);
  if (!budgetId) return next();
  try {
    const requestPath = String(req.originalUrl || req.path || "").toLowerCase();
    let modulePermission = "modulo:presupuesto";
    let operationPermission = getRequestOperationPermission(req);
    if (requestPath.includes("supplier-order")) modulePermission = "modulo:compras";
    if (requestPath.includes("/bill")) {
      modulePermission = "modulo:cuentas-cobrar";
      operationPermission = "accion:facturar";
    } else if (requestPath.includes("/files") && String(req.method || "").toUpperCase() === "POST") {
      operationPermission = "accion:subir-archivos";
    }
    if (!(await canAccessBudget(
      req.session.user,
      budgetId,
      modulePermission,
      operationPermission
    ))) {
      return res.status(403).json({ ok: false, message: "No tienes acceso a este presupuesto o a esta operación." });
    }
    return next();
  } catch (error) {
    logServerError("budget-access", error);
    return res.status(500).json({ ok: false, message: "No se pudo validar el acceso al presupuesto." });
  }
}

async function getClientQuoteAccessRow(quoteId, connection = pool) {
  const numericQuoteId = Number(quoteId || 0);
  if (!numericQuoteId) return null;
  const [rows] = await connection.execute(
    `SELECT q.id, p.id AS presupuesto_id, p.usuario_id, p.sucursal_id
     FROM cotizaciones_cliente q
     INNER JOIN presupuestos p ON p.id = q.presupuesto_id
     WHERE q.id = ?
     LIMIT 1`,
    [numericQuoteId]
  );
  return rows[0] || null;
}

async function canAccessClientQuote(
  user,
  quoteId,
  modulePermission = "modulo:presupuesto",
  operationPermission = ""
) {
  if (!shouldRestrictToOwnedBudgets(user)) return true;
  const row = await getClientQuoteAccessRow(quoteId);
  if (!row) return false;
  const userId = Number(user?.id || 0);
  if (userId && Number(row.usuario_id || 0) === userId) return true;
  const branchId = Number(row.sucursal_id || 0);
  if (!sessionHasBranchPermission(user, branchId, modulePermission)) return false;
  if (operationPermission && !sessionHasBranchPermission(user, branchId, operationPermission)) return false;
  return true;
}

async function requireClientQuoteAccess(req, res, next) {
  const quoteId = Number(req.params.quoteId);
  if (!quoteId) return next();
  try {
    if (!(await canAccessClientQuote(
      req.session.user,
      quoteId,
      "modulo:presupuesto",
      getRequestOperationPermission(req)
    ))) {
      return res.status(403).json({ ok: false, message: "No tienes acceso a esta cotización o a esta operación." });
    }
    return next();
  } catch (error) {
    logServerError("client-quote-access", error);
    return res.status(500).json({ ok: false, message: "No se pudo validar el acceso a la cotización." });
  }
}

function displayRoleName(roleName) {
  const normalized = String(roleName || "").toLowerCase();
  const labels = {
    administracion: "Administración",
    compras: "Compras",
    supervisor: "Supervisor",
    superadmin: "Superadmin"
  };

  return labels[normalized] || roleName;
}

function displayPermissionName(permissionName) {
  const modulePermission = USER_MODULE_PERMISSION_CATALOG.find(([name]) => name === permissionName);
  if (modulePermission) return modulePermission[1];
  const operationPermission = USER_OPERATION_PERMISSION_CATALOG.find(([name]) => name === permissionName);
  if (operationPermission) return operationPermission[1];
  const labels = {
    "botones:aprobar": "Mostrar y permitir botones de aprobar",
    "botones:eliminar": "Mostrar y permitir botones de eliminar"
  };

  return labels[permissionName] || permissionName;
}

async function getUserModuleCatalogs() {
  const [roleRows] = await pool.execute(
    `SELECT id, nombre
     FROM roles
     WHERE LOWER(nombre) IN (${USER_MODULE_ROLES.map(() => "?").join(", ")})
     ORDER BY FIELD(LOWER(nombre), ${USER_MODULE_ROLES.map(() => "?").join(", ")})`,
    [...USER_MODULE_ROLES, ...USER_MODULE_ROLES]
  );

  const permissionNames = [
    ...USER_MODULE_PERMISSION_CATALOG.map(([name]) => name),
    ...USER_OPERATION_PERMISSION_CATALOG.map(([name]) => name)
  ];
  const [permissionRows] = await pool.execute(
    `SELECT id, nombre
     FROM permisos
     WHERE nombre IN (${permissionNames.map(() => "?").join(", ")})
     ORDER BY FIELD(nombre, ${permissionNames.map(() => "?").join(", ")})`,
    [...permissionNames, ...permissionNames]
  );
  const permissionByName = Object.fromEntries(permissionRows.map((permission) => [permission.nombre, permission.id]));
  const mapPermissionCatalog = (catalog) =>
    catalog
      .map(([nombre, label]) => ({
        id: permissionByName[nombre],
        nombre,
        label
      }))
      .filter((permission) => permission.id);

  let branchScopes = [];
  try {
    branchScopes = (await getClientBranchLocations("", { includeInactive: false })).map((branch) => ({
      id: Number(branch.id),
      empresa: branch.empresa || "",
      sucursal: branch.nombre || "",
      label: [branch.empresa, branch.nombre].filter(Boolean).join(" · ")
    }));
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }

  return {
    roles: roleRows.map((role) => ({
      id: role.id,
      nombre: role.nombre,
      label: displayRoleName(role.nombre)
    })),
    branchScopes,
    modulePermissions: mapPermissionCatalog(USER_MODULE_PERMISSION_CATALOG),
    operationPermissions: mapPermissionCatalog(USER_OPERATION_PERMISSION_CATALOG),
    branchModulePermissions: mapPermissionCatalog(
      USER_MODULE_PERMISSION_CATALOG.filter(([name]) => BRANCH_SCOPED_MODULE_PERMISSION_NAMES.includes(name))
    ),
    branchOperationPermissions: mapPermissionCatalog(
      USER_OPERATION_PERMISSION_CATALOG.filter(([name]) => BRANCH_SCOPED_OPERATION_PERMISSION_NAMES.includes(name))
    ),
    roleDefaults: Object.fromEntries(Object.entries(DEFAULT_ROLE_PERMISSIONS).map(([role, permissions]) => [role, permissions])),
    specialPermissions: permissionRows.map((permission) => ({
      id: permission.id,
      nombre: permission.nombre,
      label: displayPermissionName(permission.nombre)
    }))
  };
}

async function getRoleNameById(roleId) {
  const [rows] = await pool.execute("SELECT nombre FROM roles WHERE id = ? LIMIT 1", [roleId]);
  return rows[0]?.nombre || "";
}

async function getUsers(search = "") {
  const values = [];
  let where = "";

  if (search) {
    const terms = getServerSearchTerms(search);
    if (terms.length) {
      where = `WHERE ${terms
        .map(() => "(CONCAT_WS(' ', u.nombre, u.apellido, u.usuario, r.nombre) LIKE ?)")
        .join(" AND ")}`;
      values.push(...terms.map((term) => `%${term}%`));
    }
  }

  const [rows] = await pool.execute(
    `SELECT
        u.user_id,
        u.nombre,
        u.apellido,
        u.usuario,
        u.rol_id,
        u.comision_supervisor,
        u.banco,
        u.cuenta,
        u.clabe,
        u.activo,
        r.nombre AS rol_nombre,
        (SELECT COUNT(*) FROM presupuestos p_owner WHERE p_owner.usuario_id = u.user_id) AS proyectos_count,
        GROUP_CONCAT(DISTINCT up.permiso_id ORDER BY up.permiso_id SEPARATOR ',') AS permisos_especiales_ids,
        GROUP_CONCAT(DISTINCT p.nombre ORDER BY p.nombre SEPARATOR ',') AS permisos_especiales,
        GROUP_CONCAT(DISTINCT rt.rol_id ORDER BY rt.rol_id SEPARATOR ',') AS roles_temporales_ids,
        GROUP_CONCAT(DISTINCT tr.nombre ORDER BY tr.nombre SEPARATOR ',') AS roles_temporales
      FROM usuarios u
      LEFT JOIN roles r ON r.id = u.rol_id
      LEFT JOIN usuarios_permisos up ON up.usuario_id = u.user_id
      LEFT JOIN permisos p ON p.id = up.permiso_id
      LEFT JOIN usuarios_roles_temporales rt ON rt.usuario_id = u.user_id
      LEFT JOIN roles tr ON tr.id = rt.rol_id
      ${where}
      GROUP BY u.user_id, u.nombre, u.apellido, u.usuario, u.rol_id, u.comision_supervisor, u.banco, u.cuenta, u.clabe, u.activo, r.nombre
      ORDER BY u.activo DESC, u.user_id DESC
      LIMIT 100`,
    values
  );

  const userIds = rows.map((row) => Number(row.user_id || 0)).filter(Boolean);
  const scopesByUser = new Map();
  if (userIds.length) {
    const [scopeRows] = await pool.execute(
      `SELECT
          us.usuario_id,
          us.sucursal_id,
          cs.empresa,
          COALESCE(NULLIF(cu.nombre, ''), cs.nombre) AS sucursal,
          usp.permiso_id,
          p.nombre AS permiso
       FROM usuarios_sucursales us
       INNER JOIN cliente_sucursales cs ON cs.id = us.sucursal_id
       LEFT JOIN catalogo_ubicaciones cu ON cu.id = cs.ubicacion_id
       LEFT JOIN usuarios_sucursales_permisos usp
         ON usp.usuario_id = us.usuario_id AND usp.sucursal_id = us.sucursal_id
       LEFT JOIN permisos p ON p.id = usp.permiso_id
       WHERE us.usuario_id IN (${userIds.map(() => "?").join(",")})
       ORDER BY us.usuario_id, cs.empresa, COALESCE(NULLIF(cu.nombre, ''), cs.nombre), p.nombre`,
      userIds
    );
    for (const scopeRow of scopeRows) {
      const userId = Number(scopeRow.usuario_id || 0);
      const branchId = Number(scopeRow.sucursal_id || 0);
      if (!userId || !branchId) continue;
      if (!scopesByUser.has(userId)) scopesByUser.set(userId, new Map());
      const branchMap = scopesByUser.get(userId);
      if (!branchMap.has(branchId)) {
        branchMap.set(branchId, {
          sucursalId: branchId,
          empresa: scopeRow.empresa || "",
          sucursal: scopeRow.sucursal || "",
          label: [scopeRow.empresa, scopeRow.sucursal].filter(Boolean).join(" · "),
          permisosIds: [],
          permisos: []
        });
      }
      const scope = branchMap.get(branchId);
      const permissionId = Number(scopeRow.permiso_id || 0);
      if (permissionId && scopeRow.permiso && BRANCH_SCOPED_PERMISSION_NAMES.has(scopeRow.permiso)) {
        scope.permisosIds.push(permissionId);
        scope.permisos.push(scopeRow.permiso);
      }
    }
  }

  return rows.map((row) => {
    const scopes = [...(scopesByUser.get(Number(row.user_id))?.values() || [])]
      .map((scope) => ({
        ...scope,
        permisosIds: [...new Set(scope.permisosIds)],
        permisos: [...new Set(scope.permisos)]
      }))
      .filter((scope) => scope.permisos.some((permission) => permission.startsWith("modulo:")));
    return {
      id: row.user_id,
      nombre: row.nombre || "",
      apellido: row.apellido || "",
      usuario: row.usuario,
      rolId: row.rol_id,
      rol: displayRoleName(row.rol_nombre || ""),
      comisionSupervisor: Number(row.comision_supervisor || 0),
      banco: row.banco || "",
      cuenta: row.cuenta || "",
      clabe: row.clabe || "",
      activo: Boolean(row.activo),
      proyectosCount: Number(row.proyectos_count || 0),
      permisosEspecialesIds: row.permisos_especiales_ids
        ? row.permisos_especiales_ids.split(",").map((id) => Number(id))
        : [],
      permisosEspeciales: row.permisos_especiales ? row.permisos_especiales.split(",") : [],
      rolesTemporalesIds: row.roles_temporales_ids
        ? row.roles_temporales_ids.split(",").map((id) => Number(id))
        : [],
      rolesTemporales: row.roles_temporales
        ? row.roles_temporales.split(",").map((role) => displayRoleName(role))
        : [],
      alcancesSucursal: scopes,
      sucursalesAccesoIds: scopes.map((scope) => scope.sucursalId),
      sucursalesAcceso: scopes.map((scope) => scope.label),
      alcancesSucursalResumen: scopes.map((scope) =>
        `${scope.label}: ${scope.permisos.filter((permission) => permission.startsWith("modulo:")).map(displayPermissionName).join(", ")}`
      )
    };
  });
}


async function getUserCreditsOverview(search = "", status = "active", options = {}) {
  const conditions = [];
  const values = [];
  if (search) {
    const term = `%${search}%`;
    conditions.push("(u.nombre LIKE ? OR u.apellido LIKE ? OR u.usuario LIKE ? OR c.concepto LIKE ? OR c.notas LIKE ?)");
    values.push(term, term, term, term, term);
  }
  if (status === "active") conditions.push("c.saldo_pendiente > 0 AND c.estado = 'ACTIVO'");
  if (status === "paid") conditions.push("(c.saldo_pendiente = 0 OR c.estado = 'LIQUIDADO')");
  const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";

  const rowLimit = Math.min(5000, Math.max(1, Number(options.limit || 300)));

  const [creditRows] = await pool.execute(
    `SELECT
       c.id,
       c.usuario_id,
       c.tipo,
       c.monto_original,
       c.saldo_pendiente,
       c.concepto,
       c.notas,
       c.fecha_otorgamiento,
       c.estado,
       c.created_at,
       c.updated_at,
       CONCAT_WS(' ', u.nombre, u.apellido) AS usuario_nombre,
       u.usuario,
       CONCAT_WS(' ', creador.nombre, creador.apellido) AS creado_por
     FROM usuarios_creditos c
     INNER JOIN usuarios u ON u.user_id = c.usuario_id
     LEFT JOIN usuarios creador ON creador.user_id = c.usuario_registro_id
     ${where}
     ORDER BY c.saldo_pendiente > 0 DESC, c.fecha_otorgamiento DESC, c.id DESC
     LIMIT ${rowLimit}`,
    values
  );

  const [summaryRows] = await pool.execute(
    `SELECT
       COALESCE(SUM(monto_original), 0) AS monto_original,
       COALESCE(SUM(saldo_pendiente), 0) AS saldo_pendiente,
       COALESCE(SUM(monto_original - saldo_pendiente), 0) AS total_recuperado,
       COUNT(DISTINCT CASE WHEN saldo_pendiente > 0 AND estado = 'ACTIVO' THEN usuario_id END) AS personas_con_saldo,
       SUM(CASE WHEN saldo_pendiente > 0 AND estado = 'ACTIVO' THEN 1 ELSE 0 END) AS creditos_activos
     FROM usuarios_creditos`
  );

  const [userRows] = await pool.execute(
    `SELECT
       u.user_id AS id,
       u.nombre,
       u.apellido,
       u.usuario,
       COALESCE(SUM(c.saldo_pendiente), 0) AS saldo_adeudo_total
     FROM usuarios u
     LEFT JOIN usuarios_creditos c ON c.usuario_id = u.user_id
     WHERE u.activo = 1
     GROUP BY u.user_id, u.nombre, u.apellido, u.usuario
     ORDER BY u.nombre, u.apellido, u.usuario`
  );

  const summary = summaryRows[0] || {};
  return {
    summary: {
      montoOriginal: Number(summary.monto_original || 0),
      saldoPendiente: Number(summary.saldo_pendiente || 0),
      totalRecuperado: Number(summary.total_recuperado || 0),
      personasConSaldo: Number(summary.personas_con_saldo || 0),
      creditosActivos: Number(summary.creditos_activos || 0)
    },
    users: userRows.map((row) => ({
      id: Number(row.id),
      nombre: row.nombre || "",
      apellido: row.apellido || "",
      usuario: row.usuario || "",
      saldoAdeudoTotal: Number(row.saldo_adeudo_total || 0)
    })),
    credits: creditRows.map((row) => ({
      id: Number(row.id),
      usuarioId: Number(row.usuario_id),
      usuarioNombre: String(row.usuario_nombre || row.usuario || "").trim(),
      usuario: row.usuario || "",
      tipo: row.tipo || "PRESTAMO",
      montoOriginal: Number(row.monto_original || 0),
      saldoPendiente: Number(row.saldo_pendiente || 0),
      totalRecuperado: roundMoneyServer(Number(row.monto_original || 0) - Number(row.saldo_pendiente || 0)),
      concepto: row.concepto || "",
      notas: row.notas || "",
      fechaOtorgamiento: row.fecha_otorgamiento,
      estado: row.estado || "ACTIVO",
      creadoPor: String(row.creado_por || "Sistema").trim(),
      createdAt: row.created_at,
      updatedAt: row.updated_at
    }))
  };
}

async function getUserCreditDetail(userId) {
  const [userRows] = await pool.execute(
    `SELECT user_id, nombre, apellido, usuario
     FROM usuarios
     WHERE user_id = ?
     LIMIT 1`,
    [userId]
  );
  if (!userRows.length) return null;

  const [creditRows] = await pool.execute(
    `SELECT c.*, CONCAT_WS(' ', creador.nombre, creador.apellido) AS creado_por
     FROM usuarios_creditos c
     LEFT JOIN usuarios creador ON creador.user_id = c.usuario_registro_id
     WHERE c.usuario_id = ?
     ORDER BY c.fecha_otorgamiento DESC, c.id DESC`,
    [userId]
  );

  const [movementRows] = await pool.execute(
    `SELECT
       m.*,
       c.concepto AS credito_concepto,
       c.tipo AS credito_tipo,
       CONCAT_WS(' ', registrador.nombre, registrador.apellido) AS registrado_por
     FROM usuarios_creditos_movimientos m
     INNER JOIN usuarios_creditos c ON c.id = m.credito_id
     LEFT JOIN usuarios registrador ON registrador.user_id = m.usuario_registro_id
     WHERE m.usuario_id = ?
     ORDER BY m.created_at DESC, m.id DESC
     LIMIT 500`,
    [userId]
  );

  const montoOriginal = creditRows.reduce((sum, row) => sum + Number(row.monto_original || 0), 0);
  const saldoPendiente = creditRows.reduce((sum, row) => sum + Number(row.saldo_pendiente || 0), 0);
  const user = userRows[0];

  return {
    user: {
      id: Number(user.user_id),
      nombre: user.nombre || "",
      apellido: user.apellido || "",
      usuario: user.usuario || ""
    },
    summary: {
      montoOriginal: roundMoneyServer(montoOriginal),
      saldoPendiente: roundMoneyServer(saldoPendiente),
      totalRecuperado: roundMoneyServer(montoOriginal - saldoPendiente),
      creditosActivos: creditRows.filter((row) => Number(row.saldo_pendiente || 0) > 0).length
    },
    credits: creditRows.map((row) => ({
      id: Number(row.id),
      usuarioId: Number(row.usuario_id),
      tipo: row.tipo || "PRESTAMO",
      montoOriginal: Number(row.monto_original || 0),
      saldoPendiente: Number(row.saldo_pendiente || 0),
      totalRecuperado: roundMoneyServer(Number(row.monto_original || 0) - Number(row.saldo_pendiente || 0)),
      concepto: row.concepto || "",
      notas: row.notas || "",
      fechaOtorgamiento: row.fecha_otorgamiento,
      estado: row.estado || "ACTIVO",
      creadoPor: String(row.creado_por || "Sistema").trim(),
      createdAt: row.created_at,
      updatedAt: row.updated_at
    })),
    movements: movementRows.map((row) => ({
      id: Number(row.id),
      creditoId: Number(row.credito_id),
      tipo: row.tipo || "",
      monto: Number(row.monto || 0),
      saldoAnterior: Number(row.saldo_anterior || 0),
      saldoPosterior: Number(row.saldo_posterior || 0),
      origenTipo: row.origen_tipo || "",
      origenId: row.origen_id ? Number(row.origen_id) : null,
      referencia: row.referencia || "",
      detalle: row.detalle || "",
      creditoConcepto: row.credito_concepto || "",
      creditoTipo: row.credito_tipo || "",
      registradoPor: String(row.registrado_por || "Sistema").trim(),
      createdAt: row.created_at
    }))
  };
}

async function getUserCreditOutstandingBalance(userId, executor = pool) {
  const numericUserId = Number(userId || 0);
  if (!numericUserId) return 0;
  const [rows] = await executor.execute(
    `SELECT COALESCE(SUM(saldo_pendiente), 0) AS saldo
       FROM usuarios_creditos
      WHERE usuario_id = ?
        AND saldo_pendiente > 0
        AND estado = 'ACTIVO'`,
    [numericUserId]
  );
  return roundMoneyServer(rows[0]?.saldo || 0);
}

async function getCommissionCreditApplicationSummary(commissionIds = [], executor = pool) {
  const ids = [...new Set((commissionIds || []).map(Number).filter(Boolean))];
  if (!ids.length) return { montoAplicado: 0, saldoAntes: 0, saldoDespues: 0, registros: [] };
  const [rows] = await executor.execute(
    `SELECT id, comision_id, cuenta_por_pagar_id, usuario_id, comision_bruta,
            saldo_antes, monto_descontado, saldo_despues, monto_pagado, created_at
       FROM comisiones_descuentos_creditos
      WHERE comision_id IN (${ids.map(() => "?").join(",")})
      ORDER BY id ASC`,
    ids
  );
  return {
    montoAplicado: roundMoneyServer(rows.reduce((sum, row) => sum + Number(row.monto_descontado || 0), 0)),
    saldoAntes: rows.length ? Number(rows[0].saldo_antes || 0) : 0,
    saldoDespues: rows.length ? Number(rows[rows.length - 1].saldo_despues || 0) : 0,
    registros: rows
  };
}

async function enrichCommissionCreditApplication(detail) {
  if (!detail || detail.source !== "OCCOM") return detail;
  await ensureUserCreditTables();
  await ensureCommissionCreditDiscountTable();
  const accounts = detail.groupedCommissions?.length ? detail.groupedCommissions : [detail.account].filter(Boolean);
  const commissionIds = accounts.map((account) => Number(account.commissionId || 0)).filter(Boolean);
  const supervisorIds = [...new Set(accounts.map((account) => Number(account.supervisorId || 0)).filter(Boolean))];
  const userId = supervisorIds.length === 1 ? supervisorIds[0] : Number(detail.account?.supervisorId || 0);
  const currentBalance = userId ? await getUserCreditOutstandingBalance(userId) : 0;
  const application = await getCommissionCreditApplicationSummary(commissionIds);
  const grossTotal = Number(detail.order?.subtotal ?? detail.account?.montoOriginal ?? detail.account?.subtotal ?? 0);
  detail.creditApplication = {
    usuarioId: userId || null,
    saldoPendiente: currentBalance,
    montoAplicado: Number(application.montoAplicado || 0),
    saldoAntesAplicacion: application.montoAplicado > 0
      ? Number(application.saldoAntes || currentBalance + application.montoAplicado)
      : currentBalance,
    saldoDespuesAplicacion: application.montoAplicado > 0 ? Number(application.saldoDespues || currentBalance) : currentBalance,
    maxAplicable: application.montoAplicado > 0
      ? Number(application.montoAplicado || 0)
      : Math.max(0, Math.min(grossTotal, currentBalance)),
    bloqueado: Number(application.montoAplicado || 0) > 0,
    tienePersonaRegistrada: Boolean(userId)
  };
  return detail;
}

async function applyCommissionChargeToUserCredits(connection, {
  userId,
  amount,
  commissionId,
  accountId,
  grossCommission,
  registeredBy
}) {
  const numericUserId = Number(userId || 0);
  const numericCommissionId = Number(commissionId || 0);
  const requestedAmount = Math.max(0, roundMoneyServer(amount));
  if (!numericUserId || !numericCommissionId || requestedAmount <= 0) {
    return { saldoAntes: 0, saldoDespues: 0, montoAplicado: 0 };
  }

  const [creditRows] = await connection.execute(
    `SELECT id, saldo_pendiente, concepto, tipo
       FROM usuarios_creditos
      WHERE usuario_id = ?
        AND saldo_pendiente > 0
        AND estado = 'ACTIVO'
      ORDER BY fecha_otorgamiento ASC, id ASC
      FOR UPDATE`,
    [numericUserId]
  );
  const balanceBefore = roundMoneyServer(creditRows.reduce((sum, row) => sum + Number(row.saldo_pendiente || 0), 0));
  if (requestedAmount > balanceBefore + 0.009) {
    const error = new Error(`El cobro no puede ser mayor al saldo pendiente de ${formatCurrencyServer(balanceBefore)}.`);
    error.statusCode = 400;
    throw error;
  }

  let remaining = requestedAmount;
  for (const credit of creditRows) {
    if (remaining <= 0.009) break;
    const previousBalance = Number(credit.saldo_pendiente || 0);
    const applied = roundMoneyServer(Math.min(previousBalance, remaining));
    const nextBalance = roundMoneyServer(previousBalance - applied);
    await connection.execute(
      `UPDATE usuarios_creditos
          SET saldo_pendiente = ?, estado = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?`,
      [nextBalance, nextBalance <= 0 ? "LIQUIDADO" : "ACTIVO", credit.id]
    );
    await connection.execute(
      `INSERT INTO usuarios_creditos_movimientos
        (credito_id, usuario_id, tipo, monto, saldo_anterior, saldo_posterior, origen_tipo, origen_id, referencia, detalle, usuario_registro_id)
       VALUES (?, ?, 'ABONO_COMISION', ?, ?, ?, 'OCCOM', ?, ?, ?, ?)`,
      [
        credit.id,
        numericUserId,
        applied,
        previousBalance,
        nextBalance,
        numericCommissionId,
        `OCCOM-${numericCommissionId}`,
        `Cobro aplicado desde comisión a ${credit.tipo || "ADEUDO"}: ${credit.concepto || "Sin concepto"}`,
        registeredBy || null
      ]
    );
    remaining = roundMoneyServer(remaining - applied);
  }

  const balanceAfter = roundMoneyServer(balanceBefore - requestedAmount);
  await connection.execute(
    `INSERT INTO comisiones_descuentos_creditos
      (comision_id, cuenta_por_pagar_id, usuario_id, comision_bruta, saldo_antes, monto_descontado, saldo_despues, monto_pagado, usuario_registro_id)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      numericCommissionId,
      accountId || null,
      numericUserId,
      roundMoneyServer(grossCommission),
      balanceBefore,
      requestedAmount,
      balanceAfter,
      Math.max(roundMoneyServer(Number(grossCommission || 0) - requestedAmount), 0),
      registeredBy || null
    ]
  );

  return { saldoAntes: balanceBefore, saldoDespues: balanceAfter, montoAplicado: requestedAmount };
}

async function detachLegacyCommissionCreditApplication(connection, commissionId, registeredBy = null) {
  const numericCommissionId = Number(commissionId || 0);
  if (!numericCommissionId) return;

  // Si la OCCOM descontó un préstamo/adeudo, al eliminarla restauramos únicamente
  // el importe que esa comisión aplicó. Conservamos el historial mediante un movimiento
  // de reverso y dejamos activo "descontar_comisiones" para futuros pagos.
  try {
    const [movementRows] = await connection.execute(
      `SELECT
          credito_id,
          usuario_id,
          COALESCE(SUM(monto), 0) AS monto_restaurar
       FROM usuarios_creditos_movimientos
       WHERE tipo = 'ABONO_COMISION'
         AND origen_tipo = 'OCCOM'
         AND origen_id = ?
       GROUP BY credito_id, usuario_id`,
      [numericCommissionId]
    );

    for (const movement of movementRows) {
      const [creditRows] = await connection.execute(
        `SELECT id, usuario_id, monto_original, saldo_pendiente
         FROM usuarios_creditos
         WHERE id = ?
         LIMIT 1
         FOR UPDATE`,
        [movement.credito_id]
      );
      const credit = creditRows[0];
      if (!credit) continue;

      const currentBalance = roundMoneyServer(Number(credit.saldo_pendiente || 0));
      const requestedRestore = Math.max(0, roundMoneyServer(Number(movement.monto_restaurar || 0)));
      const restoredBalance = Math.min(
        roundMoneyServer(Number(credit.monto_original || 0)),
        roundMoneyServer(currentBalance + requestedRestore)
      );
      const restoredAmount = Math.max(0, roundMoneyServer(restoredBalance - currentBalance));
      if (restoredAmount <= 0.009) continue;

      await connection.execute(
        `UPDATE usuarios_creditos
         SET saldo_pendiente = ?,
             estado = ?,
             updated_at = CURRENT_TIMESTAMP
         WHERE id = ?`,
        [restoredBalance, restoredBalance > 0 ? "ACTIVO" : "LIQUIDADO", credit.id]
      );

      await connection.execute(
        `INSERT INTO usuarios_creditos_movimientos
          (credito_id, usuario_id, tipo, monto, saldo_anterior, saldo_posterior,
           origen_tipo, origen_id, referencia, detalle, usuario_registro_id)
         VALUES (?, ?, 'REVERSO_COMISION', ?, ?, ?, 'OCCOM', ?, ?, ?, ?)`,
        [
          credit.id,
          Number(credit.usuario_id || movement.usuario_id || 0),
          restoredAmount,
          currentBalance,
          restoredBalance,
          numericCommissionId,
          `REVERSO-OCCOM-${numericCommissionId}`,
          "Reverso automático por eliminación de la OCCOM.",
          registeredBy || null
        ]
      );
    }
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }

  try {
    await connection.execute(
      "DELETE FROM comisiones_descuentos_creditos WHERE comision_id = ?",
      [numericCommissionId]
    );
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }

  try {
    await connection.execute(
      `UPDATE cuentas_por_pagar
       SET adeudo_monto = 0,
           adeudo_detalle = '',
           descuento_monto = 0,
           descuento_detalle = '',
           updated_at = CURRENT_TIMESTAMP
       WHERE tipo_origen = 'OCCOM'
         AND comision_id = ?`,
      [numericCommissionId]
    );
  } catch (error) {
    if (!["ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }
}

async function searchGlobal(term, user = null) {
  const cleanTerm = String(term || "").trim();
  if (cleanTerm.length < 2) return [];

  // Para supervisores no se hace una búsqueda cruda sobre toda la BD.
  // Se reutiliza el alcance de presupuestos (propios + sucursales asignadas),
  // evitando que la búsqueda global salte el aislamiento operativo.
  if (shouldRestrictToOwnedBudgets(user)) {
    const budgets = await getBudgets(cleanTerm, user, { limit: 25 });
    return budgets.slice(0, 25).map((budget) => ({
      table: "presupuestos",
      text: [budget.folio, budget.empresa, budget.sucursal, budget.tituloProyecto, budget.owner]
        .filter(Boolean)
        .join(" · ")
    }));
  }

  const [columns] = await pool.execute(
    `SELECT TABLE_NAME, COLUMN_NAME
     FROM INFORMATION_SCHEMA.COLUMNS
     WHERE TABLE_SCHEMA = ?
       AND DATA_TYPE IN ('char', 'varchar', 'text', 'mediumtext', 'longtext')
     ORDER BY TABLE_NAME, ORDINAL_POSITION`,
    [DB_NAME]
  );

  const tableColumns = new Map();
  for (const column of columns) {
    if (HIDDEN_SEARCH_COLUMNS.has(column.COLUMN_NAME.toLowerCase())) continue;
    if (!tableColumns.has(column.TABLE_NAME)) tableColumns.set(column.TABLE_NAME, []);
    tableColumns.get(column.TABLE_NAME).push(column.COLUMN_NAME);
  }

  const results = [];
  for (const [tableName, searchableColumns] of tableColumns.entries()) {
    if (!searchableColumns.length || results.length >= 25) continue;

    const where = searchableColumns.map((column) => `${escapeId(column)} LIKE ?`).join(" OR ");
    const selects = searchableColumns.slice(0, 3).map((column) => escapeId(column)).join(", ");
    const values = searchableColumns.map(() => `%${cleanTerm}%`);
    let rows = [];
    try {
      [rows] = await pool.execute(
        `SELECT ${selects}
         FROM ${escapeId(tableName)}
         WHERE ${where}
         LIMIT 5`,
        values
      );
    } catch (error) {
      logServerError(`global-search:${tableName}`, error);
      continue;
    }

    for (const row of rows) {
      const text = Object.values(row)
        .filter((value) => value !== null && value !== undefined && String(value).trim())
        .map((value) => String(value).trim())
        .join(" · ");

      if (text) results.push({ table: tableName, text });
      if (results.length >= 25) break;
    }
  }

  return results;
}

