async function getProjectOwnerUsers({ includeInactive = false } = {}) {
  const where = includeInactive ? "" : "WHERE u.activo = 1";
  const [rows] = await pool.execute(
    `SELECT
       u.user_id,
       u.nombre,
       u.apellido,
       u.usuario,
       u.activo,
       r.nombre AS rol,
       (SELECT COUNT(*) FROM presupuestos p WHERE p.usuario_id = u.user_id) AS proyectos_count
     FROM usuarios u
     LEFT JOIN roles r ON r.id = u.rol_id
     ${where}
     ORDER BY u.activo DESC, u.nombre, u.apellido, u.usuario`
  );
  return rows.map((row) => ({
    id: Number(row.user_id),
    nombre: row.nombre || "",
    apellido: row.apellido || "",
    usuario: row.usuario || "",
    rol: displayRoleName(row.rol || ""),
    activo: Boolean(row.activo),
    proyectosCount: Number(row.proyectos_count || 0),
    nombreCompleto: `${row.nombre || ""} ${row.apellido || ""}`.trim() || row.usuario || `Usuario ${row.user_id}`
  }));
}

function assignmentNameSimilarity(a, b) {
  const left = normalizePersonAssignmentKey(a);
  const right = normalizePersonAssignmentKey(b);
  if (!left || !right) return 0;
  if (left === right) return 1;
  const leftTokens = left.split(" ").filter(Boolean);
  const rightTokens = right.split(" ").filter(Boolean);
  const intersection = leftTokens.filter((token) => rightTokens.includes(token)).length;
  const union = new Set([...leftTokens, ...rightTokens]).size || 1;
  const tokenScore = intersection / union;
  const prefixScore =
    left.startsWith(right) || right.startsWith(left)
      ? Math.min(left.length, right.length) / Math.max(left.length, right.length)
      : 0;
  return Math.max(tokenScore, prefixScore);
}

async function getProjectOwnerAuditData() {
  await ensureClientBranchAndAssignmentTables();
  const users = await getProjectOwnerUsers({ includeInactive: true });
  const activeUsers = users.filter((user) => user.activo);
  const sources = [];

  users
    .filter((user) => user.proyectosCount > 0)
    .forEach((user) => {
      sources.push({
        key: `user:${user.id}`,
        kind: "user",
        sourceUserId: user.id,
        label: user.nombreCompleto,
        meta: `${user.usuario || "sin usuario"} · ${user.proyectosCount} proyecto(s)${user.activo ? "" : " · inactivo"}`,
        projectCount: user.proyectosCount,
        suggestedUserId: user.id
      });
    });

  if (await tableExists("ordenes_servicio")) {
    const [aliasRows] = await pool.execute(
      `SELECT
         TRIM(os.supervisor) AS alias,
         COUNT(DISTINCT p.id) AS proyectos_count
       FROM ordenes_servicio os
       INNER JOIN presupuestos p ON p.id = os.id
       LEFT JOIN usuarios u ON u.user_id = p.usuario_id
       WHERE NULLIF(TRIM(os.supervisor), '') IS NOT NULL
         AND (
           p.usuario_id IS NULL
           OR CONVERT(TRIM(os.supervisor) USING utf8mb4) COLLATE utf8mb4_unicode_ci <>
              CONVERT(TRIM(COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '')) USING utf8mb4) COLLATE utf8mb4_unicode_ci
         )
       GROUP BY TRIM(os.supervisor)
       ORDER BY proyectos_count DESC, alias`
    );
    aliasRows.forEach((row) => {
      const alias = String(row.alias || "").trim();
      if (!alias) return;
      let best = null;
      activeUsers.forEach((user) => {
        const score = assignmentNameSimilarity(alias, user.nombreCompleto);
        if (!best || score > best.score) best = { user, score };
      });
      sources.push({
        key: `legacy:${alias}`,
        kind: "legacy",
        alias,
        label: alias,
        meta: `Nombre histórico · ${Number(row.proyectos_count || 0)} proyecto(s)`,
        projectCount: Number(row.proyectos_count || 0),
        suggestedUserId: best && best.score >= 0.5 ? best.user.id : null,
        suggestedScore: best ? Number(best.score.toFixed(3)) : 0
      });
    });
  }

  const [projectRows] = await pool.execute(
    `SELECT
       p.id,
       p.folio,
       p.titulo_proyecto,
       p.empresa,
       p.usuario_id,
       COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS owner_nombre
     FROM presupuestos p
     LEFT JOIN usuarios u ON u.user_id = p.usuario_id
     ORDER BY p.id DESC`
  );
  const legacyByProject = new Map();
  if (await tableExists("ordenes_servicio")) {
    const [legacyRows] = await pool.execute(
      `SELECT id, TRIM(supervisor) AS supervisor
       FROM ordenes_servicio
       WHERE NULLIF(TRIM(supervisor), '') IS NOT NULL`
    );
    legacyRows.forEach((row) => legacyByProject.set(Number(row.id), row.supervisor || ""));
  }

  const projects = projectRows.map((row) => ({
    id: Number(row.id),
    folio: row.folio || "",
    tituloProyecto: row.titulo_proyecto || "",
    empresa: row.empresa || "",
    ownerId: row.usuario_id || null,
    ownerNombre: row.owner_nombre || "",
    legacyOwner: legacyByProject.get(Number(row.id)) || ""
  }));

  return { users, sources, projects };
}

