app.post("/api/project-owner-audit/assign", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const sourceKind = String(req.body.sourceKind || "").trim();
  const sourceUserId = Number(req.body.sourceUserId || 0);
  const alias = String(req.body.alias || "").trim();
  const targetUserId = Number(req.body.targetUserId || 0);
  const projectIds = Array.isArray(req.body.projectIds)
    ? [...new Set(req.body.projectIds.map(Number).filter(Boolean))]
    : [];
  const normalizeLegacyName = req.body.normalizeLegacyName !== false;
  const deactivateSource = Boolean(req.body.deactivateSource);

  if (!["user", "legacy"].includes(sourceKind) || !targetUserId || !projectIds.length) {
    return res.status(400).json({ ok: false, message: "Selecciona origen, usuario principal y al menos un proyecto." });
  }
  if (sourceKind === "user" && (!sourceUserId || sourceUserId === targetUserId)) {
    return res.status(400).json({ ok: false, message: "Selecciona un usuario principal diferente al usuario duplicado." });
  }
  if (sourceKind === "legacy" && !alias) {
    return res.status(400).json({ ok: false, message: "Selecciona un nombre histórico." });
  }

  const connection = await pool.getConnection();
  try {
    await ensureClientBranchAndAssignmentTables();
    await connection.beginTransaction();

    const [targetRows] = await connection.execute(
      `SELECT user_id, nombre, apellido, usuario, activo
       FROM usuarios
       WHERE user_id = ?
       LIMIT 1
       FOR UPDATE`,
      [targetUserId]
    );
    const target = targetRows[0];
    if (!target || !Number(target.activo)) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "El usuario principal no está activo." });
    }
    const targetName = `${target.nombre || ""} ${target.apellido || ""}`.trim() || target.usuario || `Usuario ${targetUserId}`;

    const placeholders = projectIds.map(() => "?").join(",");
    let validRows = [];
    if (sourceKind === "user") {
      [validRows] = await connection.execute(
        `SELECT id
         FROM presupuestos
         WHERE usuario_id = ?
           AND id IN (${placeholders})
         FOR UPDATE`,
        [sourceUserId, ...projectIds]
      );
    } else {
      if (!(await tableExists("ordenes_servicio"))) {
        await connection.rollback();
        return res.status(409).json({ ok: false, message: "No existe información histórica para consolidar." });
      }
      [validRows] = await connection.execute(
        `SELECT p.id
         FROM presupuestos p
         INNER JOIN ordenes_servicio os ON os.id = p.id
         WHERE CONVERT(TRIM(os.supervisor) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
               CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
           AND p.id IN (${placeholders})
         FOR UPDATE`,
        [alias, ...projectIds]
      );
    }

    const validIds = validRows.map((row) => Number(row.id)).filter(Boolean);
    if (!validIds.length) {
      await connection.rollback();
      return res.status(409).json({ ok: false, message: "Los proyectos seleccionados ya no pertenecen a ese origen." });
    }
    const validPlaceholders = validIds.map(() => "?").join(",");
    await connection.execute(
      `UPDATE presupuestos
       SET usuario_id = ?
       WHERE id IN (${validPlaceholders})`,
      [targetUserId, ...validIds]
    );

    if (sourceKind === "legacy") {
      await connection.execute(
        `INSERT INTO usuario_asignacion_aliases (usuario_id, alias)
         VALUES (?, ?)
         ON DUPLICATE KEY UPDATE usuario_id = VALUES(usuario_id), updated_at = CURRENT_TIMESTAMP`,
        [targetUserId, alias]
      );
      if (normalizeLegacyName) {
        await connection.execute(
          `UPDATE ordenes_servicio
           SET supervisor = ?
           WHERE id IN (${validPlaceholders})`,
          [targetName, ...validIds]
        );
      }
    }

    if (sourceKind === "user" && deactivateSource && sourceUserId !== Number(req.session.user?.id || 0)) {
      const [remainingRows] = await connection.execute(
        "SELECT COUNT(*) AS total FROM presupuestos WHERE usuario_id = ?",
        [sourceUserId]
      );
      if (Number(remainingRows[0]?.total || 0) === 0) {
        await connection.execute("UPDATE usuarios SET activo = 0 WHERE user_id = ?", [sourceUserId]);
      }
    }

    await connection.commit();
    res.json({ ok: true, reassigned: validIds.length, targetUserId });
  } catch (error) {
    await connection.rollback();
    logServerError("project-owner-audit-assign", error);
    res.status(500).json({ ok: false, message: "No se pudieron consolidar los responsables." });
  } finally {
    connection.release();
  }
});

