app.post("/api/user-credits", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const userId = Number(req.body.usuarioId || 0);
  const type = String(req.body.tipo || "PRESTAMO").trim().toUpperCase();
  const amount = Math.max(0, roundMoneyServer(req.body.monto));
  const concept = String(req.body.concepto || "").trim().slice(0, 500);
  const notes = String(req.body.notas || "").trim().slice(0, 4000);
  const date = String(req.body.fechaOtorgamiento || "").trim();
  const grantDate = /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : new Date().toISOString().slice(0, 10);

  if (!userId) return res.status(400).json({ ok: false, message: "Selecciona una persona." });
  if (!["PRESTAMO", "ADEUDO"].includes(type)) {
    return res.status(400).json({ ok: false, message: "Selecciona un tipo de registro válido." });
  }
  if (amount <= 0) return res.status(400).json({ ok: false, message: "Captura un monto mayor a cero." });
  if (!concept) return res.status(400).json({ ok: false, message: "Captura el concepto del préstamo o adeudo." });

  const connection = await pool.getConnection();
  try {
    await ensureUserCreditTables();
    await connection.beginTransaction();

    const [userRows] = await connection.execute(
      "SELECT user_id FROM usuarios WHERE user_id = ? AND activo = 1 LIMIT 1",
      [userId]
    );
    if (!userRows.length) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "La persona seleccionada no está disponible." });
    }

    const [result] = await connection.execute(
      `INSERT INTO usuarios_creditos
        (usuario_id, tipo, monto_original, saldo_pendiente, concepto, notas, fecha_otorgamiento, estado, descontar_comisiones, usuario_registro_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'ACTIVO', 0, ?)`,
      [userId, type, amount, amount, concept, notes || null, grantDate, req.session.user?.id || null]
    );

    await connection.execute(
      `INSERT INTO usuarios_creditos_movimientos
        (credito_id, usuario_id, tipo, monto, saldo_anterior, saldo_posterior, origen_tipo, origen_id, referencia, detalle, usuario_registro_id)
       VALUES (?, ?, 'CARGO_INICIAL', ?, 0, ?, 'CREDITO', ?, ?, ?, ?)`,
      [
        result.insertId,
        userId,
        amount,
        amount,
        result.insertId,
        `${type}-${result.insertId}`,
        concept,
        req.session.user?.id || null
      ]
    );

    await connection.commit();
    const detail = await getUserCreditDetail(userId);
    res.status(201).json({ ok: true, creditId: result.insertId, ...detail });
  } catch (error) {
    await connection.rollback();
    logServerError("user-credit-create", error);
    res.status(500).json({ ok: false, message: "No se pudo registrar el préstamo o adeudo." });
  } finally {
    connection.release();
  }
});

app.post("/api/user-credits/:id/payments", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const creditId = Number(req.params.id);
  const amount = Math.max(0, roundMoneyServer(req.body.monto));
  const detailText = String(req.body.detalle || "").trim().slice(0, 500);
  const reference = String(req.body.referencia || "").trim().slice(0, 120);

  if (!creditId) return res.status(400).json({ ok: false, message: "Préstamo inválido." });
  if (amount <= 0) return res.status(400).json({ ok: false, message: "Captura un abono mayor a cero." });
  if (!detailText) return res.status(400).json({ ok: false, message: "Captura el motivo o detalle del abono." });

  const connection = await pool.getConnection();
  try {
    await ensureUserCreditTables();
    await connection.beginTransaction();

    const [creditRows] = await connection.execute(
      `SELECT id, usuario_id, saldo_pendiente
       FROM usuarios_creditos
       WHERE id = ?
       LIMIT 1
       FOR UPDATE`,
      [creditId]
    );

    if (!creditRows.length) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Préstamo no encontrado." });
    }

    const credit = creditRows[0];
    const previousBalance = Number(credit.saldo_pendiente || 0);
    if (previousBalance <= 0) {
      await connection.rollback();
      return res.status(409).json({ ok: false, message: "Este préstamo ya está liquidado." });
    }
    if (amount > previousBalance) {
      await connection.rollback();
      return res.status(400).json({
        ok: false,
        message: `El abono no puede ser mayor al saldo pendiente de ${formatCurrencyServer(previousBalance)}.`
      });
    }

    const nextBalance = roundMoneyServer(previousBalance - amount);
    await connection.execute(
      `UPDATE usuarios_creditos
       SET saldo_pendiente = ?, estado = ?, updated_at = CURRENT_TIMESTAMP
       WHERE id = ?`,
      [nextBalance, nextBalance <= 0 ? "LIQUIDADO" : "ACTIVO", creditId]
    );

    await connection.execute(
      `INSERT INTO usuarios_creditos_movimientos
        (credito_id, usuario_id, tipo, monto, saldo_anterior, saldo_posterior, origen_tipo, origen_id, referencia, detalle, usuario_registro_id)
       VALUES (?, ?, 'ABONO_EXTERNO', ?, ?, ?, 'ABONO_EXTERNO', NULL, ?, ?, ?)`,
      [
        creditId,
        credit.usuario_id,
        amount,
        previousBalance,
        nextBalance,
        reference,
        detailText,
        req.session.user?.id || null
      ]
    );

    await connection.commit();
    const userDetail = await getUserCreditDetail(Number(credit.usuario_id));
    res.json({ ok: true, ...userDetail });
  } catch (error) {
    await connection.rollback();
    logServerError("user-credit-payment", error);
    res.status(500).json({ ok: false, message: "No se pudo registrar el abono." });
  } finally {
    connection.release();
  }
});

function parseUserPayload(body, { requirePassword = true } = {}) {
  const rawBranchScopes = Array.isArray(body.alcancesSucursal) ? body.alcancesSucursal : [];
  const branchScopeMap = new Map();
  for (const rawScope of rawBranchScopes) {
    const branchId = Number(rawScope?.sucursalId || 0);
    if (!branchId) continue;
    const permissionIds = Array.isArray(rawScope?.permisos)
      ? rawScope.permisos.map(Number).filter(Boolean)
      : [];
    if (!branchScopeMap.has(branchId)) branchScopeMap.set(branchId, new Set());
    for (const permissionId of permissionIds) branchScopeMap.get(branchId).add(permissionId);
  }

  const payload = {
    nombre: String(body.nombre || "").trim(),
    apellido: String(body.apellido || "").trim(),
    usuario: String(body.usuario || "").trim(),
    password: String(body.password || ""),
    rolId: Number(body.rolId || 0),
    comisionSupervisor: Number(body.comisionSupervisor || 0),
    banco: String(body.banco || "").trim(),
    cuenta: String(body.cuenta || "").trim(),
    clabe: String(body.clabe || "").trim(),
    permisosEspeciales: Array.isArray(body.permisosEspeciales)
      ? body.permisosEspeciales.map(Number).filter(Boolean)
      : [],
    rolesTemporales: Array.isArray(body.rolesTemporales)
      ? body.rolesTemporales.map(Number).filter(Boolean)
      : [],
    alcancesSucursal: [...branchScopeMap.entries()]
      .map(([sucursalId, permisos]) => ({ sucursalId, permisos: [...permisos] }))
      .filter((scope) => scope.permisos.length)
  };

  if (!payload.nombre || !payload.apellido || !payload.usuario || !payload.rolId) {
    return { error: "Completa nombre, apellido, usuario y rol." };
  }

  if (requirePassword && !payload.password) {
    return { error: "Completa la contrasena." };
  }

  if (payload.password && payload.password.length < 8) {
    return { error: "La contrasena debe tener al menos 8 caracteres." };
  }

  if (payload.comisionSupervisor < 0 || payload.comisionSupervisor > 100) {
    return { error: "La comision supervisor debe estar entre 0 y 100." };
  }

  return { payload };
}

async function replaceUserPermissions(
  connection,
  userId,
  permisosEspeciales,
  rolesTemporales,
  rolId,
  alcancesSucursal = []
) {
  await connection.execute("DELETE FROM usuarios_permisos WHERE usuario_id = ?", [userId]);
  await connection.execute("DELETE FROM usuarios_roles_temporales WHERE usuario_id = ?", [userId]);
  await connection.execute("DELETE FROM usuarios_sucursales_permisos WHERE usuario_id = ?", [userId]);
  await connection.execute("DELETE FROM usuarios_sucursales WHERE usuario_id = ?", [userId]);

  for (const permisoId of permisosEspeciales) {
    await connection.execute(
      "INSERT IGNORE INTO usuarios_permisos (usuario_id, permiso_id) VALUES (?, ?)",
      [userId, permisoId]
    );
  }

  for (const tempRoleId of rolesTemporales) {
    if (tempRoleId === rolId) continue;
    await connection.execute(
      "INSERT IGNORE INTO usuarios_roles_temporales (usuario_id, rol_id) VALUES (?, ?)",
      [userId, tempRoleId]
    );
  }

  const allowedPermissionNames = [...BRANCH_SCOPED_PERMISSION_NAMES];
  for (const scope of alcancesSucursal) {
    const branchId = Number(scope?.sucursalId || 0);
    const permissionIds = [...new Set((scope?.permisos || []).map(Number).filter(Boolean))];
    if (!branchId || !permissionIds.length) continue;
    const [branchResult] = await connection.execute(
      `INSERT IGNORE INTO usuarios_sucursales (usuario_id, sucursal_id, nivel_acceso)
       SELECT ?, s.id, 'modular'
       FROM cliente_sucursales s
       WHERE s.id = ? AND s.activo = 1`,
      [userId, branchId]
    );
    const [branchRows] = await connection.execute(
      "SELECT id FROM cliente_sucursales WHERE id = ? AND activo = 1 LIMIT 1",
      [branchId]
    );
    if (!branchRows.length) continue;
    for (const permissionId of permissionIds) {
      await connection.execute(
        `INSERT IGNORE INTO usuarios_sucursales_permisos (usuario_id, sucursal_id, permiso_id)
         SELECT ?, ?, p.id
         FROM permisos p
         WHERE p.id = ? AND p.nombre IN (${allowedPermissionNames.map(() => "?").join(",")})`,
        [userId, branchId, permissionId, ...allowedPermissionNames]
      );
    }
  }
}

app.post("/api/users", requireAuth, requireSuperAdmin, async (req, res) => {
  const parsed = parseUserPayload(req.body, { requirePassword: true });
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });

  const {
    nombre,
    apellido,
    usuario,
    password,
    rolId,
    comisionSupervisor,
    banco,
    cuenta,
    clabe,
    permisosEspeciales,
    rolesTemporales,
    alcancesSucursal
  } = parsed.payload;
  const selectedRoleName = await getRoleNameById(rolId);
  const effectivePermissions =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : permisosEspeciales;
  const effectiveTempRoles =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : rolesTemporales;
  const effectiveBranchScopes =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : alcancesSucursal;

  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();

    const [existingRows] = await connection.execute(
      "SELECT user_id FROM usuarios WHERE usuario = ? LIMIT 1",
      [usuario]
    );

    if (existingRows.length) {
      await connection.rollback();
      return res.status(409).json({ ok: false, message: "Ese usuario ya existe." });
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const [result] = await connection.execute(
      `INSERT INTO usuarios (nombre, apellido, usuario, password, rol_id, comision_supervisor, banco, cuenta, clabe)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [nombre, apellido, usuario, passwordHash, rolId, comisionSupervisor, banco, cuenta, clabe]
    );

    const userId = result.insertId;
    await replaceUserPermissions(connection, userId, effectivePermissions, effectiveTempRoles, rolId, effectiveBranchScopes);

    await connection.commit();
    res.status(201).json({ ok: true, userId });
  } catch (error) {
    await connection.rollback();
    logServerError("users-create", error);
    res.status(500).json({ ok: false, message: "No se pudo crear el usuario." });
  } finally {
    connection.release();
  }
});

app.put("/api/users/:id", requireAuth, requireSuperAdmin, async (req, res) => {
  const userId = Number(req.params.id);
  const parsed = parseUserPayload(req.body, { requirePassword: false });
  if (!userId) return res.status(400).json({ ok: false, message: "Usuario invalido." });
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });

  const nombre = String(req.body.nombre || "").trim();
  const { apellido, usuario, password, rolId, comisionSupervisor, banco, cuenta, clabe, permisosEspeciales, rolesTemporales, alcancesSucursal } =
    parsed.payload;
  const selectedRoleName = await getRoleNameById(rolId);
  const effectivePermissions =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : permisosEspeciales;
  const effectiveTempRoles =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : rolesTemporales;
  const effectiveBranchScopes =
    String(selectedRoleName).toLowerCase() === "superadmin" ? [] : alcancesSucursal;

  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();

    const [existingRows] = await connection.execute(
      "SELECT user_id FROM usuarios WHERE usuario = ? AND user_id <> ? LIMIT 1",
      [usuario, userId]
    );

    if (existingRows.length) {
      await connection.rollback();
      return res.status(409).json({ ok: false, message: "Ese usuario ya existe." });
    }

    const fields = [
      "nombre = ?",
      "apellido = ?",
      "usuario = ?",
      "rol_id = ?",
      "comision_supervisor = ?",
      "banco = ?",
      "cuenta = ?",
      "clabe = ?"
    ];
    const values = [nombre, apellido, usuario, rolId, comisionSupervisor, banco, cuenta, clabe];

    if (password) {
      fields.push("password = ?");
      values.push(await bcrypt.hash(password, 12));
    }

    values.push(userId);
    await connection.execute(`UPDATE usuarios SET ${fields.join(", ")} WHERE user_id = ?`, values);
    await replaceUserPermissions(connection, userId, effectivePermissions, effectiveTempRoles, rolId, effectiveBranchScopes);

    await connection.commit();
    res.json({ ok: true, userId });
  } catch (error) {
    await connection.rollback();
    logServerError("users-update", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar el usuario." });
  } finally {
    connection.release();
  }
});

function parseClientPayload(body, { allowLegacyBranch = false } = {}) {
  const payload = {
    empresa: String(body.empresa || "").trim(),
    sucursalId: Number(body.sucursalId || 0) || null,
    sucursal: String(body.sucursal || "").trim(),
    nombre: String(body.nombre || "").trim(),
    telefono: String(body.telefono || "").trim(),
    rfc: String(body.rfc || "").trim(),
    direccion: String(body.direccion || "").trim(),
    email: String(body.email || "").trim(),
    usoCfdi: String(body.usoCfdi || "").trim(),
    valorVenta: Number(body.valorVenta || 1.45),
    metodoPago: String(body.metodoPago || "contado").trim().toLowerCase(),
    diasCredito: Number(body.diasCredito || 0),
    notas: String(body.notas || "").trim()
  };

  if (!payload.empresa || !payload.nombre || (!allowLegacyBranch && !payload.sucursalId)) {
    return { error: "Completa empresa, ubicación / sucursal y cliente / usuario (contacto)." };
  }

  if (!["contado", "credito"].includes(payload.metodoPago)) {
    payload.metodoPago = "contado";
  }

  if (Number.isNaN(payload.valorVenta) || payload.valorVenta < 0) {
    return { error: "El valor de venta no es valido." };
  }
  if (!Number.isFinite(payload.diasCredito) || payload.diasCredito < 0) {
    payload.diasCredito = payload.metodoPago === "credito" ? 30 : 0;
  }
  if (payload.metodoPago === "contado") payload.diasCredito = 0;

  return { payload };
}

async function getLocationCatalog({ includeInactive = false } = {}, connection = pool) {
  const where = includeInactive ? "" : "WHERE u.activo = 1";
  const [rows] = await connection.execute(
    `SELECT
       u.id,
       u.nombre,
       u.activo,
       u.created_at,
       u.updated_at,
       (SELECT COUNT(DISTINCT s.empresa) FROM cliente_sucursales s WHERE s.ubicacion_id = u.id) AS empresas_count
     FROM catalogo_ubicaciones u
     ${where}
     ORDER BY u.nombre`
  );
  return rows.map((row) => ({
    id: Number(row.id),
    nombre: row.nombre || "",
    activo: Boolean(row.activo),
    empresasCount: Number(row.empresas_count || 0),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }));
}

async function resolveLocationCatalogSelection(locationId, connection = pool) {
  const numericLocationId = Number(locationId || 0);
  if (!numericLocationId) return null;
  const [rows] = await connection.execute(
    `SELECT id, nombre, activo
     FROM catalogo_ubicaciones
     WHERE id = ? AND activo = 1
     LIMIT 1`,
    [numericLocationId]
  );
  return rows[0] || null;
}

async function getClientBranchLocations(company = "", { includeInactive = false } = {}, connection = pool) {
  const conditions = [];
  const values = [];
  const normalizedCompany = String(company || "").trim();
  if (normalizedCompany) {
    conditions.push(
      "CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci"
    );
    values.push(normalizedCompany);
  }
  if (!includeInactive) {
    conditions.push("s.activo = 1");
    conditions.push("COALESCE(u.activo, 0) = 1");
  }
  const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
  const [rows] = await connection.execute(
    `SELECT
       s.id,
       s.empresa_id,
       s.empresa,
       s.ubicacion_id,
       COALESCE(NULLIF(u.nombre, ''), s.nombre) AS nombre,
       s.direccion,
       s.activo,
       s.created_at,
       s.updated_at,
       e.rfc AS empresa_rfc,
       e.direccion AS empresa_direccion,
       e.email AS empresa_email,
       e.uso_cfdi AS empresa_uso_cfdi,
       e.valor_venta AS empresa_valor_venta,
       e.condiciones_pago AS empresa_condiciones_pago,
       e.dias_credito AS empresa_dias_credito,
       e.notas AS empresa_notas,
       (SELECT COUNT(*) FROM clientes c WHERE c.sucursal_id = s.id) AS contactos_count,
       (SELECT COUNT(*) FROM presupuestos p WHERE p.sucursal_id = s.id) AS proyectos_count
     FROM cliente_sucursales s
     LEFT JOIN cliente_empresas e ON e.id = s.empresa_id
     LEFT JOIN catalogo_ubicaciones u ON u.id = s.ubicacion_id
     ${where}
     ORDER BY s.empresa, COALESCE(NULLIF(u.nombre, ''), s.nombre)`,
    values
  );
  return rows.map((row) => ({
    id: Number(row.id),
    empresaId: Number(row.empresa_id || 0) || null,
    empresa: row.empresa || "",
    ubicacionId: Number(row.ubicacion_id || 0) || null,
    nombre: row.nombre || "",
    direccion: row.direccion || "",
    empresaRfc: row.empresa_rfc || "",
    empresaDireccion: row.empresa_direccion || "",
    empresaEmail: row.empresa_email || "",
    empresaUsoCfdi: row.empresa_uso_cfdi || "",
    empresaValorVenta: Number(row.empresa_valor_venta || 0),
    empresaMetodoPago: row.empresa_condiciones_pago || "contado",
    empresaDiasCredito: Number(row.empresa_dias_credito || 0),
    empresaNotas: row.empresa_notas || "",
    activo: Boolean(row.activo),
    contactosCount: Number(row.contactos_count || 0),
    proyectosCount: Number(row.proyectos_count || 0),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }));
}

function parseClientCompanyPayload(body = {}) {
  const metodoPago = String(body.empresaMetodoPago || body.metodoPago || "contado").trim().toLowerCase();
  const valorVenta = Number(body.empresaValorVenta || body.valorVenta || 0);
  const diasCredito = Number(body.empresaDiasCredito ?? body.diasCredito ?? 0);
  if (!Number.isFinite(valorVenta) || valorVenta <= 0) {
    return { error: "Captura un valor de venta de empresa mayor a cero." };
  }
  return {
    payload: {
      rfc: String(body.empresaRfc || body.rfc || "").trim(),
      direccion: String(body.empresaDireccion || "").trim(),
      email: String(body.empresaEmail || "").trim(),
      usoCfdi: String(body.empresaUsoCfdi || body.usoCfdi || "").trim(),
      valorVenta,
      metodoPago: ["contado", "credito"].includes(metodoPago) ? metodoPago : "contado",
      diasCredito: metodoPago === "credito" && Number.isFinite(diasCredito) && diasCredito >= 0 ? diasCredito : 0,
      notas: String(body.empresaNotas || body.notas || "").trim()
    }
  };
}

async function upsertClientCompany(connection, empresa, company) {
  await connection.execute(
    `INSERT INTO cliente_empresas
      (nombre, rfc, direccion, email, uso_cfdi, valor_venta, condiciones_pago, dias_credito, notas, activo)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
     ON DUPLICATE KEY UPDATE
       rfc = VALUES(rfc), direccion = VALUES(direccion), email = VALUES(email),
       uso_cfdi = VALUES(uso_cfdi), valor_venta = VALUES(valor_venta),
       condiciones_pago = VALUES(condiciones_pago), dias_credito = VALUES(dias_credito),
       notas = VALUES(notas), activo = 1`,
    [
      empresa, company.rfc, company.direccion, company.email, company.usoCfdi,
      company.valorVenta, company.metodoPago, company.diasCredito, company.notas
    ]
  );
  const [rows] = await connection.execute(
    `SELECT id FROM cliente_empresas
     WHERE CONVERT(TRIM(nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
           CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     LIMIT 1`,
    [empresa]
  );
  const companyId = Number(rows[0]?.id || 0) || null;
  if (companyId) {
    // Compatibilidad temporal con módulos históricos: replicar las condiciones
    // de la empresa, sin permitir que un contacto sea quien las defina.
    await connection.execute(
      `UPDATE clientes
       SET empresa_id = ?, rfc = ?, direccion = ?, uso_cfdi = ?, valor_venta = ?,
           condiciones_pago = ?, dias_credito = ?, notas = ?
       WHERE CONVERT(TRIM(empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
             CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci`,
      [
        companyId, company.rfc, company.direccion, company.usoCfdi, company.valorVenta,
        company.metodoPago, company.diasCredito, company.notas, empresa
      ]
    );
  }
  return companyId;
}

async function resolveClientBranchSelection(company, branchId, connection = pool) {
  const numericBranchId = Number(branchId || 0);
  const normalizedCompany = String(company || "").trim();
  if (!numericBranchId || !normalizedCompany) return null;
  const [rows] = await connection.execute(
    `SELECT
       s.id,
       s.empresa_id,
       s.empresa,
       COALESCE(NULLIF(u.nombre, ''), s.nombre) AS nombre,
       s.direccion,
       s.activo,
       s.ubicacion_id,
       e.rfc AS empresa_rfc,
       e.direccion AS empresa_direccion,
       e.uso_cfdi AS empresa_uso_cfdi,
       e.valor_venta AS empresa_valor_venta,
       e.condiciones_pago AS empresa_condiciones_pago,
       e.dias_credito AS empresa_dias_credito,
       e.notas AS empresa_notas
     FROM cliente_sucursales s
     INNER JOIN cliente_empresas e ON e.id = s.empresa_id AND e.activo = 1
     INNER JOIN catalogo_ubicaciones u ON u.id = s.ubicacion_id AND u.activo = 1
     WHERE s.id = ?
       AND s.activo = 1
       AND CONVERT(TRIM(s.empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
           CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     LIMIT 1`,
    [numericBranchId, normalizedCompany]
  );
  return rows[0] || null;
}

async function resolveLegacyCompanyBranch(connection, company, legacyBranchName) {
  const normalizedCompany = String(company || "").trim();
  const legacyName = String(legacyBranchName || "").trim();
  if (!normalizedCompany || !legacyName) return null;

  const activeBranches = await getClientBranchLocations(normalizedCompany, { includeInactive: false }, connection);
  const existingActive = activeBranches.find((branch) => branchLabelsEquivalent(branch.nombre, legacyName));
  if (existingActive) return existingActive;

  const [activeLocations] = await connection.execute(
    `SELECT id, nombre
     FROM catalogo_ubicaciones
     WHERE activo = 1
     ORDER BY id`
  );
  const location = activeLocations.find((row) => branchLabelsEquivalent(row.nombre, legacyName));
  if (!location) return null;

  const [companyBranches] = await connection.execute(
    `SELECT id, empresa, ubicacion_id, nombre, direccion, activo
     FROM cliente_sucursales
     WHERE CONVERT(TRIM(empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
           CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
     ORDER BY id`,
    [normalizedCompany]
  );

  const sameLocation = companyBranches.find((row) => Number(row.ubicacion_id || 0) === Number(location.id));
  if (sameLocation) {
    await connection.execute(
      `UPDATE cliente_sucursales
       SET nombre = ?, ubicacion_id = ?, activo = 1
       WHERE id = ?`,
      [location.nombre, location.id, sameLocation.id]
    );
    return {
      id: Number(sameLocation.id),
      empresa: normalizedCompany,
      ubicacionId: Number(location.id),
      nombre: location.nombre,
      direccion: sameLocation.direccion || "",
      activo: true
    };
  }

  const canonicalNameBranch = companyBranches.find(
    (row) => normalizeBranchLookupKey(row.nombre) === normalizeBranchLookupKey(location.nombre)
  );
  if (canonicalNameBranch) {
    await connection.execute(
      `UPDATE cliente_sucursales
       SET ubicacion_id = ?, activo = 1
       WHERE id = ?`,
      [location.id, canonicalNameBranch.id]
    );
    return {
      id: Number(canonicalNameBranch.id),
      empresa: normalizedCompany,
      ubicacionId: Number(location.id),
      nombre: location.nombre,
      direccion: canonicalNameBranch.direccion || "",
      activo: true
    };
  }

  const legacyBranch = companyBranches.find((row) => branchLabelsEquivalent(row.nombre, legacyName));
  if (legacyBranch) {
    try {
      await connection.execute(
        `UPDATE cliente_sucursales
         SET nombre = ?, ubicacion_id = ?, activo = 1
         WHERE id = ?`,
        [location.nombre, location.id, legacyBranch.id]
      );
      return {
        id: Number(legacyBranch.id),
        empresa: normalizedCompany,
        ubicacionId: Number(location.id),
        nombre: location.nombre,
        direccion: legacyBranch.direccion || "",
        activo: true
      };
    } catch (error) {
      if (error.code !== "ER_DUP_ENTRY") throw error;
      const [duplicateRows] = await connection.execute(
        `SELECT id, direccion
         FROM cliente_sucursales
         WHERE CONVERT(TRIM(empresa) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
               CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
           AND CONVERT(TRIM(nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
               CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
         LIMIT 1`,
        [normalizedCompany, location.nombre]
      );
      if (duplicateRows[0]) {
        await connection.execute(
          "UPDATE cliente_sucursales SET ubicacion_id = ?, activo = 1 WHERE id = ?",
          [location.id, duplicateRows[0].id]
        );
        return {
          id: Number(duplicateRows[0].id),
          empresa: normalizedCompany,
          ubicacionId: Number(location.id),
          nombre: location.nombre,
          direccion: duplicateRows[0].direccion || "",
          activo: true
        };
      }
    }
  }

  const [insertResult] = await connection.execute(
    `INSERT INTO cliente_sucursales (empresa, ubicacion_id, nombre, direccion, activo)
     VALUES (?, ?, ?, '', 1)`,
    [normalizedCompany, location.id, location.nombre]
  );
  return {
    id: Number(insertResult.insertId),
    empresa: normalizedCompany,
    ubicacionId: Number(location.id),
    nombre: location.nombre,
    direccion: "",
    activo: true
  };
}

async function getClients(search = "") {
  const values = [];
  let where = "";

  if (search) {
    const terms = getServerSearchTerms(search);
    if (terms.length) {
      where = `WHERE ${terms
        .map(
          () => `(CONCAT_WS(' ',
              CONVERT(c.empresa USING utf8mb4) COLLATE utf8mb4_unicode_ci,
              COALESCE(
                NULLIF(CONVERT(s.nombre USING utf8mb4) COLLATE utf8mb4_unicode_ci, ''),
                CONVERT(c.sucursal USING utf8mb4) COLLATE utf8mb4_unicode_ci
              ),
              CONVERT(c.nombre USING utf8mb4) COLLATE utf8mb4_unicode_ci,
              CONVERT(c.rfc USING utf8mb4) COLLATE utf8mb4_unicode_ci,
              CONVERT(c.email USING utf8mb4) COLLATE utf8mb4_unicode_ci,
              CONVERT(c.telefono USING utf8mb4) COLLATE utf8mb4_unicode_ci
            ) COLLATE utf8mb4_unicode_ci LIKE CONVERT(? USING utf8mb4) COLLATE utf8mb4_unicode_ci
            OR EXISTS (
              SELECT 1
              FROM cliente_archivos af
              WHERE af.cliente_id = c.id
                AND CONVERT(af.nombre USING utf8mb4) COLLATE utf8mb4_unicode_ci
                    LIKE CONVERT(? USING utf8mb4) COLLATE utf8mb4_unicode_ci
            ))`
        )
        .join(" AND ")}`;
      terms.forEach((term) => values.push(`%${term}%`, `%${term}%`));
    }
  }

  const [rows] = await pool.execute(
    `SELECT
        c.id,
        c.empresa,
        c.sucursal_id,
        COALESCE(
          NULLIF(CONVERT(s.nombre USING utf8mb4) COLLATE utf8mb4_unicode_ci, ''),
          CONVERT(c.sucursal USING utf8mb4) COLLATE utf8mb4_unicode_ci
        ) AS sucursal,
        c.nombre,
        c.telefono,
        COALESCE(MAX(e.rfc), c.rfc) AS rfc,
        COALESCE(MAX(e.direccion), c.direccion) AS direccion,
        c.email,
        COALESCE(MAX(e.uso_cfdi), c.uso_cfdi) AS uso_cfdi,
        COALESCE(MAX(e.valor_venta), c.valor_venta) AS valor_venta,
        COALESCE(MAX(e.condiciones_pago), c.condiciones_pago) AS condiciones_pago,
        COALESCE(MAX(e.dias_credito), c.dias_credito) AS dias_credito,
        COALESCE(MAX(e.notas), c.notas) AS notas,
        COUNT(a.id) AS archivos_count,
        GROUP_CONCAT(DISTINCT a.nombre ORDER BY a.nombre SEPARATOR ' ') AS archivos_nombres
      FROM clientes c
      LEFT JOIN cliente_sucursales s ON s.id = c.sucursal_id
      LEFT JOIN cliente_empresas e ON e.id = COALESCE(c.empresa_id, s.empresa_id)
      LEFT JOIN cliente_archivos a ON a.cliente_id = c.id
      ${where}
      GROUP BY c.id
      ORDER BY c.id DESC
      LIMIT 150`,
    values
  );

  return rows.map((row) => ({
    id: row.id,
    empresa: row.empresa || "",
    sucursalId: row.sucursal_id || null,
    sucursal: row.sucursal || "",
    nombre: row.nombre || "",
    telefono: row.telefono || "",
    rfc: row.rfc || "",
    direccion: row.direccion || "",
    email: row.email || "",
    usoCfdi: row.uso_cfdi || "",
    valorVenta: Number(row.valor_venta || 0),
    metodoPago: row.condiciones_pago || "contado",
    diasCredito: Number(row.dias_credito || 0),
    notas: row.notas || "",
    archivosCount: Number(row.archivos_count || 0),
    archivosNombres: row.archivos_nombres || "",
    searchText: [
      row.empresa,
      row.sucursal,
      row.nombre,
      row.telefono,
      row.rfc,
      row.email,
      row.uso_cfdi,
      row.condiciones_pago,
      row.archivos_nombres
    ].join(" ")
  }));
}

async function getRegisteredBranches(company = "", connection = pool) {
  const normalizedCompany = String(company || "").trim();
  if (normalizedCompany) {
    const branches = await getClientBranchLocations(normalizedCompany, { includeInactive: false }, connection);
    return [...new Set(branches.map((branch) => String(branch.nombre || "").trim()).filter(Boolean))]
      .sort((a, b) => a.localeCompare(b, "es", { numeric: true }));
  }
  const locations = await getLocationCatalog({ includeInactive: false }, connection);
  return locations
    .map((location) => String(location.nombre || "").trim())
    .filter(Boolean)
    .sort((a, b) => a.localeCompare(b, "es", { numeric: true }));
}

async function getClientFiles(clientId) {
  const [rows] = await pool.execute(
    `SELECT id, cliente_id, tipo, nombre, ruta, usuario_id, created_at
     FROM cliente_archivos
     WHERE cliente_id = ?
     ORDER BY id DESC`,
    [clientId]
  );

  return rows.map((row) => ({
    id: row.id,
    clienteId: row.cliente_id,
    tipo: row.tipo,
    nombre: row.nombre,
    ruta: row.ruta,
    url: `/${row.ruta.replace(/\\/g, "/")}`,
    usuarioId: row.usuario_id,
    createdAt: row.created_at
  }));
}

app.get("/api/branches", requireAuth, async (_req, res) => {
  try {
    await ensureClientBranchAndAssignmentTables();
    res.json({ ok: true, branches: await getLocationCatalog() });
  } catch (error) {
    logServerError("branches-list", error);
    res.status(500).json({ ok: false, message: "No se pudieron cargar las sucursales." });
  }
});

app.get("/api/location-catalog", requireAuth, async (_req, res) => {
  try {
    await ensureClientBranchAndAssignmentTables();
    const locationCatalog = await getLocationCatalog();
    res.json({ ok: true, locationCatalog });
  } catch (error) {
    logServerError("location-catalog-list", error);
    res.status(500).json({ ok: false, message: "No se pudo cargar el catálogo de ubicaciones." });
  }
});

app.post("/api/location-catalog", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const nombre = normalizeClientBranchLabel(req.body.nombre);
  if (!nombre) return res.status(400).json({ ok: false, message: "Escribe el nombre de la ubicación." });
  try {
    await ensureClientBranchAndAssignmentTables();
    const [existingRows] = await pool.execute(
      `SELECT id, activo FROM catalogo_ubicaciones
       WHERE CONVERT(TRIM(nombre) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
             CONVERT(TRIM(?) USING utf8mb4) COLLATE utf8mb4_unicode_ci
       LIMIT 1`,
      [nombre]
    );
    if (existingRows[0]) {
      await pool.execute("UPDATE catalogo_ubicaciones SET activo = 1 WHERE id = ?", [existingRows[0].id]);
      return res.json({
        ok: true,
        locationId: existingRows[0].id,
        existing: true,
        message: "La ubicación ya existía; se reactivó el registro."
      });
    }
    const [result] = await pool.execute(
      "INSERT INTO catalogo_ubicaciones (nombre, activo) VALUES (?, 1)",
      [nombre]
    );
    res.status(201).json({ ok: true, locationId: result.insertId, existing: false });
  } catch (error) {
    logServerError("location-catalog-create", error);
    if (error.code === "ER_DUP_ENTRY") {
      return res.status(409).json({ ok: false, message: "Esa ubicación ya existe en el catálogo." });
    }
    res.status(500).json({ ok: false, message: "No se pudo crear la ubicación de catálogo." });
  }
});

app.put("/api/location-catalog/:id", requireAuth, requireSuperAdminOrAdministration, async (req, res) => {
  const locationId = Number(req.params.id || 0);
  const nombre = normalizeClientBranchLabel(req.body.nombre);
  if (!locationId || !nombre) return res.status(400).json({ ok: false, message: "Ubicación inválida." });

  const connection = await pool.getConnection();
  try {
    await ensureClientBranchAndAssignmentTables();
    await connection.beginTransaction();
    const [rows] = await connection.execute(
      "SELECT id, nombre FROM catalogo_ubicaciones WHERE id = ? FOR UPDATE",
      [locationId]
    );
    if (!rows[0]) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Ubicación no encontrada." });
    }

    await connection.execute(
      "UPDATE catalogo_ubicaciones SET nombre = ?, activo = 1 WHERE id = ?",
      [nombre, locationId]
    );
    await connection.execute(
      "UPDATE cliente_sucursales SET nombre = ? WHERE ubicacion_id = ?",
      [nombre, locationId]
    );
    await connection.execute(
      `UPDATE clientes c
       INNER JOIN cliente_sucursales s ON s.id = c.sucursal_id
       SET c.sucursal = s.nombre
       WHERE s.ubicacion_id = ?`,
      [locationId]
    );
    await connection.execute(
      `UPDATE presupuestos p
       INNER JOIN cliente_sucursales s ON s.id = p.sucursal_id
       SET p.sucursal = s.nombre
       WHERE s.ubicacion_id = ?`,
      [locationId]
    );

    await connection.commit();
    res.json({ ok: true, locationId });
  } catch (error) {
    await connection.rollback();
    logServerError("location-catalog-update", error);
    if (error.code === "ER_DUP_ENTRY") {
      return res.status(409).json({ ok: false, message: "Ya existe otra ubicación con ese nombre." });
    }
    res.status(500).json({ ok: false, message: "No se pudo actualizar la ubicación de catálogo." });
  } finally {
    connection.release();
  }
});

