app.put("/api/clients/:id", requireAuth, async (req, res) => {
  const clientId = Number(req.params.id);
  const parsed = parseClientPayload(req.body, { allowLegacyBranch: true });
  if (!clientId) return res.status(400).json({ ok: false, message: "Cliente invalido." });
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });

  const client = parsed.payload;

  try {
    await ensureClientBranchAndAssignmentTables();
    const [existingRows] = await pool.execute(
      "SELECT id, empresa, empresa_id, sucursal_id, sucursal FROM clientes WHERE id = ? LIMIT 1",
      [clientId]
    );
    const existing = existingRows[0];
    if (!existing) return res.status(404).json({ ok: false, message: "Cliente no encontrado." });

    let branch = client.sucursalId
      ? await resolveClientBranchSelection(client.empresa, client.sucursalId)
      : null;
    if (!branch) {
      branch = await resolveLegacyCompanyBranch(
        pool,
        client.empresa || existing.empresa,
        client.sucursal || existing.sucursal
      );
    }
    if (!branch) {
      return res.status(400).json({
        ok: false,
        message: "Selecciona una ubicación / sucursal registrada para esa empresa."
      });
    }
    client.sucursalId = Number(branch.id);
    client.sucursal = branch.nombre;
    await pool.execute(
      `UPDATE clientes
       SET empresa_id = ?, empresa = ?, sucursal_id = ?, sucursal = ?, nombre = ?, telefono = ?,
           rfc = ?, direccion = ?, email = ?, uso_cfdi = ?, valor_venta = ?,
           condiciones_pago = ?, dias_credito = ?, notas = ?
       WHERE id = ?`,
      [
        branch.empresa_id,
        client.empresa,
        client.sucursalId,
        client.sucursal,
        client.nombre,
        client.telefono,
        branch.empresa_rfc || "",
        branch.empresa_direccion || "",
        client.email,
        branch.empresa_uso_cfdi || "",
        Number(branch.empresa_valor_venta || 1.45),
        branch.empresa_condiciones_pago || "contado",
        Number(branch.empresa_dias_credito || 0),
        branch.empresa_notas || "",
        clientId
      ]
    );

    res.json({ ok: true, clientId });
  } catch (error) {
    logServerError("clients-update", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar el cliente." });
  }
});

app.delete("/api/clients/:id", requireAuth, requireClientDeletePermission, async (req, res) => {
  const clientId = Number(req.params.id);
  if (!clientId) return res.status(400).json({ ok: false, message: "Cliente invalido." });

  const connection = await pool.getConnection();
  try {
    const [[clientRow]] = await connection.execute(
      "SELECT id, empresa, sucursal, nombre FROM clientes WHERE id = ? LIMIT 1",
      [clientId]
    );
    if (!clientRow) {
      return res.status(404).json({ ok: false, message: "El contacto ya no existe." });
    }

    let projectLinks = 0;
    if (await tableExists("presupuestos")) {
      const columns = await getTableColumns("presupuestos");
      if (columns.includes("cliente_id")) {
        const [[row]] = await connection.execute(
          "SELECT COUNT(*) AS total FROM presupuestos WHERE cliente_id = ?",
          [clientId]
        );
        projectLinks += Number(row?.total || 0);
      }
    }
    if (await tableExists("ordenes_servicio")) {
      const columns = await getTableColumns("ordenes_servicio");
      if (columns.includes("cliente_id")) {
        const [[row]] = await connection.execute(
          "SELECT COUNT(*) AS total FROM ordenes_servicio WHERE cliente_id = ?",
          [clientId]
        );
        projectLinks += Number(row?.total || 0);
      }
    }

    if (projectLinks > 0) {
      return res.status(409).json({
        ok: false,
        message: `No se puede eliminar ${clientRow.nombre || "este contacto"} porque está asociado a ${projectLinks} proyecto(s) o presupuesto(s). Reasigna esos registros o edita el contacto primero.`
      });
    }

    await connection.beginTransaction();
    const [files] = await connection.execute("SELECT ruta FROM cliente_archivos WHERE cliente_id = ?", [
      clientId
    ]);
    await connection.execute("DELETE FROM cliente_archivos WHERE cliente_id = ?", [clientId]);
    await connection.execute("DELETE FROM clientes WHERE id = ?", [clientId]);
    await connection.commit();

    for (const file of files) {
      const absolutePath = path.join(__dirname, file.ruta);
      if (absolutePath.startsWith(CLIENT_UPLOAD_DIR)) {
        fs.promises.unlink(absolutePath).catch(() => {});
      }
    }

    res.json({ ok: true });
  } catch (error) {
    await connection.rollback();
    logServerError("clients-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar el cliente." });
  } finally {
    connection.release();
  }
});

