function parseProviderPayload(body) {
  const payload = {
    empresa: String(body.empresa || "").trim(),
    rfc: String(body.rfc || "").trim(),
    direccion: String(body.direccion || "").trim(),
    telefono: String(body.telefono || "").trim(),
    correo: String(body.correo || "").trim(),
    contactoVentas: String(body.contactoVentas || "").trim(),
    contactoCompras: String(body.contactoCompras || "").trim(),
    contactoContabilidad: String(body.contactoContabilidad || "").trim(),
    pago: String(body.pago || "contado").trim().toLowerCase(),
    diasCredito: Number(body.diasCredito ?? body.dias_credito ?? 30),
    banco: String(body.banco || "").trim(),
    cuenta: String(body.cuenta || "").trim(),
    clabe: String(body.clabe || "").trim(),
    spei: String(body.spei || "").trim()
  };

  if (!payload.empresa) return { error: "Completa la empresa del proveedor." };
  if (!["contado", "credito"].includes(payload.pago)) payload.pago = "contado";
  if (payload.pago === "contado") payload.diasCredito = 0;
  if (payload.pago === "credito" && (!Number.isFinite(payload.diasCredito) || payload.diasCredito < 0)) payload.diasCredito = 30;
  payload.diasCredito = Math.max(0, Math.trunc(Number(payload.diasCredito || 0)));

  return { payload };
}

async function getProviders(search = "", options = {}) {
  const values = [];
  let where = "";
  const limitClause = options.limit === null
    ? ""
    : `LIMIT ${Math.max(1, Math.min(1000, Number(options.limit) || 150))}`;

  if (search) {
    const terms = getServerSearchTerms(search);
    if (terms.length) {
      where = `WHERE ${terms
        .map(
          () => `(CONCAT_WS(' ', p.empresa, p.rfc, p.correo, p.telefono, p.ejecutivo_comercial, p.ejecutivo_compras, p.contabilidad) LIKE ?
            OR EXISTS (
              SELECT 1
              FROM proveedor_archivos af
              WHERE af.proveedor_id = p.id AND af.nombre LIKE ?
            ))`
        )
        .join(" AND ")}`;
      terms.forEach((term) => values.push(`%${term}%`, `%${term}%`));
    }
  }

  const [rows] = await pool.execute(
    `SELECT
        p.id,
        p.empresa,
        p.rfc,
        p.direccion,
        p.telefono,
        p.correo,
        p.ejecutivo_comercial,
        p.ejecutivo_compras,
        p.contabilidad,
        p.condiciones_pago,
        p.dias_credito,
        p.banco,
        p.cuenta,
        p.clabe,
        p.spei,
        COUNT(a.id) AS archivos_count,
        GROUP_CONCAT(DISTINCT a.nombre ORDER BY a.nombre SEPARATOR ' ') AS archivos_nombres
      FROM proveedores p
      LEFT JOIN proveedor_archivos a ON a.proveedor_id = p.id
      ${where}
      GROUP BY p.id
      ORDER BY p.empresa ASC, p.id DESC
      ${limitClause}`,
    values
  );

  return rows.map((row) => ({
    id: row.id,
    empresa: row.empresa || "",
    rfc: row.rfc || "",
    direccion: row.direccion || "",
    telefono: row.telefono || "",
    correo: row.correo || "",
    contactoVentas: row.ejecutivo_comercial || "",
    contactoCompras: row.ejecutivo_compras || "",
    contactoContabilidad: row.contabilidad || "",
    pago: row.condiciones_pago || "contado",
    diasCredito: Number(row.dias_credito || 0),
    banco: row.banco || "",
    cuenta: row.cuenta || "",
    clabe: row.clabe || "",
    spei: row.spei || "",
    archivosCount: Number(row.archivos_count || 0),
    archivosNombres: row.archivos_nombres || "",
    searchText: [
      row.empresa,
      row.rfc,
      row.direccion,
      row.telefono,
      row.correo,
      row.ejecutivo_comercial,
      row.ejecutivo_compras,
      row.contabilidad,
      row.condiciones_pago,
      row.dias_credito,
      row.banco,
      row.cuenta,
      row.clabe,
      row.archivos_nombres
    ].join(" ")
  }));
}

async function getProviderFiles(providerId) {
  const [rows] = await pool.execute(
    `SELECT id, proveedor_id, tipo, nombre, ruta, usuario_id, created_at
     FROM proveedor_archivos
     WHERE proveedor_id = ?
     ORDER BY id DESC`,
    [providerId]
  );

  return rows.map((row) => ({
    id: row.id,
    proveedorId: row.proveedor_id,
    tipo: row.tipo,
    nombre: row.nombre,
    ruta: row.ruta,
    url: `/${row.ruta.replace(/\\/g, "/")}`,
    usuarioId: row.usuario_id,
    createdAt: row.created_at
  }));
}

