function parsePricePayload(body) {
  const payload = {
    tipo: String(body.tipo || "").trim(),
    item: String(body.item || "").trim(),
    costo: Number(body.costo || 0)
  };

  if (!PRICE_TYPES.includes(payload.tipo)) payload.tipo = PRICE_TYPES[0];
  if (!payload.item) return { error: "Captura el item." };
  if (Number.isNaN(payload.costo) || payload.costo < 0) {
    return { error: "Captura un costo valido." };
  }

  return { payload };
}

async function getPriceItems(search = "") {
  const values = [];
  let where = "";

  if (search) {
    where = "WHERE tipo LIKE ? OR item LIKE ?";
    const term = `%${search}%`;
    values.push(term, term);
  }

  const [rows] = await pool.execute(
    `SELECT id, tipo, item, costo, created_at
     FROM lista_precios
     ${where}
     ORDER BY id DESC
     LIMIT 200`,
    values
  );

  return rows.map((row) => ({
    id: row.id,
    tipo: row.tipo,
    item: row.item,
    costo: Number(row.costo || 0),
    createdAt: row.created_at
  }));
}

