async function getFixedExpenseCatalogIdsByName(gasto, connection = pool) {
  if (!String(gasto || "").trim()) return [];
  const [rows] = await connection.execute(
    `SELECT id
     FROM gastos_fijos
     WHERE COALESCE(es_catalogo, 1) = 1
       AND LOWER(TRIM(gasto)) = LOWER(TRIM(?))`,
    [gasto]
  );
  return rows.map((row) => Number(row.id)).filter(Boolean);
}

function businessDateOnly(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: process.env.BUSINESS_TIME_ZONE || "America/Mexico_City",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(date);
  const byType = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return `${byType.year}-${byType.month}-${byType.day}`;
}

function fixedExpensePeriod(value) {
  const date = formatDateOnly(value);
  return date ? date.slice(0, 7) : "";
}

async function createAutomaticFixedExpensePeriod(connection, fixed, scheduledDate, userId = null) {
  const period = fixedExpensePeriod(scheduledDate);
  if (!period) return null;
  const [existing] = await connection.execute(
    `SELECT id FROM ocgf_compras
     WHERE gasto_fijo_id = ? AND periodo_generacion = ?
     LIMIT 1`,
    [fixed.id, period]
  );
  if (existing.length) return { id: existing[0].id, created: false };

  const folio = await generateOcgfFolio(connection);
  const description = fixed.descripcion_automatica || `${fixed.gasto} ${period}`;
  const [purchaseResult] = await connection.execute(
    `INSERT INTO ocgf_compras
      (gasto_fijo_id, gasto, sucursal, proveedor_id, proveedor_nombre, descripcion,
       fecha, periodo_generacion, generado_automaticamente, presupuesto, folio,
       estado, estado_registro, usuario_id, updated_by_user_id)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, 'OCGF Generada', 'Activa', ?, ?)`,
    [
      fixed.id,
      fixed.gasto || "",
      fixed.sucursal || "",
      fixed.proveedor_id,
      fixed.proveedor_nombre || "",
      description,
      formatDateOnly(scheduledDate),
      period,
      Number(fixed.presupuesto || 0),
      folio,
      userId || null,
      userId || null
    ]
  );
  const ocgfId = purchaseResult.insertId;
  const [orderResult] = await connection.execute(
    `INSERT INTO ocgf_ordenes
      (ocgf_id, tipo, folio, version, estatus, retencion_activa, retencion_monto,
       sin_iva, usuario_id, updated_by_user_id)
     VALUES (?, 'borrador', '', 0, 'Borrador', 0, 0, 0, ?, ?)`,
    [ocgfId, userId || null, userId || null]
  );
  await connection.execute(
    `INSERT INTO ocgf_orden_partidas
      (orden_id, presupuesto, proveedor_id, proveedor_nombre, descripcion,
       cantidad, precio_unitario, total)
     VALUES (?, 'Gastos Fijos', ?, ?, ?, 1, ?, ?)`,
    [
      orderResult.insertId,
      fixed.proveedor_id,
      fixed.proveedor_nombre || "",
      description,
      Number(fixed.presupuesto || 0),
      Number(fixed.presupuesto || 0)
    ]
  );
  return { id: ocgfId, created: true };
}

async function generateDueFixedExpenseOrders({ userId = null, today = new Date() } = {}) {
  const todayValue = typeof today === "string" ? formatDateOnly(today) : businessDateOnly(today);
  if (!todayValue) return [];
  const [dueRows] = await pool.execute(
    `SELECT gf.*, p.empresa AS proveedor_nombre
     FROM gastos_fijos gf
     LEFT JOIN proveedores p ON p.id = gf.proveedor_id
     WHERE COALESCE(gf.es_catalogo, 1) = 1
       AND gf.generacion_automatica = 1
       AND gf.estado_registro = 'Activo'
       AND gf.proxima_generacion IS NOT NULL
       AND gf.proxima_generacion <= ?
     ORDER BY gf.proxima_generacion, gf.id
     LIMIT 200`,
    [todayValue]
  );
  const generated = [];

  for (const due of dueRows) {
    const connection = await pool.getConnection();
    let folioLockAcquired = false;
    const generatedForExpense = [];
    try {
      const [lockRows] = await connection.query("SELECT GET_LOCK('dalvo_ocgf_automatic_generation', 10) AS acquired");
      folioLockAcquired = Number(lockRows[0]?.acquired || 0) === 1;
      if (!folioLockAcquired) throw new Error("No se pudo obtener el bloqueo para generar folios OCGF.");
      await connection.beginTransaction();
      const [lockedRows] = await connection.execute(
        `SELECT gf.*, p.empresa AS proveedor_nombre
         FROM gastos_fijos gf
         LEFT JOIN proveedores p ON p.id = gf.proveedor_id
         WHERE gf.id = ? FOR UPDATE`,
        [due.id]
      );
      const fixed = lockedRows[0];
      if (!fixed || !fixed.generacion_automatica || fixed.estado_registro !== "Activo") {
        await connection.rollback();
        continue;
      }

      let nextDate = formatDateOnly(fixed.proxima_generacion);
      let lastGenerated = formatDateOnly(fixed.ultima_generacion);
      let iterations = 0;
      while (nextDate && nextDate <= todayValue && iterations < 24) {
        if (fixed.fecha_fin_recurrencia && nextDate > formatDateOnly(fixed.fecha_fin_recurrencia)) break;
        const result = await createAutomaticFixedExpensePeriod(connection, fixed, nextDate, userId);
        if (result?.created) {
          generatedForExpense.push({ fixedExpenseId: fixed.id, ocgfId: result.id, period: fixedExpensePeriod(nextDate) });
        }
        lastGenerated = nextDate;
        nextDate = formatDateOnly(addRecurrence(nextDate, fixed.recurrencia, fixed.dia_generacion));
        iterations += 1;
      }

      const finished = Boolean(fixed.fecha_fin_recurrencia && nextDate && nextDate > formatDateOnly(fixed.fecha_fin_recurrencia));
      await connection.execute(
        `UPDATE gastos_fijos
         SET ultima_generacion = ?,
             proxima_generacion = ?,
             generacion_automatica = CASE WHEN ? THEN 0 ELSE generacion_automatica END,
             estado_registro = CASE WHEN ? THEN 'Finalizado' ELSE estado_registro END
         WHERE id = ?`,
        [lastGenerated || null, finished ? null : nextDate, finished ? 1 : 0, finished ? 1 : 0, fixed.id]
      );
      await connection.commit();
      generated.push(...generatedForExpense);
    } catch (error) {
      try {
        await connection.rollback();
      } catch (_rollbackError) {
        // La transacción puede no haberse iniciado si no se obtuvo el bloqueo.
      }
      logServerError(`fixed-expense-auto-${due.id}`, error);
    } finally {
      if (folioLockAcquired) {
        try {
          await connection.query("SELECT RELEASE_LOCK('dalvo_ocgf_automatic_generation')");
        } catch (releaseError) {
          logServerError(`fixed-expense-auto-lock-release-${due.id}`, releaseError);
        }
      }
      connection.release();
    }
  }

  return generated;
}

function parseOcgfRows(rows) {
  if (!Array.isArray(rows)) return [];
  return rows.map((row, index) => {
    const cantidad = Number(row.cantidad || 0);
    const precioUnitario = Number(row.precioUnitario || row.precio_unitario || 0);
    const parsed = {
      presupuesto: String(row.presupuesto || "Gastos Fijos").trim() || "Gastos Fijos",
      proveedorId: Number(row.proveedorId || 0) || null,
      proveedorNombre: String(row.proveedorNombre || "").trim(),
      descripcion: String(row.descripcion || "").trim(),
      cantidad,
      precioUnitario,
      total: cantidad * precioUnitario
    };
    if (!parsed.proveedorNombre || !parsed.descripcion || parsed.cantidad <= 0 || parsed.precioUnitario <= 0) {
      const error = new Error(`Completa proveedor, descripción, cantidad y precio unitario en la partida OCGF ${index + 1}.`);
      error.statusCode = 400;
      throw error;
    }
    return parsed;
  });
}

async function generateOcgfFolio(connection) {
  const [rows] = await connection.execute(
    `SELECT folio
     FROM ocgf_compras
     WHERE folio REGEXP '^OCGF[0-9]+$'
     ORDER BY CAST(SUBSTRING(folio, 5) AS UNSIGNED) DESC
     LIMIT 1`
  );
  const last = rows[0]?.folio || "OCGF0000";
  const number = Number(String(last).replace(/\D/g, "")) + 1;
  return `OCGF${String(number).padStart(4, "0")}`;
}

function normalizeOcgfStatus(status) {
  const allowed = ["OCGF Generada", "Aprobada", "No aprobada", "Orden cerrada", "Factura Cargada", "OCGF Pagada"];
  return allowed.includes(status) ? status : "OCGF Generada";
}

async function getOcgfOrderRows(orderId) {
  const [rows] = await pool.execute(
    `SELECT id, presupuesto, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario, total
     FROM ocgf_orden_partidas
     WHERE orden_id = ?
     ORDER BY id`,
    [orderId]
  );
  return rows.map((row) => ({
    id: row.id,
    presupuesto: row.presupuesto || "Gastos Fijos",
    proveedorId: row.proveedor_id || null,
    proveedorNombre: row.proveedor_nombre || "",
    descripcion: row.descripcion || "",
    cantidad: Number(row.cantidad || 0),
    precioUnitario: Number(row.precio_unitario || 0),
    total: Number(row.total || 0)
  }));
}

async function replaceOcgfOrderRows(connection, orderId, rows) {
  await connection.execute("DELETE FROM ocgf_orden_partidas WHERE orden_id = ?", [orderId]);
  for (const row of rows) {
    await connection.execute(
      `INSERT INTO ocgf_orden_partidas
        (orden_id, presupuesto, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario, total)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        orderId,
        row.presupuesto,
        row.proveedorId,
        row.proveedorNombre,
        row.descripcion,
        row.cantidad,
        row.precioUnitario,
        row.total
      ]
    );
  }
}

async function getOcgfOrderById(orderId) {
  const [rows] = await pool.execute(
    `SELECT id, ocgf_id, tipo, folio, version, estatus, retencion_activa, retencion_monto, sin_iva, pdf_ruta,
            usuario_id, created_at, updated_at
     FROM ocgf_ordenes
     WHERE id = ?
     LIMIT 1`,
    [orderId]
  );
  const order = rows[0];
  if (!order) return null;
  const items = await getOcgfOrderRows(order.id);
  return {
    id: order.id,
    ocgfId: order.ocgf_id,
    tipo: order.tipo || "borrador",
    folio: order.folio || "",
    version: Number(order.version || 0),
    estatus: order.estatus || "Borrador",
    retencionActiva: Boolean(order.retencion_activa),
    retencionMonto: Number(order.retencion_monto || 0),
    sinIva: Boolean(order.sin_iva),
    pdfRuta: order.pdf_ruta || "",
    pdfUrl: order.pdf_ruta ? `/${String(order.pdf_ruta).replace(/\\/g, "/")}` : "",
    usuarioId: order.usuario_id || null,
    createdAt: order.created_at,
    updatedAt: order.updated_at,
    items
  };
}

async function getOcgfDraft(ocgfId) {
  const [rows] = await pool.execute(
    "SELECT id FROM ocgf_ordenes WHERE ocgf_id = ? AND tipo = 'borrador' ORDER BY id DESC LIMIT 1",
    [ocgfId]
  );
  return rows.length ? getOcgfOrderById(rows[0].id) : null;
}

async function getOcgfVersions(ocgfId) {
  const [rows] = await pool.execute(
    "SELECT id FROM ocgf_ordenes WHERE ocgf_id = ? AND tipo = 'version' ORDER BY version DESC, id DESC",
    [ocgfId]
  );
  const versions = [];
  for (const row of rows) {
    const order = await getOcgfOrderById(row.id);
    if (order) versions.push(order);
  }
  return versions;
}

async function getOcgfFiles(ocgfId) {
  const [rows] = await pool.execute(
    `SELECT id, ocgf_id, tipo, nombre, ruta, usuario_id, created_at
     FROM ocgf_archivos
     WHERE ocgf_id = ?
     ORDER BY id DESC`,
    [ocgfId]
  );
  return rows.map((row) => ({
    id: row.id,
    ocgfId: row.ocgf_id,
    tipo: row.tipo || "Cotización proveedor",
    nombre: row.nombre || "",
    ruta: row.ruta || "",
    url: row.ruta ? `/${String(row.ruta).replace(/\\/g, "/")}` : "",
    usuarioId: row.usuario_id || null,
    createdAt: row.created_at
  }));
}

async function calculateOcgfUsedTotal(connection, whereSql, values = [], options = {}) {
  const params = [...values];
  const excludeOrderId = Number(options.excludeOrderId || 0);
  const excludeSql = excludeOrderId ? "AND o.id <> ?" : "";
  if (excludeOrderId) params.push(excludeOrderId);
  const [rows] = await connection.execute(
    `SELECT COALESCE(SUM(total_orden), 0) AS total
     FROM (
       SELECT
         o.id,
         GREATEST(
           0,
           COALESCE(SUM(p.total), 0) * CASE WHEN MAX(o.sin_iva) = 1 THEN 1 ELSE 1.16 END
           - CASE WHEN MAX(o.retencion_activa) = 1 THEN COALESCE(MAX(o.retencion_monto), 0) ELSE 0 END
         ) AS total_orden
       FROM ocgf_ordenes o
       INNER JOIN ocgf_compras g ON g.id = o.ocgf_id
       LEFT JOIN gastos_fijos gf ON gf.id = g.gasto_fijo_id
       LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
       WHERE ${whereSql}
         AND o.tipo = 'version'
         AND o.estatus <> 'Cancelada'
         ${excludeSql}
       GROUP BY o.id
     ) usados`,
    params
  );
  return Number(rows[0]?.total || 0);
}

async function calculateOcgfUsedByFixedExpense(fixedExpenseId, options = {}) {
  const id = Number(fixedExpenseId || 0);
  if (!id) return 0;
  const connection = options.connection || pool;
  const [rows] = await connection.execute("SELECT gasto FROM gastos_fijos WHERE id = ? LIMIT 1", [id]);
  const expenseName = String(rows[0]?.gasto || "").trim();
  if (!expenseName) {
    return calculateOcgfUsedTotal(connection, "g.gasto_fijo_id = ?", [id], options);
  }
  return calculateOcgfUsedByFixedExpenseName(expenseName, options);
}

async function calculateOcgfUsedByFixedExpenseName(expenseName, options = {}) {
  const name = String(expenseName || "").trim();
  if (!name) return 0;
  return calculateOcgfUsedTotal(
    options.connection || pool,
    "LOWER(TRIM(COALESCE(NULLIF(g.gasto, ''), NULLIF(gf.gasto, ''), ''))) = LOWER(TRIM(?))",
    [name],
    options
  );
}

async function calculateOcgfUsed(ocgfId, options = {}) {
  const [expenseRows] = await (options.connection || pool).execute(
    `SELECT g.id,
            g.gasto_fijo_id,
            g.generado_automaticamente,
            g.periodo_generacion,
            COALESCE(NULLIF(g.gasto, ''), NULLIF(gf.gasto, '')) AS gasto
     FROM ocgf_compras g
     LEFT JOIN gastos_fijos gf ON gf.id = g.gasto_fijo_id
     WHERE g.id = ?
     LIMIT 1`,
    [ocgfId]
  );
  const expense = expenseRows[0];
  if (!expense) return 0;
  if (expense.generado_automaticamente && expense.periodo_generacion) {
    return calculateOcgfUsedTotal(options.connection || pool, "o.ocgf_id = ?", [ocgfId], options);
  }
  if (expense.gasto) {
    return calculateOcgfUsedByFixedExpenseName(expense.gasto, options);
  }
  if (expense.gasto_fijo_id) {
    return calculateOcgfUsedByFixedExpense(expense.gasto_fijo_id, options);
  }
  return calculateOcgfUsedTotal(options.connection || pool, "o.ocgf_id = ?", [ocgfId], options);
}

async function validateOcgfBudgetAvailability(connection, ocgfId, items, options = {}) {
  const currentOrderId = options.currentOrderId || null;
  const retencionActiva = Boolean(options.retencionActiva);
  const retencionMonto = Number(options.retencionMonto || 0);
  const sinIva = Boolean(options.sinIva);
  const expense = await getOcgfById(ocgfId);
  if (!expense) return "No se encontró el gasto fijo.";
  const subtotal = items.reduce((sum, row) => sum + Number(row.total || 0), 0);
  const requested = Math.max(0, subtotal * (sinIva ? 1 : 1.16) - (retencionActiva ? retencionMonto : 0));
  const used = await calculateOcgfUsed(ocgfId, { connection, excludeOrderId: currentOrderId });
  const available = Number(expense.presupuesto || 0) + Number(expense.presupuestoAdicional || 0) - used;
  if (requested > available + 0.005) {
    return `No hay presupuesto disponible para este gasto fijo. Disponible: ${formatCurrencyServer(available)}.`;
  }
  return null;
}

async function getOcgfPurchases(search = "") {
  await ensureFixedExpensesTable();
  await ensureFixedExpensePurchaseTables();
  const values = [];
  let where = "";
  const hasNumericSearch = /\d/.test(String(search || ""));
  if (search && !hasNumericSearch) {
    const term = `%${search}%`;
    where = `WHERE o.gasto LIKE ? OR o.folio LIKE ? OR o.sucursal LIKE ? OR o.proveedor_nombre LIKE ?
      OR o.descripcion LIKE ? OR o.estado LIKE ?
      OR EXISTS (
        SELECT 1
        FROM ocgf_archivos af
        WHERE af.ocgf_id = o.id AND af.nombre LIKE ?
      )`;
    values.push(term, term, term, term, term, term, term);
  }
  const [rows] = await pool.execute(
    `SELECT
        o.id,
        o.gasto_fijo_id,
        o.gasto,
        o.sucursal,
        o.proveedor_id,
        o.proveedor_nombre,
        o.descripcion,
        o.fecha,
        COALESCE(NULLIF(gf.presupuesto, 0), o.presupuesto) AS presupuesto,
        COALESCE(gf.presupuesto_adicional, 0) AS presupuesto_adicional,
        o.folio,
        o.estado,
        o.created_at,
        o.updated_at,
        COALESCE(NULLIF(CONCAT_WS(' ', creator.nombre, creator.apellido), ''), creator.usuario, '') AS owner_nombre,
        COALESCE(NULLIF(CONCAT_WS(' ', updater.nombre, updater.apellido), ''), updater.usuario, '') AS updated_by_nombre,
        (SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', af.tipo, af.nombre) ORDER BY af.nombre SEPARATOR ' ')
         FROM ocgf_archivos af
         WHERE af.ocgf_id = o.id) AS archivos_nombres,
        COALESCE(COUNT(DISTINCT CASE
          WHEN ord.tipo = 'version'
            AND LOWER(TRIM(COALESCE(ord.estatus, ''))) IN ('pendiente de aprobación', 'pendiente de aprobacion')
          THEN ord.id
          ELSE NULL
        END), 0) AS approval_pending_count,
        COALESCE(SUM(CASE WHEN ord.tipo = 'version' AND ord.estatus <> 'Cancelada' THEN part.total ELSE 0 END), 0) AS subtotal,
        COALESCE(MAX(CASE WHEN ord.tipo = 'version' AND ord.estatus <> 'Cancelada' THEN ord.retencion_monto ELSE 0 END), 0) AS retencion,
        COALESCE(MAX(CASE WHEN ord.tipo = 'version' AND ord.estatus <> 'Cancelada' THEN ord.retencion_activa ELSE 0 END), 0) AS retencion_activa,
        COALESCE(MAX(CASE WHEN ord.tipo = 'version' AND ord.estatus <> 'Cancelada' THEN ord.sin_iva ELSE 0 END), 0) AS sin_iva
     FROM ocgf_compras o
     LEFT JOIN gastos_fijos gf ON gf.id = o.gasto_fijo_id AND COALESCE(gf.es_catalogo, 1) = 1
     LEFT JOIN usuarios creator ON creator.user_id = o.usuario_id
     LEFT JOIN usuarios updater ON updater.user_id = COALESCE(o.updated_by_user_id, o.usuario_id)
     LEFT JOIN ocgf_ordenes ord ON ord.ocgf_id = o.id
     LEFT JOIN ocgf_orden_partidas part ON part.orden_id = ord.id
     ${where}
     GROUP BY o.id, o.gasto_fijo_id, o.gasto, o.sucursal, o.proveedor_id, o.proveedor_nombre,
       o.descripcion, o.fecha, o.presupuesto, gf.presupuesto, gf.presupuesto_adicional, o.folio, o.estado, o.created_at, o.updated_at,
       creator.nombre, creator.apellido, creator.usuario, updater.nombre, updater.apellido, updater.usuario
     ORDER BY o.id DESC
     LIMIT 200`,
    values
  );
  const normalizedSearch = normalizeSearchText(search);
  const expenses = await Promise.all(rows.map(async (row) => {
    const subtotal = Number(row.subtotal || 0);
    const retencion = row.retencion_activa ? Number(row.retencion || 0) : 0;
    const amount = Math.max(0, subtotal * (row.sin_iva ? 1 : 1.16) - retencion);
    const presupuestoAsignado = Number(row.presupuesto || 0);
    const presupuestoAdicional = Number(row.presupuesto_adicional || 0);
    const usadoGlobal = await calculateOcgfUsed(row.id);
    const presupuestoDisponible = Math.max(0, presupuestoAsignado + presupuestoAdicional - usadoGlobal);
    return {
      id: row.id,
      gastoFijoId: row.gasto_fijo_id || null,
      gasto: row.gasto || "",
      sucursal: row.sucursal || "",
      proveedorId: row.proveedor_id || null,
      proveedorNombre: row.proveedor_nombre || "",
      descripcion: row.descripcion || "",
      fecha: row.fecha,
      presupuesto: presupuestoAsignado,
      presupuestoAsignado,
      presupuestoAdicional,
      presupuestoDisponible,
      usadoGlobal,
      folio: row.folio || "",
      estado: row.estado || "OCGF Generada",
      monto: amount,
      approvalPending: Number(row.approval_pending_count || 0),
      archivosNombres: row.archivos_nombres || "",
      owner: row.owner_nombre || "Sin dato",
      updatedBy: row.updated_by_nombre || row.owner_nombre || "Sin dato",
      searchText: [
        row.gasto,
        row.folio,
        row.sucursal,
        row.proveedor_nombre,
        row.descripcion,
        row.estado,
        row.archivos_nombres,
        row.owner_nombre,
        row.updated_by_nombre,
        buildMoneySearchTermsServer(
          amount,
          presupuestoAsignado,
          presupuestoAdicional,
          presupuestoDisponible,
          usadoGlobal
        )
      ].join(" "),
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  }));
  return normalizedSearch ? expenses.filter((item) => purchaseMatchesSearch(item, normalizedSearch)) : expenses;
}

async function getOcgfById(ocgfId) {
  await ensureFixedExpensesTable();
  const [rows] = await pool.execute(
    `SELECT o.*,
            COALESCE(NULLIF(gf.presupuesto, 0), o.presupuesto) AS presupuesto_actual,
            COALESCE(gf.presupuesto_adicional, 0) AS presupuesto_adicional_actual,
            COALESCE(NULLIF(gf.gasto, ''), o.gasto) AS gasto_actual,
            COALESCE(NULLIF(o.sucursal, ''), NULLIF(gf.sucursal, '')) AS sucursal_actual,
            COALESCE(NULLIF(CONCAT_WS(' ', creator.nombre, creator.apellido), ''), creator.usuario, '') AS owner_nombre,
            COALESCE(NULLIF(CONCAT_WS(' ', updater.nombre, updater.apellido), ''), updater.usuario, '') AS updated_by_nombre
     FROM ocgf_compras o
     LEFT JOIN gastos_fijos gf ON gf.id = o.gasto_fijo_id AND COALESCE(gf.es_catalogo, 1) = 1
     LEFT JOIN usuarios creator ON creator.user_id = o.usuario_id
     LEFT JOIN usuarios updater ON updater.user_id = COALESCE(o.updated_by_user_id, o.usuario_id)
     WHERE o.id = ?
     LIMIT 1`,
    [ocgfId]
  );
  const row = rows[0];
  if (!row) return null;
  const used = await calculateOcgfUsed(ocgfId);
  const assignedBudget = Number(row.presupuesto_actual || row.presupuesto || 0);
  const additionalBudget = Number(row.presupuesto_adicional_actual || 0);
  const draft = await getOcgfDraft(ocgfId);
  const versions = await getOcgfVersions(ocgfId);
  const files = await getOcgfFiles(ocgfId);
  const reassignments = await getExpenseReassignmentHistory("OCGF", [ocgfId]);
  return {
    id: row.id,
    gastoFijoId: row.gasto_fijo_id || null,
    gasto: row.gasto_actual || row.gasto || "",
    sucursal: row.sucursal_actual || row.sucursal || "",
    proveedorId: row.proveedor_id || null,
    proveedorNombre: row.proveedor_nombre || "",
    descripcion: row.descripcion || "",
    fecha: row.fecha,
    presupuesto: assignedBudget,
    presupuestoAdicional: additionalBudget,
    folio: row.folio || "",
    estado: row.estado || "OCGF Generada",
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    owner: row.owner_nombre || "Sin dato",
    updatedBy: row.updated_by_nombre || row.owner_nombre || "Sin dato",
    budget: {
      asignado: assignedBudget,
      adicional: additionalBudget,
      usado: used,
      disponible: Math.max(0, assignedBudget + additionalBudget - used)
    },
    draft,
    versions,
    files,
    reassignments
  };
}

async function touchOcgfUpdatedAt(ocgfId, connection = pool, userId = null) {
  if (!ocgfId) return;
  await connection.execute(
    `UPDATE ocgf_compras
     SET updated_at = CURRENT_TIMESTAMP,
         updated_by_user_id = COALESCE(?, updated_by_user_id)
     WHERE id = ?`,
    [userId || null, ocgfId]
  );
}

