app.post("/api/fixed-expenses", requireAuth, async (req, res) => {
  const parsed = parseFixedExpensePayload(req.body);
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });
  const expense = parsed.payload;

  try {
    await ensureFixedExpensesTable();
    await ensureFixedExpensePurchaseTables();
    await ensureClientBranchAndAssignmentTables();
    const selectedBranch = resolveFixedExpenseBranch(expense.sucursal);
    if (!selectedBranch) {
      return res.status(400).json({ ok: false, message: "Selecciona GTO, SLP o QRO como sucursal." });
    }
    expense.sucursal = selectedBranch;
    const duplicate = await findFixedExpenseDuplicate(expense);
    if (duplicate) {
      return res.status(409).json({ ok: false, message: "Ya existe un gasto fijo con el mismo gasto, recurrencia y presupuesto." });
    }

    const automatic = expense.generacionAutomatica && expense.estadoRegistro === "Activo";
    const [result] = await pool.execute(
      `INSERT INTO gastos_fijos
        (proveedor_id, gasto, sucursal, recurrencia, descripcion_automatica,
         generacion_automatica, dia_generacion, fecha_inicio_recurrencia,
         fecha_fin_recurrencia, proxima_generacion, estado_registro,
         presupuesto, presupuesto_adicional, es_catalogo)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)`,
      [
        expense.proveedorId,
        expense.gasto,
        expense.sucursal || "",
        expense.recurrencia,
        expense.descripcionAutomatica,
        automatic ? 1 : 0,
        expense.diaGeneracion,
        expense.fechaInicio,
        expense.fechaFin || null,
        automatic ? expense.proximaGeneracion : null,
        expense.estadoRegistro,
        expense.presupuesto,
        expense.presupuestoAdicional
      ]
    );
    const generated = automatic
      ? await generateDueFixedExpenseOrders({ userId: req.session.user?.id || null })
      : [];
    res.status(201).json({ ok: true, expenseId: result.insertId, generated });
  } catch (error) {
    logServerError("fixed-expenses-create", error);
    res.status(500).json({ ok: false, message: "No se pudo crear el gasto fijo." });
  }
});

app.put("/api/fixed-expenses/:id", requireAuth, async (req, res) => {
  const expenseId = Number(req.params.id);
  const parsed = parseFixedExpensePayload(req.body);
  if (!expenseId) return res.status(400).json({ ok: false, message: "Gasto fijo inválido." });
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });
  const expense = parsed.payload;

  try {
    await ensureFixedExpensesTable();
    await ensureFixedExpensePurchaseTables();
    await ensureClientBranchAndAssignmentTables();
    const selectedBranch = resolveFixedExpenseBranch(expense.sucursal);
    if (!selectedBranch) {
      return res.status(400).json({ ok: false, message: "Selecciona GTO, SLP o QRO como sucursal." });
    }
    expense.sucursal = selectedBranch;
    const currentExpense = await getFixedExpenseCatalogRow(expenseId);
    if (!currentExpense || String(currentExpense.es_catalogo) === "0") {
      return res.status(404).json({ ok: false, message: "No se encontró el gasto fijo activo." });
    }

    const duplicate = await findFixedExpenseDuplicate(expense, expenseId);
    if (duplicate) {
      return res.status(409).json({ ok: false, message: "Ya existe un gasto fijo con el mismo gasto, recurrencia y presupuesto." });
    }

    const automatic = expense.generacionAutomatica && expense.estadoRegistro === "Activo";
    let nextGeneration = automatic ? expense.proximaGeneracion : null;
    const scheduleChanged =
      normalizeFixedExpenseRecurrence(currentExpense.recurrencia) !== expense.recurrencia ||
      Number(currentExpense.dia_generacion || 1) !== expense.diaGeneracion ||
      formatDateOnly(currentExpense.fecha_inicio_recurrencia) !== expense.fechaInicio;
    if (automatic && scheduleChanged) {
      nextGeneration = formatDateOnly(firstScheduledDate({
        startDate: expense.fechaInicio,
        recurrence: expense.recurrencia,
        generationDay: expense.diaGeneracion
      }));
    } else if (automatic && !nextGeneration) {
      nextGeneration = formatDateOnly(currentExpense.proxima_generacion) || formatDateOnly(firstScheduledDate({
        startDate: expense.fechaInicio,
        recurrence: expense.recurrencia,
        generationDay: expense.diaGeneracion
      }));
    }

    const [result] = await pool.execute(
      `UPDATE gastos_fijos
       SET proveedor_id = ?, gasto = ?, sucursal = ?, recurrencia = ?,
           descripcion_automatica = ?, generacion_automatica = ?, dia_generacion = ?,
           fecha_inicio_recurrencia = ?, fecha_fin_recurrencia = ?,
           proxima_generacion = ?, estado_registro = ?, presupuesto = ?,
           presupuesto_adicional = ?
       WHERE id = ? AND COALESCE(es_catalogo, 1) = 1`,
      [
        expense.proveedorId,
        expense.gasto,
        expense.sucursal || "",
        expense.recurrencia,
        expense.descripcionAutomatica,
        automatic ? 1 : 0,
        expense.diaGeneracion,
        expense.fechaInicio,
        expense.fechaFin || null,
        automatic ? nextGeneration : null,
        expense.estadoRegistro,
        expense.presupuesto,
        expense.presupuestoAdicional,
        expenseId
      ]
    );
    if (!result.affectedRows) {
      return res.status(404).json({ ok: false, message: "No se pudo actualizar el gasto fijo activo." });
    }

    const generated = automatic
      ? await generateDueFixedExpenseOrders({ userId: req.session.user?.id || null })
      : [];
    res.json({ ok: true, expenseId, generated });
  } catch (error) {
    logServerError("fixed-expenses-update", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar el gasto fijo." });
  }
});

