app.post("/api/purchases/fixed-expenses", requireAuth, async (req, res) => {
  const gastoFijoId = Number(req.body.gastoFijoId || 0);
  let proveedorId = Number(req.body.proveedorId || 0) || null;
  const proveedorNombre = String(req.body.proveedorNombre || "").trim();
  const sucursalInput = String(req.body.sucursal || "").trim();
  const sucursal = resolveFixedExpenseBranch(sucursalInput);
  const descripcion = String(req.body.descripcion || "").trim();
  const fecha = String(req.body.fecha || new Date().toISOString().slice(0, 10)).slice(0, 10);
  if (!gastoFijoId) return res.status(400).json({ ok: false, message: "Selecciona un gasto fijo." });
  if (!sucursal) return res.status(400).json({ ok: false, message: "Selecciona GTO, SLP o QRO como sucursal de la OCGF." });
  if (!descripcion) return res.status(400).json({ ok: false, message: "Captura la descripción del gasto fijo." });

  const connection = await pool.getConnection();
  try {
    await ensureFixedExpensesTable();
    await ensureFixedExpensePurchaseTables();
    const [fixedRows] = await connection.execute(
      "SELECT id, gasto, sucursal, presupuesto, presupuesto_adicional FROM gastos_fijos WHERE id = ? LIMIT 1",
      [gastoFijoId]
    );
    let providerRows = [];
    if (proveedorId) {
      [providerRows] = await connection.execute("SELECT id, empresa FROM proveedores WHERE id = ? LIMIT 1", [proveedorId]);
    } else if (proveedorNombre) {
      [providerRows] = await connection.execute(
        `SELECT id, empresa FROM proveedores
         WHERE CONVERT(LOWER(TRIM(empresa)) USING utf8mb4) COLLATE utf8mb4_unicode_ci =
               CONVERT(LOWER(TRIM(?)) USING utf8mb4) COLLATE utf8mb4_unicode_ci
         LIMIT 1`,
        [proveedorNombre]
      );
      proveedorId = Number(providerRows[0]?.id || 0) || null;
    }
    const fixed = fixedRows[0];
    const provider = providerRows[0];
    if (!fixed) return res.status(404).json({ ok: false, message: "Gasto fijo no encontrado." });
    if (!provider) return res.status(400).json({ ok: false, message: "Selecciona un proveedor registrado." });

    await connection.beginTransaction();
    const folio = await generateOcgfFolio(connection);
    const [result] = await connection.execute(
      `INSERT INTO ocgf_compras
        (gasto_fijo_id, gasto, sucursal, proveedor_id, proveedor_nombre, descripcion, fecha, presupuesto, folio, estado, usuario_id, updated_by_user_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'OCGF Generada', ?, ?)`,
      [
        fixed.id,
        fixed.gasto || "",
        sucursal,
        provider.id,
        provider.empresa || "",
        descripcion,
        fecha,
        Number(fixed.presupuesto || 0),
        folio,
        req.session.user?.id || null,
        req.session.user?.id || null
      ]
    );
    await connection.commit();
    const expense = await getOcgfById(result.insertId);
    res.status(201).json({ ok: true, expense });
  } catch (error) {
    await connection.rollback();
    logServerError("ocgf-create", error);
    res.status(500).json({ ok: false, message: "No se pudo generar el gasto fijo." });
  } finally {
    connection.release();
  }
});

