app.patch("/api/purchases/fixed-expenses/:id/reassign", requireAuth, requireSuperAdmin, async (req, res) => {
  const ocgfId = Number(req.params.id || 0);
  const destinationFixedExpenseId = Number(req.body.gastoFijoId || req.body.destinationId || 0);
  const reason = String(req.body.motivo || req.body.reason || "").trim().slice(0, 500);
  if (!ocgfId || !destinationFixedExpenseId) {
    return res.status(400).json({ ok: false, message: "Selecciona la OCGF y el gasto fijo destino." });
  }
  if (!reason) {
    return res.status(400).json({ ok: false, message: "Captura el motivo de la reasignación para conservar la auditoría." });
  }

  const connection = await pool.getConnection();
  try {
    await ensureFixedExpensesTable();
    await ensureFixedExpensePurchaseTables();
    await ensureExpenseReassignmentTables();
    await connection.beginTransaction();
    const [sourceRows] = await connection.execute(
      `SELECT id, gasto_fijo_id, gasto, sucursal, folio
       FROM ocgf_compras
       WHERE id = ?
       LIMIT 1 FOR UPDATE`,
      [ocgfId]
    );
    const source = sourceRows[0];
    if (!source) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "OCGF no encontrada." });
    }
    if (Number(source.gasto_fijo_id || 0) === destinationFixedExpenseId) {
      await connection.rollback();
      return res.status(409).json({ ok: false, message: "La OCGF ya pertenece a ese gasto fijo." });
    }
    const [destinationRows] = await connection.execute(
      `SELECT id, gasto, sucursal, presupuesto, presupuesto_adicional
       FROM gastos_fijos
       WHERE id = ? AND COALESCE(es_catalogo, 1) = 1
       LIMIT 1 FOR UPDATE`,
      [destinationFixedExpenseId]
    );
    const destination = destinationRows[0];
    if (!destination) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "El gasto fijo destino no existe o está inactivo." });
    }

    const [movedRows] = await connection.execute(
      `SELECT COALESCE(SUM(total_orden), 0) AS total
       FROM (
         SELECT o.id,
                GREATEST(0,
                  COALESCE(SUM(p.total), 0) * CASE WHEN MAX(o.sin_iva) = 1 THEN 1 ELSE 1.16 END
                  - CASE WHEN MAX(o.retencion_activa) = 1 THEN COALESCE(MAX(o.retencion_monto), 0) ELSE 0 END
                ) AS total_orden
         FROM ocgf_ordenes o
         LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
         WHERE o.ocgf_id = ? AND o.tipo = 'version' AND o.estatus <> 'Cancelada'
         GROUP BY o.id
       ) montos`,
      [ocgfId]
    );
    const movedAmount = Number(movedRows[0]?.total || 0);
    const destinationUsed = await calculateOcgfUsedByFixedExpense(destinationFixedExpenseId, { connection });
    const destinationAvailable = Math.max(
      0,
      Number(destination.presupuesto || 0) + Number(destination.presupuesto_adicional || 0) - destinationUsed
    );
    if (movedAmount > destinationAvailable + 0.005) {
      await connection.rollback();
      return res.status(409).json({
        ok: false,
        message: `El gasto fijo destino no tiene presupuesto suficiente. Disponible: ${formatCurrencyServer(destinationAvailable)}; OCGF a mover: ${formatCurrencyServer(movedAmount)}.`
      });
    }

    const sourceReference = [source.gasto, source.sucursal].filter(Boolean).join(" · ");
    const destinationReference = [destination.gasto, destination.sucursal].filter(Boolean).join(" · ");
    await connection.execute(
      `UPDATE ocgf_compras
       SET gasto_fijo_id = ?, gasto = ?, sucursal = ?, presupuesto = ?,
           updated_at = CURRENT_TIMESTAMP, updated_by_user_id = ?
       WHERE id = ?`,
      [
        destination.id,
        destination.gasto || "",
        resolveFixedExpenseBranch(destination.sucursal) || destination.sucursal || source.sucursal || "",
        Number(destination.presupuesto || 0),
        req.session.user?.id || null,
        ocgfId
      ]
    );
    await connection.execute("UPDATE ocgf_ordenes SET pdf_ruta = '' WHERE ocgf_id = ?", [ocgfId]);
    await connection.execute(
      `INSERT INTO gasto_reasignaciones
        (tipo_documento, registro_id, folio, origen_tipo, origen_id, origen_referencia,
         destino_tipo, destino_id, destino_referencia, motivo, usuario_id)
       VALUES ('OCGF', ?, ?, 'GASTO_FIJO', ?, ?, 'GASTO_FIJO', ?, ?, ?, ?)`,
      [
        ocgfId,
        source.folio || "",
        Number(source.gasto_fijo_id || 0),
        sourceReference,
        destination.id,
        destinationReference,
        reason,
        req.session.user?.id || null
      ]
    );
    await connection.commit();
    const expense = await getOcgfById(ocgfId);
    const fixedExpenses = await getFixedExpenses("", { includeAvailability: true });
    res.json({
      ok: true,
      expense,
      fixedExpenses,
      message: `${source.folio || "La OCGF"} se movió a ${destinationReference || destination.gasto}. El movimiento quedó registrado en el historial.`
    });
  } catch (error) {
    await connection.rollback();
    logServerError("ocgf-reassign", error);
    res.status(500).json({ ok: false, message: "No se pudo reasignar la OCGF." });
  } finally {
    connection.release();
  }
});

