app.post("/api/purchases/fixed-expenses/:id/supplier-order/draft", requireAuth, async (req, res) => {
  const ocgfId = Number(req.params.id);
  const items = parseRowsOrRespond(res, parseOcgfRows, req.body.items);
  if (!items) return;
  const retencionActiva = Boolean(req.body.retencionActiva);
  const retencionMonto = Number(req.body.retencionMonto || 0);
  const sinIva = Boolean(req.body.sinIva);
  if (!ocgfId) return res.status(400).json({ ok: false, message: "Gasto fijo inválido." });

  const connection = await pool.getConnection();
  try {
    await ensureFixedExpensePurchaseTables();
    const availabilityError = await validateOcgfBudgetAvailability(connection, ocgfId, items, {
      retencionActiva,
      retencionMonto,
      sinIva
    });
    if (availabilityError) return res.status(400).json({ ok: false, message: availabilityError });
    await connection.beginTransaction();
    const [existing] = await connection.execute(
      "SELECT id FROM ocgf_ordenes WHERE ocgf_id = ? AND tipo = 'borrador' ORDER BY id DESC LIMIT 1",
      [ocgfId]
    );
    let orderId = existing[0]?.id;
    if (orderId) {
      await connection.execute(
        "UPDATE ocgf_ordenes SET retencion_activa = ?, retencion_monto = ?, sin_iva = ?, updated_by_user_id = ? WHERE id = ?",
        [retencionActiva ? 1 : 0, retencionMonto, sinIva ? 1 : 0, req.session.user?.id || null, orderId]
      );
    } else {
      const [result] = await connection.execute(
        `INSERT INTO ocgf_ordenes
          (ocgf_id, tipo, folio, version, estatus, retencion_activa, retencion_monto, sin_iva, usuario_id, updated_by_user_id)
         VALUES (?, 'borrador', '', 0, 'Borrador', ?, ?, ?, ?, ?)`,
        [ocgfId, retencionActiva ? 1 : 0, retencionMonto, sinIva ? 1 : 0, req.session.user?.id || null, req.session.user?.id || null]
      );
      orderId = result.insertId;
    }
    await replaceOcgfOrderRows(connection, orderId, items);
    await touchOcgfUpdatedAt(ocgfId, connection, req.session.user?.id || null);
    await connection.commit();
    const expense = await getOcgfById(ocgfId);
    res.json({ ok: true, expense });
  } catch (error) {
    await connection.rollback();
    logServerError("ocgf-order-draft", error);
    res.status(500).json({ ok: false, message: "No se pudo guardar el borrador." });
  } finally {
    connection.release();
  }
});

app.post("/api/purchases/fixed-expenses/:id/supplier-order/versions", requireAuth, async (req, res) => {
  const ocgfId = Number(req.params.id);
  const items = parseRowsOrRespond(res, parseOcgfRows, req.body.items);
  if (!items) return;
  const retencionActiva = Boolean(req.body.retencionActiva);
  const retencionMonto = Number(req.body.retencionMonto || 0);
  const sinIva = Boolean(req.body.sinIva);
  if (!ocgfId) return res.status(400).json({ ok: false, message: "Gasto fijo inválido." });
  if (!items.length) return res.status(400).json({ ok: false, message: "Agrega al menos una partida." });

  const connection = await pool.getConnection();
  try {
    await ensureFixedExpensePurchaseTables();
    const expense = await getOcgfById(ocgfId);
    if (!expense) {
      return res.status(404).json({ ok: false, message: "No se encontró el gasto fijo." });
    }
    const availabilityError = await validateOcgfBudgetAvailability(connection, ocgfId, items, {
      retencionActiva,
      retencionMonto,
      sinIva
    });
    if (availabilityError) return res.status(400).json({ ok: false, message: availabilityError });
    await connection.beginTransaction();
    const [versionRows] = await connection.execute(
      "SELECT COALESCE(MAX(version), 0) AS last_version FROM ocgf_ordenes WHERE ocgf_id = ? AND tipo = 'version'",
      [ocgfId]
    );
    const version = Number(versionRows[0]?.last_version || 0) + 1;
    const [result] = await connection.execute(
      `INSERT INTO ocgf_ordenes
        (ocgf_id, tipo, folio, version, estatus, retencion_activa, retencion_monto, sin_iva, usuario_id, updated_by_user_id)
       VALUES (?, 'version', ?, ?, 'Pendiente de aprobación', ?, ?, ?, ?, ?)`,
      [
        ocgfId,
        `${expense.folio}-${version}`,
        version,
        retencionActiva ? 1 : 0,
        retencionMonto,
        sinIva ? 1 : 0,
        req.session.user?.id || null,
        req.session.user?.id || null
      ]
    );
    await replaceOcgfOrderRows(connection, result.insertId, items);
    await touchOcgfUpdatedAt(ocgfId, connection, req.session.user?.id || null);
    await connection.commit();
    const nextExpense = await getOcgfById(ocgfId);
    res.status(201).json({ ok: true, expense: nextExpense });
  } catch (error) {
    await connection.rollback();
    logServerError("ocgf-order-version", error);
    res.status(500).json({ ok: false, message: "No se pudo guardar la versión." });
  } finally {
    connection.release();
  }
});

app.put("/api/purchases/fixed-expenses/:id/supplier-order/versions/:orderId", requireAuth, async (req, res) => {
  const ocgfId = Number(req.params.id);
  const orderId = Number(req.params.orderId);
  const items = parseRowsOrRespond(res, parseOcgfRows, req.body.items);
  if (!items) return;
  const retencionActiva = Boolean(req.body.retencionActiva);
  const retencionMonto = Number(req.body.retencionMonto || 0);
  const sinIva = Boolean(req.body.sinIva);
  if (!ocgfId || !orderId) return res.status(400).json({ ok: false, message: "OCGF inválida." });
  if (!items.length) return res.status(400).json({ ok: false, message: "Agrega al menos una partida." });

  const connection = await pool.getConnection();
  try {
    await ensureFixedExpensePurchaseTables();
    const [existing] = await connection.execute(
      "SELECT id, estatus FROM ocgf_ordenes WHERE id = ? AND ocgf_id = ? AND tipo = 'version' LIMIT 1",
      [orderId, ocgfId]
    );
    if (!existing.length) return res.status(404).json({ ok: false, message: "Versión OCGF no encontrada." });
    if (existing[0].estatus === "Cancelada") {
      return res.status(409).json({ ok: false, message: "No se puede editar una OCGF cancelada." });
    }
    const availabilityError = await validateOcgfBudgetAvailability(connection, ocgfId, items, {
      currentOrderId: orderId,
      retencionActiva,
      retencionMonto,
      sinIva
    });
    if (availabilityError) return res.status(400).json({ ok: false, message: availabilityError });

    await connection.beginTransaction();
    await connection.execute(
      "UPDATE ocgf_ordenes SET retencion_activa = ?, retencion_monto = ?, sin_iva = ?, updated_by_user_id = ? WHERE id = ?",
      [retencionActiva ? 1 : 0, retencionMonto, sinIva ? 1 : 0, req.session.user?.id || null, orderId]
    );
    await replaceOcgfOrderRows(connection, orderId, items);
    await touchOcgfUpdatedAt(ocgfId, connection, req.session.user?.id || null);
    await connection.commit();
    const expense = await getOcgfById(ocgfId);
    res.json({ ok: true, expense });
  } catch (error) {
    await connection.rollback();
    logServerError("ocgf-order-version-update", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar la versión OCGF." });
  } finally {
    connection.release();
  }
});


