app.post("/api/ocgf-orders/:orderId/approve", requireAuth, requireApprovePermission, async (req, res) => {
  const orderId = Number(req.params.orderId);
  if (!orderId) return res.status(400).json({ ok: false, message: "OCGF inválida." });

  try {
    await ensureFixedExpensePurchaseTables();
    await ensureAccountsPayableTables();
    const order = await getOcgfOrderById(orderId);
    if (!order || order.tipo !== "version") {
      return res.status(404).json({ ok: false, message: "OCGF no encontrada." });
    }
    if (order.estatus === "Cancelada") {
      return res.status(409).json({ ok: false, message: "No se puede aprobar una OCGF cancelada." });
    }
    if (!order.items.length) return res.status(400).json({ ok: false, message: "La OCGF no tiene partidas." });
    await pool.execute("UPDATE ocgf_ordenes SET estatus = 'Aprobada', updated_by_user_id = ? WHERE id = ?", [
      req.session.user?.id || null,
      orderId
    ]);
    await touchOcgfUpdatedAt(order.ocgfId, pool, req.session.user?.id || null);
    const pdfRuta = await generateFixedExpenseOrderPdf(orderId);
    await ensureAccountsPayableRecordForOcgf(orderId, req.session.user?.id || null);
    const nextOrder = await getOcgfOrderById(orderId);
    const expense = await getOcgfById(nextOrder.ocgfId);
    res.json({ ok: true, expense, pdfUrl: `/${pdfRuta}` });
  } catch (error) {
    logServerError("ocgf-order-approve", error);
    res.status(500).json({ ok: false, message: "No se pudo aprobar la OCGF." });
  }
});

