const BUDGET_WARRANTY_RATE = 0.05;

function normalizeBudgetBlock(value) {
  const raw = String(value || "").trim();
  const compact = raw
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
  const normalized = {
    equipo: "equipos",
    equipos: "equipos",
    equiposdeelevacioneizaje: "equipos",
    mano: "manoObra",
    manoobra: "manoObra",
    manodeobra: "manoObra",
    contratista: "manoObra",
    contratistas: "manoObra",
    material: "materiales",
    materiales: "materiales"
  }[compact];
  return normalized || raw;
}

function resolveBudgetState(estado, hasClientPo = false, workflowStatus = "") {
  const normalized = String(estado || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (normalized.includes("cerrad")) return "Cerrada";
  const normalizedWorkflow = String(workflowStatus || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (normalizedWorkflow.includes("cerrad")) return "Cerrada";
  const truthyClientPo =
    hasClientPo === true ||
    Number(hasClientPo || 0) === 1 ||
    ["true", "si", "sí"].includes(String(hasClientPo || "").toLowerCase().trim());
  const isPostPoWorkflow =
    normalizedWorkflow.includes("facturacion") ||
    normalizedWorkflow.includes("gr") ||
    normalizedWorkflow.includes("track") ||
    normalizedWorkflow.includes("comprobante") ||
    normalizedWorkflow.includes("cobrado");
  if (truthyClientPo || isPostPoWorkflow) return "En proceso";
  return "Abierta";
}

function normalizeWorkflowValue(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function isBudgetWorkflowClosed(budget = {}) {
  const state = normalizeWorkflowValue(budget.estado);
  const status = normalizeWorkflowValue(budget.estatus);
  return state.includes("cerrad") || status.includes("cerrad");
}

function canUseClientQuoteModule(budget = {}) {
  if (isBudgetWorkflowClosed(budget)) return false;
  const status = normalizeWorkflowValue(budget.estatus);
  return (
    status === "aprobado" ||
    status === "en espera de aprobacion de cotizacion" ||
    status === "en espera de po" ||
    status === "en espera de facturacion" ||
    status === "en espera de comprobante de pago" ||
    status.includes("cobrado")
  );
}

function canUploadClientPoForBudget(budget = {}) {
  if (isBudgetWorkflowClosed(budget)) return false;
  const status = normalizeWorkflowValue(budget.estatus);
  return (
    status === "en espera de po" ||
    status === "en espera de facturacion" ||
    status === "en espera de comprobante de pago" ||
    status.includes("cobrado") ||
    Boolean(budget.po)
  );
}

async function budgetHasApprovedClientQuote(budgetId, connection = pool) {
  const [rows] = await connection.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ?
       AND tipo = 'version'
       AND LOWER(estatus) LIKE 'aprob%'
     ORDER BY version DESC, id DESC
     LIMIT 1`,
    [budgetId]
  );
  return Boolean(rows.length);
}

async function resolveBudgetWorkflowStatus(row) {
  const budgetStatus = normalizeWorkflowValue(row.estatus);
  const budgetState = normalizeWorkflowValue(row.estado);
  const isClosed = budgetState.includes("cerrad") || budgetStatus.includes("cerrad");

  const [quoteRows] = await pool.execute(
    `SELECT id, estatus
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ? AND tipo = 'version'
     ORDER BY version DESC, id DESC
     LIMIT 1`,
    [row.id]
  );
  const quote = quoteRows[0];

  if (budgetStatus.startsWith("no aprobad")) return "No aprobado";
  const budgetApproved = budgetStatus.startsWith("aprobad");

  if (!quote) {
    if (isClosed) return "Cerrado";
    return budgetApproved ? "Aprobado" : "En espera de aprobación";
  }

  if (!normalizeWorkflowValue(quote.estatus).startsWith("aprob")) {
    return isClosed ? "Cerrado" : "En espera de aprobación de cotización";
  }

  const hasClientPo = Boolean(row.has_client_po) || Boolean(String(row.po || "").trim());
  if (!hasClientPo) return isClosed ? "Cerrado" : "En espera de PO";

  const [receivableRows] = await pool.execute(
    `SELECT estado, pendiente
     FROM cuentas_por_cobrar
     WHERE presupuesto_id = ?
       AND (cotizacion_cliente_id = ? OR cotizacion_cliente_id IS NULL)
     ORDER BY id DESC
     LIMIT 1`,
    [row.id, quote.id]
  );
  const receivable = receivableRows[0] || null;
  const receivableState = normalizeWorkflowValue(receivable?.estado);
  const receivablePending = normalizeWorkflowValue(receivable?.pendiente);
  if (receivablePending.includes("sin pendiente") || receivableState.includes("pago completo")) {
    return "Cobrado y documentación completa";
  }
  if (receivableState.includes("comprobante") || receivablePending.includes("complemento")) {
    return "Cobrado pendiente de documentación";
  }
  if (receivablePending.includes("gr")) return "En espera de GR";
  if (receivablePending.includes("track")) return "En espera de Track ID";
  if (receivablePending.includes("comprobante")) return "En espera de comprobante de pago";

  const files = await getAccountsReceivableFilesByQuote(quote.id);
  const fileTypes = new Set(files.map((file) => file.tipo));
  if (!fileTypes.has("Factura")) return "En espera de facturación";

  const [clientRows] = await pool.execute(
    `SELECT condiciones_pago
     FROM clientes
     WHERE empresa COLLATE utf8mb4_unicode_ci = ?
     ORDER BY id DESC
     LIMIT 1`,
    [row.empresa || ""]
  );
  const arStatus = resolveAccountsReceivableStatus(
    files,
    clientRows[0]?.condiciones_pago || "contado",
    row.empresa || ""
  );
  const pending = String(arStatus.pendiente || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  if (pending.includes("sin pendiente")) return "Cobrado y documentación completa";
  if (fileTypes.has("Comprobante de pago")) return "Cobrado pendiente de documentación";
  if (pending.includes("gr")) return "En espera de GR";
  if (pending.includes("track")) return "En espera de Track ID";
  if (pending.includes("comprobante")) return "En espera de comprobante de pago";
  if (pending.includes("complemento")) return "Cobrado pendiente de documentación";
  return "En espera de facturación";
}

async function getBudgets(search = "", user = null, options = {}) {
  const hasLegacyOrders = await tableExists("ordenes_servicio");
  const clientUserExpression = hasLegacyOrders
    ? `COALESCE(
        NULLIF(CASE
          WHEN p.cliente_usuario = p.sucursal THEN ''
          ELSE p.cliente_usuario
        END, ''),
        NULLIF(c_fallback.nombre, ''),
        ''
      )`
    : "COALESCE(NULLIF(p.cliente_usuario, ''), NULLIF(c_fallback.nombre, ''), '')";
  const branchExpression =
    "COALESCE(NULLIF(p.sucursal, ''), NULLIF(c_fallback.sucursal, ''), NULLIF(c_fallback.nombre, ''), '')";
  const legacyOrderJoin = hasLegacyOrders ? "LEFT JOIN ordenes_servicio os_legacy ON os_legacy.id = p.id" : "";
  const clientFallbackJoin = hasLegacyOrders
    ? "LEFT JOIN clientes c_fallback ON c_fallback.id = COALESCE(p.cliente_id, os_legacy.cliente_id)"
    : "LEFT JOIN clientes c_fallback ON c_fallback.id = p.cliente_id";
  const values = [];
  const conditions = [];
  const searchTerm = normalizeSearchText(search);

  appendBudgetOwnerCondition(conditions, values, user, "p");
  const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
  const rowLimit = Number(options.limit || 0) > 0 ? Number(options.limit) : searchTerm ? 5000 : 150;
  const legacySearchSelect = hasLegacyOrders
    ? "os_legacy.po_cliente, os_legacy.nombre_cliente, os_legacy.supervisor, os_legacy.proyecto,"
    : "";

  const [rows] = await pool.execute(
    `SELECT
        p.id,
        p.empresa,
        ${branchExpression} AS sucursal,
        ${clientUserExpression} AS cliente_usuario,
        p.area,
        p.titulo_proyecto,
        p.folio,
        p.po,
        p.folio_manual,
        p.estado,
        p.estatus,
        p.cliente_id AS cliente_id,
        p.sucursal_id AS sucursal_id,
        p.sin_garantia,
        p.valor_venta_override,
        p.comision_supervisor_override,
        p.usuario_id AS owner_id,
        p.created_at,
        p.updated_at,
        (
          NULLIF(p.po, '') IS NOT NULL
          OR EXISTS(
          SELECT 1
          FROM presupuesto_po_cliente po_check
          WHERE po_check.presupuesto_id = p.id
            AND COALESCE(po_check.estado_documento, 'Activo') = 'Activo'
            AND po_check.deleted_at IS NULL
            AND (
              po_check.sin_po = 1
              OR NULLIF(po_check.numero_po, '') IS NOT NULL
              OR NULLIF(po_check.ruta, '') IS NOT NULL
            )
          LIMIT 1
          )
        ) AS has_client_po,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS owner,
        COALESCE(u.comision_supervisor, 0) AS comision_supervisor_base,
        COALESCE(
          company_settings.valor_venta,
          c_fallback.valor_venta,
          (SELECT c2.valor_venta
           FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id ASC
           LIMIT 1),
          0
        ) AS valor_venta_base,
        COALESCE(equipos.total, 0) AS total_equipos,
        COALESCE(equipos.total_rows, 0) AS equipos_count,
        COALESCE(contratistas.total, 0) AS total_contratistas,
        COALESCE(contratistas.total_rows, 0) AS contratistas_count,
        COALESCE(mano_obra.total, 0) AS total_mano_obra,
        COALESCE(mano_obra.total_rows, 0) AS mano_obra_count,
        COALESCE(materiales.total, 0) AS total_materiales,
        COALESCE(materiales.total_rows, 0) AS materiales_count,
        COALESCE(cotizacion_aprobada.monto, 0) AS monto_cotizacion,
        CONCAT_WS(' ',
          p.empresa,
          ${branchExpression},
          ${clientUserExpression},
          p.area,
          p.titulo_proyecto,
          p.folio,
          p.po,
          p.estado,
          p.estatus,
          COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, ''),
          ${legacySearchSelect}
          (SELECT GROUP_CONCAT(CONCAT_WS(' ', e.item, e.unidad_medida) SEPARATOR ' ')
           FROM presupuesto_costos_equipos e
           WHERE e.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(c.descripcion SEPARATOR ' ')
           FROM presupuesto_costos_contratistas c
           WHERE c.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(m.descripcion SEPARATOR ' ')
           FROM presupuesto_costos_mano_obra m
           WHERE m.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(CONCAT_WS(' ', mt.descripcion, mt.unidad) SEPARATOR ' ')
           FROM presupuesto_costos_materiales mt
           WHERE mt.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(CONCAT_WS(' ', pa.tipo, pa.nombre) SEPARATOR ' ')
           FROM presupuesto_archivos pa
           WHERE pa.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(CONCAT_WS(' ', poa.numero_po, poa.nombre) SEPARATOR ' ')
           FROM presupuesto_po_cliente poa
           WHERE poa.presupuesto_id = p.id),
          (SELECT GROUP_CONCAT(CONCAT_WS(' ', ofa.tipo, ofa.nombre) SEPARATOR ' ')
           FROM ocp_proveedor_archivos ofa
           WHERE ofa.presupuesto_id = p.id)
        ) AS search_text
      FROM presupuestos p
      LEFT JOIN usuarios u ON u.user_id = p.usuario_id
      ${legacyOrderJoin}
      ${clientFallbackJoin}
      LEFT JOIN cliente_empresas company_settings ON company_settings.id = p.empresa_id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.equipos()} equipos ON equipos.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.contratistas()} contratistas ON contratistas.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.manoObra()} mano_obra ON mano_obra.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.materiales()} materiales ON materiales.presupuesto_id = p.id
      LEFT JOIN (
        SELECT
          q.presupuesto_id,
          COALESCE(SUM(i.subtotal), 0) AS monto
        FROM cotizaciones_cliente q
        LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
        WHERE q.tipo = 'version'
          AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
          AND q.id = (
            SELECT q2.id
            FROM cotizaciones_cliente q2
            WHERE q2.presupuesto_id = q.presupuesto_id
              AND q2.tipo = 'version'
              AND LOWER(TRIM(q2.estatus)) LIKE 'aprob%'
            ORDER BY q2.version DESC, q2.id DESC
            LIMIT 1
          )
        GROUP BY q.presupuesto_id
      ) cotizacion_aprobada ON cotizacion_aprobada.presupuesto_id = p.id
      ${where}
      ORDER BY p.id DESC
      LIMIT ${rowLimit}`,
    values
  );

  const budgets = await Promise.all(
    rows.map(async (row) => {
      const workflowStatus = await resolveBudgetWorkflowStatus(row);
      const totalProyecto =
        Number(row.total_equipos || 0) +
        Number(row.total_contratistas || 0) +
        Number(row.total_mano_obra || 0) +
        Number(row.total_materiales || 0);
      const valorVenta = Number(row.valor_venta_override ?? row.valor_venta_base ?? 0);
      const costoCotizacion = totalProyecto + (row.sin_garantia ? 0 : totalProyecto * BUDGET_WARRANTY_RATE);
      const precioVenta = costoCotizacion * valorVenta;
      return {
        id: row.id,
        clienteId: row.cliente_id || null,
        sucursalId: row.sucursal_id || null,
        empresa: row.empresa || "",
        sucursal: row.sucursal || "",
        clienteUsuario: row.cliente_usuario || "",
        area: row.area || "",
        tituloProyecto: row.titulo_proyecto || "",
        folio: row.folio || "",
        po: row.po || "",
        folioManual: Boolean(row.folio_manual),
        estado: resolveBudgetState(row.estado, row.has_client_po, workflowStatus),
        estatus: workflowStatus,
        owner: row.owner || "",
        ownerId: row.owner_id || null,
        sinGarantia: Boolean(row.sin_garantia),
        valorVentaBase: Number(row.valor_venta_base || 0),
        valorVenta,
        comisionSupervisorBase: Number(row.comision_supervisor_base || 0),
        comisionSupervisor: Number(row.comision_supervisor_override ?? row.comision_supervisor_base ?? 0),
        totalEquipos: Number(row.total_equipos || 0),
        equiposCount: Number(row.equipos_count || 0),
        totalContratistas: Number(row.total_contratistas || 0),
        contratistasCount: Number(row.contratistas_count || 0),
        totalManoObra: Number(row.total_mano_obra || 0),
        manoObraCount: Number(row.mano_obra_count || 0),
        totalMateriales: Number(row.total_materiales || 0),
        materialesCount: Number(row.materiales_count || 0),
        totalAdicional: 0,
        searchText: row.search_text || "",
        totalProyecto,
        costoCotizacion,
        precioVenta,
        montoCotizacion: Number(row.monto_cotizacion || 0),
        hasClientPo: Boolean(row.has_client_po),
        createdAt: row.created_at,
        updatedAt: row.updated_at
      };
    })
  );

  if (!searchTerm) return budgets;
  return budgets.filter((budget) =>
    matchesAllServerSearchTerms(
      [
        budget.searchText,
        budget.empresa,
        budget.sucursal,
        budget.clienteUsuario,
        budget.area,
        budget.tituloProyecto,
        budget.folio,
        budget.po,
        budget.estado,
        budget.estatus,
        budget.owner,
        buildMoneySearchTermsServer(
          budget.montoCotizacion,
          budget.precioVenta,
          budget.costoCotizacion,
          budget.totalProyecto,
          budget.totalEquipos,
          budget.totalManoObra,
          budget.totalMateriales
        )
      ].join(" "),
      searchTerm
    )
  );
}

async function getBudgetById(budgetId) {
  const hasLegacyOrders = await tableExists("ordenes_servicio");
  const clientUserExpression = hasLegacyOrders
    ? `COALESCE(
        NULLIF(CASE
          WHEN p.cliente_usuario = p.sucursal THEN ''
          ELSE p.cliente_usuario
        END, ''),
        NULLIF(c_fallback.nombre, ''),
        ''
      )`
    : "COALESCE(NULLIF(p.cliente_usuario, ''), NULLIF(c_fallback.nombre, ''), '')";
  const branchExpression =
    "COALESCE(NULLIF(p.sucursal, ''), NULLIF(c_fallback.sucursal, ''), NULLIF(c_fallback.nombre, ''), '')";
  const legacyOrderJoin = hasLegacyOrders ? "LEFT JOIN ordenes_servicio os_legacy ON os_legacy.id = p.id" : "";
  const clientFallbackJoin = hasLegacyOrders
    ? "LEFT JOIN clientes c_fallback ON c_fallback.id = COALESCE(p.cliente_id, os_legacy.cliente_id)"
    : "LEFT JOIN clientes c_fallback ON c_fallback.id = p.cliente_id";
  const [rows] = await pool.execute(
    `SELECT
        p.id,
        p.empresa,
        ${branchExpression} AS sucursal,
        ${clientUserExpression} AS cliente_usuario,
        p.area,
        p.titulo_proyecto,
        p.folio,
        p.po,
        p.folio_manual,
        p.estado,
        p.estatus,
        p.cliente_id AS cliente_id,
        p.sucursal_id AS sucursal_id,
        p.sin_garantia,
        p.valor_venta_override,
        p.comision_supervisor_override,
        p.usuario_id AS owner_id,
        p.created_at,
        p.updated_at,
        (
          NULLIF(p.po, '') IS NOT NULL
          OR EXISTS(
          SELECT 1
          FROM presupuesto_po_cliente po_check
          WHERE po_check.presupuesto_id = p.id
            AND COALESCE(po_check.estado_documento, 'Activo') = 'Activo'
            AND po_check.deleted_at IS NULL
            AND (
              po_check.sin_po = 1
              OR NULLIF(po_check.numero_po, '') IS NOT NULL
              OR NULLIF(po_check.ruta, '') IS NOT NULL
            )
          LIMIT 1
          )
        ) AS has_client_po,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS owner,
        COALESCE(u.comision_supervisor, 0) AS comision_supervisor_base,
        COALESCE(
          company_settings.valor_venta,
          c_fallback.valor_venta,
          (SELECT c2.valor_venta
           FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id ASC
           LIMIT 1),
          0
        ) AS valor_venta_base,
        COALESCE(equipos.total, 0) AS total_equipos,
        COALESCE(equipos.total_rows, 0) AS equipos_count,
        COALESCE(contratistas.total, 0) AS total_contratistas,
        COALESCE(contratistas.total_rows, 0) AS contratistas_count,
        COALESCE(mano_obra.total, 0) AS total_mano_obra,
        COALESCE(mano_obra.total_rows, 0) AS mano_obra_count,
        COALESCE(materiales.total, 0) AS total_materiales,
        COALESCE(materiales.total_rows, 0) AS materiales_count
      FROM presupuestos p
      LEFT JOIN usuarios u ON u.user_id = p.usuario_id
      ${legacyOrderJoin}
      ${clientFallbackJoin}
      LEFT JOIN cliente_empresas company_settings ON company_settings.id = p.empresa_id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.equipos()} equipos ON equipos.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.contratistas()} contratistas ON contratistas.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.manoObra()} mano_obra ON mano_obra.presupuesto_id = p.id
      LEFT JOIN ${BUDGET_COST_AGGREGATES.materiales()} materiales ON materiales.presupuesto_id = p.id
      WHERE p.id = ?
      LIMIT 1`,
    [budgetId]
  );

  const row = rows[0];
  if (!row) return null;
  const workflowStatus = await resolveBudgetWorkflowStatus(row);
  const totalProyecto =
    Number(row.total_equipos || 0) +
    Number(row.total_contratistas || 0) +
    Number(row.total_mano_obra || 0) +
    Number(row.total_materiales || 0);
  const valorVenta = Number(row.valor_venta_override ?? row.valor_venta_base ?? 0);
  const costoCotizacion = totalProyecto + (row.sin_garantia ? 0 : totalProyecto * BUDGET_WARRANTY_RATE);
  const precioVenta = costoCotizacion * valorVenta;

  return {
    id: row.id,
    clienteId: row.cliente_id,
    sucursalId: row.sucursal_id || null,
    empresa: row.empresa || "",
    sucursal: row.sucursal || "",
    clienteUsuario: row.cliente_usuario || "",
    area: row.area || "",
    tituloProyecto: row.titulo_proyecto || "",
    folio: row.folio || "",
    po: row.po || "",
    folioManual: Boolean(row.folio_manual),
    estado: resolveBudgetState(row.estado, row.has_client_po, workflowStatus),
    estatus: workflowStatus,
    owner: row.owner || "",
    ownerId: row.owner_id || null,
    sinGarantia: Boolean(row.sin_garantia),
    valorVentaBase: Number(row.valor_venta_base || 0),
    valorVenta,
    comisionSupervisorBase: Number(row.comision_supervisor_base || 0),
    comisionSupervisor: Number(row.comision_supervisor_override ?? row.comision_supervisor_base ?? 0),
    totalEquipos: Number(row.total_equipos || 0),
    equiposCount: Number(row.equipos_count || 0),
    totalContratistas: Number(row.total_contratistas || 0),
    contratistasCount: Number(row.contratistas_count || 0),
    totalManoObra: Number(row.total_mano_obra || 0),
    manoObraCount: Number(row.mano_obra_count || 0),
    totalMateriales: Number(row.total_materiales || 0),
    materialesCount: Number(row.materiales_count || 0),
    totalAdicional: 0,
    totalProyecto,
    costoCotizacion,
    precioVenta,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

function normalizedFolioSqlExpression(expression) {
  return `UPPER(REPLACE(TRIM(CONVERT(${expression} USING utf8mb4)) COLLATE utf8mb4_unicode_ci, _utf8mb4' ' COLLATE utf8mb4_unicode_ci, _utf8mb4'' COLLATE utf8mb4_unicode_ci))`;
}

function folioEqualsCondition(columnExpression) {
  return `${normalizedFolioSqlExpression(columnExpression)} = ${normalizedFolioSqlExpression("?")}`;
}

async function getBudgetByFolioExact(folio, user = null) {
  const cleanFolio = String(folio || "").trim();
  if (!cleanFolio) return null;
  const values = [cleanFolio];
  const conditions = [folioEqualsCondition("p.folio")];
  appendBudgetOwnerCondition(conditions, values, user, "p");
  const [rows] = await pool.execute(
    `SELECT p.id
     FROM presupuestos p
     WHERE ${conditions.join(" AND ")}
     ORDER BY p.id DESC
     LIMIT 1`,
    values
  );
  if (!rows.length) return null;
  return getBudgetById(rows[0].id);
}

async function getBudgetByFolioForManualCommission(folio, user = null) {
  try {
    const fullBudget = await getBudgetByFolioExact(folio, user);
    if (fullBudget) {
      // Los presupuestos históricos pueden contener filas de costo duplicadas por
      // importaciones antiguas. La vista financiera ya las depura; la comisión
      // manual debe usar exactamente la misma base para no duplicar la utilidad.
      return (await getBudgetWithDedupedCostTotals(fullBudget.id)) || fullBudget;
    }
  } catch (error) {
    logServerError("manual-commission-full-budget-lookup", error);
  }

  if (!(await tableExists("presupuestos"))) return null;
  const budgetColumns = await getTableColumns("presupuestos");
  const hasUserId = budgetColumns.includes("usuario_id");
  const hasTitle = budgetColumns.includes("titulo_proyecto");
  const hasEmpresa = budgetColumns.includes("empresa");
  const hasSinGarantia = budgetColumns.includes("sin_garantia");
  const hasValorVenta = budgetColumns.includes("valor_venta_override");
  const hasComisionOverride = budgetColumns.includes("comision_supervisor_override");
  const hasCreatedAt = budgetColumns.includes("created_at");
  const hasUpdatedAt = budgetColumns.includes("updated_at");
  const hasUsers = await tableExists("usuarios");
  const hasClientQuotes = (await tableExists("cotizaciones_cliente")) && (await tableExists("cotizacion_cliente_partidas"));
  const hasEquipos = await tableExists("presupuesto_costos_equipos");
  const hasContratistas = await tableExists("presupuesto_costos_contratistas");
  const hasManoObra = await tableExists("presupuesto_costos_mano_obra");
  const hasMateriales = await tableExists("presupuesto_costos_materiales");

  const values = [folio];
  const conditions = [folioEqualsCondition("p.folio")];
  if (shouldRestrictToOwnedBudgets(user) && hasUserId) {
    appendBudgetOwnerCondition(conditions, values, user, "p");
  } else if (shouldRestrictToOwnedBudgets(user)) {
    conditions.push("1 = 0");
  }

  const ownerJoin = hasUsers && hasUserId ? "LEFT JOIN usuarios u ON u.user_id = p.usuario_id" : "";
  const ownerSelect = hasUsers && hasUserId
    ? "COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '')"
    : "''";
  const ownerIdSelect = hasUserId ? "p.usuario_id" : "NULL";
  const comisionSelect = hasUsers && hasUserId
    ? `COALESCE(${hasComisionOverride ? "p.comision_supervisor_override," : ""} u.comision_supervisor, 0)`
    : `COALESCE(${hasComisionOverride ? "p.comision_supervisor_override" : "0"}, 0)`;
  const quoteSelect = hasClientQuotes
    ? `COALESCE((
        SELECT SUM(i.subtotal)
        FROM cotizaciones_cliente q
        LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
        WHERE q.presupuesto_id = p.id
          AND q.tipo = 'version'
          AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
          AND q.id = (
            SELECT q2.id
            FROM cotizaciones_cliente q2
            WHERE q2.presupuesto_id = p.id
              AND q2.tipo = 'version'
              AND LOWER(TRIM(q2.estatus)) LIKE 'aprob%'
            ORDER BY q2.version DESC, q2.id DESC
            LIMIT 1
          )
      ), 0)`
    : "0";

  const joins = [
    ownerJoin,
    hasEquipos
      ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.equipos()} equipos ON equipos.presupuesto_id = p.id`
      : "",
    hasContratistas
      ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.contratistas()} contratistas ON contratistas.presupuesto_id = p.id`
      : "",
    hasManoObra
      ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.manoObra()} mano_obra ON mano_obra.presupuesto_id = p.id`
      : "",
    hasMateriales
      ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.materiales()} materiales ON materiales.presupuesto_id = p.id`
      : ""
  ].filter(Boolean).join("\n");

  let rows = [];
  try {
    [rows] = await pool.execute(
      `SELECT
         p.id,
         p.folio,
         ${hasEmpresa ? "p.empresa" : "''"} AS empresa,
         ${hasTitle ? "p.titulo_proyecto" : "p.folio"} AS titulo_proyecto,
         ${ownerIdSelect} AS owner_id,
         ${ownerSelect} AS owner,
         ${comisionSelect} AS comision_supervisor,
         ${hasValorVenta ? "COALESCE(p.valor_venta_override, 0)" : "0"} AS valor_venta,
         ${hasSinGarantia ? "COALESCE(p.sin_garantia, 0)" : "0"} AS sin_garantia,
         ${hasEquipos ? "COALESCE(equipos.total, 0)" : "0"} AS total_equipos,
         ${hasContratistas ? "COALESCE(contratistas.total, 0)" : "0"} AS total_contratistas,
         ${hasManoObra ? "COALESCE(mano_obra.total, 0)" : "0"} AS total_mano_obra,
         ${hasMateriales ? "COALESCE(materiales.total, 0)" : "0"} AS total_materiales,
         ${quoteSelect} AS monto_cotizacion,
         ${hasCreatedAt ? "p.created_at" : "NULL"} AS created_at,
         ${hasUpdatedAt ? "p.updated_at" : "NULL"} AS updated_at
       FROM presupuestos p
       ${joins}
       WHERE ${conditions.join(" AND ")}
       ORDER BY p.id DESC
       LIMIT 1`,
      values
    );
  } catch (error) {
    logServerError("manual-commission-budget-rich-fallback", error);
    const minimalValues = [folio];
    const minimalConditions = [folioEqualsCondition("p.folio")];
    if (shouldRestrictToOwnedBudgets(user) && hasUserId) {
      appendBudgetOwnerCondition(minimalConditions, minimalValues, user, "p");
    } else if (shouldRestrictToOwnedBudgets(user)) {
      minimalConditions.push("1 = 0");
    }
    [rows] = await pool.execute(
      `SELECT
         p.id,
         p.folio,
         ${hasEmpresa ? "p.empresa" : "''"} AS empresa,
         ${hasTitle ? "p.titulo_proyecto" : "p.folio"} AS titulo_proyecto,
         ${hasUserId ? "p.usuario_id" : "NULL"} AS owner_id,
         '' AS owner,
         0 AS comision_supervisor,
         0 AS valor_venta,
         0 AS sin_garantia,
         0 AS total_equipos,
         0 AS total_contratistas,
         0 AS total_mano_obra,
         0 AS total_materiales,
         0 AS monto_cotizacion,
         ${hasCreatedAt ? "p.created_at" : "NULL"} AS created_at,
         ${hasUpdatedAt ? "p.updated_at" : "NULL"} AS updated_at
       FROM presupuestos p
       WHERE ${minimalConditions.join(" AND ")}
       ORDER BY p.id DESC
       LIMIT 1`,
      minimalValues
    );
  }

  const row = rows[0];
  if (!row) return null;
  const totalProyecto =
    Number(row.total_equipos || 0) +
    Number(row.total_contratistas || 0) +
    Number(row.total_mano_obra || 0) +
    Number(row.total_materiales || 0);
  const costoCotizacion = totalProyecto + (row.sin_garantia ? 0 : totalProyecto * BUDGET_WARRANTY_RATE);
  const fallbackPrice = costoCotizacion * Number(row.valor_venta || 0);
  return {
    id: row.id,
    empresa: row.empresa || "",
    tituloProyecto: row.titulo_proyecto || row.folio || "",
    folio: row.folio || "",
    owner: row.owner || "",
    ownerId: row.owner_id || null,
    sinGarantia: Boolean(row.sin_garantia),
    valorVenta: Number(row.valor_venta || 0),
    comisionSupervisor: Number(row.comision_supervisor || 0),
    totalEquipos: Number(row.total_equipos || 0),
    totalContratistas: Number(row.total_contratistas || 0),
    totalManoObra: Number(row.total_mano_obra || 0),
    totalMateriales: Number(row.total_materiales || 0),
    totalProyecto,
    costoCotizacion,
    precioVenta: fallbackPrice,
    montoCotizacion: Number(row.monto_cotizacion || 0),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

async function getBudgetByIdForManualCommission(budgetId) {
  const cleanId = Number(budgetId || 0);
  if (!cleanId) return null;
  try {
    const fullBudget = await getBudgetWithDedupedCostTotals(cleanId);
    if (fullBudget) return fullBudget;
  } catch (error) {
    logServerError("manual-commission-budget-id-lookup", error);
  }

  if (!(await tableExists("presupuestos"))) return null;
  const budgetColumns = await getTableColumns("presupuestos");
  const hasUserId = budgetColumns.includes("usuario_id");
  const hasTitle = budgetColumns.includes("titulo_proyecto");
  const hasEmpresa = budgetColumns.includes("empresa");
  const hasSinGarantia = budgetColumns.includes("sin_garantia");
  const hasValorVenta = budgetColumns.includes("valor_venta_override");
  const hasComisionOverride = budgetColumns.includes("comision_supervisor_override");
  const hasUsers = await tableExists("usuarios");
  const hasClientQuotes = (await tableExists("cotizaciones_cliente")) && (await tableExists("cotizacion_cliente_partidas"));
  const hasEquipos = await tableExists("presupuesto_costos_equipos");
  const hasContratistas = await tableExists("presupuesto_costos_contratistas");
  const hasManoObra = await tableExists("presupuesto_costos_mano_obra");
  const hasMateriales = await tableExists("presupuesto_costos_materiales");
  const ownerJoin = hasUsers && hasUserId ? "LEFT JOIN usuarios u ON u.user_id = p.usuario_id" : "";
  const ownerSelect = hasUsers && hasUserId
    ? "COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '')"
    : "''";
  const ownerIdSelect = hasUserId ? "p.usuario_id" : "NULL";
  const comisionSelect = hasUsers && hasUserId
    ? `COALESCE(${hasComisionOverride ? "p.comision_supervisor_override," : ""} u.comision_supervisor, 0)`
    : `COALESCE(${hasComisionOverride ? "p.comision_supervisor_override" : "0"}, 0)`;
  const quoteSelect = hasClientQuotes
    ? `COALESCE((
        SELECT SUM(i.subtotal)
        FROM cotizaciones_cliente q
        LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
        WHERE q.presupuesto_id = p.id
          AND q.tipo = 'version'
          AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
        ORDER BY q.version DESC, q.id DESC
        LIMIT 1
      ), 0)`
    : "0";
  const joins = [
    ownerJoin,
    hasEquipos ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.equipos()} equipos ON equipos.presupuesto_id = p.id` : "",
    hasContratistas ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.contratistas()} contratistas ON contratistas.presupuesto_id = p.id` : "",
    hasManoObra ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.manoObra()} mano_obra ON mano_obra.presupuesto_id = p.id` : "",
    hasMateriales ? `LEFT JOIN ${BUDGET_COST_AGGREGATES.materiales()} materiales ON materiales.presupuesto_id = p.id` : ""
  ].filter(Boolean).join("\n");
  let rows = [];
  try {
    [rows] = await pool.execute(
      `SELECT
         p.id,
         p.folio,
         ${hasEmpresa ? "p.empresa" : "''"} AS empresa,
         ${hasTitle ? "p.titulo_proyecto" : "p.folio"} AS titulo_proyecto,
         ${ownerIdSelect} AS owner_id,
         ${ownerSelect} AS owner,
         ${comisionSelect} AS comision_supervisor,
         ${hasValorVenta ? "COALESCE(p.valor_venta_override, 0)" : "0"} AS valor_venta,
         ${hasSinGarantia ? "COALESCE(p.sin_garantia, 0)" : "0"} AS sin_garantia,
         ${hasEquipos ? "COALESCE(equipos.total, 0)" : "0"} AS total_equipos,
         ${hasContratistas ? "COALESCE(contratistas.total, 0)" : "0"} AS total_contratistas,
         ${hasManoObra ? "COALESCE(mano_obra.total, 0)" : "0"} AS total_mano_obra,
         ${hasMateriales ? "COALESCE(materiales.total, 0)" : "0"} AS total_materiales,
         ${quoteSelect} AS monto_cotizacion
       FROM presupuestos p
       ${joins}
       WHERE p.id = ?
       LIMIT 1`,
      [cleanId]
    );
  } catch (error) {
    logServerError("manual-commission-budget-id-rich-fallback", error);
    [rows] = await pool.execute(
      `SELECT
         p.id,
         p.folio,
         ${hasEmpresa ? "p.empresa" : "''"} AS empresa,
         ${hasTitle ? "p.titulo_proyecto" : "p.folio"} AS titulo_proyecto,
         ${hasUserId ? "p.usuario_id" : "NULL"} AS owner_id,
         '' AS owner,
         0 AS comision_supervisor,
         0 AS valor_venta,
         0 AS sin_garantia,
         0 AS total_equipos,
         0 AS total_contratistas,
         0 AS total_mano_obra,
         0 AS total_materiales,
         0 AS monto_cotizacion
       FROM presupuestos p
       WHERE p.id = ?
       LIMIT 1`,
      [cleanId]
    );
  }
  const row = rows[0];
  if (!row) return null;
  const totalProyecto =
    Number(row.total_equipos || 0) +
    Number(row.total_contratistas || 0) +
    Number(row.total_mano_obra || 0) +
    Number(row.total_materiales || 0);
  const costoCotizacion = totalProyecto + (row.sin_garantia ? 0 : totalProyecto * BUDGET_WARRANTY_RATE);
  const precioVentaPvp1 = costoCotizacion * Number(row.valor_venta || 0);
  return {
    id: row.id,
    empresa: row.empresa || "",
    tituloProyecto: row.titulo_proyecto || row.folio || "",
    folio: row.folio || "",
    owner: row.owner || "",
    ownerId: row.owner_id || null,
    sinGarantia: Boolean(row.sin_garantia),
    valorVenta: Number(row.valor_venta || 0),
    comisionSupervisor: Number(row.comision_supervisor || 0),
    totalEquipos: Number(row.total_equipos || 0),
    totalContratistas: Number(row.total_contratistas || 0),
    totalManoObra: Number(row.total_mano_obra || 0),
    totalMateriales: Number(row.total_materiales || 0),
    totalProyecto,
    costoCotizacion,
    precioVenta: precioVentaPvp1,
    montoCotizacion: Number(row.monto_cotizacion || 0)
  };
}

async function getBudgetByFolioBareMinimum(folio) {
  if (!(await tableExists("presupuestos"))) return null;
  const columns = await getTableColumns("presupuestos");
  const idColumn = pickColumn(columns, ["id", "presupuesto_id", "id_presupuesto"]) || "id";
  const folioColumn = pickColumn(columns, ["folio", "folio_presupuesto", "dlv"]) || "folio";
  const [rows] = await pool.execute(
    `SELECT *
     FROM presupuestos
     WHERE ${folioEqualsCondition(escapeId(folioColumn))}
     ORDER BY ${escapeId(idColumn)} DESC
     LIMIT 1`,
    [String(folio || "").trim()]
  );
  const row = rows[0];
  if (!row) return null;
  return {
    id: row[idColumn],
    empresa: row.empresa || "",
    tituloProyecto: row.titulo_proyecto || row.proyecto || row.folio || "",
    folio: row[folioColumn] || String(folio || "").trim(),
    owner: "",
    ownerId: row.usuario_id || null,
    sinGarantia: Boolean(row.sin_garantia),
    valorVenta: Number(row.valor_venta_override || row.valor_venta || 0),
    comisionSupervisor: Number(row.comision_supervisor_override || row.comision_supervisor || 0),
    totalEquipos: 0,
    totalContratistas: 0,
    totalManoObra: 0,
    totalMateriales: 0,
    totalProyecto: 0,
    precioVenta: Number(row.precio_venta || row.monto || row.total || 0),
    montoCotizacion: Number(row.monto_cotizacion || row.precio_venta || row.monto || row.total || 0)
  };
}

async function touchBudgetUpdatedAt(budgetId, connection = pool) {
  if (!budgetId) return;
  await connection.execute("UPDATE presupuestos SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", [budgetId]);
}

async function getBudgetCosts(budgetId) {
  const [equiposRows] = await pool.execute(
    `SELECT item_precio_id, item, cantidad_equipos, cantidad_um, unidad_medida, costo_unitario, flete, subtotal
     FROM presupuesto_costos_equipos
     WHERE presupuesto_id = ?
     ORDER BY id`,
    [budgetId]
  );
  const [contratistasRows] = await pool.execute(
    `SELECT descripcion, cantidad, costo, subtotal
     FROM presupuesto_costos_contratistas
     WHERE presupuesto_id = ?
     ORDER BY id`,
    [budgetId]
  );
  const [manoObraRows] = await pool.execute(
    `SELECT item_precio_id, descripcion, personas, horas, horas_total, costo_hora, comidas, costo_comida, subtotal
     FROM presupuesto_costos_mano_obra
     WHERE presupuesto_id = ?
     ORDER BY id`,
    [budgetId]
  );
  const [materialesRows] = await pool.execute(
    `SELECT descripcion, cantidad, unidad, costo, subtotal
     FROM presupuesto_costos_materiales
     WHERE presupuesto_id = ?
     ORDER BY id`,
    [budgetId]
  );

  return cleanBudgetCosts({
    equipos: equiposRows.map((row) => ({
      itemPrecioId: row.item_precio_id,
      item: row.item || "",
      cantidadEquipos: Number(row.cantidad_equipos || 0),
      cantidadUm: Number(row.cantidad_um || 0),
      unidadMedida: row.unidad_medida || "",
      costoUnitario: Number(row.costo_unitario || 0),
      flete: Number(row.flete || 0),
      subtotal: calculateBudgetEquipmentSubtotalServer(row)
    })),
    contratistas: contratistasRows.map((row) => ({
      descripcion: row.descripcion || "",
      cantidad: Number(row.cantidad || 0),
      costo: Number(row.costo || 0),
      subtotal: Number(row.subtotal || 0)
    })),
    manoObra: manoObraRows.map((row) => ({
      itemPrecioId: row.item_precio_id,
      descripcion: row.descripcion || "",
      personas: Number(row.personas || 0),
      horas: Number(row.horas || 0),
      horasTotal: Number(row.horas_total || 0),
      costoHora: Number(row.costo_hora || 0),
      comidas: Number(row.comidas || 0),
      costoComida: Number(row.costo_comida || 0),
      subtotal: Number(row.subtotal || 0)
    })),
    materiales: materialesRows.map((row) => ({
      descripcion: row.descripcion || "",
      cantidad: Number(row.cantidad || 0),
      unidad: row.unidad || "",
      costo: Number(row.costo || 0),
      subtotal: Number(row.subtotal || 0)
    }))
  });
}

function sumBudgetCostRows(rows = []) {
  return rows.reduce((sum, row) => sum + Number(row.subtotal || 0), 0);
}

function applyBudgetCostTotals(budget, costs = {}) {
  const totalEquipos = sumBudgetCostRows(costs.equipos);
  const totalContratistas = sumBudgetCostRows(costs.contratistas);
  const totalManoObra = sumBudgetCostRows(costs.manoObra);
  const totalMateriales = sumBudgetCostRows(costs.materiales);
  const totalProyecto = totalEquipos + totalContratistas + totalManoObra + totalMateriales;
  const costoCotizacion = totalProyecto + (budget.sinGarantia ? 0 : totalProyecto * BUDGET_WARRANTY_RATE);

  budget.totalEquipos = totalEquipos;
  budget.equiposCount = (costs.equipos || []).length;
  budget.totalContratistas = totalContratistas;
  budget.contratistasCount = (costs.contratistas || []).length;
  budget.totalManoObra = totalManoObra;
  budget.manoObraCount = (costs.manoObra || []).length;
  budget.totalMateriales = totalMateriales;
  budget.materialesCount = (costs.materiales || []).length;
  budget.totalProyecto = totalProyecto;
  budget.costoCotizacion = costoCotizacion;
  budget.precioVenta = costoCotizacion * Number(budget.valorVenta || 0);

  return budget;
}

async function getBudgetWithDedupedCostTotals(budgetId) {
  const budget = await getBudgetById(budgetId);
  if (!budget) return null;
  const costs = await getBudgetCosts(budgetId);
  return applyBudgetCostTotals(budget, costs);
}

function calculateBudgetBlockTotalsServer(budget, transfers = [], additionals = []) {
  const blocks = {
    equipos: Number(budget.totalEquipos || 0),
    manoObra: Number(budget.totalManoObra || 0) + Number(budget.totalContratistas || 0),
    materiales: Number(budget.totalMateriales || 0)
  };

  transfers.forEach((transfer) => {
    const origen = normalizeBudgetBlock(transfer.origen);
    const destino = normalizeBudgetBlock(transfer.destino);
    const amount = Number(transfer.monto || 0);
    if (blocks[origen] === undefined || blocks[destino] === undefined) return;
    blocks[origen] -= amount;
    blocks[destino] += amount;
  });

  additionals.forEach((additional) => {
    const normalizedBlock = normalizeBudgetBlock(additional.bloque ?? additional.block ?? additional.presupuesto ?? additional.tipo);
    const block = blocks[normalizedBlock] === undefined ? "materiales" : normalizedBlock;
    if (blocks[block] === undefined) return;
    blocks[block] += Number(additional.monto ?? additional.amount ?? 0);
  });

  return blocks;
}

function getBudgetBaseBlocksServer(budget = {}) {
  return {
    equipos: Number(budget.totalEquipos || 0),
    manoObra: Number(budget.totalManoObra || 0) + Number(budget.totalContratistas || 0),
    materiales: Number(budget.totalMateriales || 0)
  };
}

function eventTimestampServer(value) {
  const time = new Date(value || 0).getTime();
  return Number.isFinite(time) ? time : 0;
}

function calculateSupplierOrderAvailableTimelineServer(budget = {}, transfers = [], additionals = [], versions = [], currentOrderId = null) {
  const balances = getBudgetBaseBlocksServer(budget);
  const events = [];
  const activeFolios = versions
    .filter((order) => order.estatus !== "Cancelada" && Number(order.id) !== Number(currentOrderId))
    .map((order) => String(order.folio || ""));

  versions.forEach((order) => {
    if (order.estatus === "Cancelada" || Number(order.id) === Number(currentOrderId)) return;
    const folio = String(order.folio || "");
    if (folio && activeFolios.some((activeFolio) => activeFolio.startsWith(`${folio}.`))) return;
    events.push({
      type: "ocp",
      at: eventTimestampServer(order.createdAt || order.updatedAt),
      order: 20,
      items: order.items || []
    });
  });

  transfers.forEach((transfer) => {
    events.push({
      type: "transfer",
      at: eventTimestampServer(transfer.createdAt),
      order: 10,
      origen: normalizeBudgetBlock(transfer.origen),
      destino: normalizeBudgetBlock(transfer.destino),
      monto: Number(transfer.monto || 0)
    });
  });

  additionals.forEach((additional) => {
    const normalizedBlock = normalizeBudgetBlock(additional.bloque ?? additional.block ?? additional.presupuesto ?? additional.tipo);
    events.push({
      type: "additional",
      at: eventTimestampServer(additional.createdAt),
      order: 10,
      bloque: balances[normalizedBlock] === undefined ? "materiales" : normalizedBlock,
      monto: Number(additional.monto ?? additional.amount ?? 0)
    });
  });

  events
    .sort((a, b) => a.at - b.at || a.order - b.order)
    .forEach((event) => {
      if (event.type === "additional") {
        balances[event.bloque] += event.monto;
        return;
      }
      if (event.type === "transfer") {
        if (balances[event.origen] === undefined || balances[event.destino] === undefined) return;
        balances[event.origen] = Math.max(0, balances[event.origen] - event.monto);
        balances[event.destino] += event.monto;
        return;
      }
      (event.items || []).forEach((item) => {
        const block = normalizeBudgetBlock(item.presupuesto);
        if (balances[block] === undefined) return;
        balances[block] = Math.max(0, balances[block] - Number(item.total || 0));
      });
    });

  return balances;
}

function calculateBudgetSalePriceServer(budget) {
  const tablesCost =
    Number(budget.totalEquipos || 0) +
    Number(budget.totalContratistas || 0) +
    Number(budget.totalManoObra || 0) +
    Number(budget.totalMateriales || 0);
  const warranty = budget.sinGarantia ? 0 : tablesCost * BUDGET_WARRANTY_RATE;
  return (tablesCost + warranty) * Number(budget.valorVenta || 0);
}

function calculateBudgetGrossProfitServer(budget) {
  const tablesCost =
    Number(budget.totalEquipos || 0) +
    Number(budget.totalContratistas || 0) +
    Number(budget.totalManoObra || 0) +
    Number(budget.totalMateriales || 0);
  const warranty = budget.sinGarantia ? 0 : tablesCost * BUDGET_WARRANTY_RATE;
  const costoCotizacion = Number(budget.costoCotizacion || 0) || tablesCost + warranty;
  const precioVenta = Number(budget.montoCotizacion || budget.precioVenta || 0) || calculateBudgetSalePriceServer(budget);
  return Math.round((precioVenta - costoCotizacion) * 100) / 100;
}

function calculateBudgetUtilityTotalServer(budget) {
  const precioVenta = Number(budget.montoCotizacion || budget.precioVenta || 0) || calculateBudgetSalePriceServer(budget);
  const utilidadBruta = calculateBudgetGrossProfitServer(budget);
  const comisionSupervisor = precioVenta * (Number(budget.comisionSupervisor || 0) / 100);
  return Math.round((utilidadBruta - comisionSupervisor) * 100) / 100;
}

function commissionFolioBaseFromBudget(folio = "", budgetId = 0) {
  const digits = String(folio || "").match(/\d+/g)?.join("") || String(budgetId || "");
  return `OCCOM${String(digits).slice(-4).padStart(4, "0")}`;
}

async function generateCommissionFolio(connection, budget, reservedFolios = []) {
  const base = commissionFolioBaseFromBudget(budget?.folio, budget?.id);
  const [rows] = await connection.execute(
    "SELECT folio FROM comisiones WHERE folio LIKE ? ORDER BY id ASC",
    [`${base}%`]
  );
  const used = new Set([
    ...rows.map((row) => String(row.folio || "")),
    ...reservedFolios.map((folio) => String(folio || ""))
  ]);
  if (!used.has(base)) return base;
  let next = 1;
  while (used.has(`${base}-${next}`)) next += 1;
  return `${base}-${next}`;
}

async function getSupervisorUsers() {
  const [rows] = await pool.execute(
    `SELECT
        u.user_id AS id,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario) AS nombre,
        u.usuario,
        COALESCE(u.comision_supervisor, 0) AS comision_supervisor
      FROM usuarios u
      INNER JOIN roles r ON r.id = u.rol_id
      WHERE LOWER(r.nombre) IN ('supervisor', 'superadmin') AND COALESCE(u.activo, 1) = 1
      ORDER BY nombre ASC`
  );
  return rows.map((row) => ({
    id: row.id,
    nombre: row.nombre || row.usuario || "Supervisor",
    usuario: row.usuario || "",
    comisionSupervisor: Number(row.comision_supervisor || 0)
  }));
}

async function getBudgetAdditionalsSummary(budgetIds = []) {
  const ids = [...new Set(budgetIds.map((id) => Number(id || 0)).filter(Boolean))];
  if (!ids.length) return new Map();
  try {
    const placeholders = ids.map(() => "?").join(",");
    const [rows] = await pool.execute(
      `SELECT presupuesto_id, SUM(COALESCE(monto, 0)) AS total
       FROM presupuesto_adicionales
       WHERE presupuesto_id IN (${placeholders})
       GROUP BY presupuesto_id`,
      ids
    );
    return new Map(rows.map((row) => [Number(row.presupuesto_id), Number(row.total || 0)]));
  } catch (error) {
    if (["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) return new Map();
    throw error;
  }
}

async function getCommissionBudgetDocumentSearchMap(budgetIds = []) {
  const ids = [...new Set(budgetIds.map((id) => Number(id || 0)).filter(Boolean))];
  const map = new Map();
  if (!ids.length) return map;

  const addRows = (rows = []) => {
    rows.forEach((row) => {
      const budgetId = Number(row.presupuesto_id || 0);
      if (!budgetId) return;
      const text = String(row.search_text || "").trim();
      if (!text) return;
      map.set(budgetId, [map.get(budgetId), text].filter(Boolean).join(" "));
    });
  };

  const placeholders = ids.map(() => "?").join(",");
  const queries = [
    `SELECT presupuesto_id, GROUP_CONCAT(CONCAT_WS(' ', tipo, nombre) SEPARATOR ' ') AS search_text
     FROM presupuesto_archivos
     WHERE presupuesto_id IN (${placeholders})
     GROUP BY presupuesto_id`,
    `SELECT presupuesto_id, GROUP_CONCAT(CONCAT_WS(' ', numero_po, nombre) SEPARATOR ' ') AS search_text
     FROM presupuesto_po_cliente
     WHERE presupuesto_id IN (${placeholders})
     GROUP BY presupuesto_id`,
    `SELECT presupuesto_id, GROUP_CONCAT(CONCAT_WS(' ', tipo, nombre) SEPARATOR ' ') AS search_text
     FROM ocp_proveedor_archivos
     WHERE presupuesto_id IN (${placeholders})
     GROUP BY presupuesto_id`,
    `SELECT presupuesto_id, GROUP_CONCAT(CONCAT_WS(' ', folio, estatus) SEPARATOR ' ') AS search_text
     FROM cotizaciones_cliente
     WHERE presupuesto_id IN (${placeholders})
     GROUP BY presupuesto_id`,
    `SELECT COALESCE(c.presupuesto_id, q.presupuesto_id) AS presupuesto_id,
            GROUP_CONCAT(CONCAT_WS(' ', a.tipo, a.nombre) SEPARATOR ' ') AS search_text
     FROM cuentas_por_cobrar_archivos a
     INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
     LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
     WHERE COALESCE(c.presupuesto_id, q.presupuesto_id) IN (${placeholders})
     GROUP BY COALESCE(c.presupuesto_id, q.presupuesto_id)`
  ];

  for (const query of queries) {
    try {
      const [rows] = await pool.execute(query, ids);
      addRows(rows);
    } catch (error) {
      if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
    }
  }

  return map;
}

async function getApprovedClientQuoteNetAmountMap(budgetIds = [], executor = pool) {
  const ids = [...new Set(budgetIds.map((id) => Number(id || 0)).filter(Boolean))];
  const map = new Map();
  if (!ids.length) return map;
  const placeholders = ids.map(() => "?").join(",");
  try {
    const [rows] = await executor.execute(
      `SELECT
          q.presupuesto_id,
          GREATEST(
            COALESCE(SUM(i.subtotal), 0) - COALESCE(MAX(q.descuento_monto), 0),
            0
          ) AS monto_cotizacion
       FROM cotizaciones_cliente q
       LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
       WHERE q.presupuesto_id IN (${placeholders})
         AND q.tipo = 'version'
         AND LOWER(TRIM(COALESCE(q.estatus, ''))) LIKE 'aprob%'
         AND q.id = (
           SELECT q2.id
           FROM cotizaciones_cliente q2
           WHERE q2.presupuesto_id = q.presupuesto_id
             AND q2.tipo = 'version'
             AND LOWER(TRIM(COALESCE(q2.estatus, ''))) LIKE 'aprob%'
           ORDER BY q2.version DESC, q2.id DESC
           LIMIT 1
         )
       GROUP BY q.presupuesto_id`,
      ids
    );
    rows.forEach((row) => {
      const budgetId = Number(row.presupuesto_id || 0);
      if (!budgetId) return;
      map.set(budgetId, Math.max(0, Math.round(Number(row.monto_cotizacion || 0) * 100) / 100));
    });
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }
  return map;
}

async function getCommissionBudgetPaymentDateMap(budgetIds = []) {
  const ids = [...new Set(budgetIds.map((id) => Number(id || 0)).filter(Boolean))];
  const map = new Map();
  if (!ids.length) return map;
  const placeholders = ids.map(() => "?").join(",");

  // La comisión requiere complemento de pago, pero la fecha mostrada debe corresponder
  // al cobro real: FechaPago del XML del comprobante; si no existe XML legible, usamos
  // la fecha de carga del comprobante. El complemento queda como respaldo histórico.
  try {
    const [rows] = await pool.execute(
      `SELECT
          p.id AS presupuesto_id,
          cx.id AS cuenta_id,
          (
            SELECT MAX(a.created_at)
            FROM cuentas_por_cobrar_archivos a
            WHERE a.cuenta_id = cx.id
              AND a.tipo = 'Complemento de pago'
          ) AS complemento_pago_fecha,
          (
            SELECT MAX(a.created_at)
            FROM cuentas_por_cobrar_archivos a
            WHERE a.cuenta_id = cx.id
              AND a.tipo = 'Comprobante de pago'
          ) AS comprobante_pago_fecha,
          (
            SELECT a.ruta
            FROM cuentas_por_cobrar_archivos a
            WHERE a.cuenta_id = cx.id
              AND a.tipo = 'Comprobante de pago'
              AND LOWER(a.nombre) LIKE '%.xml'
            ORDER BY a.created_at DESC, a.id DESC
            LIMIT 1
          ) AS comprobante_pago_xml_ruta
       FROM presupuestos p
       INNER JOIN cotizaciones_cliente q ON q.presupuesto_id = p.id
        AND q.tipo = 'version'
        AND LOWER(TRIM(COALESCE(q.estatus, ''))) LIKE 'aprob%'
        AND q.id = (
          SELECT q2.id
          FROM cotizaciones_cliente q2
          WHERE q2.presupuesto_id = p.id
            AND q2.tipo = 'version'
            AND LOWER(TRIM(COALESCE(q2.estatus, ''))) LIKE 'aprob%'
          ORDER BY q2.version DESC, q2.id DESC
          LIMIT 1
        )
       INNER JOIN cuentas_por_cobrar cx ON cx.cotizacion_cliente_id = q.id
       WHERE p.id IN (${placeholders})`,
      ids
    );

    for (const row of rows) {
      const budgetId = Number(row.presupuesto_id || 0);
      if (!budgetId || !row.complemento_pago_fecha) continue;
      const xmlPaymentDate = await getPaymentDateFromXmlPath(row.comprobante_pago_xml_ruta);
      const realPaymentDate = xmlPaymentDate || row.comprobante_pago_fecha || row.complemento_pago_fecha || null;
      if (!realPaymentDate) continue;
      const current = map.get(budgetId);
      if (!current || new Date(realPaymentDate).getTime() > new Date(current).getTime()) {
        map.set(budgetId, realPaymentDate);
      }
    }
  } catch (error) {
    if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
  }

  // Respaldo para históricos donde la documentación quedó enlazada de forma antigua.
  const addLegacyRows = (rows = []) => {
    rows.forEach((row) => {
      const budgetId = Number(row.presupuesto_id || 0);
      if (!budgetId || map.has(budgetId) || !row.fecha_pago) return;
      map.set(budgetId, row.fecha_pago);
    });
  };
  const legacyQueries = [
    {
      sql:
      `SELECT
          COALESCE(c.presupuesto_id, q.presupuesto_id) AS presupuesto_id,
          MAX(a.created_at) AS fecha_pago
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
       LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
       WHERE COALESCE(c.presupuesto_id, q.presupuesto_id) IN (${placeholders})
         AND (
           LOWER(TRIM(COALESCE(a.tipo, ''))) LIKE '%complemento%'
           OR LOWER(COALESCE(a.nombre, '')) LIKE '%complemento%'
           OR LOWER(COALESCE(a.ruta, '')) LIKE '%complemento%'
         )
       GROUP BY COALESCE(c.presupuesto_id, q.presupuesto_id)
       HAVING fecha_pago IS NOT NULL`,
      values: ids
    },
    {
      sql:
      `SELECT
          p.id AS presupuesto_id,
          MAX(a.created_at) AS fecha_pago
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
       INNER JOIN presupuestos p ON p.id IN (${placeholders})
        AND REPLACE(COALESCE(a.ruta, ''), CHAR(92), '/') LIKE CONCAT('%/', p.folio, '/%')
       WHERE LOWER(TRIM(COALESCE(a.tipo, ''))) LIKE '%complemento%'
          OR LOWER(COALESCE(a.nombre, '')) LIKE '%complemento%'
          OR LOWER(COALESCE(a.ruta, '')) LIKE '%complemento%'
       GROUP BY p.id
       HAVING fecha_pago IS NOT NULL`,
      values: ids
    },
    {
      sql:
      `SELECT
          presupuesto_id,
          MAX(created_at) AS fecha_pago
       FROM presupuesto_archivos
       WHERE presupuesto_id IN (${placeholders})
         AND (
           LOWER(TRIM(COALESCE(tipo, ''))) LIKE '%complemento%'
           OR LOWER(COALESCE(nombre, '')) LIKE '%complemento%'
           OR LOWER(COALESCE(ruta, '')) LIKE '%complemento%'
         )
       GROUP BY presupuesto_id
       HAVING fecha_pago IS NOT NULL`,
      values: ids
    },
    {
      sql:
      `SELECT
          p.id AS presupuesto_id,
          MAX(a.created_at) AS fecha_pago
       FROM presupuesto_archivos a
       INNER JOIN presupuestos p ON p.id IN (${placeholders})
        AND REPLACE(COALESCE(a.ruta, ''), CHAR(92), '/') LIKE CONCAT('%/', p.folio, '/%')
       WHERE LOWER(TRIM(COALESCE(a.tipo, ''))) LIKE '%complemento%'
          OR LOWER(COALESCE(a.nombre, '')) LIKE '%complemento%'
          OR LOWER(COALESCE(a.ruta, '')) LIKE '%complemento%'
       GROUP BY p.id
       HAVING fecha_pago IS NOT NULL`,
      values: ids
    }
  ];
  for (const query of legacyQueries) {
    try {
      const [rows] = await pool.execute(query.sql, query.values);
      addLegacyRows(rows);
    } catch (error) {
      if (!["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) throw error;
    }
  }
  return map;
}

function applyCommissionAdditionalCarry(items = []) {
  const sorted = [...items].sort((a, b) => {
    const ownerCompare = Number(a.supervisorId || 0) - Number(b.supervisorId || 0);
    if (ownerCompare) return ownerCompare;
    const dateCompare = new Date(a.createdAt || 0).getTime() - new Date(b.createdAt || 0).getTime();
    if (dateCompare) return dateCompare;
    return Number(a.presupuestoId || 0) - Number(b.presupuestoId || 0);
  });
  const carryByOwner = new Map();
  sorted.forEach((item) => {
    const ownerKey = Number(item.supervisorId || 0) || `owner:${item.supervisorNombre || ""}`;
    const carryIn = Number(carryByOwner.get(ownerKey) || 0);
    const base = Number(item.montoComisionBase ?? item.montoComision ?? 0);
    const additional = Number(item.presupuestoAdicional || 0);
    const net = base + carryIn - additional;
    item.saldoComisionAnterior = carryIn;
    item.montoComisionMenosPa = net;
    item.montoComisionDisponible = Math.max(0, net);
    item.montoComision = item.montoComisionDisponible;
    item.saldoComisionSiguiente = Math.min(0, net);
    carryByOwner.set(ownerKey, item.saldoComisionSiguiente);
  });
  return items;
}

async function getCommissionAvailableForBudget(budget, ownerSupervisor = null) {
  const montoProyecto = Number(budget?.precioVenta || 0) || calculateBudgetSalePriceServer(budget || {});
  const porcentaje = Number(budget?.comisionSupervisor ?? ownerSupervisor?.comisionSupervisor ?? 0);
  const montoComisionBase = Math.round(montoProyecto * (porcentaje / 100) * 100) / 100;
  const [rows] = await pool.execute(
    `SELECT COALESCE(SUM(monto_comision), 0) AS asignado
       FROM comisiones
      WHERE presupuesto_id = ?
        AND COALESCE(supervisor_nombre_manual, '') = ''
        AND LOWER(COALESCE(estatus, '')) NOT IN (
          'cancelada', 'cancelado', 'eliminada', 'eliminado',
          'rechazada', 'rechazado', 'no aprobada', 'no aprobado'
        )`,
    [budget.id]
  );
  const asignado = Number(rows[0]?.asignado || 0);
  // La comisión normal se calcula exclusivamente sobre PVP1. Un presupuesto adicional
  // aumenta/distribuye presupuesto operativo, pero no descuenta la comisión del supervisor.
  return Math.max(0, Math.round((montoComisionBase - asignado) * 100) / 100);
}

async function getCommissionsPayload(user, search = "") {
  await ensureCommissionTables();
  const supervisors = await getSupervisorUsers();
  const supervisorMap = new Map(supervisors.map((supervisor) => [Number(supervisor.id), supervisor]));
  const budgets = await getBudgets("", user, { limit: 5000 });
  const paymentDateMap = await getCommissionBudgetPaymentDateMap(budgets.map((budget) => budget.id));
  const additionalMap = await getBudgetAdditionalsSummary(budgets.map((budget) => budget.id));
  const rawBudgetItems = budgets
    .map((budget) => {
      const ownerSupervisor = supervisorMap.get(Number(budget.ownerId || 0));
      const montoProyecto = Number(budget.precioVenta || 0) || calculateBudgetSalePriceServer(budget);
      const porcentaje = Number(budget.comisionSupervisor ?? ownerSupervisor?.comisionSupervisor ?? 0);
      const montoComisionBase = montoProyecto * (porcentaje / 100);
      const fechaPago = paymentDateMap.get(Number(budget.id)) || null;
      return {
        presupuestoId: budget.id,
        supervisorId: budget.ownerId || ownerSupervisor?.id || null,
        supervisorNombre: budget.owner || ownerSupervisor?.nombre || "Sin supervisor",
        nombreProyecto: budget.tituloProyecto || budget.folio,
        descripcionProyecto: budget.folio || "",
        empresa: budget.empresa || "",
        folioPresupuesto: budget.folio || "",
        montoProyecto,
        porcentajeComision: porcentaje,
        montoComisionBase,
        montoComision: montoComisionBase,
        presupuestoAdicional: Number(additionalMap.get(Number(budget.id)) || 0),
        saldoComisionAnterior: 0,
        montoComisionMenosPa: montoComisionBase,
        montoComisionDisponible: montoComisionBase,
        saldoComisionSiguiente: 0,
        fechaPago,
        cobrada: paymentDateMap.has(Number(budget.id)),
        createdAt: budget.createdAt,
        updatedAt: budget.updatedAt,
        searchText: [
          budget.empresa,
          budget.sucursal,
          budget.clienteUsuario,
          budget.area,
          budget.tituloProyecto,
          budget.folio,
          fechaPago,
          budget.owner,
          budget.searchText
        ].join(" ")
      };
    })
    .filter((item) => Number(item.montoProyecto || 0) > 0);
  // La comisión normal parte de PVP1 y no se reduce por presupuesto adicional.
  // El PA se conserva únicamente como dato informativo del proyecto.
  const budgetItems = rawBudgetItems.map((item) => ({
    ...item,
    saldoComisionAnterior: 0,
    montoComisionMenosPa: Number(item.montoComisionBase || 0),
    montoComisionDisponible: Number(item.montoComisionBase || 0),
    montoComision: Number(item.montoComisionBase || 0),
    saldoComisionSiguiente: 0
  }));

  const values = [];
  const conditions = [];
  if (shouldRestrictToOwnedBudgets(user)) {
    const userId = Number(user.id || 0);
    const branchIds = getSessionBranchAccessIds(user, "modulo:comisiones");
    const accessParts = [];
    if (userId) {
      accessParts.push("c.supervisor_id = ?", "p.usuario_id = ?");
      values.push(userId, userId);
    }
    if (branchIds.length) {
      accessParts.push(`p.sucursal_id IN (${branchIds.map(() => "?").join(",")})`);
      values.push(...branchIds);
    }
    conditions.push(accessParts.length ? `(${accessParts.join(" OR ")})` : "1 = 0");
  }
  const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
  const [commissionRows] = await pool.execute(
    `SELECT
        c.id,
        c.presupuesto_id,
        c.supervisor_id,
        c.supervisor_nombre_manual,
        c.folio,
        c.nombre_proyecto,
        c.descripcion_proyecto,
        c.empresa,
        c.monto_proyecto,
        c.porcentaje_comision,
        c.porcentaje_distribucion,
        c.descuento,
        c.monto_comision,
        c.estatus,
        c.created_at,
        c.updated_at,
        c.supervisor_nombre_manual,
        p.folio AS presupuesto_folio,
        COALESCE(NULLIF(c.supervisor_nombre_manual, ''), NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS supervisor_nombre,
        cp.pagado AS cuenta_pagada
      FROM comisiones c
      LEFT JOIN presupuestos p ON p.id = c.presupuesto_id
      LEFT JOIN usuarios u ON u.user_id = c.supervisor_id
      LEFT JOIN cuentas_por_pagar cp ON cp.comision_id = c.id AND cp.tipo_origen = 'OCCOM'
      ${where}
      ORDER BY c.id DESC
      LIMIT 1000`,
    values
  );
  const normalizedSearch = normalizeSearchText(search);
  let documentSearchMap = new Map();
  if (normalizedSearch) {
    const visibleBudgetMatches = budgetItems.some((item) =>
      normalizeSearchText(Object.values(item).join(" ")).includes(normalizedSearch)
    );
    const visibleCommissionMatches = commissionRows.some((row) =>
      normalizeSearchText(Object.values(row).join(" ")).includes(normalizedSearch)
    );
    if (!visibleBudgetMatches && !visibleCommissionMatches) {
      documentSearchMap = await getCommissionBudgetDocumentSearchMap([
        ...budgetItems.map((item) => item.presupuestoId),
        ...commissionRows.map((row) => row.presupuesto_id)
      ]);
    }
  }
  const activeCommissionStatuses = new Set(["no aprobada", "rechazada", "cancelada", "cancelado", "eliminada", "eliminado"]);
  const assignedByBudget = new Map();
  commissionRows.forEach((row) => {
    const status = normalizeSearchText(row.estatus || "");
    const isManualCommission = Boolean(String(row.supervisor_nombre_manual || "").trim());
    if (isManualCommission || activeCommissionStatuses.has(status)) return;
    const budgetId = Number(row.presupuesto_id || 0);
    if (!budgetId) return;
    const amount = Number(row.monto_comision || 0);
    assignedByBudget.set(budgetId, Math.round((Number(assignedByBudget.get(budgetId) || 0) + amount) * 100) / 100);
  });
  budgetItems.forEach((item) => {
    const budgetId = Number(item.presupuestoId || 0);
    const assigned = Math.max(0, Number(assignedByBudget.get(budgetId) || 0));
    const available = Math.max(0, Math.round((Number(item.montoComisionDisponible || 0) - assigned) * 100) / 100);
    item.montoComisionAsignada = assigned;
    item.montoComisionDisponible = available;
    item.montoComision = available;
  });
  const commissionBudgetMap = new Map(budgets.map((budget) => [Number(budget.id || 0), budget]));
  const manualBudgetIds = [...new Set(
    commissionRows
      .filter((row) => Boolean(String(row.supervisor_nombre_manual || "").trim()))
      .map((row) => Number(row.presupuesto_id || 0))
      .filter(Boolean)
  )];
  const manualPvp2Map = new Map();
  await Promise.all(
    manualBudgetIds.map(async (budgetId) => {
      try {
        const pvp2 = await getLatestClientQuotePvp2(budgetId);
        if (pvp2) manualPvp2Map.set(budgetId, pvp2);
      } catch (_error) {
        // Los históricos conservan su monto almacenado si no hay PVP2 disponible.
      }
    })
  );

  const history = commissionRows
    .map((row) => {
      const budgetId = Number(row.presupuesto_id || 0);
      const isManualCommission = Boolean(String(row.supervisor_nombre_manual || "").trim());
      const budgetReference = commissionBudgetMap.get(budgetId) || {};
      const pvp2Reference = manualPvp2Map.get(budgetId);
      const baseProyecto = isManualCommission
        ? Number(pvp2Reference?.monto || row.monto_proyecto || 0)
        : Number(budgetReference.precioVenta || 0) || Number(row.monto_proyecto || 0);
      return {
      id: row.id,
      presupuestoId: row.presupuesto_id,
      supervisorId: row.supervisor_id,
      supervisorNombre: row.supervisor_nombre || "Sin supervisor",
      folio: row.folio || "",
      folioPresupuesto: row.presupuesto_folio || "",
      nombreProyecto: row.nombre_proyecto || "",
      descripcionProyecto: row.descripcion_proyecto || "",
      empresa: row.empresa || "",
      montoProyecto: baseProyecto,
      pvp1: Number(budgetReference.precioVenta || 0),
      pvp2Version: isManualCommission ? Number(pvp2Reference?.version || 0) : 0,
      pvp2Folio: isManualCommission ? String(pvp2Reference?.folio || "") : "",
      porcentajeComision: Number(row.porcentaje_comision || 0),
      porcentajeDistribucion: Number(row.porcentaje_distribucion || 100),
      descuento: Number(row.descuento || 0),
      montoComision: Number(row.monto_comision || 0),
      manualCommission: Boolean(row.supervisor_nombre_manual),
      estatus: row.estatus || "Generada",
      estatusPago: row.cuenta_pagada ? "Pagada" : "Pendiente de pago",
      fechaPago: paymentDateMap.get(Number(row.presupuesto_id || 0)) || null,
      cobrada: paymentDateMap.has(Number(row.presupuesto_id || 0)),
      documentosBusqueda: documentSearchMap.get(Number(row.presupuesto_id || 0)) || "",
      createdAt: row.created_at,
      updatedAt: row.updated_at
      };
    })
    .filter((item) => {
      if (!normalizedSearch) return true;
      return normalizeSearchText(Object.values(item).join(" ")).includes(normalizedSearch);
    });

  return {
    supervisors,
    budgets: budgetItems.filter((item) => {
      if (Number(item.montoComisionDisponible || 0) <= 0.009) return false;
      if (!normalizedSearch) return true;
      const documentSearch = documentSearchMap.get(Number(item.presupuestoId || 0)) || "";
      return normalizeSearchText([Object.values(item).join(" "), documentSearch].join(" ")).includes(normalizedSearch);
    }),
    commissions: history,
    canManage: canManageCommissions(user)
  };
}

function getClientQuoteItemsSubtotal(items = []) {
  return items.reduce((sum, row) => sum + Number(row.subtotal || 0), 0);
}

function normalizeClientQuoteDiscount(value, subtotal = 0) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount) || amount <= 0) return 0;
  return Math.min(amount, Math.max(Number(subtotal || 0), 0));
}

function validateClientQuoteAmount(budget, items, user = null, discountAmount = 0) {
  if (isSuperAdminSession(user)) return null;
  const salePrice = calculateBudgetSalePriceServer(budget);
  if (!salePrice) return null;
  const subtotal = getClientQuoteItemsSubtotal(items);
  const netTotal = Math.max(subtotal - normalizeClientQuoteDiscount(discountAmount, subtotal), 0);
  const max = salePrice * 1.1;
  if (netTotal < salePrice) {
    return `La cotización no puede ser menor al precio de venta (${formatCurrencyServer(salePrice)}).`;
  }
  if (netTotal > max) {
    return `La cotización solo puede exceder hasta 10% el precio de venta (${formatCurrencyServer(max)} máximo).`;
  }
  return null;
}

async function validateSupplierOrderBudgetAvailability(connection, budgetId, items, currentOrderId = null) {
  const budget = await getBudgetWithDedupedCostTotals(budgetId);
  if (!budget) return "Presupuesto no encontrado.";
  const [transfers, additionals] = await Promise.all([getBudgetTransfers(budgetId), getBudgetAdditionals(budgetId)]);
  const versions = await getSupplierOrderVersions(budgetId);
  const availableBlocks = calculateSupplierOrderAvailableTimelineServer(
    budget,
    transfers,
    additionals,
    versions,
    currentOrderId
  );
  const requested = items.reduce((acc, row) => {
    const block = normalizeBudgetBlock(row.presupuesto);
    acc[block] = Number(acc[block] || 0) + Number(row.total || 0);
    return acc;
  }, {});
  const totalAvailable = Object.values(availableBlocks).reduce((sum, value) => sum + Math.max(0, Number(value || 0)), 0);
  const totalRequested = Object.values(requested).reduce((sum, value) => sum + Math.max(0, Number(value || 0)), 0);

  if (totalRequested > 0 && totalAvailable <= 0.005) {
    return "No se puede crear otra OCP porque no hay presupuesto disponible. Agrega presupuesto adicional o transfiere presupuesto antes de continuar.";
  }

  for (const [block, amount] of Object.entries(requested)) {
    const available = Number(availableBlocks[block] || 0);
    if (amount > available + 0.005) {
      return `No se puede crear la OCP porque ${getBudgetBlockLabelServer(block)} no tiene presupuesto suficiente. Disponible: ${formatCurrencyServer(available)}.`;
    }
  }
  return null;
}

async function getSupplierOrderAvailableBlocksServer(budgetId) {
  const budget = await getBudgetWithDedupedCostTotals(budgetId);
  if (!budget) return null;
  const [transfers, additionals] = await Promise.all([getBudgetTransfers(budgetId), getBudgetAdditionals(budgetId)]);
  const versions = await getSupplierOrderVersions(budgetId);
  return calculateSupplierOrderAvailableTimelineServer(budget, transfers, additionals, versions);
}

async function getBudgetTransfers(budgetId) {
  try {
    const [rows] = await pool.execute(
      `SELECT t.id, t.origen, t.destino, t.monto, t.usuario_id, t.created_at,
              COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, 'Sistema') AS registrado_por
       FROM presupuesto_transferencias t
       LEFT JOIN usuarios u ON u.user_id = t.usuario_id
       WHERE t.presupuesto_id = ?
       ORDER BY t.id DESC`,
      [budgetId]
    );
    return rows.map((row) => ({
      id: row.id,
      origen: normalizeBudgetBlock(row.origen),
      destino: normalizeBudgetBlock(row.destino),
      monto: Number(row.monto || 0),
      usuarioId: row.usuario_id || null,
      registradoPor: row.registrado_por || "Sistema",
      createdAt: row.created_at
    }));
  } catch (error) {
    if (["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) return [];
    throw error;
  }
}

async function getBudgetAdditionals(budgetId) {
  try {
    const [rows] = await pool.execute(
      `SELECT a.id, a.bloque, a.monto, a.usuario_id, a.created_at,
              COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, 'Sistema') AS registrado_por
       FROM presupuesto_adicionales a
       LEFT JOIN usuarios u ON u.user_id = a.usuario_id
       WHERE a.presupuesto_id = ?
       ORDER BY a.id DESC`,
      [budgetId]
    );
    return rows.map((row) => ({
      id: row.id,
      bloque: BUDGET_BLOCKS.has(normalizeBudgetBlock(row.bloque)) ? normalizeBudgetBlock(row.bloque) : "materiales",
      monto: Number(row.monto || 0),
      usuarioId: row.usuario_id || null,
      registradoPor: row.registrado_por || "Sistema",
      createdAt: row.created_at
    }));
  } catch (error) {
    if (["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) return [];
    throw error;
  }
}

async function getExpenseReassignmentHistory(type, recordIds = [], connection = pool, scope = {}) {
  const normalizedType = String(type || "").trim().toUpperCase();
  const ids = [...new Set((recordIds || []).map((value) => Number(value || 0)).filter(Boolean))];
  const scopeType = String(scope.type || "").trim().toUpperCase();
  const scopeId = Number(scope.id || 0);
  if (!normalizedType || (!ids.length && (!scopeType || !scopeId))) return [];
  try {
    const conditions = [];
    const values = [normalizedType];
    if (ids.length) {
      conditions.push(`r.registro_id IN (${ids.map(() => "?").join(",")})`);
      values.push(...ids);
    }
    if (scopeType && scopeId) {
      conditions.push("((r.origen_tipo = ? AND r.origen_id = ?) OR (r.destino_tipo = ? AND r.destino_id = ?))");
      values.push(scopeType, scopeId, scopeType, scopeId);
    }
    const [rows] = await connection.execute(
      `SELECT r.id, r.tipo_documento, r.registro_id, r.folio,
              r.origen_tipo, r.origen_id, r.origen_referencia,
              r.destino_tipo, r.destino_id, r.destino_referencia,
              r.motivo, r.usuario_id, r.created_at,
              COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, 'Sistema') AS registrado_por
       FROM gasto_reasignaciones r
       LEFT JOIN usuarios u ON u.user_id = r.usuario_id
       WHERE r.tipo_documento = ?
         AND (${conditions.join(" OR ")})
       ORDER BY r.created_at DESC, r.id DESC`,
      values
    );
    return rows.map((row) => ({
      id: Number(row.id),
      tipoDocumento: row.tipo_documento,
      registroId: Number(row.registro_id),
      folio: row.folio || "",
      origenTipo: row.origen_tipo || "",
      origenId: Number(row.origen_id || 0),
      origenReferencia: row.origen_referencia || "",
      destinoTipo: row.destino_tipo || "",
      destinoId: Number(row.destino_id || 0),
      destinoReferencia: row.destino_referencia || "",
      motivo: row.motivo || "",
      usuarioId: row.usuario_id || null,
      registradoPor: row.registrado_por || "Sistema",
      createdAt: row.created_at
    }));
  } catch (error) {
    if (["ER_NO_SUCH_TABLE", "ER_BAD_FIELD_ERROR"].includes(error.code)) return [];
    throw error;
  }
}

function clientQuoteBaseFromBudgetFolio(folio = "") {
  const normalizedFolio = String(folio || "").trim();
  return normalizedFolio || "COTIZACION";
}

function purchaseOrderBaseFromBudgetFolio(folio = "") {
  const digits = String(folio || "").replace(/\D/g, "");
  const sequence = digits.slice(-4) || "0000";
  return `OCP${sequence.padStart(4, "0")}`;
}

function escapeHtmlServer(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function formatCurrencyServer(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(Number(value || 0));
}

function parseMoneyServer(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  const cleaned = String(value ?? "")
    .replace(/,/g, "")
    .replace(/[^\d.-]/g, "");
  const parsed = Number(cleaned);
  return Number.isFinite(parsed) ? parsed : 0;
}

function roundMoneyServer(value) {
  return Math.round(parseMoneyServer(value) * 100) / 100;
}

function getBudgetBlockLabelServer(value) {
  const labels = {
    equipos: "Equipos",
    manoObra: "Mano de obra",
    materiales: "Materiales"
  };
  return labels[normalizeBudgetBlock(value)] || value || "presupuesto";
}

function unlinkStoredFile(relativePath, allowedRoot) {
  if (!relativePath) return;
  const absolutePath = path.resolve(__dirname, relativePath);
  const root = path.resolve(allowedRoot);
  if (absolutePath.startsWith(root)) {
    fs.promises.unlink(absolutePath).catch(() => {});
  }
}

function formatQuoteDate(value = new Date()) {
  return new Intl.DateTimeFormat("es-MX", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "2-digit"
  }).format(new Date(value));
}

function normalizeQuoteFileName(value) {
  return String(value || "cotizacion")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 120);
}

function clientQuoteBaseFolioForDocument(quote = {}) {
  const budgetFolio = String(quote.presupuestoFolio || "").trim();
  if (budgetFolio) return budgetFolio;
  const quoteFolio = String(quote.folio || "").trim();
  return quoteFolio.replace(/-\d+$/, "") || quoteFolio;
}

function clientQuotePdfFileBase(quote = {}, suffix = "") {
  const baseFolio = clientQuoteBaseFolioForDocument(quote) || quote.folio || `cotizacion_${quote.id}`;
  const version = Number(quote.version || 0);
  const versionSuffix = version > 0 ? `_v${version}` : "";
  const extraSuffix = suffix ? `_${suffix}` : "";
  return normalizeQuoteFileName(`${baseFolio}${versionSuffix}${extraSuffix}`);
}

function parseClientQuoteRows(rows) {
  if (!Array.isArray(rows)) return [];
  return rows
    .map((row) => {
      const cantidad = Number(row.cantidad || 0);
      const precio = Number(row.precio || 0);
      return {
        cantidad,
        unidadMedida: String(row.unidadMedida || row.um || "").trim(),
        descripcion: String(row.descripcion || "").trim(),
        precio,
        subtotal: cantidad * precio
      };
    })
    .filter((row) => row.descripcion);
}

async function replaceClientQuoteRows(connection, quoteId, rows) {
  await connection.execute("DELETE FROM cotizacion_cliente_partidas WHERE cotizacion_id = ?", [quoteId]);
  for (const row of rows) {
    await connection.execute(
      `INSERT INTO cotizacion_cliente_partidas
        (cotizacion_id, cantidad, unidad_medida, descripcion, precio, subtotal)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [quoteId, row.cantidad, row.unidadMedida, row.descripcion, row.precio, row.subtotal]
    );
  }
}

async function deleteClientQuoteDraft(connection, budgetId, draftId = null) {
  if (draftId) {
    await connection.execute(
      `DELETE FROM cotizacion_cliente_partidas
       WHERE cotizacion_id = (
         SELECT id FROM cotizaciones_cliente
         WHERE id = ? AND presupuesto_id = ? AND tipo = 'borrador'
       )`,
      [draftId, budgetId]
    );
    await connection.execute(
      "DELETE FROM cotizaciones_cliente WHERE id = ? AND presupuesto_id = ? AND tipo = 'borrador'",
      [draftId, budgetId]
    );
    return;
  }

  await connection.execute(
    `DELETE p
     FROM cotizacion_cliente_partidas p
     INNER JOIN cotizaciones_cliente q ON q.id = p.cotizacion_id
     WHERE q.presupuesto_id = ? AND q.tipo = 'borrador'`,
    [budgetId]
  );
  await connection.execute("DELETE FROM cotizaciones_cliente WHERE presupuesto_id = ? AND tipo = 'borrador'", [
    budgetId
  ]);
}

async function getClientQuoteRows(quoteId) {
  const [rows] = await pool.execute(
    `SELECT id, cantidad, unidad_medida, descripcion, precio, subtotal
     FROM cotizacion_cliente_partidas
     WHERE cotizacion_id = ?
     ORDER BY id`,
    [quoteId]
  );
  return rows.map((row) => ({
    id: row.id,
    cantidad: Number(row.cantidad || 0),
    unidadMedida: row.unidad_medida || "",
    descripcion: row.descripcion || "",
    precio: Number(row.precio || 0),
    subtotal: Number(row.subtotal || 0)
  }));
}

async function getClientQuoteById(quoteId) {
  const [rows] = await pool.execute(
    `SELECT
        q.id,
        q.presupuesto_id,
        q.tipo,
        q.folio,
        q.version,
        q.estatus,
        q.terminos,
        q.descuento_monto,
        q.usuario_id,
        q.aprobada_at,
        q.pdf_ruta,
        q.created_at,
        q.updated_at,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS sent_by
     FROM cotizaciones_cliente q
     LEFT JOIN usuarios u ON u.user_id = q.usuario_id
     WHERE q.id = ?
     LIMIT 1`,
    [quoteId]
  );
  const quote = rows[0];
  if (!quote) return null;
  const items = await getClientQuoteRows(quote.id);
  return {
    id: quote.id,
    presupuestoId: quote.presupuesto_id,
    tipo: quote.tipo,
    folio: quote.folio || "",
    version: Number(quote.version || 0),
    estatus: quote.estatus || "Borrador",
    terminos: quote.terminos || CLIENT_QUOTE_DEFAULT_TERMS,
    descuentoMonto: Number(quote.descuento_monto || 0),
    usuarioId: quote.usuario_id || null,
    sentBy: quote.sent_by || "",
    aprobadaAt: quote.aprobada_at,
    pdfRuta: quote.pdf_ruta || "",
    pdfUrl: quote.pdf_ruta ? `/${String(quote.pdf_ruta).replace(/\\/g, "/")}` : "",
    subtotal: getClientQuoteItemsSubtotal(items),
    total: Math.max(getClientQuoteItemsSubtotal(items) - normalizeClientQuoteDiscount(quote.descuento_monto, getClientQuoteItemsSubtotal(items)), 0),
    items,
    createdAt: quote.created_at,
    updatedAt: quote.updated_at
  };
}

async function getClientQuoteDraft(budgetId) {
  const [rows] = await pool.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ? AND tipo = 'borrador'
     ORDER BY id DESC
     LIMIT 1`,
    [budgetId]
  );
  if (!rows.length) return null;
  return getClientQuoteById(rows[0].id);
}

async function getClientQuoteDrafts(budgetId) {
  const [rows] = await pool.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ? AND tipo = 'borrador'
     ORDER BY updated_at DESC, id DESC`,
    [budgetId]
  );
  const drafts = [];
  for (const row of rows) {
    const quote = await getClientQuoteById(row.id);
    if (quote) drafts.push(quote);
  }
  return drafts;
}

async function getClientQuoteVersions(budgetId) {
  const [rows] = await pool.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ? AND tipo = 'version'
     ORDER BY version DESC, id DESC`,
    [budgetId]
  );
  const versions = [];
  for (const row of rows) {
    const quote = await getClientQuoteById(row.id);
    if (quote) versions.push(quote);
  }
  return versions;
}

async function getClientQuoteCostParts(budgetId) {
  const [costs, budget] = await Promise.all([getBudgetCosts(budgetId), getBudgetById(budgetId)]);
  const saleValue = Number(budget?.valorVenta || 1);
  const warrantyFactor = budget?.sinGarantia ? 1 : 1 + BUDGET_WARRANTY_RATE;
  const applySaleValue = (value) => Number(value || 0) * warrantyFactor * saleValue;
  const unitQuotePrice = (subtotal, quantity) => {
    const safeQuantity = Number(quantity || 0) > 0 ? Number(quantity) : 1;
    return applySaleValue(Number(subtotal || 0) / safeQuantity);
  };
  return {
    equipos: (costs.equipos || []).map((row) => {
      const quantity = Number(row.cantidadEquipos || 0) > 0 ? Number(row.cantidadEquipos) : 1;
      return {
        cantidad: quantity,
        unidadMedida: row.unidadMedida || "U.M.",
        descripcion: row.item || "",
        precio: unitQuotePrice(row.subtotal || 0, quantity),
        costoBase: Number(row.subtotal || 0),
        valorVenta: saleValue
      };
    }),
    manoObra: [
      ...(costs.contratistas || []).map((row) => {
        const quantity = Number(row.cantidad || 0) > 0 ? Number(row.cantidad) : 1;
        return {
          cantidad: quantity,
          unidadMedida: "Servicio",
          descripcion: row.descripcion || "",
          precio: unitQuotePrice(row.subtotal || 0, quantity),
          costoBase: Number(row.subtotal || 0),
          valorVenta: saleValue
        };
      }),
      ...(costs.manoObra || []).map((row) => {
        const quantity = Number(row.horasTotal || 0) > 0 ? Number(row.horasTotal) : 1;
        return {
          cantidad: quantity,
          unidadMedida: "Hora",
          descripcion: row.descripcion || "",
          precio: unitQuotePrice(row.subtotal || 0, quantity),
          costoBase: Number(row.subtotal || 0),
          valorVenta: saleValue
        };
      })
    ],
    materiales: (costs.materiales || []).map((row) => {
      const quantity = Number(row.cantidad || 0) > 0 ? Number(row.cantidad) : 1;
      return {
        cantidad: quantity,
        unidadMedida: row.unidad || "U.M.",
        descripcion: row.descripcion || "",
        precio: unitQuotePrice(row.subtotal || 0, quantity),
        costoBase: Number(row.subtotal || 0),
        valorVenta: saleValue
      };
    })
  };
}

async function getLegacyClientPoFileByBudget(budgetId) {
  if (await tableExists("os_archivos")) {
    const [rows] = await pool.execute(
      `SELECT nombre, ruta
       FROM os_archivos
       WHERE orden_id = ?
         AND LOWER(TRIM(tipo)) IN ('oc_cliente', 'po_cliente', 'po cliente')
         AND NULLIF(ruta, '') IS NOT NULL
       ORDER BY id DESC
       LIMIT 1`,
      [budgetId]
    );
    if (rows[0]) return rows[0];
  }

  if (await tableExists("presupuesto_archivos")) {
    const [rows] = await pool.execute(
      `SELECT nombre, ruta
       FROM presupuesto_archivos
       WHERE presupuesto_id = ?
         AND (
           LOWER(TRIM(tipo)) IN ('oc_cliente', 'po_cliente', 'po cliente')
           OR LOWER(TRIM(tipo)) LIKE '%po%'
         )
         AND NULLIF(ruta, '') IS NOT NULL
       ORDER BY id DESC
       LIMIT 1`,
      [budgetId]
    );
    if (rows[0]) return rows[0];
  }

  return null;
}

async function getClientPoByBudget(budgetId) {
  const [rows] = await pool.execute(
    `SELECT po.id, po.presupuesto_id, po.numero_po, po.sin_po, po.nombre, po.ruta,
            po.po_compartida_id, po.monto_asignado, po.usuario_id, po.created_at, po.updated_at,
            shared.numero_po AS shared_numero_po,
            shared.monto_total AS shared_monto_total,
            shared.empresa AS shared_empresa,
            shared.nombre AS shared_nombre,
            shared.ruta AS shared_ruta,
            shared.estado AS shared_estado
     FROM presupuesto_po_cliente po
     LEFT JOIN po_cliente_compartidas shared ON shared.id = po.po_compartida_id
     WHERE po.presupuesto_id = ?
       AND COALESCE(po.estado_documento, 'Activo') = 'Activo'
       AND po.deleted_at IS NULL
     ORDER BY po.id DESC
     LIMIT 1`,
    [budgetId]
  );
  const row = rows[0];
  if (!row) {
    const legacyFile = await getLegacyClientPoFileByBudget(budgetId);
    const [budgetRows] = await pool.execute("SELECT id, po, usuario_id, created_at, updated_at FROM presupuestos WHERE id = ? LIMIT 1", [
      budgetId
    ]);
    const budget = budgetRows[0];
    const legacyPo = String(budget?.po || "").trim();
    if (!legacyPo) return null;
    return {
      id: null,
      budgetId: budget.id,
      numeroPo: legacyPo === "Sin PO" ? "" : legacyPo,
      sinPo: normalizeWorkflowValue(legacyPo) === "sin po",
      nombre: legacyFile?.nombre || legacyPo,
      ruta: legacyFile?.ruta || "",
      url: legacyFile?.ruta ? `/${String(legacyFile.ruta).replace(/\\/g, "/")}` : "",
      usuarioId: budget.usuario_id,
      createdAt: budget.created_at,
      updatedAt: budget.updated_at
    };
  }
  let shared = null;
  if (row.po_compartida_id) {
    const [members] = await pool.execute(
      `SELECT po.presupuesto_id AS budget_id, p.folio, p.titulo_proyecto, po.monto_asignado
       FROM presupuesto_po_cliente po
       INNER JOIN presupuestos p ON p.id = po.presupuesto_id
       WHERE po.po_compartida_id = ?
         AND COALESCE(po.estado_documento, 'Activo') = 'Activo'
         AND po.deleted_at IS NULL
       ORDER BY p.folio, p.id`,
      [row.po_compartida_id]
    );
    shared = {
      id: Number(row.po_compartida_id),
      numeroPo: row.shared_numero_po || row.numero_po || "",
      montoTotal: Number(row.shared_monto_total || 0),
      empresa: row.shared_empresa || "",
      nombre: row.shared_nombre || row.nombre || "",
      ruta: row.shared_ruta || row.ruta || "",
      estado: row.shared_estado || "Activa",
      members: members.map((member) => ({
        budgetId: Number(member.budget_id),
        folio: member.folio || "",
        proyecto: member.titulo_proyecto || "",
        montoAsignado: Number(member.monto_asignado || 0)
      }))
    };
  }
  return {
    id: row.id,
    budgetId: row.presupuesto_id,
    numeroPo: row.shared_numero_po || row.numero_po || "",
    sinPo: Boolean(row.sin_po),
    nombre: row.shared_nombre || row.nombre || "",
    ruta: row.shared_ruta || row.ruta || "",
    url: (row.shared_ruta || row.ruta) ? `/${String(row.shared_ruta || row.ruta).replace(/\\/g, "/")}` : "",
    shared,
    montoAsignado: Number(row.monto_asignado || 0),
    usuarioId: row.usuario_id,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

async function cleanupClientPoWorkflow(connection, budgetId, userId = null) {
  const filesToUnlink = [];

  const [versionRows] = await connection.execute(
    "SELECT id FROM ocp_proveedor WHERE presupuesto_id = ? AND tipo = 'version' AND estatus <> 'Cancelada' LIMIT 1",
    [budgetId]
  );
  if (versionRows.length) {
    const error = new Error("Este presupuesto ya tiene OCP creadas. Cancela las OCP antes de quitar la PO.");
    error.statusCode = 409;
    throw error;
  }

  const [poRows] = await connection.execute(
    "SELECT ruta, po_compartida_id FROM presupuesto_po_cliente WHERE presupuesto_id = ?",
    [budgetId]
  );
  const sharedPoIds = [...new Set(poRows.map((row) => Number(row.po_compartida_id || 0)).filter(Boolean))];
  filesToUnlink.push(
    ...poRows
      .filter((row) => !row.po_compartida_id)
      .map((row) => ({ ruta: row.ruta, root: BUDGET_UPLOAD_DIR }))
  );

  const [receivableFiles] = await connection.execute(
    `SELECT a.ruta
     FROM cuentas_por_cobrar_archivos a
     INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
     LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
     WHERE c.presupuesto_id = ? OR q.presupuesto_id = ?`,
    [budgetId, budgetId]
  );
  filesToUnlink.push(...receivableFiles.map((row) => ({ ruta: row.ruta, root: ACCOUNTS_RECEIVABLE_UPLOAD_DIR })));

  const [supplierFiles] = await connection.execute(
    `SELECT ruta
     FROM ocp_proveedor_archivos
     WHERE presupuesto_id = ? AND (ocp_id IS NULL OR ocp_id = 0)`,
    [budgetId]
  );
  filesToUnlink.push(...supplierFiles.map((row) => ({ ruta: row.ruta, root: BUDGET_UPLOAD_DIR })));

  await connection.execute(
    `DELETE a
     FROM cuentas_por_cobrar_archivos a
     INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
     LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
     WHERE c.presupuesto_id = ? OR q.presupuesto_id = ?`,
    [budgetId, budgetId]
  );
  await connection.execute(
    `DELETE c
     FROM cuentas_por_cobrar c
     LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
     WHERE c.presupuesto_id = ? OR q.presupuesto_id = ?`,
    [budgetId, budgetId]
  );
  await connection.execute(
    "DELETE FROM ocp_proveedor_archivos WHERE presupuesto_id = ? AND (ocp_id IS NULL OR ocp_id = 0)",
    [budgetId]
  );
  await connection.execute(
    `DELETE op
     FROM ocp_proveedor_partidas op
     INNER JOIN ocp_proveedor o ON o.id = op.ocp_id
     WHERE o.presupuesto_id = ? AND o.tipo = 'borrador'`,
    [budgetId]
  );
  await connection.execute("DELETE FROM ocp_proveedor WHERE presupuesto_id = ? AND tipo = 'borrador'", [budgetId]);
  await connection.execute(
    `UPDATE presupuesto_po_cliente
     SET estado_documento = 'Cancelada', deleted_at = NOW(), deleted_by = ?, updated_at = NOW()
     WHERE presupuesto_id = ? AND COALESCE(estado_documento, 'Activo') = 'Activo' AND deleted_at IS NULL`,
    [userId, budgetId]
  );
  for (const sharedPoId of sharedPoIds) {
    const [activeMembers] = await connection.execute(
      `SELECT COUNT(*) AS total
       FROM presupuesto_po_cliente
       WHERE po_compartida_id = ?
         AND COALESCE(estado_documento, 'Activo') = 'Activo'
         AND deleted_at IS NULL`,
      [sharedPoId]
    );
    if (Number(activeMembers[0]?.total || 0) > 0) continue;
    const [sharedRows] = await connection.execute(
      "SELECT ruta FROM po_cliente_compartidas WHERE id = ? LIMIT 1",
      [sharedPoId]
    );
    if (sharedRows[0]?.ruta) filesToUnlink.push({ ruta: sharedRows[0].ruta, root: BUDGET_UPLOAD_DIR });
    await connection.execute(
      "UPDATE po_cliente_compartidas SET estado = 'Cancelada', updated_at = NOW() WHERE id = ?",
      [sharedPoId]
    );
  }
  await connection.execute(
    `UPDATE presupuestos
     SET po = '', estado = 'Abierta', estatus = 'En espera de PO'
     WHERE id = ? AND LOWER(COALESCE(estado, '')) NOT LIKE 'cerrad%'`,
    [budgetId]
  );

  return filesToUnlink;
}

function parseSupplierOrderRows(rows) {
  if (!Array.isArray(rows)) return [];
  return rows.map((row, index) => {
    const cantidad = Number(row.cantidad || 0);
    const precioUnitario = Number(row.precioUnitario || row.precio_unitario || 0);
    const porcentajeRaw = row.porcentajeAplicado ?? row.porcentaje_aplicado ?? 100;
    const porcentajeAplicado = Number(porcentajeRaw);
    const montoBasePresupuesto = Math.round(cantidad * precioUnitario * 100) / 100;
    const montoPagoAplicado = appliedPercentageAmount(montoBasePresupuesto, porcentajeAplicado);
    const total = montoBasePresupuesto;
    const parsed = {
      presupuesto: String(row.presupuesto || row.presupuestoBloque || "").trim(),
      proveedorId: Number(row.proveedorId || 0) || null,
      proveedorNombre: String(row.proveedorNombre || "").trim(),
      descripcion: String(row.descripcion || "").trim(),
      cantidad,
      precioUnitario,
      montoBasePresupuesto,
      porcentajeAplicado,
      montoPagoAplicado,
      total
    };
    if (
      !parsed.presupuesto ||
      !parsed.proveedorNombre ||
      !parsed.descripcion ||
      parsed.cantidad <= 0 ||
      parsed.precioUnitario <= 0 ||
      !Number.isFinite(parsed.porcentajeAplicado) ||
      parsed.porcentajeAplicado <= 0 ||
      parsed.porcentajeAplicado > 100
    ) {
      const error = new Error(
        `Completa presupuesto, proveedor, descripción, cantidad, precio unitario y un porcentaje entre 0.01% y 100% en la partida OCP ${index + 1}.`
      );
      error.statusCode = 400;
      throw error;
    }
    return parsed;
  });
}

function parseRowsOrRespond(res, parser, rows) {
  try {
    return parser(rows);
  } catch (error) {
    res.status(error.statusCode || 400).json({ ok: false, message: error.message || "Partidas inválidas." });
    return null;
  }
}

async function replaceSupplierOrderRows(connection, ocpId, rows) {
  await connection.execute("DELETE FROM ocp_proveedor_partidas WHERE ocp_id = ?", [ocpId]);
  for (const row of rows) {
    await connection.execute(
      `INSERT INTO ocp_proveedor_partidas
        (ocp_id, presupuesto_bloque, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario, monto_base_presupuesto, porcentaje_aplicado, monto_pago_aplicado, total)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        ocpId,
        row.presupuesto,
        row.proveedorId,
        row.proveedorNombre,
        row.descripcion,
        row.cantidad,
        row.precioUnitario,
        row.montoBasePresupuesto,
        row.porcentajeAplicado,
        row.montoPagoAplicado,
        row.total
      ]
    );
  }
}

async function getSupplierOrderRows(ocpId) {
  const [rows] = await pool.execute(
    `SELECT id, presupuesto_bloque, proveedor_id, proveedor_nombre, descripcion, cantidad, precio_unitario,
            monto_base_presupuesto, porcentaje_aplicado, monto_pago_aplicado, total
     FROM ocp_proveedor_partidas
     WHERE ocp_id = ?
     ORDER BY id`,
    [ocpId]
  );
  return rows.map((row) => ({
    id: row.id,
    presupuesto: normalizeBudgetBlock(row.presupuesto_bloque),
    proveedorId: row.proveedor_id || null,
    proveedorNombre: row.proveedor_nombre || "",
    descripcion: row.descripcion || "",
    cantidad: Number(row.cantidad || 0),
    precioUnitario: Number(row.precio_unitario || 0),
    montoBasePresupuesto: Number(row.monto_base_presupuesto || (Number(row.cantidad || 0) * Number(row.precio_unitario || 0)) || 0),
    porcentajeAplicado: Number(row.porcentaje_aplicado ?? 100),
    montoPagoAplicado: Number(row.monto_pago_aplicado || 0) || appliedPercentageAmount(Number(row.monto_base_presupuesto || (Number(row.cantidad || 0) * Number(row.precio_unitario || 0)) || 0), Number(row.porcentaje_aplicado ?? 100)),
    total: Number(row.total || row.monto_base_presupuesto || 0)
  }));
}

async function getSupplierOrderById(ocpId) {
  const [rows] = await pool.execute(
    `SELECT id, presupuesto_id, tipo, folio, version, estatus, retencion_activa, retencion_monto, pdf_ruta,
            usuario_id, created_at, updated_at
     FROM ocp_proveedor
     WHERE id = ?
     LIMIT 1`,
    [ocpId]
  );
  const order = rows[0];
  if (!order) return null;
  const items = await getSupplierOrderRows(order.id);
  return {
    id: order.id,
    budgetId: order.presupuesto_id,
    tipo: order.tipo || "borrador",
    folio: order.folio || "",
    version: Number(order.version || 0),
    estatus: order.estatus || "Borrador",
    retencionActiva: Boolean(order.retencion_activa),
    retencionMonto: Number(order.retencion_monto || 0),
    pdfRuta: order.pdf_ruta || "",
    pdfUrl: order.pdf_ruta ? `/${String(order.pdf_ruta).replace(/\\/g, "/")}` : "",
    usuarioId: order.usuario_id || null,
    total: items.reduce((sum, row) => sum + Number(row.total || 0), 0),
    pagoSubtotal: items.reduce((sum, row) => sum + Number(row.montoPagoAplicado || 0), 0),
    items,
    createdAt: order.created_at,
    updatedAt: order.updated_at
  };
}

async function getSupplierOrderPreviewData(ocpId) {
  const order = await getSupplierOrderById(ocpId);
  if (!order) return null;

  const [budgetRows] = await pool.execute(
    `SELECT id, empresa, sucursal, cliente_usuario, area, titulo_proyecto, folio, po, created_at
     FROM presupuestos
     WHERE id = ?
     LIMIT 1`,
    [order.budgetId]
  );
  const budget = budgetRows[0] || {};
  const providerId = order.items.find((item) => item.proveedorId)?.proveedorId || null;
  let provider = null;

  if (providerId) {
    const [providerRows] = await pool.execute(
      `SELECT id, empresa, rfc, direccion, telefono, correo, condiciones_pago, banco, cuenta, clabe, spei
       FROM proveedores
       WHERE id = ?
       LIMIT 1`,
      [providerId]
    );
    provider = providerRows[0] || null;
  }
  if (!provider) {
    const providerName = String(order.items.find((item) => item.proveedorNombre)?.proveedorNombre || "").trim();
    if (providerName) {
      const [providerRows] = await pool.execute(
        `SELECT id, empresa, rfc, direccion, telefono, correo, condiciones_pago, banco, cuenta, clabe, spei
         FROM proveedores
         WHERE TRIM(UPPER(empresa)) = TRIM(UPPER(?))
         LIMIT 1`,
        [providerName]
      );
      provider = providerRows[0] || null;
    }
  }
  const subtotal = Number(order.total || 0);
  const iva = subtotal * 0.16;
  const totalOrden = Math.max(0, subtotal + iva);
  const pagoSubtotal = Number(order.pagoSubtotal || 0);
  const pagoIva = pagoSubtotal * 0.16;
  const retention = order.retencionActiva ? Number(order.retencionMonto || 0) : 0;
  const totalPagar = Math.max(0, pagoSubtotal + pagoIva - retention);

  return {
    ...order,
    subtotal,
    iva,
    totalOrden,
    pagoSubtotal,
    pagoIva,
    retention,
    totalPagar,
    budget: {
      id: budget.id,
      empresa: budget.empresa || "",
      sucursal: budget.sucursal || "",
      clienteUsuario: budget.cliente_usuario || "",
      area: budget.area || "",
      tituloProyecto: budget.titulo_proyecto || "",
      folio: budget.folio || "",
      po: budget.po || "",
      createdAt: budget.created_at
    },
    provider: provider
      ? {
          id: provider.id,
          empresa: provider.empresa || "",
          rfc: provider.rfc || "",
          direccion: provider.direccion || "",
          telefono: provider.telefono || "",
          correo: provider.correo || "",
          condicionesPago: provider.condiciones_pago || "",
          banco: provider.banco || "",
          cuenta: provider.cuenta || "",
          clabe: provider.clabe || "",
          spei: provider.spei || ""
        }
      : null
  };
}

function supplierOrderPdfRelativePath(order) {
  return path
    .join(
      "uploads",
      "ocp_proveedor",
      `${normalizeQuoteFileName(order.folio || `ocp_${order.id}`)}.pdf`
    )
    .replace(/\\/g, "/");
}

function fixedExpenseOrderPdfRelativePath(order) {
  return path
    .join("uploads", "ocgf", `${normalizeQuoteFileName(order.folio || `ocgf_${order.id}`)}.pdf`)
    .replace(/\\/g, "/");
}

async function getFixedExpenseOrderPdfData(orderId) {
  const order = await getOcgfOrderById(orderId);
  if (!order || order.tipo !== "version") return null;
  const expense = await getOcgfById(order.ocgfId);
  if (!expense) return null;
  let provider = null;
  if (expense.proveedorId) {
    const [providerRows] = await pool.execute(
      `SELECT id, empresa, rfc, telefono, correo, condiciones_pago, banco, cuenta, clabe, spei
       FROM proveedores
       WHERE id = ?
       LIMIT 1`,
      [expense.proveedorId]
    );
    provider = providerRows[0] || null;
  }
  if (!provider) {
    const providerName = String(expense.proveedorNombre || order.items.find((item) => item.proveedorNombre)?.proveedorNombre || "").trim();
    if (providerName) {
      const [providerRows] = await pool.execute(
        `SELECT id, empresa, rfc, telefono, correo, condiciones_pago, banco, cuenta, clabe, spei
         FROM proveedores
         WHERE TRIM(UPPER(empresa)) = TRIM(UPPER(?))
         LIMIT 1`,
        [providerName]
      );
      provider = providerRows[0] || null;
    }
  }
  const subtotal = order.items.reduce((sum, item) => sum + Number(item.total || 0), 0);
  const iva = order.sinIva ? 0 : subtotal * 0.16;
  const retention = order.retencionActiva ? Number(order.retencionMonto || 0) : 0;
  const total = Math.max(0, subtotal + iva - retention);
  return {
    ...order,
    expense,
    provider: provider
      ? {
          empresa: provider.empresa || "",
          rfc: provider.rfc || "",
          telefono: provider.telefono || "",
          correo: provider.correo || "",
          condicionesPago: provider.condiciones_pago || "Contado",
          banco: provider.banco || "",
          cuenta: provider.cuenta || "",
          clabe: provider.clabe || "",
          spei: provider.spei || ""
        }
      : null,
    subtotal,
    iva,
    retention,
    total
  };
}

