const ACCOUNTS_RECEIVABLE_FILE_TYPES = ["Factura", "Comprobante de pago", "Complemento de pago"];
const ACCOUNTS_RECEIVABLE_EXTENDED_FILE_TYPES = [
  "Factura",
  "GR",
  "Track ID",
  "Comprobante de pago",
  "Complemento de pago"
];

function requiresExtendedReceivableFiles(empresa = "") {
  const normalized = normalizeFolioCompanyName(empresa);
  return normalized.includes("bmw") || normalized.includes("honda");
}

function getAccountsReceivableFileTypes(empresa = "") {
  return requiresExtendedReceivableFiles(empresa)
    ? ACCOUNTS_RECEIVABLE_EXTENDED_FILE_TYPES
    : ACCOUNTS_RECEIVABLE_FILE_TYPES;
}

function inferPaymentDays(conditions) {
  const normalized = String(conditions || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  return normalized.includes("contado") ? 0 : 30;
}

function addDays(dateValue, days) {
  const date = dateValue ? new Date(dateValue) : new Date();
  date.setDate(date.getDate() + Number(days || 0));
  return date.toISOString().slice(0, 10);
}

function calculateRemainingPaymentDays(startDate, totalDays, paid = false, explicitDueDate = null) {
  if (paid) return 0;
  const days = Number(totalDays || 0);
  const dueDateValue = explicitDueDate || (startDate ? addDays(startDate, days) : null);
  if (!dueDateValue) return days;
  const dueDate = new Date(dueDateValue);
  if (Number.isNaN(dueDate.getTime())) return days;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  dueDate.setHours(0, 0, 0, 0);
  return Math.max(0, Math.ceil((dueDate.getTime() - today.getTime()) / 86400000));
}

function isCashPayment(conditions) {
  const normalized = String(conditions || "contado")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  return normalized.includes("contado");
}

function resolveAccountsReceivableStatus(files, conditions = "contado", empresa = "", currentPending = "") {
  const types = new Set((files || []).map((file) => file.tipo));
  const hasExtendedFlow = requiresExtendedReceivableFiles(empresa);
  if (!types.has("Factura")) {
    return { estado: "En proceso", pendiente: "En proceso" };
  }
  const hasPaymentProof = types.has("Comprobante de pago");
  if (hasExtendedFlow && !hasPaymentProof && !types.has("GR")) {
    return { estado: "Factura cargada", pendiente: "Cargar GR" };
  }
  if (hasExtendedFlow && !hasPaymentProof && !types.has("Track ID")) {
    return { estado: "GR cargada", pendiente: "Cargar Track ID" };
  }
  if (!types.has("Comprobante de pago")) {
    return {
      estado: hasExtendedFlow ? "Track ID cargado" : "Factura cargada",
      pendiente: "Cargar comprobante de pago"
    };
  }
  if (isCashPayment(conditions)) {
    return { estado: "Pago completo", pendiente: "Sin pendientes de documentación" };
  }
  if (!types.has("Complemento de pago")) {
    return { estado: "Comprobante de pago cargado", pendiente: "Cargar complemento de pago" };
  }
  return { estado: "Pago completo", pendiente: "Sin pendientes de documentación" };
}

