async function getAccountsReceivableBillingSummary(cuentaId, total = 0, connection = pool) {
  const movements = await getAccountsReceivableBillingMovements(cuentaId, connection);
  const projectTotal = Math.max(0, Math.round(Number(total || 0) * 100) / 100);
  const chronological = [...movements].sort((a, b) => Number(a.id || 0) - Number(b.id || 0));
  let runningBalance = projectTotal;
  const enrichedById = new Map();

  for (const movement of chronological) {
    const isCancelled = normalizeWorkflowValue(movement.estado) === "cancelada";
    const amount = Math.max(0, Math.round(Number(movement.monto || 0) * 100) / 100);
    const saldoAnterior = runningBalance;
    const saldoPosterior = isCancelled
      ? runningBalance
      : Math.max(0, Math.round((runningBalance - amount) * 100) / 100);
    if (!isCancelled) runningBalance = saldoPosterior;
    enrichedById.set(Number(movement.id), {
      ...movement,
      saldoAnterior,
      saldoPosterior
    });
  }

  const enrichedMovements = movements.map((movement) => enrichedById.get(Number(movement.id)) || movement);
  const active = enrichedMovements.filter((movement) => normalizeWorkflowValue(movement.estado) !== "cancelada");
  const billed = Math.round(active.reduce((sum, movement) => sum + Number(movement.monto || 0), 0) * 100) / 100;
  const requested = Math.round(
    active
      .filter((movement) => normalizeWorkflowValue(movement.estado) === "solicitada")
      .reduce((sum, movement) => sum + Number(movement.monto || 0), 0) * 100
  ) / 100;
  const invoiced = Math.round(
    active
      .filter((movement) => ["facturada", "pagada"].includes(normalizeWorkflowValue(movement.estado)))
      .reduce((sum, movement) => sum + Number(movement.monto || 0), 0) * 100
  ) / 100;

  return {
    total: projectTotal,
    billed,
    requested,
    invoiced,
    remaining: Math.max(0, Math.round((projectTotal - billed) * 100) / 100),
    movements: enrichedMovements
  };
}

async function createAccountsReceivableBillingMovement({ cuentaId, monto, observaciones = "", userId = null }) {
  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();
    const [accounts] = await connection.execute(
      "SELECT monto FROM cuentas_por_cobrar WHERE id = ? FOR UPDATE",
      [cuentaId]
    );
    if (!accounts.length) {
      const error = new Error("Cuenta por cobrar no encontrada.");
      error.statusCode = 404;
      throw error;
    }
    const total = Math.max(0, Number(accounts[0].monto || 0));
    const summary = await getAccountsReceivableBillingSummary(cuentaId, total, connection);
    const hasAmount = monto !== null && monto !== undefined && String(monto).trim() !== "";
    const rawAmount = hasAmount ? Number(monto) : summary.remaining;
    const amount = Math.round(rawAmount * 100) / 100;
    if (!Number.isFinite(amount) || amount <= 0) {
      const error = new Error("Ingresa un monto válido para la parcialidad.");
      error.statusCode = 400;
      throw error;
    }
    if (amount - summary.remaining > 0.004) {
      const error = new Error(`El monto supera el saldo por facturar (${summary.remaining.toFixed(2)}).`);
      error.statusCode = 409;
      throw error;
    }
    const [result] = await connection.execute(
      `INSERT INTO cuentas_por_cobrar_facturacion (cuenta_id, monto, estado, observaciones, usuario_id)
       VALUES (?, ?, 'Solicitada', ?, ?)`,
      [cuentaId, amount, String(observaciones || "").trim().slice(0, 500), userId || null]
    );
    await connection.commit();
    await refreshAccountsReceivableStatus(cuentaId);
    return Number(result.insertId);
  } catch (error) {
    await connection.rollback();
    throw error;
  } finally {
    connection.release();
  }
}

async function getAccountsReceivableSupportDocuments(quoteId, account = {}, quote = {}) {
  const documents = [];
  const po = account.presupuestoId ? await getClientPoByBudget(account.presupuestoId) : null;

  if (po) {
    documents.push(
      mapSupportDocument(
        {
          key: `po-${account.presupuestoId}`,
          tipo: "PO Cliente",
          nombre: po.sinPo ? "Sin PO" : po.nombre || po.numeroPo || account.po || "PO Cliente",
          ruta: po.ruta || "",
          url: po.url || "",
          createdAt: po.createdAt || account.createdAt
        },
        "PO Cliente"
      )
    );
  }

  documents.push(
    mapSupportDocument(
      {
        key: `client-quote-${quoteId}`,
        tipo: "Cotización cliente",
        nombre: quote.folio || account.quoteFolio || "Cotización cliente",
        url: `/api/client-quotes/${Number(quoteId)}/preview`,
        createdAt: quote.createdAt || account.fecha || account.createdAt
      },
      "Cotización cliente"
    )
  );

  return documents;
}

async function getAccountsReceivableBaseRows(quoteId = null) {
  const values = [];
  let quoteFilter = "";
  if (quoteId) {
    quoteFilter = "AND q.id = ?";
    values.push(quoteId);
  }

  const [rows] = await pool.execute(
    `SELECT
        q.id AS quote_id,
        q.folio AS quote_folio,
        q.version AS quote_version,
        q.created_at AS quote_created_at,
        p.id AS presupuesto_id,
        p.empresa,
        p.sucursal,
        p.sucursal_id AS presupuesto_sucursal_id,
        p.cliente_usuario,
        p.usuario_id AS presupuesto_usuario_id,
        p.created_at AS presupuesto_created_at,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS owner_nombre,
        p.folio AS presupuesto_folio,
        p.po AS presupuesto_po,
        p.titulo_proyecto,
        COALESCE(NULLIF(po.numero_po, ''), NULLIF(p.po, ''), IF(po.sin_po = 1, 'Sin PO', '')) AS po_cliente,
        po.created_at AS po_created_at,
        po.sin_po AS po_sin_po,
        cx.id AS cuenta_id,
        cx.estado,
        cx.pendiente,
        cx.dias_pago,
        cx.fecha_pago,
        cx.monto,
        cx.created_at AS cuenta_created_at,
        cx.updated_at AS cuenta_updated_at,
        lcci.id AS cobro_lote_item_id,
        lcci.monto_original AS cobro_monto_original,
        lcci.porcentaje_descuento AS cobro_porcentaje_descuento,
        lcci.descuento_monto AS cobro_descuento_monto,
        lcci.ajuste_redondeo AS cobro_ajuste_redondeo,
        lcci.monto_cobrar AS cobro_monto_neto,
        lcc.id AS cobro_lote_id,
        lcc.folio AS cobro_lote_folio,
        lcc.estado AS cobro_lote_estado,
        lcc.monto_cobrar AS cobro_lote_total,
        lcc.intermediario AS cobro_intermediario,
        lcc.referencia_externa AS cobro_referencia_externa,
        lcc.fecha_cobro AS cobro_lote_fecha,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
            AND a.tipo = 'Factura'
        ) AS factura_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT a.nombre ORDER BY a.created_at DESC, a.id DESC SEPARATOR ', ')
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
            AND a.tipo = 'Factura'
        ) AS factura_archivos,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
            AND a.tipo = 'Track ID'
        ) AS track_id_fecha,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
            AND a.tipo = 'GR'
        ) AS gr_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', a.tipo, a.nombre) ORDER BY a.nombre SEPARATOR ' ')
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
        ) AS archivos_nombres,
        (
          SELECT MAX(a.created_at)
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id AND a.tipo = 'Comprobante de pago'
        ) AS comprobante_pago_fecha,
        (
          SELECT a.ruta
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id
            AND a.tipo = 'Comprobante de pago'
            AND LOWER(a.nombre) LIKE '%.xml'
          ORDER BY a.created_at DESC, a.id DESC
          LIMIT 1
        ) AS comprobante_pago_xml_ruta,
        (
          SELECT GROUP_CONCAT(DISTINCT a.nombre ORDER BY a.nombre SEPARATOR ', ')
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id AND a.tipo = 'Complemento de pago'
        ) AS complemento_pago_archivos,
        (
          SELECT MAX(a.created_at)
          FROM cuentas_por_cobrar_archivos a
          WHERE a.cuenta_id = cx.id AND a.tipo = 'Complemento de pago'
        ) AS complemento_pago_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', pof.numero_po, pof.nombre) ORDER BY pof.nombre SEPARATOR ' ')
          FROM presupuesto_po_cliente pof
          WHERE pof.presupuesto_id = p.id
        ) AS po_archivos_nombres,
        COALESCE(
          (SELECT c2.condiciones_pago FROM clientes c2 WHERE c2.id = p.cliente_id LIMIT 1),
          (SELECT c2.condiciones_pago FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
             AND c2.nombre COLLATE utf8mb4_unicode_ci = p.cliente_usuario COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id DESC LIMIT 1),
          (SELECT c2.condiciones_pago FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id DESC LIMIT 1),
          'contado'
        ) AS condiciones_pago,
        COALESCE(
          (SELECT c2.dias_credito FROM clientes c2 WHERE c2.id = p.cliente_id LIMIT 1),
          (SELECT c2.dias_credito FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
             AND c2.nombre COLLATE utf8mb4_unicode_ci = p.cliente_usuario COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id DESC LIMIT 1),
          (SELECT c2.dias_credito FROM clientes c2
           WHERE c2.empresa COLLATE utf8mb4_unicode_ci = p.empresa COLLATE utf8mb4_unicode_ci
           ORDER BY c2.id DESC LIMIT 1),
          NULL
        ) AS cliente_dias_credito
     FROM cotizaciones_cliente q
     INNER JOIN presupuestos p ON p.id = q.presupuesto_id
     LEFT JOIN usuarios u ON u.user_id = p.usuario_id
     LEFT JOIN presupuesto_po_cliente po ON po.id = (
       SELECT po_actual.id
       FROM presupuesto_po_cliente po_actual
       WHERE po_actual.presupuesto_id = p.id
         AND COALESCE(po_actual.estado_documento, 'Activo') = 'Activo'
         AND po_actual.deleted_at IS NULL
       ORDER BY po_actual.id DESC
       LIMIT 1
     )
     LEFT JOIN cuentas_por_cobrar cx ON cx.cotizacion_cliente_id = q.id
     LEFT JOIN lotes_cobro_clientes_items lcci ON lcci.cotizacion_cliente_id = q.id
     LEFT JOIN lotes_cobro_clientes lcc ON lcc.id = lcci.lote_id
     WHERE q.tipo = 'version'
       AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
       AND (
         NULLIF(p.po, '') IS NOT NULL
         OR po.sin_po = 1
         OR NULLIF(po.numero_po, '') IS NOT NULL
         OR NULLIF(po.ruta, '') IS NOT NULL
       )
       AND q.id = (
         SELECT q2.id
         FROM cotizaciones_cliente q2
         WHERE q2.presupuesto_id = q.presupuesto_id
           AND q2.tipo = 'version'
           AND LOWER(TRIM(q2.estatus)) LIKE 'aprob%'
         ORDER BY q2.version DESC, q2.id DESC
         LIMIT 1
       )
       ${quoteFilter}
     ORDER BY q.created_at DESC, q.id DESC`,
    values
  );
  return rows;
}

async function getClientQuoteTotalWithTax(quoteId, executor = pool) {
  const [rows] = await executor.execute(
    `SELECT
        COALESCE(SUM(p.subtotal), 0) AS subtotal,
        COALESCE(MAX(q.descuento_monto), 0) AS descuento_monto
     FROM cotizaciones_cliente q
     LEFT JOIN cotizacion_cliente_partidas p ON p.cotizacion_id = q.id
     WHERE q.id = ?`,
    [quoteId]
  );
  const grossSubtotal = Number(rows[0]?.subtotal || 0);
  const discount = normalizeClientQuoteDiscount(rows[0]?.descuento_monto, grossSubtotal);
  const subtotal = Math.max(grossSubtotal - discount, 0);
  return {
    subtotal,
    descuento: discount,
    iva: subtotal * 0.16,
    total: subtotal * 1.16
  };
}

async function getLatestClientQuotePvp2(budgetId, executor = pool) {
  const numericBudgetId = Number(budgetId || 0);
  if (!numericBudgetId || !(await tableExists("cotizaciones_cliente")) || !(await tableExists("cotizacion_cliente_partidas"))) {
    return null;
  }
  const [rows] = await executor.execute(
    `SELECT
       q.id,
       q.folio,
       q.version,
       q.estatus,
       q.created_at,
       GREATEST(COALESCE(SUM(i.subtotal), 0) - COALESCE(MAX(q.descuento_monto), 0), 0) AS monto
     FROM cotizaciones_cliente q
     LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
     WHERE q.presupuesto_id = ?
       AND q.tipo = 'version'
     GROUP BY q.id, q.folio, q.version, q.estatus, q.created_at
     ORDER BY q.version DESC, q.id DESC
     LIMIT 1`,
    [numericBudgetId]
  );
  const row = rows[0];
  if (!row) return null;
  return {
    id: Number(row.id),
    folio: row.folio || "",
    version: Number(row.version || 0),
    estatus: row.estatus || "",
    createdAt: row.created_at,
    monto: roundMoneyServer(row.monto || 0)
  };
}

async function getApprovedClientQuoteDashboardValue(user = null, modulePermission = "modulo:presupuesto") {
  const ownerConditions = [];
  const ownerValues = [];
  appendBudgetOwnerCondition(ownerConditions, ownerValues, user, "p", modulePermission);
  const ownerWhere = ownerConditions.length ? `AND ${ownerConditions.join(" AND ")}` : "";
  const [rows] = await pool.execute(
    `SELECT
        COUNT(*) AS total_quotes,
        COALESCE(SUM(latest.subtotal), 0) AS total_value
     FROM (
       SELECT
          q.id,
          q.presupuesto_id,
          GREATEST(COALESCE(SUM(i.subtotal), 0) - COALESCE(MAX(q.descuento_monto), 0), 0) AS subtotal
       FROM cotizaciones_cliente q
       INNER JOIN presupuestos p ON p.id = q.presupuesto_id
       LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
       WHERE q.tipo = 'version'
         ${ownerWhere}
         AND q.id = (
           SELECT q2.id
           FROM cotizaciones_cliente q2
           WHERE q2.presupuesto_id = q.presupuesto_id
             AND q2.tipo = 'version'
           ORDER BY q2.version DESC, q2.id DESC
           LIMIT 1
         )
       GROUP BY q.id, q.presupuesto_id
     ) latest`,
    ownerValues
  );

  return {
    count: Number(rows[0]?.total_quotes || 0),
    total: Number(rows[0]?.total_value || 0)
  };
}

async function getLatestApprovedClientQuoteRows(user = null, modulePermission = "modulo:presupuesto") {
  const ownerConditions = [];
  const ownerValues = [];
  appendBudgetOwnerCondition(ownerConditions, ownerValues, user, "p", modulePermission);
  const ownerWhere = ownerConditions.length ? `AND ${ownerConditions.join(" AND ")}` : "";
  const [rows] = await pool.execute(
    `SELECT
        q.id AS quote_id,
        q.presupuesto_id,
        q.folio AS quote_folio,
        q.version,
        COALESCE(q.aprobada_at, q.created_at) AS quote_date,
        p.empresa,
        p.folio AS presupuesto_folio,
        p.usuario_id AS owner_id,
        COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS owner_nombre,
        p.titulo_proyecto,
        GREATEST(COALESCE(SUM(i.subtotal), 0) - COALESCE(MAX(q.descuento_monto), 0), 0) AS subtotal,
        (COALESCE(equipos_d.total, 0) + COALESCE(contratistas_d.total, 0) + COALESCE(mano_obra_d.total, 0) + COALESCE(materiales_d.total, 0)) AS total_costo,
        COALESCE(comisiones.total_comision, 0) AS total_comision
     FROM cotizaciones_cliente q
     INNER JOIN presupuestos p ON p.id = q.presupuesto_id
     LEFT JOIN usuarios u ON u.user_id = p.usuario_id
     LEFT JOIN cotizacion_cliente_partidas i ON i.cotizacion_id = q.id
     LEFT JOIN ${BUDGET_COST_AGGREGATES.equipos()} equipos_d ON equipos_d.presupuesto_id = p.id
     LEFT JOIN ${BUDGET_COST_AGGREGATES.contratistas()} contratistas_d ON contratistas_d.presupuesto_id = p.id
     LEFT JOIN ${BUDGET_COST_AGGREGATES.manoObra()} mano_obra_d ON mano_obra_d.presupuesto_id = p.id
     LEFT JOIN ${BUDGET_COST_AGGREGATES.materiales()} materiales_d ON materiales_d.presupuesto_id = p.id
     LEFT JOIN (
       SELECT presupuesto_id, COALESCE(SUM(monto_comision), 0) AS total_comision
       FROM comisiones
       WHERE LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE 'cancel%'
         AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE 'rechaz%'
         AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE 'elimin%'
         AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE 'no aprobad%'
       GROUP BY presupuesto_id
     ) comisiones ON comisiones.presupuesto_id = p.id
     WHERE q.tipo = 'version'
       ${ownerWhere}
       AND q.id = (
         SELECT q2.id
         FROM cotizaciones_cliente q2
         WHERE q2.presupuesto_id = q.presupuesto_id
           AND q2.tipo = 'version'
         ORDER BY q2.version DESC, q2.id DESC
         LIMIT 1
       )
     GROUP BY
       q.id, q.presupuesto_id, q.folio, q.version, q.aprobada_at, q.created_at,
       p.empresa, p.folio, p.usuario_id, u.nombre, u.apellido, u.usuario, p.titulo_proyecto, equipos_d.total, contratistas_d.total, mano_obra_d.total, materiales_d.total, comisiones.total_comision
     ORDER BY COALESCE(q.aprobada_at, q.created_at) DESC, q.id DESC`,
    ownerValues
  );

  return rows.map((row) => ({
    quoteId: row.quote_id,
    presupuestoId: row.presupuesto_id,
    quoteFolio: row.quote_folio || "",
    version: Number(row.version || 0),
    date: row.quote_date,
    empresa: row.empresa || "Sin empresa",
    folio: row.presupuesto_folio || "",
    ownerId: row.owner_id || null,
    owner: row.owner_nombre || "Sin owner",
    proyecto: row.titulo_proyecto || "Sin proyecto",
    subtotal: Number(row.subtotal || 0),
    costo: Number(row.total_costo || 0),
    comision: Number(row.total_comision || 0)
  }));
}

