  const values = [];
  appendBudgetOwnerCondition(conditions, values, user, "p", modulePermission);
  const [rows] = await pool.execute(
    `SELECT COUNT(*) AS total
     FROM presupuestos p
     WHERE ${conditions.join(" AND ")}`,
    values
  );
