async function getBudgetPendingInitialApprovalCount(user = null, modulePermission = "modulo:presupuesto") {
  const legacyFilter = (await tableExists("ordenes_servicio"))
    ? `AND NOT EXISTS (
         SELECT 1
         FROM ordenes_servicio os
         WHERE os.id = p.id
         LIMIT 1
       )`
    : "";
  const ownerConditions = [];
  const ownerValues = [];
  appendBudgetOwnerCondition(ownerConditions, ownerValues, user, "p", modulePermission);
  const ownerWhere = ownerConditions.length ? `AND ${ownerConditions.join(" AND ")}` : "";
  const [rows] = await pool.execute(
    `SELECT COUNT(*) AS total
     FROM presupuestos p
     WHERE LOWER(TRIM(COALESCE(p.estatus, ''))) IN ('en espera de aprobación', 'en espera de aprobacion')
       AND LOWER(TRIM(COALESCE(p.estado, 'abierta'))) NOT LIKE 'cerrad%'
       AND NOT EXISTS (
         SELECT 1
         FROM cotizaciones_cliente q
         WHERE q.presupuesto_id = p.id
           AND q.tipo = 'version'
           AND LOWER(TRIM(q.estatus)) LIKE 'aprob%'
         LIMIT 1
       )
       AND NULLIF(p.po, '') IS NULL
       AND NOT EXISTS (
         SELECT 1
         FROM presupuesto_po_cliente po
         WHERE po.presupuesto_id = p.id
           AND (po.sin_po = 1 OR NULLIF(po.numero_po, '') IS NOT NULL OR NULLIF(po.ruta, '') IS NOT NULL)
         LIMIT 1
       )
       AND NOT EXISTS (
         SELECT 1
         FROM ocp_proveedor o
         WHERE o.presupuesto_id = p.id
           AND o.tipo = 'version'
           AND o.estatus <> 'Cancelada'
         LIMIT 1
       )
       ${ownerWhere}
       ${legacyFilter}`,
    ownerValues
  );
  return Number(rows[0]?.total || 0);
}

