function isCurrentMonthServer(value) {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return false;
  const now = new Date();
  return date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth();
}

function getValidServerDate(value) {
  const date = value ? new Date(value) : null;
  return date && !Number.isNaN(date.getTime()) ? date : null;
}

function isCurrentQuarterServer(value) {
  const date = getValidServerDate(value);
  if (!date) return false;
  const now = new Date();
  return (
    date.getFullYear() === now.getFullYear() &&
    Math.floor(date.getMonth() / 3) === Math.floor(now.getMonth() / 3)
  );
}

function isCurrentYearServer(value) {
  const date = getValidServerDate(value);
  return Boolean(date && date.getFullYear() === new Date().getFullYear());
}

function getServerMonthKey(value) {
  const date = getValidServerDate(value);
  if (!date) return "Sin fecha";
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function normalizeServerMonthValue(value) {
  const raw = String(value || "").trim();
  if (/^\d{4}-\d{2}$/.test(raw)) return raw;
  return getServerMonthKey(new Date());
}

function isServerMonth(value, monthValue) {
  const month = normalizeServerMonthValue(monthValue);
  return getServerMonthKey(value) === month;
}

function getReceivableCollectionDate(item = {}) {
  // Para reportes de cobro se usa primero la fecha real del comprobante/XML.
  // No usamos la fecha de creación del presupuesto como sustituto de un cobro.
  return item.fechaCobro || null;
}

function expandReceivablePaymentEvents(items = []) {
  const rows = [];
  for (const item of items || []) {
    const payments = Array.isArray(item.pagos) ? item.pagos : [];
    if (payments.length) {
      for (const payment of payments) {
        rows.push({
          ...item,
          pagoId: payment.id || null,
          monto: Number(payment.monto || 0),
          fechaCobro: payment.fechaPago || payment.createdAt || item.fechaCobro || null,
          referenciaPago: payment.referencia || "",
          saldoCobrar: Number(payment.saldoPosterior ?? item.saldoCobrar ?? 0)
        });
      }
    } else if (isReceivableCollected(item)) {
      // Históricos anteriores a la tabla de pagos: se conserva el cobro total.
      rows.push(item);
    }
  }
  return rows;
}

async function getProjectAdditionalExpenseTotals(budgetIds = []) {
  const ids = [...new Set((budgetIds || []).map((value) => Number(value || 0)).filter(Boolean))];
  const totals = new Map();
  if (!ids.length) return totals;
  const placeholders = ids.map(() => "?").join(",");
  const [rows] = await pool.execute(
    `SELECT presupuesto_id, COALESCE(SUM(monto), 0) AS total
     FROM presupuesto_adicionales
     WHERE presupuesto_id IN (${placeholders})
     GROUP BY presupuesto_id`,
    ids
  );
  rows.forEach((row) => totals.set(Number(row.presupuesto_id), Number(row.total || 0)));
  return totals;
}

function buildProjectActualExpenseMap(budgetIds = [], payableOcpRows = [], commissionRawRows = [], additionalTotals = new Map()) {
  const allowed = new Set((budgetIds || []).map((value) => Number(value || 0)).filter(Boolean));
  const totals = new Map();
  const ensure = (budgetId) => {
    const id = Number(budgetId || 0);
    if (!id || (allowed.size && !allowed.has(id))) return null;
    if (!totals.has(id)) totals.set(id, { totalOcp: 0, totalOccom: 0, totalAdditional: Number(additionalTotals.get(id) || 0) });
    return totals.get(id);
  };

  for (const item of payableOcpRows || []) {
    const current = ensure(item.presupuestoId);
    if (!current) continue;
    // Para utilidad usamos el subtotal de la OCP (sin IVA), consistente con la venta sin IVA.
    current.totalOcp += Number(item.subtotal ?? item.subtotalOcp ?? item.montoTotal ?? item.monto ?? 0);
  }
  for (const row of commissionRawRows || []) {
    const current = ensure(row.presupuesto_id ?? row.presupuestoId);
    if (!current) continue;
    current.totalOccom += Number(row.monto_comision ?? row.montoOriginal ?? row.subtotal ?? row.monto ?? 0);
  }

  // Garantiza entrada aun cuando un proyecto solo tenga gastos adicionales.
  for (const id of allowed) ensure(id);
  return totals;
}

function buildPaidProjectProfitability(receivableCollectedRows = [], quotes = [], monthValue = "", projectExpenseMap = new Map()) {
  const month = normalizeServerMonthValue(monthValue);
  const quotesByBudget = new Map();
  const quotesById = new Map();
  for (const quote of quotes) {
    if (Number(quote.presupuestoId || 0)) quotesByBudget.set(Number(quote.presupuestoId), quote);
    if (Number(quote.quoteId || 0)) quotesById.set(Number(quote.quoteId), quote);
  }

  const rows = receivableCollectedRows
    .filter((item) => {
      const paidAt = getReceivableCollectionDate(item);
      return paidAt && isServerMonth(paidAt, month);
    })
    .map((item) => {
      const quote = quotesById.get(Number(item.quoteId || 0)) || quotesByBudget.get(Number(item.presupuestoId || 0)) || {};
      const venta = Number(item.monto ?? quote.subtotal ?? 0);
      const actualExpenses = projectExpenseMap.get(Number(item.presupuestoId || quote.presupuestoId || 0));
      // La utilidad REAL nunca toma el costo/comisión presupuestados como respaldo.
      // Si todavía no hay movimiento real capturado, ese rubro queda en cero hasta
      // que exista una OCP, OCCOM o gasto adicional asociado al proyecto.
      const totalOcp = Number(actualExpenses?.totalOcp || 0);
      const totalOccom = Number(actualExpenses?.totalOccom || 0);
      const totalAdditional = Number(actualExpenses?.totalAdditional || 0);
      const gastoTotal = totalOcp + totalOccom + totalAdditional;
      const utilidadDalvo = venta - gastoTotal;
      return {
        quoteId: Number(item.quoteId || quote.quoteId || 0),
        presupuestoId: Number(item.presupuestoId || quote.presupuestoId || 0),
        empresa: item.empresa || quote.empresa || "Sin empresa",
        owner: item.owner || quote.owner || "Sin owner",
        folio: item.folio || quote.folio || "",
        proyecto: item.proyecto || quote.proyecto || "Sin proyecto",
        fechaCobro: getReceivableCollectionDate(item),
        venta,
        totalOcp,
        totalOccom,
        totalAdditional,
        // Alias conservados para compatibilidad con clientes anteriores.
        costoBase: totalOcp,
        comision: totalOccom,
        gastoTotal,
        utilidadDalvo,
        margen: venta ? (utilidadDalvo / venta) * 100 : 0
      };
    });

  // Una cuenta por cobrar representa el cobro del proyecto/cotización. Evitamos
  // duplicados accidentales conservando el cobro más reciente de la misma cuenta.
  const deduped = new Map();
  for (const row of rows) {
    const key = row.quoteId ? `q:${row.quoteId}` : `p:${row.presupuestoId}:${row.folio}`;
    const previous = deduped.get(key);
    if (!previous || new Date(row.fechaCobro || 0) > new Date(previous.fechaCobro || 0)) deduped.set(key, row);
  }

  return [...deduped.values()].sort((a, b) => {
    const dateDiff = new Date(b.fechaCobro || 0) - new Date(a.fechaCobro || 0);
    if (dateDiff) return dateDiff;
    return String(a.folio || "").localeCompare(String(b.folio || ""), "es", { numeric: true });
  });
}


async function getAccountsReceivablePaymentEvents(cuentaId, total = 0, connection = pool) {
  if (!cuentaId) return [];
  const [rows] = await connection.execute(
    `SELECT id, cuenta_id, archivo_id, facturacion_id, monto, fecha_pago, referencia, usuario_id, created_at, updated_at
     FROM cuentas_por_cobrar_pagos
     WHERE cuenta_id = ?
     ORDER BY COALESCE(fecha_pago, DATE(created_at)) ASC, id ASC`,
    [cuentaId]
  );
  const projectTotal = Math.max(0, Math.round(Number(total || 0) * 100) / 100);
  let runningPaid = 0;
  return rows.map((row) => {
    const amount = Math.max(0, Math.round(Number(row.monto || 0) * 100) / 100);
    const saldoAnterior = Math.max(0, Math.round((projectTotal - runningPaid) * 100) / 100);
    runningPaid = Math.min(projectTotal, Math.round((runningPaid + amount) * 100) / 100);
    const saldoPosterior = Math.max(0, Math.round((projectTotal - runningPaid) * 100) / 100);
    return {
      id: Number(row.id),
      cuentaId: Number(row.cuenta_id),
      archivoId: row.archivo_id ? Number(row.archivo_id) : null,
      facturacionId: row.facturacion_id ? Number(row.facturacion_id) : null,
      monto: amount,
      fechaPago: row.fecha_pago || row.created_at || null,
      referencia: row.referencia || "",
      usuarioId: row.usuario_id || null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      saldoAnterior,
      saldoPosterior,
      liquidaCuenta: saldoPosterior <= 0.004
    };
  });
}

async function getAccountsReceivablePaymentSummary(cuentaId, total = 0, connection = pool) {
  const payments = await getAccountsReceivablePaymentEvents(cuentaId, total, connection);
  const paid = Math.round(payments.reduce((sum, payment) => sum + Number(payment.monto || 0), 0) * 100) / 100;
  const projectTotal = Math.max(0, Math.round(Number(total || 0) * 100) / 100);
  const cappedPaid = Math.min(projectTotal, paid);
  const latest = payments.length ? payments[payments.length - 1] : null;
  return {
    hasPayments: payments.length > 0,
    paid: cappedPaid,
    remaining: Math.max(0, Math.round((projectTotal - cappedPaid) * 100) / 100),
    latestDate: latest?.fechaPago || latest?.createdAt || null,
    payments
  };
}

function extractXmlAttribute(tag = "", attribute = "") {
  const match = String(tag || "").match(new RegExp(`\\b${attribute}\\s*=\\s*["']([^"']+)["']`, "i"));
  return String(match?.[1] || "").trim();
}

function extractInvoiceDataFromXmlContent(xml = "") {
  const source = String(xml || "");
  const timbre = source.match(/<(?:(?:\w+):)?TimbreFiscalDigital\b[^>]*>/i)?.[0] || "";
  const comprobante = source.match(/<(?:(?:\w+):)?Comprobante\b[^>]*>/i)?.[0] || "";
  const uuid = extractXmlAttribute(timbre, "UUID");
  const subtotal = Number(extractXmlAttribute(comprobante, "SubTotal") || 0);
  const total = Number(extractXmlAttribute(comprobante, "Total") || 0);
  return { uuid, subtotal, total };
}

function extractPaymentDetailsFromXmlContent(xml = "") {
  const source = String(xml || "");
  const paymentTag = source.match(/<(?:(?:\w+):)?Pago\b[^>]*>/i)?.[0] || "";
  const fechaPagoRaw = extractXmlAttribute(paymentTag, "FechaPago");
  const fechaPago = fechaPagoRaw.match(/((?:19|20)\d{2}-\d{2}-\d{2})/)?.[1] || extractPaymentDateFromXmlContent(source);
  const referencia = extractXmlAttribute(paymentTag, "NumOperacion");
  const documents = [];
  const documentRegex = /<(?:(?:\w+):)?DoctoRelacionado\b[^>]*>/gi;
  for (const match of source.matchAll(documentRegex)) {
    const tag = match[0];
    const uuid = extractXmlAttribute(tag, "IdDocumento").toLowerCase();
    const paid = Number(extractXmlAttribute(tag, "ImpPagado") || 0);
    if (uuid && Number.isFinite(paid) && paid > 0) documents.push({ uuid, paid });
  }
  return { fechaPago: fechaPago || null, referencia, documents };
}

async function readXmlFile(relativePath = "") {
  const storedPath = String(relativePath || "").trim();
  if (!storedPath || path.extname(storedPath).toLowerCase() !== ".xml") return null;
  try {
    return await fs.promises.readFile(path.resolve(__dirname, storedPath), "utf8");
  } catch (_error) {
    return null;
  }
}

async function getAccountsReceivableInvoiceDocuments(cuentaId, connection = pool) {
  if (!cuentaId) return [];
  const [rows] = await connection.execute(
    `SELECT id, ruta, facturacion_id
     FROM cuentas_por_cobrar_archivos
     WHERE cuenta_id = ? AND tipo = 'Factura' AND LOWER(ruta) LIKE '%.xml'
     ORDER BY id ASC`,
    [cuentaId]
  );
  const documents = [];
  for (const row of rows) {
    const xml = await readXmlFile(row.ruta);
    if (!xml) continue;
    const parsed = extractInvoiceDataFromXmlContent(xml);
    if (!parsed.uuid) continue;
    documents.push({
      archivoId: Number(row.id),
      facturacionId: row.facturacion_id ? Number(row.facturacion_id) : null,
      uuid: parsed.uuid.toLowerCase(),
      subtotal: Number(parsed.subtotal || 0),
      total: Number(parsed.total || 0)
    });
  }
  return documents;
}

async function registerAccountsReceivablePaymentFromProof({ cuentaId, archivoId, relativePath, fileName, userId = null }) {
  if (!cuentaId || !archivoId) return null;
  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();
    const [existing] = await connection.execute("SELECT id FROM cuentas_por_cobrar_pagos WHERE archivo_id = ? LIMIT 1", [archivoId]);
    if (existing.length) {
      await connection.commit();
      return existing[0].id;
    }
    const [accounts] = await connection.execute("SELECT monto FROM cuentas_por_cobrar WHERE id = ? FOR UPDATE", [cuentaId]);
    if (!accounts.length) {
      await connection.rollback();
      return null;
    }
    const projectTotal = Math.max(0, Number(accounts[0].monto || 0));
    const paymentSummary = await getAccountsReceivablePaymentSummary(cuentaId, projectTotal, connection);
    const outstanding = paymentSummary.remaining;
    if (outstanding <= 0.004) {
      await connection.commit();
      return null;
    }

    const xml = await readXmlFile(relativePath);
    const paymentXml = xml ? extractPaymentDetailsFromXmlContent(xml) : { fechaPago: null, referencia: "", documents: [] };
    const invoiceDocuments = await getAccountsReceivableInvoiceDocuments(cuentaId, connection);
    const invoiceByUuid = new Map(invoiceDocuments.map((invoice) => [invoice.uuid, invoice]));
    const matched = paymentXml.documents.filter((document) => invoiceByUuid.has(document.uuid));
    let amount = 0;
    let facturacionId = null;
    for (const document of matched) {
      const invoice = invoiceByUuid.get(document.uuid);
      const ratio = invoice.total > 0 && invoice.subtotal > 0 ? invoice.subtotal / invoice.total : 1;
      amount += Number(document.paid || 0) * ratio;
      if (!facturacionId && invoice.facturacionId) facturacionId = invoice.facturacionId;
    }

    if (!facturacionId) {
      const [billingRows] = await connection.execute(
        `SELECT f.id, f.monto,
                COALESCE((SELECT SUM(p.monto) FROM cuentas_por_cobrar_pagos p WHERE p.facturacion_id = f.id), 0) AS pagado
         FROM cuentas_por_cobrar_facturacion f
         WHERE f.cuenta_id = ? AND LOWER(TRIM(f.estado)) IN ('facturada', 'pagada')
         HAVING pagado + 0.004 < f.monto
         ORDER BY f.id ASC
         LIMIT 1`,
        [cuentaId]
      );
      if (billingRows.length) {
        facturacionId = Number(billingRows[0].id);
        if (!(amount > 0)) amount = Math.max(0, Number(billingRows[0].monto || 0) - Number(billingRows[0].pagado || 0));
      }
    }
    if (!(amount > 0)) amount = outstanding;
    amount = Math.min(outstanding, Math.round(amount * 100) / 100);
    if (amount <= 0.004) {
      await connection.commit();
      return null;
    }

    const [result] = await connection.execute(
      `INSERT INTO cuentas_por_cobrar_pagos
        (cuenta_id, archivo_id, facturacion_id, monto, fecha_pago, referencia, usuario_id)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        cuentaId,
        archivoId,
        facturacionId || null,
        amount,
        paymentXml.fechaPago || null,
        paymentXml.referencia || fileName || "",
        userId || null
      ]
    );

    if (facturacionId) {
      const [paidRows] = await connection.execute(
        "SELECT COALESCE(SUM(monto), 0) AS pagado FROM cuentas_por_cobrar_pagos WHERE facturacion_id = ?",
        [facturacionId]
      );
      const [billingRows] = await connection.execute("SELECT monto FROM cuentas_por_cobrar_facturacion WHERE id = ? LIMIT 1", [facturacionId]);
      if (Number(paidRows[0]?.pagado || 0) + 0.004 >= Number(billingRows[0]?.monto || 0)) {
        await connection.execute("UPDATE cuentas_por_cobrar_facturacion SET estado = 'Pagada', updated_at = NOW() WHERE id = ?", [facturacionId]);
      }
    }
    await connection.commit();
    return result.insertId;
  } catch (error) {
    await connection.rollback();
    throw error;
  } finally {
    connection.release();
  }
}

function isPastDueServer(value) {
  const date = getValidServerDate(value);
  if (!date) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  date.setHours(0, 0, 0, 0);
  return date < today;
}

function sumServerMoney(rows = [], getter = (item) => item.monto) {
  return rows.reduce((total, item) => total + Number(getter(item) || 0), 0);
}

function toServerChartRows(map, { limit = 8, sortByValue = true } = {}) {
  const rows = [...map.entries()].map(([label, value]) => ({ label, value: Number(value || 0) }));
  rows.sort((a, b) => (sortByValue ? b.value - a.value : String(a.label).localeCompare(String(b.label))));
  return rows.slice(0, limit);
}

function isWithoutPendingDocumentation(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .includes("sin pendiente");
}

function isReceivableCollected(item = {}) {
  // El estado documental/histórico de Dalvo sigue siendo la fuente de verdad.
  // La tabla de pagos puede estar incompleta para proyectos históricos, por lo que
  // nunca debe degradar un "Pago completo" existente a parcial.
  const status = normalizeWorkflowValue(`${item.estado || ""} ${item.pendiente || ""}`);
  if (
    status.includes("cobrad") ||
    status.includes("pago completo") ||
    isWithoutPendingDocumentation(item.pendiente)
  ) {
    return true;
  }
  if (item.pagosRegistrados === true) {
    return Number(item.saldoCobrar ?? item.monto ?? 0) <= 0.004;
  }
  return false;
}

function isReceivableClosed(item = {}) {
  const status = normalizeWorkflowValue(`${item.estado || ""} ${item.pendiente || ""}`);
  return status.includes("cerrad");
}

function isReceivablePending(item = {}) {
  return !isReceivableCollected(item) && !isReceivableClosed(item);
}

function filterOwnedRowsForUser(rows = [], user = null, modulePermission = "modulo:presupuesto") {
  if (!shouldRestrictToOwnedBudgets(user)) return rows;
  const userId = Number(user?.id || 0);
  const branchIds = new Set(getSessionBranchAccessIds(user, modulePermission));
  if (!userId && !branchIds.size) return [];
  return rows.filter((row) =>
    Number(row.ownerId || 0) === userId || branchIds.has(Number(row.sucursalId || 0))
  );
}

function extractPaymentDateFromXmlContent(xml = "") {
  const source = String(xml || "");
  const patterns = [
    /\bFechaPago\s*=\s*["']([^"']+)["']/i,
    /<(?:(?:\w+):)?FechaPago\b[^>]*>([^<]+)<\//i,
    /<(?:(?:\w+):)?fecha_pago\b[^>]*>([^<]+)<\//i,
    /\bfecha[_\s-]*pago\s*[=:]\s*["']?((?:19|20)\d{2}-\d{2}-\d{2}(?:[T\s][^<"']+)?)/i
  ];
  for (const pattern of patterns) {
    const match = source.match(pattern);
    const value = String(match?.[1] || "").trim();
    const dateMatch = value.match(/((?:19|20)\d{2}-\d{2}-\d{2})/);
    if (dateMatch) return dateMatch[1];
  }
  return null;
}

async function getPaymentDateFromXmlPath(relativePath = "") {
  const storedPath = String(relativePath || "").trim();
  if (!storedPath || path.extname(storedPath).toLowerCase() !== ".xml") return null;
  try {
    const absolutePath = path.resolve(__dirname, storedPath);
    const xml = await fs.promises.readFile(absolutePath, "utf8");
    return extractPaymentDateFromXmlContent(xml);
  } catch (_error) {
    return null;
  }
}

function latestReceivableEventDate(values = []) {
  const valid = (values || [])
    .filter(Boolean)
    .map((value) => ({ value, time: new Date(value).getTime() }))
    .filter((item) => Number.isFinite(item.time));
  if (!valid.length) return null;
  valid.sort((a, b) => b.time - a.time);
  return valid[0].value;
}

function latestReceivableBillingMovementDate(movements = [], acceptedStates = []) {
  const accepted = new Set((acceptedStates || []).map((value) => normalizeWorkflowValue(value)));
  return latestReceivableEventDate(
    (movements || [])
      .filter((movement) => {
        const state = normalizeWorkflowValue(movement.estado || "");
        return !accepted.size || accepted.has(state);
      })
      .flatMap((movement) => [movement.updatedAt, movement.createdAt])
  );
}

function resolveAccountsReceivableStateEventDate({ row = {}, billingSummary = {}, paymentSummary = {} } = {}) {
  const state = normalizeWorkflowValue(`${row.estado || ""} ${row.pendiente || ""}`);
  const billingMovements = Array.isArray(billingSummary.movements) ? billingSummary.movements : [];
  const payments = Array.isArray(paymentSummary.payments) ? paymentSummary.payments : [];
  const latestPaymentUpload = latestReceivableEventDate(payments.flatMap((payment) => [payment.createdAt, payment.updatedAt]));

  // El filtro por fecha representa CUANDO ocurrio el estado actual, no cuando
  // se creo el proyecto. Los archivos del flujo son la fuente mas precisa.
  if (state.includes("facturacion parcial")) {
    return latestReceivableBillingMovementDate(billingMovements, ["Facturada", "Solicitada"]) || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("facturacion")) {
    return latestReceivableBillingMovementDate(billingMovements, ["Solicitada"]) || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("pago completo") || state.includes("sin pendientes de documentacion")) {
    return row.complemento_pago_fecha || row.comprobante_pago_fecha || latestPaymentUpload || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("pago parcial")) {
    return latestPaymentUpload || row.comprobante_pago_fecha || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("comprobante de pago cargado")) {
    return row.comprobante_pago_fecha || latestPaymentUpload || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("track id cargado")) {
    return row.track_id_fecha || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("gr cargada")) {
    return row.gr_fecha || row.cuenta_updated_at || row.cuenta_created_at;
  }
  if (state.includes("factura cargada")) {
    return row.factura_fecha || row.cuenta_updated_at || row.cuenta_created_at;
  }
  return row.cuenta_updated_at || row.cuenta_created_at || row.quote_created_at || row.presupuesto_created_at || null;
}

async function mapAccountsReceivableRow(row) {
  const totals = await getClientQuoteTotalWithTax(row.quote_id);
  const originalSubtotal = Number(totals.subtotal || 0);
  const groupedSubtotal = Number(row.cobro_monto_neto);
  const financialSubtotal = row.cobro_lote_item_id && Number.isFinite(groupedSubtotal)
    ? Math.max(0, groupedSubtotal)
    : originalSubtotal;
  const xmlPaymentDate = await getPaymentDateFromXmlPath(row.comprobante_pago_xml_ruta);
  const billingSummary = row.cuenta_id
    ? await getAccountsReceivableBillingSummary(row.cuenta_id, financialSubtotal)
    : { total: financialSubtotal, billed: 0, remaining: financialSubtotal, movements: [] };
  const paymentSummary = row.cuenta_id
    ? await getAccountsReceivablePaymentSummary(row.cuenta_id, financialSubtotal)
    : { hasPayments: false, paid: 0, remaining: financialSubtotal, latestDate: null, payments: [] };
  const stateEventDate = resolveAccountsReceivableStateEventDate({ row, billingSummary, paymentSummary });
  const clientDays = row.cliente_dias_credito === null || row.cliente_dias_credito === undefined ? null : Number(row.cliente_dias_credito);
  const days = paymentDaysFromTerms(row.condiciones_pago, clientDays, inferPaymentDays(row.condiciones_pago));
  const paymentStartDate = requiresExtendedReceivableFiles(row.empresa) ? row.track_id_fecha : row.factura_fecha;
  const fechaPago = row.fecha_pago || (paymentStartDate ? addDays(paymentStartDate, days) : null);
  return {
    cuentaId: row.cuenta_id || null,
    quoteId: row.quote_id,
    quoteFolio: row.quote_folio || "",
    quoteVersion: Number(row.quote_version || 0),
    presupuestoId: row.presupuesto_id,
    ownerId: row.presupuesto_usuario_id || null,
    sucursalId: row.presupuesto_sucursal_id || null,
    owner: row.owner_nombre || "Sin usuario asignado",
    empresa: row.empresa || "",
    sucursal: row.sucursal || "",
    clienteUsuario: row.cliente_usuario || "",
    folio: row.presupuesto_folio || "",
    po: row.po_cliente || "",
    proyecto: row.titulo_proyecto || "",
    fecha: row.quote_created_at,
    fechaCreacionProyecto: row.presupuesto_created_at || row.quote_created_at,
    fechaCargaPo: Number(row.po_sin_po || 0) === 1 ? null : row.po_created_at || null,
    // Fechas exactas de cada hito documental. Exportaciones usa fechaEventoEstado
    // para decidir si una CxC pertenece al periodo seleccionado.
    fechaFactura: row.factura_fecha || null,
    fechaGr: row.gr_fecha || null,
    fechaTrackId: row.track_id_fecha || null,
    fechaComprobantePago: row.comprobante_pago_fecha || null,
    fechaComplementoPago: row.complemento_pago_fecha || null,
    fechaEventoEstado: stateEventDate,
    estado: row.estado || "En proceso",
    pendiente: row.pendiente || "En proceso",
    diasPago: days,
    fechaPago,
    // Para cobros reales, priorizamos la FechaPago del XML del comprobante.
    // Si el histórico no tiene XML legible, conservamos como respaldo la fecha de carga.
    fechaCobro: paymentSummary.latestDate || row.cobro_lote_fecha || xmlPaymentDate || row.comprobante_pago_fecha || null,
    monto: financialSubtotal,
    montoOriginal: originalSubtotal,
    descuentoCobranza: row.cobro_lote_item_id ? Number(row.cobro_descuento_monto || 0) : 0,
    porcentajeDescuentoCobranza: row.cobro_lote_item_id ? Number(row.cobro_porcentaje_descuento || 0) : 0,
    ajusteRedondeoCobranza: row.cobro_lote_item_id ? Number(row.cobro_ajuste_redondeo || 0) : 0,
    cobroAgrupado: row.cobro_lote_id ? {
      id: Number(row.cobro_lote_id),
      folio: row.cobro_lote_folio || "",
      estado: row.cobro_lote_estado || "Pendiente",
      total: Number(row.cobro_lote_total || 0),
      empresa: row.empresa || "",
      intermediario: row.cobro_intermediario || "",
      referenciaExterna: row.cobro_referencia_externa || ""
    } : null,
    // Para históricos, un estado documental de Pago completo prevalece sobre una
    // tabla de eventos de pago que puede contener solo los movimientos recientes.
    montoCobrado: isReceivableCollected({ estado: row.estado, pendiente: row.pendiente })
      ? financialSubtotal
      : (paymentSummary.hasPayments ? paymentSummary.paid : 0),
    saldoCobrar: isReceivableCollected({ estado: row.estado, pendiente: row.pendiente })
      ? 0
      : (paymentSummary.hasPayments ? paymentSummary.remaining : financialSubtotal),
    pagosRegistrados: paymentSummary.hasPayments,
    pagos: paymentSummary.payments,
    solicitadoFacturar: billingSummary.billed,
    saldoRestante: billingSummary.remaining,
    porcentajeFacturado: financialSubtotal > 0 ? Math.min(100, Math.max(0, (billingSummary.billed / financialSubtotal) * 100)) : 0,
    createdAt: row.cuenta_created_at || row.quote_created_at,
    updatedAt: row.cuenta_updated_at || row.quote_created_at,
    subtotal: financialSubtotal,
    subtotalOriginal: originalSubtotal,
    iva: financialSubtotal * 0.16,
    condicionesPago: row.condiciones_pago || "contado",
    complementoPagoCargado: Boolean(String(row.complemento_pago_archivos || "").trim()),
    complementoPagoNombre: row.complemento_pago_archivos || "",
    facturaNombre: row.factura_archivos || "",
    complementoPagoFecha: row.complemento_pago_fecha || null,
    archivosNombres: [row.archivos_nombres, row.po_archivos_nombres].filter(Boolean).join(" "),
    searchText: [
      row.empresa,
      row.cliente_usuario,
      row.presupuesto_folio,
      row.po_cliente,
      row.titulo_proyecto,
      row.quote_folio,
      row.estado,
      row.pendiente,
      row.archivos_nombres,
      row.po_archivos_nombres,
      row.cobro_lote_folio,
      row.cobro_intermediario,
      row.cobro_referencia_externa,
      buildMoneySearchTermsServer(originalSubtotal, financialSubtotal, billingSummary.billed, billingSummary.remaining, paymentSummary.paid, paymentSummary.remaining)
    ].join(" ")
  };
}

async function getAccountsReceivableList() {
  const rows = (await getAccountsReceivableBaseRows()).filter((row) => row.cuenta_id);
  const accounts = [];
  for (const row of rows) {
    let currentRow = row;
    if (row.cuenta_id) {
      await refreshAccountsReceivableStatus(row.cuenta_id);
      const refreshedRows = await getAccountsReceivableBaseRows(row.quote_id);
      currentRow = refreshedRows[0] || row;
    }
    accounts.push(await mapAccountsReceivableRow(currentRow));
  }
  return accounts;
}

async function getAccountsReceivableDetail(quoteId) {
  const rows = await getAccountsReceivableBaseRows(quoteId);
  if (!rows.length) return null;
  if (rows[0].cuenta_id) {
    await refreshAccountsReceivableStatus(rows[0].cuenta_id);
    const refreshedRows = await getAccountsReceivableBaseRows(quoteId);
    if (refreshedRows.length) rows[0] = refreshedRows[0];
  }
  const account = await mapAccountsReceivableRow(rows[0]);
  const quote = await getClientQuoteById(quoteId);
  const files = await getAccountsReceivableFilesByQuote(quoteId);
  const supportDocuments = await getAccountsReceivableSupportDocuments(quoteId, account, quote || {});
  const billingSummary = account.cuentaId
    ? await getAccountsReceivableBillingSummary(account.cuentaId, account.monto)
    : { total: Number(account.monto || 0), billed: 0, remaining: Number(account.monto || 0), movements: [] };
  return {
    account,
    quote,
    supportDocuments,
    files,
    billingSummary,
    billingMovements: billingSummary.movements,
    fileTypes: getAccountsReceivableFileTypes(account.empresa || rows[0].empresa)
  };
}

async function getLatestApprovedClientQuoteIdByBudget(budgetId, executor = pool) {
  const [rows] = await executor.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ?
       AND tipo = 'version'
       AND LOWER(TRIM(estatus)) LIKE 'aprob%'
     ORDER BY version DESC, id DESC
     LIMIT 1`,
    [budgetId]
  );
  return Number(rows[0]?.id || 0);
}

async function getLatestClientQuoteIdForPoByBudget(budgetId, connection = pool) {
  const [rows] = await connection.execute(
    `SELECT id
     FROM cotizaciones_cliente
     WHERE presupuesto_id = ?
       AND tipo = 'version'
       AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE '%cancel%'
       AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE '%rechaz%'
       AND LOWER(TRIM(COALESCE(estatus, ''))) NOT LIKE '%no aprob%'
     ORDER BY version DESC, id DESC
     LIMIT 1`,
    [budgetId]
  );
  return Number(rows[0]?.id || 0);
}

async function ensureAccountsReceivableRecord(quoteId, userId) {
  const detail = await getAccountsReceivableDetail(quoteId);
  if (!detail) return null;
  if (detail.account.cuentaId) return detail.account.cuentaId;

  const [result] = await pool.execute(
    `INSERT INTO cuentas_por_cobrar
      (cotizacion_cliente_id, presupuesto_id, estado, pendiente, dias_pago, fecha_pago, monto, usuario_id)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      quoteId,
      detail.account.presupuestoId,
      detail.account.estado,
      detail.account.pendiente || "En proceso",
      detail.account.diasPago,
      null,
      detail.account.monto,
      userId || null
    ]
  );
  return result.insertId;
}

async function refreshAccountsReceivableStatus(cuentaId) {
  const [accountRows] = await pool.execute(
    "SELECT cotizacion_cliente_id, dias_pago, pendiente, monto FROM cuentas_por_cobrar WHERE id = ? LIMIT 1",
    [cuentaId]
  );
  if (!accountRows.length) return;
  const files = await getAccountsReceivableFilesByQuote(accountRows[0].cotizacion_cliente_id);
  const baseRows = await getAccountsReceivableBaseRows(accountRows[0].cotizacion_cliente_id);
  let status = resolveAccountsReceivableStatus(
    files,
    baseRows[0]?.condiciones_pago || "contado",
    baseRows[0]?.empresa || "",
    accountRows[0]?.pendiente || ""
  );
  const requiredStartType = requiresExtendedReceivableFiles(baseRows[0]?.empresa || "") ? "Track ID" : "Factura";
  const startFile = files
    .filter((file) => file.tipo === requiredStartType)
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))[0];
  const groupedTotal = Number(baseRows[0]?.cobro_monto_neto);
  const total = baseRows[0]?.cobro_lote_item_id && Number.isFinite(groupedTotal)
    ? Math.max(0, groupedTotal)
    : Number(accountRows[0]?.monto || baseRows[0]?.monto || 0) || (await getClientQuoteTotalWithTax(accountRows[0].cotizacion_cliente_id)).subtotal;
  const billingSummary = await getAccountsReceivableBillingSummary(cuentaId, total);
  const paymentSummary = await getAccountsReceivablePaymentSummary(cuentaId, total);
  const activeMovements = billingSummary.movements.filter((movement) => normalizeWorkflowValue(movement.estado) !== "cancelada");
  const requestedMovements = activeMovements.filter((movement) => normalizeWorkflowValue(movement.estado) === "solicitada");
  const hasRequestedBilling = requestedMovements.length > 0;
  const hasBillingActivity = billingSummary.billed > 0.004;
  const hasRemainingBilling = billingSummary.remaining > 0.004;

  // La facturación manda sobre el estado documental: nunca mostramos "Pago completo"
  // mientras todavía exista saldo por facturar o una parcialidad solicitada sin factura.
  if (hasRequestedBilling) {
    status = { estado: "Facturación", pendiente: "Facturación" };
  } else if (hasRemainingBilling && hasBillingActivity) {
    status = { estado: "Facturación parcial", pendiente: "En proceso" };
  } else if (!hasBillingActivity) {
    status = { estado: "En proceso", pendiente: "En proceso" };
  }

  const hasPaymentComplement = files.some((file) => file.tipo === "Complemento de pago");
  if (paymentSummary.hasPayments && paymentSummary.remaining <= 0.004) {
    // El dinero ya fue recibido, pero el flujo documental no termina hasta que
    // exista el complemento. Antes este bloque ignoraba los archivos y cerraba
    // la cuenta inmediatamente al cargar el comprobante.
    status = hasPaymentComplement
      ? { estado: "Pago completo", pendiente: "Sin pendientes de documentación" }
      : { estado: "Comprobante de pago cargado", pendiente: "Cargar complemento de pago" };
  } else if (paymentSummary.hasPayments && paymentSummary.paid > 0.004) {
    status = { estado: "Pago parcial", pendiente: "Saldo pendiente" };
  }


  const configuredDays = paymentDaysFromTerms(
    baseRows[0]?.condiciones_pago,
    baseRows[0]?.cliente_dias_credito,
    inferPaymentDays(baseRows[0]?.condiciones_pago)
  );
  const fechaPago = startFile ? addDays(startFile.createdAt, configuredDays) : null;
  await pool.execute("UPDATE cuentas_por_cobrar SET estado = ?, pendiente = ?, dias_pago = ?, fecha_pago = ? WHERE id = ?", [
    status.estado,
    status.pendiente,
    configuredDays,
    fechaPago,
    cuentaId
  ]);
}

const ACCOUNTS_PAYABLE_FILE_TYPES = ["Factura", "Comprobante de pago", "Complemento de pago"];
const ACCOUNTS_PAYABLE_PENDING_INVOICE_LABEL = "Cargar Factura Proveedor";

function normalizeAccountsPayablePendingLabel(value) {
  return value === "Creación de factura" ? ACCOUNTS_PAYABLE_PENDING_INVOICE_LABEL : value;
}

function resolveAccountsPayableStatus(files) {
  const types = new Set((files || []).map((file) => file.tipo));
  if (!types.has("Factura")) {
    return { estado: "En proceso", pendiente: ACCOUNTS_PAYABLE_PENDING_INVOICE_LABEL };
  }
  if (!types.has("Comprobante de pago")) {
    return { estado: "Factura cargada", pendiente: "Cargar comprobante de pago" };
  }
  if (!types.has("Complemento de pago")) {
    return { estado: "Pago comprobado", pendiente: "Cargar complemento de pago" };
  }
  return { estado: "Documentación completa", pendiente: "Sin pendientes de documentación" };
}

function legacyPayableFileType(value) {
  const normalized = String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (normalized.includes("factura")) return "Factura";
  if (normalized.includes("comprobante") && normalized.includes("pago")) return "Comprobante de pago";
  if (normalized.includes("complemento")) return "Complemento de pago";
  return "";
}

