async function getAccountsPayableCommissionAdjustmentHistory(cuentaIds = []) {
  const ids = [...new Set((Array.isArray(cuentaIds) ? cuentaIds : [cuentaIds]).map(Number).filter(Boolean))];
  if (!ids.length) return [];
  const placeholders = ids.map(() => "?").join(",");
  let rows = [];
  try {
    [rows] = await pool.execute(
      `SELECT
          a.id,
          a.cuenta_id,
          a.descuento_monto,
          a.descuento_detalle,
          a.adeudo_monto,
          a.adeudo_detalle,
          a.usuario_id,
          a.created_at,
          CONCAT(COALESCE(u.nombre, ''), ' ', COALESCE(u.apellido, '')) AS usuario_nombre,
          u.usuario AS usuario_login
       FROM cuentas_por_pagar_occom_ajustes a
       LEFT JOIN usuarios u ON u.user_id = a.usuario_id
       WHERE a.cuenta_id IN (${placeholders})
       ORDER BY a.id DESC`,
      ids
    );
  } catch (error) {
    logServerError("occom-adjustments-history-users", error);
    try {
      [rows] = await pool.execute(
        `SELECT
            a.id,
            a.cuenta_id,
            a.descuento_monto,
            a.descuento_detalle,
            a.adeudo_monto,
            a.adeudo_detalle,
            a.usuario_id,
            a.created_at,
            '' AS usuario_nombre,
            '' AS usuario_login
         FROM cuentas_por_pagar_occom_ajustes a
         WHERE a.cuenta_id IN (${placeholders})
         ORDER BY a.id DESC`,
        ids
      );
    } catch (fallbackError) {
      logServerError("occom-adjustments-history", fallbackError);
      return [];
    }
  }
  return rows.map((row) => ({
    id: row.id,
    cuentaId: row.cuenta_id,
    descuentoMonto: Number(row.descuento_monto || 0),
    descuentoDetalle: row.descuento_detalle || "",
    adeudoMonto: Number(row.adeudo_monto || 0),
    adeudoDetalle: row.adeudo_detalle || "",
    usuarioId: row.usuario_id || null,
    usuario: String(row.usuario_nombre || "").trim() || row.usuario_login || "Sistema",
    createdAt: row.created_at
  }));
}

function mapSupportDocument(row, defaultType = "Documento") {
  return {
    id: row.id || row.key || "",
    tipo: row.tipo || defaultType,
    nombre: row.nombre || defaultType,
    ruta: row.ruta || "",
    url: row.url || (row.ruta ? `/${String(row.ruta).replace(/\\/g, "/")}` : ""),
    createdAt: row.created_at || row.createdAt || null
  };
}

async function getAccountsPayableSupportDocumentsByOrder(orderId, account = {}, order = {}) {
  order = order || {};
  const documents = [
    mapSupportDocument({
      key: `ocp-${orderId}`,
      tipo: "OCP",
      nombre: account.ocp || order.folio || "Orden de compra proveedor",
      url: `/api/supplier-orders/${Number(orderId)}/preview?payable=1`,
      createdAt: order.createdAt || account.fecha || account.createdAt
    })
  ];

  if (account.presupuestoId) {
    const [budgetFiles, supplierFiles] = await Promise.all([
      getBudgetFiles(account.presupuestoId),
      getSupplierOrderFiles(account.presupuestoId)
    ]);
    documents.push(
      ...budgetFiles.map((file) =>
        mapSupportDocument(
          {
            ...file,
            tipo: file.tipo || "Cotización proveedor del presupuesto"
          },
          "Cotización proveedor del presupuesto"
        )
      ),
      ...supplierFiles.map((file) =>
        mapSupportDocument(
          {
            ...file,
            tipo: file.tipo || "Cotización proveedor"
          },
          "Cotización proveedor"
        )
      )
    );
  }

  return documents;
}

