async function getAccountsPayableSupportDocumentsByCommission(account = {}) {
  const budgetId = Number(account.presupuestoId || 0);
  if (!budgetId) return [];

  try {
    const documents = [];
    const po = await getClientPoByBudget(budgetId);

    if (po) {
      documents.push(
        mapSupportDocument(
          {
            key: `commission-po-${budgetId}`,
            tipo: "PO Cliente",
            nombre: po.sinPo ? "Sin PO" : po.nombre || po.numeroPo || account.po || "PO Cliente",
            ruta: po.ruta || "",
            url: po.url || "",
            createdAt: po.createdAt || account.createdAt
          },
          "PO Cliente"
        )
      );
    }

    const [quoteRows] = await pool.execute(
      `SELECT id, folio, version, estatus, created_at, updated_at
       FROM cotizaciones_cliente
       WHERE presupuesto_id = ?
         AND tipo = 'version'
         AND LOWER(TRIM(estatus)) LIKE 'aprobad%'
       ORDER BY version DESC, id DESC
       LIMIT 1`,
      [budgetId]
    );
    const quote = quoteRows[0];

    if (quote) {
      documents.push(
        mapSupportDocument(
          {
            key: `commission-client-quote-${quote.id}`,
            tipo: "Cotización cliente",
            nombre: quote.folio || `Cotización v${quote.version || ""}`.trim(),
            url: `/api/client-quotes/${Number(quote.id)}/preview`,
            createdAt: quote.updated_at || quote.created_at || account.createdAt
          },
          "Cotización cliente"
        )
      );
    }

    const [receivableRows] = await pool.execute(
      `SELECT
          a.id,
          a.tipo,
          a.nombre,
          a.ruta,
          a.usuario_id,
          a.created_at
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
       LEFT JOIN cotizaciones_cliente q ON q.id = c.cotizacion_cliente_id
       WHERE c.presupuesto_id = ? OR q.presupuesto_id = ?
       ORDER BY a.id DESC`,
      [budgetId, budgetId]
    );
    documents.push(
      ...receivableRows
        .map((file) =>
          mapSupportDocument(
            {
              ...file,
              tipo: `${file.tipo} cliente`
            },
            "Documento de cobranza"
          )
        )
    );

    return documents;
  } catch (error) {
    logServerError("accounts-payable-commission-support-documents", error);
    return [];
  }
}

async function getAccountsPayableSupportDocumentsByCommissionAccounts(accounts = []) {
  const nestedDocuments = await Promise.all(accounts.map((account) => getAccountsPayableSupportDocumentsByCommission(account)));
  const seen = new Set();
  return nestedDocuments
    .flat()
    .filter((document) => {
      const key = [document.key, document.tipo, document.nombre, document.url, document.ruta].join("|");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

async function getAccountsPayableBaseRows(orderId = null) {
  const values = [];
  let orderFilter = "";
  if (orderId) {
    orderFilter = "AND o.id = ?";
    values.push(orderId);
  }

  const [rows] = await pool.execute(
    `SELECT
        o.id AS order_id,
        o.folio AS ocp_folio,
        o.version AS ocp_version,
        o.estatus_documentacion AS ocp_estatus_documentacion,
        o.created_at AS ocp_created_at,
        o.retencion_activa,
        o.retencion_monto,
        p.id AS presupuesto_id,
        p.empresa,
        p.sucursal,
        p.sucursal_id AS presupuesto_sucursal_id,
        p.cliente_usuario,
        p.usuario_id AS presupuesto_usuario_id,
        p.folio AS presupuesto_folio,
        p.po AS presupuesto_po,
        p.titulo_proyecto,
        GROUP_CONCAT(DISTINCT op.proveedor_nombre ORDER BY op.proveedor_nombre SEPARATOR ', ') AS proveedor,
        GROUP_CONCAT(
          DISTINCT COALESCE(NULLIF(pr.condiciones_pago, ''), '')
          ORDER BY COALESCE(NULLIF(pr.condiciones_pago, ''), '')
          SEPARATOR ', '
        ) AS condiciones_pago,
        MAX(CASE WHEN LOWER(COALESCE(pr.condiciones_pago, '')) = 'credito' THEN COALESCE(pr.dias_credito, 30) ELSE 0 END) AS proveedor_dias_credito,
        cp.id AS cuenta_id,
        cp.estado,
        cp.pendiente,
        cp.dias_pago,
        cp.fecha_pago,
        cp.monto,
        cp.monto_ocp_base,
        cp.porcentaje_pago,
        cp.subtotal_programado_pago,
        cp.monto_manual,
        cp.estado_registro,
        cp.estatus_pago,
        cp.estatus_documentacion,
        cp.descuento_monto,
        cp.descuento_detalle,
        cp.adeudo_monto,
        cp.adeudo_detalle,
        cp.pagado,
        lp.id AS lote_pago_id,
        lp.folio AS lote_pago_folio,
        lp.pdf_ruta AS lote_pago_pdf_ruta,
        (
          SELECT COALESCE(SUM(opg.monto), 0)
          FROM ordenes_pago opg
          WHERE opg.cuenta_id = cp.id
            AND opg.estado_movimiento = 'Aplicado'
        ) AS total_pagado,
        (
          SELECT COUNT(*)
          FROM ordenes_pago opg
          WHERE opg.cuenta_id = cp.id
        ) AS movimientos_registrados,
        cp.created_at AS cuenta_created_at,
        cp.updated_at AS cuenta_updated_at,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
            AND a.tipo = 'Factura'
        ) AS factura_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', a.tipo, a.nombre) ORDER BY a.nombre SEPARATOR ' ')
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
        ) AS archivos_pago_nombres,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', fa.tipo, fa.nombre) ORDER BY fa.nombre SEPARATOR ' ')
          FROM ocp_proveedor_archivos fa
          WHERE fa.ocp_id = o.id OR (fa.ocp_id IS NULL AND fa.presupuesto_id = o.presupuesto_id)
        ) AS archivos_soporte_nombres,
        COALESCE(SUM(op.total), 0) AS subtotal_ocp,
        COALESCE(SUM(COALESCE(NULLIF(op.monto_pago_aplicado, 0), ROUND(op.total * COALESCE(op.porcentaje_aplicado, 100) / 100, 2))), 0) AS subtotal_pago_ocp,
        GROUP_CONCAT(DISTINCT CONCAT(CAST(ROUND(COALESCE(op.porcentaje_aplicado, 100), 2) AS CHAR), '%') ORDER BY COALESCE(op.porcentaje_aplicado, 100) SEPARATOR ', ') AS porcentaje_pago_calculado
     FROM ocp_proveedor o
     INNER JOIN presupuestos p ON p.id = o.presupuesto_id
     LEFT JOIN ocp_proveedor_partidas op ON op.ocp_id = o.id
     LEFT JOIN proveedores pr ON pr.id = op.proveedor_id
     LEFT JOIN cuentas_por_pagar cp ON cp.ocp_id = o.id
     LEFT JOIN lotes_pago_comisiones_items lpi ON lpi.ocp_id = o.id AND lpi.tipo_origen = 'OCP'
     LEFT JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id AND lp.estado = 'Pagado'
     WHERE o.tipo = 'version'
       AND LOWER(TRIM(o.estatus)) LIKE 'aprobad%'
       AND NOT EXISTS (
         SELECT 1
         FROM ocp_proveedor child
         WHERE child.presupuesto_id = o.presupuesto_id
           AND child.tipo = 'version'
           AND child.estatus <> 'Cancelada'
           AND child.folio LIKE CONCAT(o.folio, '.%')
         LIMIT 1
       )
       ${orderFilter}
     GROUP BY
       o.id,
       o.folio,
       o.version,
       o.estatus_documentacion,
       o.created_at,
       o.retencion_activa,
       o.retencion_monto,
       p.id,
       p.empresa,
       p.sucursal,
       p.cliente_usuario,
       p.usuario_id,
       p.folio,
      p.po,
      p.titulo_proyecto,
      cp.id,
      cp.estado,
       cp.pendiente,
       cp.dias_pago,
       cp.fecha_pago,
       cp.monto,
       cp.monto_ocp_base,
       cp.porcentaje_pago,
       cp.subtotal_programado_pago,
       cp.monto_manual,
       cp.estado_registro,
       cp.estatus_pago,
       cp.estatus_documentacion,
       cp.pagado,
       lp.id,
       lp.folio,
       lp.pdf_ruta,
       cp.created_at,
       cp.updated_at
     ORDER BY o.created_at DESC, o.id DESC`,
    values
  );
  return applyProviderPaymentTermsFallback(rows, "proveedor", "condiciones_pago");
}

async function applyProviderPaymentTermsFallback(rows = [], providerField = "proveedor", termsField = "condiciones_pago") {
  const rowsNeedingTerms = rows.filter((row) => {
    const terms = String(row?.[termsField] || "").replace(/[, ]/g, "");
    return !terms && String(row?.[providerField] || "").trim();
  });
  if (!rowsNeedingTerms.length) return rows;

  const [providers] = await pool.execute(
    "SELECT empresa, condiciones_pago, dias_credito FROM proveedores WHERE empresa IS NOT NULL AND empresa <> ''"
  );
  const termsByProvider = new Map();
  const daysByProvider = new Map();
  providers.forEach((provider) => {
    const key = normalizeWorkflowValue(provider.empresa);
    const terms = String(provider.condiciones_pago || "").trim();
    if (key && terms && !termsByProvider.has(key)) termsByProvider.set(key, terms);
    if (key && !daysByProvider.has(key)) daysByProvider.set(key, Number(provider.dias_credito || 0));
  });

  rowsNeedingTerms.forEach((row) => {
    const providerNames = String(row[providerField] || "")
      .split(",")
      .map((name) => normalizeWorkflowValue(name))
      .filter(Boolean);
    const terms = [...new Set(providerNames.map((name) => termsByProvider.get(name)).filter(Boolean))];
    const creditDays = providerNames
      .filter((name) => normalizeWorkflowValue(termsByProvider.get(name)).includes("credito"))
      .map((name) => Number(daysByProvider.get(name) || 0));
    if (terms.length) row[termsField] = terms.join(", ");
    if (creditDays.length) row.proveedor_dias_credito = Math.max(...creditDays);
  });
  return rows;
}

function mapAccountsPayableRow(row) {
  const subtotalOcp = Number(row.subtotal_ocp || row.monto_ocp_base || 0);
  const subtotalProgramadoPago = Number(row.subtotal_pago_ocp || row.subtotal_programado_pago || 0);
  const porcentajePago = String(row.porcentaje_pago || row.porcentaje_pago_calculado || '100%');
  const retention = row.retencion_activa ? Number(row.retencion_monto || 0) : 0;
  const fullTotal = Math.max(0, Math.round((subtotalOcp * 1.16 - retention) * 100) / 100);
  const paymentRatio = subtotalOcp > 0 ? Math.min(1, Math.max(0, subtotalProgramadoPago / subtotalOcp)) : 1;
  const requestedRetention = Math.round(retention * paymentRatio * 100) / 100;
  const requestedPayment = Math.max(
    0,
    Math.round((subtotalProgramadoPago * 1.16 - requestedRetention) * 100) / 100
  );
  const requestedIva = Math.max(
    0,
    Math.round((requestedPayment + requestedRetention - subtotalProgramadoPago) * 100) / 100
  );
  const total = Boolean(row.monto_manual)
    ? Math.max(0, Number(row.monto || 0))
    : fullTotal || Math.max(0, Number(row.monto || 0));
  const days = paymentDaysFromTerms(row.condiciones_pago, row.proveedor_dias_credito, 30);
  const legacyDocumentStatus = String(row.ocp_estatus_documentacion || "").toLowerCase();
  const hasPaymentMovements = Number(row.movimientos_registrados || 0) > 0;
  const legacyPaid = !hasPaymentMovements && (Boolean(row.pagado) || legacyDocumentStatus.includes("pagad"));
  const summary = payableSummary(total, row.total_pagado, legacyPaid);
  const requestedPaymentCovered = Math.min(summary.applied, requestedPayment);
  const requestedPaymentPending = summary.paid
    ? 0
    : Math.max(0, Math.min(summary.remaining, Math.round((requestedPayment - requestedPaymentCovered) * 100) / 100));
  const document = paymentDocumentStatus([]);
  const documentStatus = row.estatus_documentacion || document.status;
  const fechaPago = summary.paid ? row.fecha_pago : row.factura_fecha ? addDays(row.factura_fecha, days) : null;
  const diasRestantes = calculateRemainingPaymentDays(row.factura_fecha, days, summary.paid, row.fecha_pago || fechaPago);
  const pending = summary.paid
    ? "Sin saldo pendiente"
    : summary.applied > 0
      ? String(row.pendiente || "").trim() ||
        (normalizeWorkflowValue(documentStatus).includes("completa")
          ? "Documentación del pago completa"
          : "Cargar documentos del pago")
      : normalizeAccountsPayablePendingLabel(row.pendiente || ACCOUNTS_PAYABLE_PENDING_INVOICE_LABEL);
  return {
    source: "OCP",
    cuentaId: row.cuenta_id || null,
    orderId: row.order_id,
    ocp: row.ocp_folio || "",
    ocpVersion: Number(row.ocp_version || 0),
    presupuestoId: row.presupuesto_id,
    ownerId: row.presupuesto_usuario_id || null,
    sucursalId: row.presupuesto_sucursal_id || null,
    empresa: row.empresa || "",
    sucursal: row.sucursal || row.cliente_usuario || "",
    cliente: row.empresa || row.cliente_usuario || "",
    proveedor: row.proveedor || "Sin proveedor",
    paymentTerms: row.condiciones_pago || "",
    dlv: row.presupuesto_folio || "",
    folio: row.presupuesto_folio || "",
    po: row.presupuesto_po || "",
    proyecto: row.titulo_proyecto || "",
    fecha: row.ocp_created_at,
    estado: row.estado_registro || (summary.paid ? "Cerrada" : "Activa"),
    estadoRegistro: row.estado_registro || (summary.paid ? "Cerrada" : "Activa"),
    estatus: summary.paymentStatus,
    estatusPago: summary.paymentStatus,
    estatusDocumentacion: documentStatus,
    pendiente: pending,
    diasPago: days,
    diasRestantes,
    fechaPago,
    monto: summary.total,
    montoTotal: summary.total,
    totalPagado: summary.applied,
    saldoRestante: summary.remaining,
    montoManual: Boolean(row.monto_manual),
    pagado: summary.paid,
    lotePagoId: row.lote_pago_id || null,
    lotePagoFolio: row.lote_pago_folio || "",
    lotePagoPdfUrl: row.lote_pago_id ? `/api/commission-payment-batches/${Number(row.lote_pago_id)}/pdf` : "",
    createdAt: row.cuenta_created_at || row.ocp_created_at,
    updatedAt: row.cuenta_updated_at || row.ocp_created_at,
    subtotal: subtotalOcp,
    subtotalOcp,
    subtotalProgramadoPago,
    pagoSolicitado: requestedPaymentPending,
    pagoSolicitadoOriginal: requestedPayment,
    pagoSolicitadoCubierto: requestedPaymentCovered,
    ivaSolicitado: requestedIva,
    retencionSolicitada: requestedRetention,
    porcentajePago,
    retencion: retention,
    archivosNombres: [row.archivos_pago_nombres, row.archivos_soporte_nombres].filter(Boolean).join(" "),
    searchText: [
      row.empresa,
      row.sucursal,
      row.cliente_usuario,
      row.proveedor,
      row.condiciones_pago,
      row.presupuesto_folio,
      row.presupuesto_po,
      row.titulo_proyecto,
      row.ocp_folio,
      porcentajePago,
      row.estado_registro,
      summary.paymentStatus,
      documentStatus,
      pending,
      row.archivos_pago_nombres,
      row.archivos_soporte_nombres,
      buildMoneySearchTermsServer(summary.total, summary.applied, summary.remaining)
    ].join(" ")
  };
}

async function getAccountsPayableList() {
  const rows = await getAccountsPayableBaseRows();
  return rows.map(mapAccountsPayableRow);
}

async function getAccountsPayableDetail(orderId) {
  const rows = await getAccountsPayableBaseRows(orderId);
  if (!rows.length) return null;
  const account = mapAccountsPayableRow(rows[0]);
  if (account.cuentaId) {
    await pool.execute(
      `UPDATE cuentas_por_pagar SET monto_ocp_base = ?, porcentaje_pago = ?, subtotal_programado_pago = ?, monto = ? WHERE id = ? AND monto_manual = 0`,
      [account.subtotalOcp || 0, account.porcentajePago || '', account.subtotalProgramadoPago || 0, account.monto || 0, account.cuentaId]
    );
  }
  const order = await getSupplierOrderPreviewData(orderId);
  const files = await getAccountsPayableFilesByOrder(orderId);
  const paymentOrders = account.cuentaId ? await getPaymentOrdersByAccount(account.cuentaId, account.monto) : [];
  const supportDocuments = await getAccountsPayableSupportDocumentsByOrder(orderId, account, order);
  return {
    account,
    order,
    supportDocuments,
    files,
    fileTypes: ACCOUNTS_PAYABLE_FILE_TYPES,
    paymentOrders,
    paymentTerms: order?.provider?.condicionesPago || ""
  };
}

async function ensureAccountsPayableRecord(orderId, userId) {
  const detail = await getAccountsPayableDetail(orderId);
  if (!detail) return null;
  if (detail.account.cuentaId) return detail.account.cuentaId;

  const [result] = await pool.execute(
    `INSERT INTO cuentas_por_pagar
      (ocp_id, presupuesto_id, estado, pendiente, dias_pago, fecha_pago, monto, monto_ocp_base, porcentaje_pago, subtotal_programado_pago, usuario_id)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      orderId,
      detail.account.presupuestoId,
      detail.account.estado,
      detail.account.pendiente,
      detail.account.diasPago,
      null,
      detail.account.monto,
      detail.account.subtotalOcp || 0,
      detail.account.porcentajePago || '',
      detail.account.subtotalProgramadoPago || 0,
      userId || null
    ]
  );
  return result.insertId;
}

async function getAccountsPayableFixedExpenseRows(orderId = null) {
  await ensureFixedExpensesTable();
  const values = [];
  let orderFilter = "";
  if (orderId) {
    orderFilter = "AND o.id = ?";
    values.push(orderId);
  }

  const [rows] = await pool.execute(
    `SELECT
        o.id AS order_id,
        o.ocgf_id,
        o.folio AS ocgf_folio,
        o.estatus AS ocgf_estatus,
        o.estatus_documentacion AS ocgf_estatus_documentacion,
        o.created_at AS ocgf_created_at,
        o.retencion_activa,
        o.retencion_monto,
        o.sin_iva,
        g.gasto,
        g.sucursal,
        g.proveedor_nombre,
        COALESCE(NULLIF(pr.condiciones_pago, ''), '') AS condiciones_pago,
        COALESCE(pr.dias_credito, 30) AS proveedor_dias_credito,
        COALESCE(NULLIF(gf.presupuesto, 0), g.presupuesto) AS presupuesto_asignado,
        COALESCE(gf.presupuesto_adicional, 0) AS presupuesto_adicional,
        cp.id AS cuenta_id,
        cp.estado,
        cp.pendiente,
        cp.dias_pago,
        cp.fecha_pago,
        cp.monto,
        cp.monto_manual,
        cp.estado_registro,
        cp.estatus_pago,
        cp.estatus_documentacion,
        cp.descuento_monto,
        cp.descuento_detalle,
        cp.adeudo_monto,
        cp.adeudo_detalle,
        cp.pagado,
        lp.id AS lote_pago_id,
        lp.folio AS lote_pago_folio,
        lp.pdf_ruta AS lote_pago_pdf_ruta,
        (
          SELECT COALESCE(SUM(opg.monto), 0)
          FROM ordenes_pago opg
          WHERE opg.cuenta_id = cp.id
            AND opg.estado_movimiento = 'Aplicado'
        ) AS total_pagado,
        (
          SELECT COUNT(*)
          FROM ordenes_pago opg
          WHERE opg.cuenta_id = cp.id
        ) AS movimientos_registrados,
        cp.created_at AS cuenta_created_at,
        cp.updated_at AS cuenta_updated_at,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
            AND a.tipo = 'Factura'
        ) AS factura_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', a.tipo, a.nombre) ORDER BY a.nombre SEPARATOR ' ')
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
        ) AS archivos_pago_nombres,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', af.tipo, af.nombre) ORDER BY af.nombre SEPARATOR ' ')
          FROM ocgf_archivos af
          WHERE af.ocgf_id = g.id
        ) AS archivos_soporte_nombres,
        COALESCE(SUM(p.total), 0) AS subtotal_ocgf
     FROM ocgf_ordenes o
     INNER JOIN ocgf_compras g ON g.id = o.ocgf_id
     LEFT JOIN gastos_fijos gf ON gf.id = g.gasto_fijo_id AND COALESCE(gf.es_catalogo, 1) = 1
     LEFT JOIN proveedores pr ON pr.id = g.proveedor_id
     LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
     LEFT JOIN cuentas_por_pagar cp ON cp.ocgf_orden_id = o.id AND cp.tipo_origen = 'OCGF'
     LEFT JOIN lotes_pago_comisiones_items lpi ON lpi.ocgf_order_id = o.id AND lpi.tipo_origen = 'OCGF'
     LEFT JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id AND lp.estado = 'Pagado'
     WHERE o.tipo = 'version'
       AND LOWER(TRIM(o.estatus)) LIKE 'aprobad%'
       ${orderFilter}
     GROUP BY
       o.id,
       o.ocgf_id,
       o.folio,
       o.estatus,
       o.estatus_documentacion,
       o.created_at,
       o.retencion_activa,
       o.retencion_monto,
       o.sin_iva,
       g.gasto,
       g.sucursal,
       g.proveedor_nombre,
       pr.condiciones_pago,
       pr.dias_credito,
       g.presupuesto,
       gf.presupuesto,
       gf.presupuesto_adicional,
       cp.id,
       cp.estado,
       cp.pendiente,
       cp.dias_pago,
       cp.fecha_pago,
       cp.monto,
       cp.monto_manual,
       cp.estado_registro,
       cp.estatus_pago,
       cp.estatus_documentacion,
       cp.pagado,
       lp.id,
       lp.folio,
       lp.pdf_ruta,
       cp.created_at,
       cp.updated_at
     ORDER BY o.created_at DESC, o.id DESC`,
    values
  );

  await applyProviderPaymentTermsFallback(rows, "proveedor_nombre", "condiciones_pago");

  return Promise.all(rows.map(async (row) => {
    const subtotal = Number(row.subtotal_ocgf || 0);
    const retention = row.retencion_activa ? Number(row.retencion_monto || 0) : 0;
    const calculatedTotal = Math.max(0, subtotal * (row.sin_iva ? 1 : 1.16) - retention);
    const total = Boolean(row.monto_manual)
      ? Math.max(0, Number(row.monto || 0))
      : calculatedTotal || Math.max(0, Number(row.monto || 0));
    const presupuestoAsignado = Number(row.presupuesto_asignado || 0);
    const presupuestoAdicional = Number(row.presupuesto_adicional || 0);
    const usadoGlobal = await calculateOcgfUsed(row.ocgf_id);
    const presupuestoDisponible = Math.max(0, presupuestoAsignado + presupuestoAdicional - usadoGlobal);
    const days = paymentDaysFromTerms(row.condiciones_pago, row.proveedor_dias_credito, 30);
    const legacyDocumentStatus = String(row.ocgf_estatus_documentacion || "").toLowerCase();
    const hasPaymentMovements = Number(row.movimientos_registrados || 0) > 0;
    const legacyPaid = !hasPaymentMovements && (
      Boolean(row.pagado) ||
      legacyDocumentStatus.includes("pagad") ||
      normalizeWorkflowValue(row.ocgf_estatus).includes("ocgf pagad")
    );
    const summary = payableSummary(total, row.total_pagado, legacyPaid);
    const fechaPago = summary.paid ? row.fecha_pago : row.factura_fecha ? addDays(row.factura_fecha, days) : null;
    const documentStatus = row.estatus_documentacion || "Factura pendiente";
    const pending = summary.paid
      ? "Sin pendientes"
      : summary.applied > 0
        ? "Registrar abono sobre saldo restante"
        : normalizeAccountsPayablePendingLabel(row.pendiente || ACCOUNTS_PAYABLE_PENDING_INVOICE_LABEL);
    return {
      source: "OCGF",
      cuentaId: row.cuenta_id || null,
      orderId: row.order_id,
      ocgfId: row.ocgf_id,
      proveedor: row.proveedor_nombre || "Sin proveedor",
      paymentTerms: row.condiciones_pago || "",
      ocgf: row.ocgf_folio || "",
      estado: row.estado_registro || (summary.paid ? "Cerrada" : "Activa"),
      estadoRegistro: row.estado_registro || (summary.paid ? "Cerrada" : "Activa"),
      estatus: summary.paymentStatus,
      estatusPago: summary.paymentStatus,
      estatusDocumentacion: documentStatus,
      pendiente: pending,
      diasPago: days,
      diasRestantes: calculateRemainingPaymentDays(row.factura_fecha, days, summary.paid, row.fecha_pago || fechaPago),
      fechaPago,
      monto: summary.total,
      montoTotal: summary.total,
      totalPagado: summary.applied,
      saldoRestante: summary.remaining,
      montoManual: Boolean(row.monto_manual),
      fecha: row.ocgf_created_at,
      pagado: summary.paid,
      lotePagoId: row.lote_pago_id || null,
      lotePagoFolio: row.lote_pago_folio || "",
      lotePagoPdfUrl: row.lote_pago_id ? `/api/commission-payment-batches/${Number(row.lote_pago_id)}/pdf` : "",
      createdAt: row.cuenta_created_at || row.ocgf_created_at,
      updatedAt: row.cuenta_updated_at || row.ocgf_created_at,
      gasto: row.gasto || "",
      sucursal: row.sucursal || "",
      presupuestoAsignado,
      presupuestoAdicional,
      presupuestoDisponible,
      usadoGlobal,
      subtotal,
      retencion: retention,
      archivosNombres: [row.archivos_pago_nombres, row.archivos_soporte_nombres].filter(Boolean).join(" "),
      searchText: [
        row.gasto,
        row.sucursal,
        row.proveedor_nombre,
        row.condiciones_pago,
        row.ocgf_folio,
        row.estado_registro,
        summary.paymentStatus,
        documentStatus,
        pending,
        row.archivos_pago_nombres,
        row.archivos_soporte_nombres,
        buildMoneySearchTermsServer(summary.total, summary.applied, summary.remaining)
      ].join(" ")
    };
  }));
}

