async function getAccountsPayableCommissionRows(commissionId = null) {
  const values = [];
  let filter = "";
  let approvalFilter = `
       AND LOWER(TRIM(COALESCE(c.estatus, ''))) NOT IN (
         'cancelada',
         'cancelado',
         'no aprobada',
         'no aprobado',
         'rechazada',
         'rechazado'
       )`;
  if (commissionId) {
    filter = "AND c.id = ?";
    approvalFilter = "";
    values.push(commissionId);
  }

  const [rows] = await pool.execute(
    `SELECT
        c.id AS commission_id,
        c.folio AS occom_folio,
        c.nombre_proyecto,
        c.descripcion_proyecto,
        c.empresa,
        c.monto_proyecto,
        c.porcentaje_comision,
        c.monto_comision,
        c.estatus AS commission_status,
        c.created_at AS commission_created_at,
        c.updated_at AS commission_updated_at,
        p.id AS presupuesto_id,
        p.folio AS presupuesto_folio,
        p.sucursal_id AS presupuesto_sucursal_id,
        p.usuario_id AS presupuesto_usuario_id,
        u.user_id AS supervisor_id,
        COALESCE(NULLIF(c.supervisor_nombre_manual, ''), NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario, '') AS supervisor_nombre,
        u.banco AS supervisor_banco,
        u.cuenta AS supervisor_cuenta,
        u.clabe AS supervisor_clabe,
        cp.id AS cuenta_id,
        cp.estado,
        cp.pendiente,
        cp.dias_pago,
        cp.fecha_pago,
        cp.monto,
        cp.monto_manual,
        cp.estado_registro,
        cp.estatus_pago,
        cp.estatus_documentacion,
        cp.descuento_monto,
        cp.descuento_detalle,
        cp.adeudo_monto,
        cp.adeudo_detalle,
        cp.pagado,
        lp.id AS lote_pago_id,
        lp.folio AS lote_pago_folio,
        lp.pdf_ruta AS lote_pago_pdf_ruta,
        (
          SELECT COALESCE(SUM(opg.monto), 0)
          FROM ordenes_pago opg
          WHERE opg.cuenta_id = cp.id
            AND opg.estado_movimiento = 'Aplicado'
        ) AS total_pagado,
        cp.created_at AS cuenta_created_at,
        cp.updated_at AS cuenta_updated_at,
        (
          SELECT MIN(a.created_at)
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
            AND a.tipo = 'Factura'
        ) AS factura_fecha,
        (
          SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', a.tipo, a.nombre) ORDER BY a.nombre SEPARATOR ' ')
          FROM cuentas_por_pagar_archivos a
          WHERE a.cuenta_id = cp.id
        ) AS archivos_pago_nombres
     FROM comisiones c
     INNER JOIN presupuestos p ON p.id = c.presupuesto_id
     LEFT JOIN usuarios u ON u.user_id = c.supervisor_id
     LEFT JOIN cuentas_por_pagar cp ON cp.comision_id = c.id AND cp.tipo_origen = 'OCCOM'
     LEFT JOIN lotes_pago_comisiones_items lpi ON lpi.comision_id = c.id
     LEFT JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id AND lp.estado = 'Pagado'
     WHERE 1 = 1
       ${approvalFilter}
       ${filter}
     ORDER BY c.created_at DESC, c.id DESC`,
    values
  );
  return rows;
}

function mapAccountsPayableCommissionRow(row) {
  const days = Number(row.dias_pago ?? 0);
  const paid = Boolean(row.pagado);
  const fechaPago = paid ? row.fecha_pago : null;
  const grossCommission = Number(row.monto_comision || 0);
  const debtAmount = Math.max(0, Number(row.adeudo_monto || 0));
  const discountAmount = Math.max(0, Number(row.descuento_monto || 0));
  const netCommission = Math.max(Math.round((grossCommission - debtAmount) * 100) / 100, 0);
  const rawCommissionStatus = String(row.commission_status || "").trim();
  const normalizedCommissionStatus = rawCommissionStatus
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  const commissionStatus =
    normalizedCommissionStatus.includes("cancel") ||
    normalizedCommissionStatus.includes("rechaz") ||
    normalizedCommissionStatus.includes("no aprob")
      ? rawCommissionStatus || "No aprobada"
      : "Aprobada";
  return {
    source: "OCCOM",
    cuentaId: row.cuenta_id || null,
    orderId: row.commission_id,
    commissionId: row.commission_id,
    occom: row.occom_folio || "",
    folio: row.presupuesto_folio || "",
    presupuestoId: row.presupuesto_id || null,
    ownerId: row.presupuesto_usuario_id || null,
    sucursalId: row.presupuesto_sucursal_id || null,
    supervisorId: row.supervisor_id || null,
    supervisor: row.supervisor_nombre || "Sin supervisor",
    proveedor: row.supervisor_nombre || "Sin supervisor",
    banco: row.supervisor_banco || "",
    cuenta: row.supervisor_cuenta || "",
    clabe: row.supervisor_clabe || "",
    empresa: row.empresa || "",
    cliente: row.empresa || "",
    proyecto: row.nombre_proyecto || "",
    descripcion: row.descripcion_proyecto || "",
    // En Cuentas por pagar mostramos el estado operativo del pago. La aprobación
    // de la comisión se conserva aparte para auditoría, pero no se confunde con su pago.
    estado: paid ? "Pagada" : "Pendiente de pago",
    estatus: paid ? "Pagada" : "Pendiente de pago",
    estadoComision: commissionStatus,
    pendiente: paid ? "Sin pendientes" : "Pendiente de pago",
    diasPago: days,
    fechaPago,
    monto: netCommission,
    montoOriginal: grossCommission,
    montoComisionBruta: grossCommission,
    descuentoMonto: 0,
    descuentoDetalle: "",
    adeudoManualMonto: debtAmount,
    descuentoManualMonto: 0,
    descuentoManualDetalle: row.descuento_detalle || "",
    adeudoMonto: debtAmount,
    adeudoDetalle: row.adeudo_detalle || "",
    pagado: paid,
    lotePagoId: row.lote_pago_id || null,
    lotePagoFolio: row.lote_pago_folio || "",
    lotePagoPdfUrl: row.lote_pago_id ? `/api/commission-payment-batches/${Number(row.lote_pago_id)}/pdf` : "",
    createdAt: row.cuenta_created_at || row.commission_created_at,
    updatedAt: row.cuenta_updated_at || row.commission_updated_at,
    montoProyecto: Number(row.monto_proyecto || 0),
    porcentajeComision: Number(row.porcentaje_comision || 0),
    subtotal: grossCommission,
    iva: 0,
    retencion: 0,
    archivosNombres: row.archivos_pago_nombres || "",
    searchText: [
      row.occom_folio,
      row.presupuesto_folio,
      row.supervisor_nombre,
      row.empresa,
      row.nombre_proyecto,
      row.descripcion_proyecto,
      row.estado,
      row.pendiente,
      row.descuento_detalle,
      row.adeudo_detalle,
      row.archivos_pago_nombres
    ].join(" ")
  };
}

function getMonthRangeFromInput(monthInput = "") {
  const rawMonth = String(monthInput || "").trim();
  const now = new Date();
  const match = rawMonth.match(/^(\d{4})-(\d{2})$/);
  const year = match ? Number(match[1]) : now.getFullYear();
  const monthIndex = match ? Number(match[2]) - 1 : now.getMonth();
  const start = new Date(year, monthIndex, 1);
  const end = new Date(year, monthIndex + 1, 1);
  return { start, end };
}

function filterCommissionAccountsByMonth(accounts = [], monthInput = "") {
  const { start, end } = getMonthRangeFromInput(monthInput);
  return accounts.filter((account) => {
    // Una OCCOM pendiente pertenece al mes en que se generó. Una OCCOM ya
    // pagada debe consultarse por el mes de pago; de otro modo desaparece del
    // grupo al pagarla en un mes distinto al de su creación.
    const referenceDate = new Date(
      account.pagado
        ? account.fechaPago || account.updatedAt || account.createdAt || Date.now()
        : account.createdAt || account.updatedAt || Date.now()
    );
    const inSelectedMonth = referenceDate >= start && referenceDate < end;
    if (account.pagado) return inSelectedMonth;
    return inSelectedMonth || referenceDate < end;
  });
}

function getCommissionAccountMonthKey(account = {}) {
  const date = new Date(account.createdAt || account.updatedAt || Date.now());
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function applyCommissionDebtCarryover(accounts = []) {
  const normalizedAccounts = accounts.map((account) => ({ ...account }));
  const bySupervisor = new Map();
  normalizedAccounts.forEach((account) => {
    const key = getCommissionGroupSupervisorKey(account);
    if (!bySupervisor.has(key)) bySupervisor.set(key, []);
    bySupervisor.get(key).push(account);
  });

  bySupervisor.forEach((supervisorAccounts) => {
    const months = new Map();
    supervisorAccounts
      .sort((left, right) => new Date(left.createdAt || left.updatedAt || 0) - new Date(right.createdAt || right.updatedAt || 0))
      .forEach((account) => {
        const monthKey = getCommissionAccountMonthKey(account);
        if (!months.has(monthKey)) months.set(monthKey, []);
        months.get(monthKey).push(account);
      });

    let pendingDebt = 0;
    [...months.keys()].sort().forEach((monthKey) => {
      const monthAccounts = months.get(monthKey) || [];
      const manualDebt = monthAccounts.reduce((sum, account) => sum + Number(account.adeudoManualMonto || account.adeudoMonto || 0), 0);
      const totalDebtForMonth = Math.round((pendingDebt + manualDebt) * 100) / 100;
      const paidCommission = monthAccounts.reduce(
        (sum, account) => sum + (account.pagado ? Number(account.montoOriginal || account.subtotal || account.monto || 0) : 0),
        0
      );
      const remainingDebt = Math.max(Math.round((totalDebtForMonth - paidCommission) * 100) / 100, 0);
      let debtAssigned = false;

      monthAccounts.forEach((account) => {
        const gross = Number(account.montoOriginal || account.subtotal || account.monto || 0);
        if (!debtAssigned) {
          account.adeudoMonto = totalDebtForMonth;
          const detailParts = [
            pendingDebt > 0 ? `Adeudo pendiente anterior: ${formatCurrencyServer(pendingDebt)}` : "",
            account.adeudoDetalle,
            account.descuentoManualDetalle
          ].filter(Boolean);
          account.adeudoDetalle = detailParts.join(" | ");
          debtAssigned = true;
        } else {
          account.adeudoMonto = 0;
          account.adeudoDetalle = "";
        }
        account.descuentoMonto = 0;
        account.descuentoDetalle = "";
        account.monto = gross;
        account.adeudoPendiente = remainingDebt;
      });

      pendingDebt = remainingDebt;
    });
  });

  return normalizedAccounts;
}

async function filterCommissionAccountsForUser(
  accounts = [],
  user = null,
  modulePermission = "modulo:comisiones",
  operationPermission = ""
) {
  const scopedAccounts = filterOwnedRowsForUser(accounts, user, modulePermission);
  if (!operationPermission || !shouldRestrictToOwnedBudgets(user)) return scopedAccounts;
  const allowedAccounts = await Promise.all(
    scopedAccounts.map(async (account) =>
      (await canAccessBudget(
        user,
        account.presupuestoId,
        modulePermission,
        operationPermission
      ))
        ? account
        : null
    )
  );
  return allowedAccounts.filter(Boolean);
}

async function getAccountsPayableCommissionList(
  monthInput = "",
  user = null,
  modulePermission = "modulo:comisiones"
) {
  const rows = await getAccountsPayableCommissionRows();
  const allAccounts = applyCommissionDebtCarryover(rows.map(mapAccountsPayableCommissionRow));
  const accounts = await filterCommissionAccountsForUser(allAccounts, user, modulePermission);
  return groupAccountsPayableCommissionRows(filterCommissionAccountsByMonth(accounts, monthInput)).map((account) => ({
    ...account,
    monto: Number(account.montoOriginal ?? account.subtotal ?? account.monto ?? 0)
  }));
}

async function getAccountsPayableCommissionDetail(
  commissionId,
  monthInput = "",
  user = null,
  modulePermission = "modulo:comisiones",
  operationPermission = ""
) {
  if (String(commissionId || "").startsWith("group-")) {
    return getAccountsPayableCommissionGroupDetail(
      String(commissionId || ""),
      monthInput,
      user,
      modulePermission,
      operationPermission
    );
  }
  const rows = await getAccountsPayableCommissionRows();
  const filteredAccounts = await filterCommissionAccountsForUser(
    applyCommissionDebtCarryover(rows.map(mapAccountsPayableCommissionRow)),
    user,
    modulePermission,
    operationPermission
  );
  const account = filteredAccounts.find(
    (item) => Number(item.commissionId || 0) === Number(commissionId || 0)
  );
  if (!account) return null;
  account.monto = Math.max(
    Math.round((Number(account.montoOriginal || account.subtotal || account.monto || 0) - Number(account.adeudoMonto || 0)) * 100) / 100,
    0
  );
  const files = await getAccountsPayableFilesByCommission(commissionId);
  const supportDocuments = await getAccountsPayableSupportDocumentsByCommission(account);
  const discountHistory = await getAccountsPayableCommissionAdjustmentHistory(account.cuentaId ? [account.cuentaId] : []);
  const detail = applyCommissionHistoryDebtFallback({
    source: "OCCOM",
    account,
    order: {
      folio: account.occom,
      provider: {
        empresa: account.supervisor,
        condicionesPago: "Comisión",
        banco: account.banco || "",
        cuenta: account.cuenta || "",
        clabe: account.clabe || ""
      },
      subtotal: account.montoOriginal || account.subtotal || account.monto,
      discount: account.descuentoMonto || 0,
      discountDetail: account.descuentoDetalle || "",
      debt: account.adeudoMonto || 0,
      debtDetail: account.adeudoDetalle || "",
      iva: 0,
      retention: 0,
      totalPagar: account.monto,
      items: [
        {
          cantidad: 1,
          presupuesto: "Comisión",
          descripcion: `${account.proyecto} · ${account.folio}`,
          precioUnitario: account.montoOriginal || account.subtotal || account.monto,
          total: account.montoOriginal || account.subtotal || account.monto
        }
      ]
    },
    supportDocuments,
    discountHistory,
    files,
    fileTypes: ACCOUNTS_PAYABLE_FILE_TYPES,
    paymentTerms: "Comisión"
  });
  return enrichCommissionCreditApplication(detail);
}

function getCommissionGroupSupervisorKey(account = {}) {
  const rawKey = Number(account.supervisorId || 0) || `name-${account.supervisor || "sin-supervisor"}`;
  return String(rawKey)
    .replace(/[^a-zA-Z0-9_-]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "") || "sin-supervisor";
}

function groupAccountsPayableCommissionRows(accounts = []) {
  const groups = new Map();
  accounts.forEach((account) => {
    const paidKey = account.pagado ? "paid" : "pending";
    const supervisorKey = getCommissionGroupSupervisorKey(account);
    const key = `${supervisorKey}-${paidKey}`;
    const current =
      groups.get(key) ||
      {
        ...account,
        source: "OCCOM",
        orderId: `group-${supervisorKey}-${paidKey}`,
        commissionIds: [],
        cuentaIds: [],
        occomFolios: [],
        foliosPresupuesto: [],
        empresas: [],
        proyectos: [],
        lotePagoIds: [],
        lotePagoFolios: [],
        monto: 0,
        subtotal: 0,
        montoOriginal: 0,
        montoComisionBruta: 0,
        descuentoMonto: 0,
        descuentoDetalles: [],
        adeudoMonto: 0,
        adeudoDetalles: [],
        estado: account.pagado ? "OCCOM pagada" : "Aprobada",
        estatus: account.pagado ? "Pagada" : "Aprobada",
        pendiente: account.pagado ? "Sin pendientes" : "Pendiente de pago",
        createdAt: account.createdAt,
        updatedAt: account.updatedAt,
        searchText: ""
      };
    current.commissionIds.push(account.commissionId);
    if (account.cuentaId) current.cuentaIds.push(account.cuentaId);
    current.occomFolios.push(account.occom);
    current.foliosPresupuesto.push(account.folio);
    current.empresas.push(account.empresa);
    current.proyectos.push(account.proyecto);
    if (account.lotePagoId) current.lotePagoIds.push(Number(account.lotePagoId));
    if (account.lotePagoFolio) current.lotePagoFolios.push(account.lotePagoFolio);
    current.monto = Math.round(
      (Number(current.monto || 0) + Number(account.montoOriginal || account.subtotal || account.monto || 0)) * 100
    ) / 100;
    current.subtotal = Math.round((Number(current.subtotal || 0) + Number(account.montoOriginal || account.subtotal || account.monto || 0)) * 100) / 100;
    current.montoOriginal = current.subtotal;
    current.montoComisionBruta = current.subtotal;
    current.descuentoMonto = Math.round((Number(current.descuentoMonto || 0) + Number(account.descuentoMonto || 0)) * 100) / 100;
    current.adeudoMonto = Math.round((Number(current.adeudoMonto || 0) + Number(account.adeudoMonto || 0)) * 100) / 100;
    if (account.descuentoDetalle) current.descuentoDetalles.push(account.descuentoDetalle);
    if (account.adeudoDetalle) current.adeudoDetalles.push(account.adeudoDetalle);
    current.descuentoDetalle = [...new Set(current.descuentoDetalles.filter(Boolean))].join(" | ");
    current.adeudoDetalle = [...new Set(current.adeudoDetalles.filter(Boolean))].join(" | ");
    current.occom = `${current.commissionIds.length} OCCOM`;
    current.folio = [...new Set(current.foliosPresupuesto.filter(Boolean))].slice(0, 3).join(", ");
    current.empresa = [...new Set(current.empresas.filter(Boolean))].join(", ");
    current.proyecto = `${current.commissionIds.length} proyecto${current.commissionIds.length === 1 ? "" : "s"}`;
    current.updatedAt =
      new Date(account.updatedAt || 0).getTime() > new Date(current.updatedAt || 0).getTime() ? account.updatedAt : current.updatedAt;
    current.searchText = [
      current.searchText,
      account.searchText,
      account.occom,
      account.folio,
      account.proyecto,
      account.empresa
    ].join(" ");
    groups.set(key, current);
  });
  return [...groups.values()].map((group) => {
    const grossAmount = Math.round(Number(group.subtotal || group.monto || 0) * 100) / 100;
    const adjustment = Math.max(0, Number(group.adeudoMonto || 0));
    const netAmount = Math.max(Math.round((grossAmount - adjustment) * 100) / 100, 0);
    const batchIds = [...new Set(group.lotePagoIds.filter(Boolean))];
    const batchFolios = [...new Set(group.lotePagoFolios.filter(Boolean))];
    return {
      ...group,
      monto: netAmount,
      montoOriginal: grossAmount,
      montoComisionBruta: grossAmount,
      montoNetoPago: netAmount,
      lotePagoId: batchIds.length === 1 ? batchIds[0] : null,
      lotePagoFolio: batchFolios.length === 1 ? batchFolios[0] : batchFolios.join(", "),
      lotePagoPdfUrl: batchIds.length === 1 ? `/api/commission-payment-batches/${batchIds[0]}/pdf` : "",
      descuentoMonto: 0,
      descuentoDetalle: ""
    };
  });
}

function applyCommissionHistoryDebtFallback(detail) {
  if (!detail || detail.source !== "OCCOM") return detail;
  const history = Array.isArray(detail.discountHistory) ? detail.discountHistory : [];
  const latestDebtMovement = history.find((item) => Number(item.adeudoMonto || 0) > 0);
  if (!latestDebtMovement) return detail;

  const currentDebt = Number(detail.order?.debt || detail.account?.adeudoMonto || 0);
  if (currentDebt > 0) return detail;

  const debtAmount = Math.max(0, Number(latestDebtMovement.adeudoMonto || 0));
  const debtDetail = latestDebtMovement.adeudoDetalle || "";
  const grossTotal = Number(detail.order?.subtotal || detail.account?.subtotal || detail.account?.montoOriginal || 0);
  const retention = Number(detail.order?.retention || detail.account?.retencion || 0);
  const netTotal = Math.max(roundMoneyServer(grossTotal - debtAmount - retention), 0);

  detail.account = {
    ...detail.account,
    adeudoMonto: debtAmount,
    adeudoDetalle: debtDetail,
    monto: netTotal
  };
  detail.order = {
    ...detail.order,
    debt: debtAmount,
    debtDetail,
    totalPagar: netTotal
  };
  return detail;
}

async function getAccountsPayableCommissionGroupDetail(
  groupId,
  monthInput = "",
  user = null,
  modulePermission = "modulo:comisiones",
  operationPermission = ""
) {
  const match = String(groupId || "").match(/^group-(.+)-(pending|paid)$/);
  if (!match) return null;
  const supervisorKey = match[1];
  const paidKey = match[2];
  const rows = await getAccountsPayableCommissionRows();
  const allAccounts = await filterCommissionAccountsForUser(
    applyCommissionDebtCarryover(rows.map(mapAccountsPayableCommissionRow)),
    user,
    modulePermission,
    operationPermission
  );
  let accounts = filterCommissionAccountsByMonth(allAccounts, monthInput).filter(
    (accountItem) => {
      const accountSupervisorKey = getCommissionGroupSupervisorKey(accountItem);
      return accountSupervisorKey === supervisorKey && (accountItem.pagado ? "paid" : "pending") === paidKey;
    }
  );
  if (!accounts.length && paidKey === "pending") {
    return getAccountsPayableCommissionGroupDetail(
      `group-${supervisorKey}-paid`,
      monthInput,
      user,
      modulePermission,
      operationPermission
    );
  }
  if (!accounts.length) {
    // Compatibilidad con pestañas que aún tengan cargado el JS anterior y no
    // envíen commissionMonth. Sólo recuperamos el grupo si existe un único
    // periodo posible para evitar asociar el archivo a otra OCCOM histórica.
    const matchingAccounts = allAccounts.filter((accountItem) => {
      const accountSupervisorKey = getCommissionGroupSupervisorKey(accountItem);
      return accountSupervisorKey === supervisorKey && (accountItem.pagado ? "paid" : "pending") === paidKey;
    });
    const periodKeys = new Set(
      matchingAccounts.map((accountItem) => {
        const date = new Date(
          accountItem.pagado
            ? accountItem.fechaPago || accountItem.updatedAt || accountItem.createdAt || Date.now()
            : accountItem.createdAt || accountItem.updatedAt || Date.now()
        );
        return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
      })
    );
    if (matchingAccounts.length && periodKeys.size === 1) accounts = matchingAccounts;
  }
  if (!accounts.length) return null;

  const grouped = groupAccountsPayableCommissionRows(accounts)[0];
  const files = (await Promise.all(accounts.map((accountItem) => getAccountsPayableFilesByCommission(accountItem.commissionId)))).flat();
  const supportDocuments = await getAccountsPayableSupportDocumentsByCommissionAccounts(accounts);
  const discountHistory = await getAccountsPayableCommissionAdjustmentHistory(accounts.map((accountItem) => accountItem.cuentaId));
  const account = {
    ...grouped,
    commissionId: grouped.orderId,
    cuentaId: null
  };
  const orderItems = accounts.map((item) => ({
    cantidad: 1,
    presupuesto: "Comisión",
    descripcion: `${item.proyecto} · ${item.folio} · ${item.occom}`,
    precioUnitario: item.montoOriginal || item.subtotal || item.monto,
    total: item.montoOriginal || item.subtotal || item.monto
  }));
  const detail = applyCommissionHistoryDebtFallback({
    source: "OCCOM",
    account,
    order: {
      folio: account.occom,
      provider: {
        empresa: account.supervisor,
        condicionesPago: "Comisión",
        banco: account.banco || "",
        cuenta: account.cuenta || "",
        clabe: account.clabe || ""
      },
      subtotal: account.subtotal || account.monto,
      discount: account.descuentoMonto || 0,
      discountDetail: account.descuentoDetalle || "",
      debt: account.adeudoMonto || 0,
      debtDetail: account.adeudoDetalle || "",
      iva: 0,
      retention: 0,
      totalPagar: account.monto,
      items: orderItems
    },
    supportDocuments,
    discountHistory,
    files,
    fileTypes: ACCOUNTS_PAYABLE_FILE_TYPES,
    paymentTerms: "Comisión",
    groupedCommissions: accounts
  });
  return enrichCommissionCreditApplication(detail);
}

async function ensureAccountsPayableRecordsForCommissionReference(
  commissionRef,
  userId,
  monthInput = "",
  accessUser = null,
  modulePermission = "modulo:comisiones",
  operationPermission = ""
) {
  const ref = String(commissionRef || "");
  if (!ref) return [];
  if (!ref.startsWith("group-")) {
    const commissionId = Number(ref);
    if (!commissionId) return [];
    const detail = await getAccountsPayableCommissionDetail(
      commissionId,
      monthInput,
      accessUser,
      modulePermission,
      operationPermission
    );
    if (!detail) return [];
    const cuentaId = await ensureAccountsPayableRecordForCommission(commissionId, userId);
    return cuentaId ? [cuentaId] : [];
  }
  const detail = await getAccountsPayableCommissionDetail(
    ref,
    monthInput,
    accessUser,
    modulePermission,
    operationPermission
  );
  const accounts = detail?.groupedCommissions || [];
  const cuentaIds = [];
  for (const account of accounts) {
    const cuentaId = await ensureAccountsPayableRecordForCommission(account.commissionId, userId);
    if (cuentaId) cuentaIds.push(cuentaId);
  }
  return cuentaIds;
}

async function ensureAccountsPayableRecordForCommission(commissionId, userId) {
  const rows = await getAccountsPayableCommissionRows(commissionId);
  const account = rows[0] ? mapAccountsPayableCommissionRow(rows[0]) : null;
  if (!account) return null;
  if (account.cuentaId) return account.cuentaId;

  const [result] = await pool.execute(
    `INSERT INTO cuentas_por_pagar
      (tipo_origen, comision_id, presupuesto_id, estado, pendiente, dias_pago, fecha_pago, monto, usuario_id)
     VALUES ('OCCOM', ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      commissionId,
      account.presupuestoId,
      account.estado,
      account.pendiente,
      Number(account.diasPago || 0),
      null,
      account.monto,
      userId || null
    ]
  );
  return result.insertId;
}

async function getAccountsPayableFinancialSummary(cuentaId, connection = pool) {
  const [rows] = await connection.execute(
    `SELECT cp.*,
            COALESCE((
              SELECT SUM(op.monto)
              FROM ordenes_pago op
              WHERE op.cuenta_id = cp.id
                AND op.estado_movimiento = 'Aplicado'
            ), 0) AS total_pagado,
            COALESCE((
              SELECT COUNT(*)
              FROM ordenes_pago op
              WHERE op.cuenta_id = cp.id
            ), 0) AS movimientos_registrados
     FROM cuentas_por_pagar cp
     WHERE cp.id = ?
     LIMIT 1`,
    [cuentaId]
  );
  const account = rows[0];
  if (!account) return null;

  let calculatedTotal = Number(account.monto || 0);
  if (!account.monto_manual) {
    if (account.tipo_origen === "OCGF" && account.ocgf_orden_id) {
      const [totals] = await connection.execute(
        `SELECT GREATEST(
                  0,
                  COALESCE(SUM(p.total), 0) * CASE WHEN MAX(o.sin_iva) = 1 THEN 1 ELSE 1.16 END
                  - CASE WHEN MAX(o.retencion_activa) = 1 THEN COALESCE(MAX(o.retencion_monto), 0) ELSE 0 END
                ) AS total
         FROM ocgf_ordenes o
         LEFT JOIN ocgf_orden_partidas p ON p.orden_id = o.id
         WHERE o.id = ?`,
        [account.ocgf_orden_id]
      );
      calculatedTotal = Number(totals[0]?.total || calculatedTotal || 0);
    } else if (account.tipo_origen === "OCCOM" && account.comision_id) {
      const [totals] = await connection.execute(
        `SELECT GREATEST(0, COALESCE(c.monto_comision, 0) - COALESCE(cp.adeudo_monto, 0)) AS total
         FROM cuentas_por_pagar cp
         LEFT JOIN comisiones c ON c.id = cp.comision_id
         WHERE cp.id = ?
         LIMIT 1`,
        [cuentaId]
      );
      calculatedTotal = Number(totals[0]?.total || calculatedTotal || 0);
    } else if (account.ocp_id) {
      const [totals] = await connection.execute(
        `SELECT GREATEST(
                  0,
                  COALESCE(SUM(p.total), 0) * 1.16
                  - CASE WHEN MAX(o.retencion_activa) = 1 THEN COALESCE(MAX(o.retencion_monto), 0) ELSE 0 END
                ) AS total
         FROM ocp_proveedor o
         LEFT JOIN ocp_proveedor_partidas p ON p.ocp_id = o.id
         WHERE o.id = ?`,
        [account.ocp_id]
      );
      calculatedTotal = Number(totals[0]?.total || calculatedTotal || 0);
    }
    calculatedTotal = Math.max(0, Math.round(calculatedTotal * 100) / 100);
    if (Math.abs(calculatedTotal - Number(account.monto || 0)) > 0.004) {
      await connection.execute("UPDATE cuentas_por_pagar SET monto = ? WHERE id = ?", [calculatedTotal, cuentaId]);
      account.monto = calculatedTotal;
    }
  }

  const legacyPaid = Boolean(account.pagado) && Number(account.movimientos_registrados || 0) === 0;
  const summary = payableSummary(calculatedTotal, account.total_pagado, legacyPaid);
  return { account, ...summary };
}

async function getAccountsPayableConfiguredDays(cuentaId, connection = pool) {
  const [accounts] = await connection.execute(
    "SELECT tipo_origen, ocp_id, ocgf_orden_id, dias_pago FROM cuentas_por_pagar WHERE id = ? LIMIT 1",
    [cuentaId]
  );
  const account = accounts[0];
  if (!account) return 0;

  if (account.tipo_origen === "OCGF" && account.ocgf_orden_id) {
    const [rows] = await connection.execute(
      `SELECT COALESCE(NULLIF(pr.condiciones_pago, ''), '') AS condiciones_pago,
              COALESCE(pr.dias_credito, 30) AS dias_credito
       FROM ocgf_ordenes o
       INNER JOIN ocgf_compras g ON g.id = o.ocgf_id
       LEFT JOIN proveedores pr ON pr.id = g.proveedor_id
          OR (g.proveedor_id IS NULL AND pr.empresa COLLATE utf8mb4_unicode_ci = g.proveedor_nombre COLLATE utf8mb4_unicode_ci)
       WHERE o.id = ?
       LIMIT 1`,
      [account.ocgf_orden_id]
    );
    return paymentDaysFromTerms(rows[0]?.condiciones_pago, rows[0]?.dias_credito, 30);
  }

  if ((!account.tipo_origen || account.tipo_origen === "OCP") && account.ocp_id) {
    const [rows] = await connection.execute(
      `SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(pr.condiciones_pago, ''), '') SEPARATOR ', ') AS condiciones_pago,
              MAX(CASE WHEN LOWER(COALESCE(pr.condiciones_pago, '')) = 'credito' THEN COALESCE(pr.dias_credito, 30) ELSE 0 END) AS dias_credito
       FROM ocp_proveedor_partidas op
       LEFT JOIN proveedores pr ON pr.id = op.proveedor_id
          OR (op.proveedor_id IS NULL AND pr.empresa COLLATE utf8mb4_unicode_ci = op.proveedor_nombre COLLATE utf8mb4_unicode_ci)
       WHERE op.ocp_id = ?`,
      [account.ocp_id]
    );
    return paymentDaysFromTerms(rows[0]?.condiciones_pago, rows[0]?.dias_credito, 30);
  }

  return Math.max(0, Number(account.dias_pago || 0));
}

async function refreshAccountsPayableStatus(cuentaId, connection = pool) {
  const financial = await getAccountsPayableFinancialSummary(cuentaId, connection);
  if (!financial) return null;
  const account = financial.account;
  const files =
    account.tipo_origen === "OCGF"
      ? await getAccountsPayableFilesByOcgfOrder(account.ocgf_orden_id)
      : account.tipo_origen === "OCCOM"
        ? await getAccountsPayableFilesByCommission(account.comision_id)
        : await getAccountsPayableFilesByOrder(account.ocp_id);
  const document = paymentDocumentStatus(files);
  const factura = files
    .filter((file) => file.tipo === "Factura")
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))[0];
  const configuredDays = await getAccountsPayableConfiguredDays(cuentaId, connection);
  const dueDate = factura ? addDays(factura.createdAt, configuredDays) : null;
  const fechaPago = financial.paid ? account.fecha_pago || businessDateOnly() : dueDate;
  const estadoRegistro = financial.paid ? "Cerrada" : "Activa";
  const pendiente = financial.paid
    ? document.status === "Completa" ? "Sin pendientes" : document.pending
    : financial.applied > 0
      ? document.status === "Completa"
        ? "Documentación del pago completa"
        : document.pending
      : document.status === "Factura pendiente"
        ? document.pending
        : "Registrar abono";

  await connection.execute(
    `UPDATE cuentas_por_pagar
     SET estado = ?, pendiente = ?, dias_pago = ?, fecha_pago = ?, pagado = ?,
         estado_registro = ?, estatus_pago = ?, estatus_documentacion = ?
     WHERE id = ?`,
    [
      financial.paymentStatus,
      pendiente,
      configuredDays,
      fechaPago,
      financial.paid ? 1 : 0,
      estadoRegistro,
      financial.paymentStatus,
      document.status,
      cuentaId
    ]
  );
  return { ...financial, estadoRegistro, pendiente, estatusDocumentacion: document.status, fechaPago };
}

async function createAccountsPayableMovement({
  cuentaId,
  monto,
  tipoMovimiento,
  estadoMovimiento = "Aplicado",
  metodoPago = "",
  referencia = "",
  observaciones = "",
  userId = null
}) {
  const amount = Math.round(Number(monto || 0) * 100) / 100;
  if (!Number.isFinite(amount) || amount <= 0) throw new Error("Ingresa un monto válido para el movimiento.");
  if (!PAYMENT_MOVEMENT_STATUSES.includes(estadoMovimiento)) throw new Error("El estado del movimiento no es válido.");

  const connection = await pool.getConnection();
  let folioLockAcquired = false;
  let movementId = null;
  let account = null;
  try {
    const [lockRows] = await connection.query("SELECT GET_LOCK('dalvo_payment_order_folio', 10) AS acquired");
    folioLockAcquired = Number(lockRows[0]?.acquired || 0) === 1;
    if (!folioLockAcquired) throw new Error("No se pudo reservar el folio del movimiento de pago.");

    await connection.beginTransaction();
    const [accountRows] = await connection.execute(
      "SELECT id FROM cuentas_por_pagar WHERE id = ? FOR UPDATE",
      [cuentaId]
    );
    if (!accountRows.length) throw new Error("Cuenta por pagar no encontrada.");

    const financial = await getAccountsPayableFinancialSummary(cuentaId, connection);
    if (!financial) throw new Error("Cuenta por pagar no encontrada.");
    if (amount > financial.remaining + 0.005) {
      throw new Error(`El movimiento excede el saldo restante de ${formatCurrencyServer(financial.remaining)}.`);
    }

    account = financial.account;
    const movementType = normalizePaymentMovementType(tipoMovimiento, financial.remaining);
    const folio = await generatePaymentOrderFolio(connection);
    const [result] = await connection.execute(
      `INSERT INTO ordenes_pago
        (cuenta_id, tipo_origen, ocp_id, ocgf_orden_id, folio, monto,
         tipo_movimiento, estado_movimiento, fecha_aplicacion, metodo_pago,
         referencia, observaciones, usuario_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        cuentaId,
        account.tipo_origen || "OCP",
        account.ocp_id || null,
        account.ocgf_orden_id || null,
        folio,
        amount,
        movementType,
        estadoMovimiento,
        estadoMovimiento === "Aplicado" ? businessDateOnly() : null,
        String(metodoPago || "").trim(),
        String(referencia || "").trim(),
        String(observaciones || "").trim(),
        userId || null
      ]
    );
    movementId = result.insertId;
    await connection.commit();
  } catch (error) {
    try {
      await connection.rollback();
    } catch (_rollbackError) {
      // La transacción puede no haberse iniciado si falló la reserva del folio.
    }
    throw error;
  } finally {
    if (folioLockAcquired) {
      try {
        await connection.query("SELECT RELEASE_LOCK('dalvo_payment_order_folio')");
      } catch (releaseError) {
        logServerError("payment-order-lock-release", releaseError);
      }
    }
    connection.release();
  }

  if (movementId && (account?.tipo_origen === "OCP" || account?.tipo_origen === "OCGF")) {
    try {
      await generatePaymentOrderPdf(movementId);
    } catch (error) {
      logServerError(`payment-order-pdf-${movementId}`, error);
    }
  }
  await refreshAccountsPayableStatus(cuentaId);
  return movementId;
}

async function markAccountsPayableRecordPaid(cuentaId, userId = null) {
  if (!cuentaId) return null;
  const financial = await getAccountsPayableFinancialSummary(cuentaId);
  if (!financial) return null;
  if (financial.remaining > 0.005) {
    await createAccountsPayableMovement({
      cuentaId,
      monto: financial.remaining,
      tipoMovimiento: "Abono",
      estadoMovimiento: "Aplicado",
      observaciones: "Abono del saldo restante",
      userId
    });
  } else {
    await refreshAccountsPayableStatus(cuentaId);
  }
  return getAccountsPayableFinancialSummary(cuentaId);
}

function commissionPaymentPdfRelativePath(account, scopeSuffix = "") {
  const safeFolio = String(account.orderId?.startsWith?.("group-") ? account.orderId : account.occom || `OCCOM-${account.commissionId}`)
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  const safeScopeSuffix = String(scopeSuffix || "")
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return path
    .join("uploads", "ordenes_pago_comisiones", `${safeFolio}${safeScopeSuffix ? `-${safeScopeSuffix}` : ""}.pdf`)
    .replace(/\\/g, "/");
}

async function generateCommissionPaymentPdf(
  commissionId,
  monthInput = "",
  user = null,
  modulePermission = "modulo:comisiones"
) {
  const detail = await getAccountsPayableCommissionDetail(
    commissionId,
    monthInput,
    user,
    modulePermission
  );
  if (!detail) throw new Error("Comisión no encontrada.");
  const account = detail.account;
  const scopeSuffix = String(commissionId || "").startsWith("group-") && shouldRestrictToOwnedBudgets(user)
    ? `u${Number(user?.id || 0)}`
    : "";
  const relativePath = commissionPaymentPdfRelativePath(account, scopeSuffix);
  const absolutePath = path.join(__dirname, relativePath);
  await fs.promises.mkdir(path.dirname(absolutePath), { recursive: true });

  await new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: "LETTER",
      margin: 36,
      bufferPages: true,
      info: {
        Title: `Orden de pago de comisiones ${account.occom}`,
        Author: "DALVO SOLUTIONS SA DE CV"
      }
    });
    const stream = fs.createWriteStream(absolutePath);
    stream.on("finish", resolve);
    stream.on("error", reject);
    doc.on("error", reject);
    doc.pipe(stream);

    const summarizeList = (value, maxItems = 3) => {
      const items = String(value || "")
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean);
      const uniqueItems = [...new Set(items)];
      if (!uniqueItems.length) return "Sin dato";
      if (uniqueItems.length <= maxItems) return uniqueItems.join(", ");
      return `${uniqueItems.slice(0, maxItems).join(", ")} y ${uniqueItems.length - maxItems} más`;
    };
    const drawCommissionTableHeader = (y) => {
      doc.rect(36, y, 520, 20).fill("#273142");
      doc.fillColor("#ffffff").font("Helvetica-Bold").fontSize(7);
      doc.text("Cantidad", 46, y + 7, { width: 50 });
      doc.text("Folio", 104, y + 7, { width: 80 });
      doc.text("Proyecto", 190, y + 7, { width: 180 });
      doc.text("% Comisión", 390, y + 7, { width: 70, align: "right" });
      doc.text("Subtotal", 470, y + 7, { width: 70, align: "right" });
      doc.fillColor("#071225").font("Helvetica").fontSize(8);
      return y + 20;
    };

    if (fs.existsSync(DALVO_QUOTE_LOGO)) doc.image(DALVO_QUOTE_LOGO, 36, 34, { width: 150 });
    doc.fillColor("#071225").font("Helvetica-Bold").fontSize(14).text("Orden de pago de comisiones", 320, 42, {
      width: 220,
      align: "right"
    });
    doc.font("Helvetica-Bold").fontSize(9).text(account.supervisor || "", 320, 64, { width: 220, align: "right" });
    doc.font("Helvetica").fontSize(9).text(`Folio ${account.occom}`, 320, 92, { width: 220, align: "right" });
    doc.text(`Fecha: ${new Intl.DateTimeFormat("es-MX", { day: "numeric", month: "numeric", year: "numeric" }).format(new Date())}`, 320, 106, {
      width: 220,
      align: "right"
    });

    doc.font("Helvetica-Bold").fontSize(11).text("DATOS DE LA ORDEN", 36, 150).moveTo(36, 164).lineTo(170, 164).stroke();
    doc.font("Helvetica-Bold").fontSize(8).text("Empresa emisora", 36, 184);
    doc.font("Helvetica").fontSize(8).text("DALVO SOLUTIONS SA DE CV", 36, 198);
    doc.text("RFC: DSO250131KZ9", 36, 211);
    doc.text(`Presupuesto: ${account.folio}`, 36, 224);
    doc.text(`OCCOM: ${account.occom}`, 36, 237);

    doc.font("Helvetica-Bold").fontSize(8).text("Supervisor", 350, 184, { width: 190, align: "right" });
    doc.font("Helvetica").fontSize(8).text(`Nombre: ${account.supervisor}`, 270, 198, { width: 270, align: "right" });
    doc.text(`Empresa cliente: ${summarizeList(account.empresa)}`, 270, 211, { width: 270, align: "right" });
    doc.text(`Proyecto: ${account.orderId?.startsWith?.("group-") ? `${detail.order?.items?.length || 0} proyectos` : account.proyecto}`, 270, 224, {
      width: 270,
      align: "right"
    });

    doc.font("Helvetica-Bold").fontSize(11).text("DETALLE DE COMISIÓN", 36, 282).moveTo(36, 296).lineTo(190, 296).stroke();
    const tableY = 312;
    const detailRows = detail.order?.items?.length
      ? detail.order.items
      : [
          {
            cantidad: 1,
            descripcion: `${account.proyecto || ""} · ${account.folio || ""}`,
            precioUnitario: account.monto,
            total: account.monto
          }
        ];
    let rowY = drawCommissionTableHeader(tableY);
    const bottomLimit = 700;
    detailRows.forEach((item, index) => {
      const descriptionText = String(item.descripcion || account.proyecto || "");
      const rowHeight = Math.max(28, doc.heightOfString(descriptionText, { width: 180 }) + 14);
      if (rowY + rowHeight > bottomLimit) {
        doc.addPage();
        doc.font("Helvetica-Bold").fontSize(11).fillColor("#071225").text("DETALLE DE COMISIÓN", 36, 54);
        rowY = drawCommissionTableHeader(76);
      }
      doc.rect(36, rowY, 520, rowHeight).strokeColor("#e3edf2").stroke();
      doc.fillColor("#071225").font("Helvetica").fontSize(8);
      doc.text(String(item.cantidad || 1), 46, rowY + 9, { width: 50 });
      doc.text(
        index === 0 && !account.orderId?.startsWith?.("group-")
          ? account.folio || ""
          : String(item.descripcion || "").split(" · ").slice(-2, -1)[0] || account.folio || "",
        104,
        rowY + 9,
        { width: 80 }
      );
      doc.text(descriptionText, 190, rowY + 7, { width: 180 });
      doc.text(`${Number(account.porcentajeComision || 0).toFixed(2)}%`, 390, rowY + 9, { width: 70, align: "right" });
      doc.text(formatCurrencyServer(item.total || item.precioUnitario || 0), 470, rowY + 9, { width: 70, align: "right" });
      rowY += rowHeight;
    });
    if (rowY + 96 > bottomLimit) {
      doc.addPage();
      rowY = 54;
    }
    const grossTotal = Number(detail.order?.subtotal || account.subtotal || account.montoOriginal || account.monto || 0);
    const debtAmount = Math.max(0, Number(detail.order?.debt || account.adeudoMonto || 0));
    const debtDetail = String(detail.order?.debtDetail || account.adeudoDetalle || "").trim();
    const retentionAmount = Math.max(0, Number(detail.order?.retention || account.retencion || 0));
    // La comisión se almacena sin IVA. Primero se descuenta el préstamo/adeudo,
    // después se calcula el IVA sobre el subtotal resultante y finalmente se aplican retenciones.
    const netSubtotal = Math.max(Math.round((grossTotal - debtAmount) * 100) / 100, 0);
    const netIva = Math.round(netSubtotal * 0.16 * 100) / 100;
    const netTotal = Math.max(Math.round((netSubtotal + netIva - retentionAmount) * 100) / 100, 0);
    let totalsY = rowY + 18;
    const ensureCommissionPdfSpace = (height = 16) => {
      if (totalsY + height > bottomLimit) {
        doc.addPage();
        totalsY = 54;
      }
    };
    const adjustmentHistory = Array.isArray(detail.discountHistory) ? detail.discountHistory : [];
    if (adjustmentHistory.length) {
      ensureCommissionPdfSpace(28);
      doc.font("Helvetica-Bold").fontSize(9).fillColor("#071225").text("HISTORIAL DE ADEUDOS Y DESCUENTOS", 36, totalsY);
      totalsY += 16;
      adjustmentHistory.slice(0, 8).forEach((item) => {
        const historyDate = new Intl.DateTimeFormat("es-MX", { day: "2-digit", month: "2-digit", year: "numeric" }).format(
          new Date(item.createdAt || Date.now())
        );
        const detailText = [item.adeudoDetalle ? `Adeudo: ${item.adeudoDetalle}` : "", item.descuentoDetalle ? `Descuento: ${item.descuentoDetalle}` : ""]
          .filter(Boolean)
          .join(" | ");
        const line = `${historyDate} · Adeudo ${formatCurrencyServer(item.adeudoMonto || 0)} · Descuento ${formatCurrencyServer(
          item.descuentoMonto || 0
        )} · ${detailText || "Sin detalle"}`;
        const lineHeight = doc.heightOfString(line, { width: 520 });
        ensureCommissionPdfSpace(lineHeight + 5);
        doc.font("Helvetica").fontSize(7).fillColor("#071225").text(line, 36, totalsY, { width: 520 });
        totalsY += lineHeight + 5;
      });
      if (adjustmentHistory.length > 8) {
        ensureCommissionPdfSpace(12);
        doc.font("Helvetica").fontSize(7).text(`+ ${adjustmentHistory.length - 8} movimientos adicionales`, 36, totalsY, { width: 520 });
        totalsY += 12;
      }
    }
    const totals = [
      ["Comisión", grossTotal],
      ["Adeudo", debtAmount],
      ["Subtotal", netSubtotal],
      ["I.V.A. 16%", netIva],
      ["Retenciones", retentionAmount],
      ["Total", netTotal]
    ];
    totals.forEach(([label, value]) => {
      ensureCommissionPdfSpace(13);
      doc
        .font(label === "Total" ? "Helvetica-Bold" : "Helvetica")
        .fontSize(label === "Total" ? 10 : 8)
        .text(`${label}: ${formatCurrencyServer(value)}`, 320, totalsY, { width: 220, align: "right" });
      totalsY += 13;
    });
    ensureCommissionPdfSpace(14);
    doc.font("Helvetica-Bold").fontSize(9).text(`Folio ${account.occom}`, 165, totalsY - 13, { width: 150, align: "center" });

    const pageRange = doc.bufferedPageRange();
    for (let index = 0; index < pageRange.count; index += 1) {
      doc.switchToPage(pageRange.start + index);
      drawQuoteFooter(doc, index + 1, pageRange.count);
    }
    doc.end();
  });

  if (!String(commissionId || "").startsWith("group-")) {
    await pool.execute("UPDATE comisiones SET pdf_ruta = ? WHERE id = ?", [relativePath, commissionId]);
  }
  return relativePath;
}

function commissionPaymentBatchPdfRelativePath(batch = {}) {
  const safeFolio = String(batch.folio || `lote_${batch.id || Date.now()}`)
    .replace(/[^a-zA-Z0-9._-]/g, "_");
  return path.join("uploads", "lotes_pago_comisiones", `${safeFolio}.pdf`).replace(/\\/g, "/");
}

async function generateCommissionPaymentBatchFolio(connection = pool) {
  const yearSuffix = String(businessDateOnly() || new Date().getFullYear()).slice(2, 4);
  const prefix = `OCPG${yearSuffix}`;
  const [rows] = await connection.execute(
    `SELECT MAX(CAST(SUBSTRING(folio, ?) AS UNSIGNED)) AS last_number
     FROM lotes_pago_comisiones
     WHERE folio LIKE ?`,
    [prefix.length + 1, `${prefix}%`]
  );
  return `${prefix}${String(Number(rows[0]?.last_number || 0) + 1).padStart(4, "0")}`;
}

async function getCommissionPaymentBatch(batchId, connection = pool) {
  const [batchRows] = await connection.execute(
    `SELECT id, folio, estado, modo_agrupacion, total, fecha_pago, pdf_ruta,
            usuario_id, created_at, updated_at
     FROM lotes_pago_comisiones
     WHERE id = ?
     LIMIT 1`,
    [batchId]
  );
  if (!batchRows.length) return null;
  const [items] = await connection.execute(
    `SELECT id, lote_id, cuenta_id, tipo_origen, ocp_id, ocgf_order_id, comision_id, movimiento_id, supervisor_id,
            supervisor_nombre, empresa, proyecto, folio_presupuesto, folio_occom,
            monto_bruto, adeudo_monto, monto_pagado, created_at
     FROM lotes_pago_comisiones_items
     WHERE lote_id = ?
     ORDER BY supervisor_nombre, proyecto, id`,
    [batchId]
  );
  const batch = batchRows[0];
  return {
    id: Number(batch.id),
    folio: batch.folio || "",
    estado: batch.estado || "Pagado",
    modoAgrupacion: batch.modo_agrupacion || "persona",
    total: Number(batch.total || 0),
    fechaPago: batch.fecha_pago,
    pdfRuta: batch.pdf_ruta || "",
    pdfUrl: `/api/commission-payment-batches/${Number(batch.id)}/pdf`,
    createdAt: batch.created_at,
    updatedAt: batch.updated_at,
    items: items.map((item) => ({
      id: Number(item.id),
      cuentaId: Number(item.cuenta_id),
      source: item.tipo_origen || (item.ocp_id ? "OCP" : item.ocgf_order_id ? "OCGF" : "OCCOM"),
      entityId: Number(item.ocp_id || item.ocgf_order_id || item.comision_id),
      orderId: Number(item.ocp_id || 0) || null,
      ocgfOrderId: Number(item.ocgf_order_id || 0) || null,
      commissionId: Number(item.comision_id || 0) || null,
      movimientoId: Number(item.movimiento_id || 0) || null,
      supervisorId: Number(item.supervisor_id || 0) || null,
      supervisor: item.supervisor_nombre || "Sin supervisor",
      empresa: item.empresa || "",
      proyecto: item.proyecto || "",
      folio: item.folio_presupuesto || "",
      occom: item.folio_occom || "",
      documento: item.folio_occom || "",
      montoBruto: Number(item.monto_bruto || 0),
      adeudoMonto: Number(item.adeudo_monto || 0),
      montoPagado: Number(item.monto_pagado || 0)
    }))
  };
}

async function generateCommissionPaymentBatchPdf(batchId) {
  const batch = await getCommissionPaymentBatch(batchId);
  if (!batch) throw new Error("Lote de pago no encontrado.");
  const relativePath = commissionPaymentBatchPdfRelativePath(batch);
  const absolutePath = path.join(__dirname, relativePath);
  await fs.promises.mkdir(path.dirname(absolutePath), { recursive: true });

  await new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: "LETTER",
      margin: 36,
      bufferPages: true,
      info: { Title: `Orden de compra general ${batch.folio}`, Author: "DALVO SOLUTIONS SA DE CV" }
    });
    const stream = fs.createWriteStream(absolutePath);
    stream.on("finish", resolve);
    stream.on("error", reject);
    doc.on("error", reject);
    doc.pipe(stream);

    const isPaid = String(batch.estado || "").toLowerCase() === "pagado";
    const paymentDate = batch.fechaPago instanceof Date
      ? batch.fechaPago
      : new Date(`${String(batch.fechaPago || "").slice(0, 10)}T12:00:00`);
    const dateText = new Intl.DateTimeFormat("es-MX", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric"
    }).format(Number.isNaN(paymentDate.getTime()) ? new Date() : paymentDate);
    const groupField = batch.modoAgrupacion === "proyecto" ? "proyecto" : "supervisor";
    const groups = new Map();
    batch.items.forEach((item) => {
      const label = String(item[groupField] || (groupField === "proyecto" ? "Sin proyecto" : "Sin supervisor"));
      if (!groups.has(label)) groups.set(label, []);
      groups.get(label).push(item);
    });

    const drawHeader = () => {
      if (fs.existsSync(DALVO_QUOTE_LOGO)) doc.image(DALVO_QUOTE_LOGO, 36, 32, { width: 145 });
      doc.fillColor("#071225").font("Helvetica-Bold").fontSize(16).text("Orden de compra general", 265, 42, {
        width: 290,
        align: "right"
      });
      doc.fontSize(11).text(batch.folio, 285, 68, { width: 270, align: "right" });
      doc.font("Helvetica").fontSize(9).text(`${isPaid ? "Fecha de pago" : "Fecha de creación"}: ${dateText}`, 285, 86, { width: 270, align: "right" });
      doc.font("Helvetica-Bold").fontSize(8).text(isPaid ? "PAGADA" : "PENDIENTE DE PAGO", 405, 102, { width: 150, align: "right" });
    };
    const drawTableHeader = (y) => {
      doc.rect(36, y, 520, 22).fill("#273142");
      doc.fillColor("#fff").font("Helvetica-Bold").fontSize(7);
      doc.text("Persona", 44, y + 8, { width: 100 });
      doc.text("Documento", 148, y + 8, { width: 72 });
      doc.text("Proyecto", 224, y + 8, { width: 170 });
      doc.text("Empresa", 398, y + 8, { width: 80 });
      doc.text("Pago", 482, y + 8, { width: 66, align: "right" });
      return y + 22;
    };
    const ensureSpace = (height, currentY) => {
      if (currentY + height <= 690) return currentY;
      doc.addPage();
      drawHeader();
      return 126;
    };

    drawHeader();
    doc.font("Helvetica").fontSize(9).text(
      `${batch.items.length} pago${batch.items.length === 1 ? "" : "s"} · ${groups.size} ${groupField === "proyecto" ? "proyecto(s)" : "persona(s)"}`,
      36,
      116,
      { width: 520 }
    );
    let y = 146;
    for (const [label, items] of groups.entries()) {
      y = ensureSpace(62, y);
      const groupTotal = items.reduce((sum, item) => sum + Number(item.montoPagado || 0), 0);
      doc.fillColor("#071225").font("Helvetica-Bold").fontSize(10).text(label, 36, y, { width: 390 });
      doc.text(formatCurrencyServer(groupTotal), 438, y, { width: 118, align: "right" });
      y = drawTableHeader(y + 18);
      for (const item of items) {
        const descriptionHeight = doc.heightOfString(item.proyecto || "Sin proyecto", { width: 170 });
        const rowHeight = Math.max(30, descriptionHeight + 12);
        y = ensureSpace(rowHeight + 4, y);
        if (y === 126) y = drawTableHeader(y);
        doc.rect(36, y, 520, rowHeight).strokeColor("#dbe4ea").lineWidth(0.5).stroke();
        doc.fillColor("#071225").font("Helvetica").fontSize(7.5);
        doc.text(item.supervisor, 44, y + 8, { width: 100 });
        doc.text(item.documento || item.occom, 148, y + 8, { width: 72 });
        doc.text(item.proyecto || item.folio, 224, y + 8, { width: 170 });
        doc.text(item.empresa, 398, y + 8, { width: 80 });
        doc.text(formatCurrencyServer(item.montoPagado), 482, y + 8, { width: 66, align: "right" });
        y += rowHeight;
      }
      y += 16;
    }
    y = ensureSpace(46, y);
    doc.fillColor("#071225").font("Helvetica-Bold").fontSize(13).text(isPaid ? "TOTAL PAGADO" : "TOTAL A PAGAR", 330, y, { width: 120, align: "right" });
    doc.text(formatCurrencyServer(batch.total), 460, y, { width: 96, align: "right" });

    const pageRange = doc.bufferedPageRange();
    for (let index = 0; index < pageRange.count; index += 1) {
      doc.switchToPage(pageRange.start + index);
      drawQuoteFooter(doc, index + 1, pageRange.count);
    }
    doc.end();
  });
  await pool.execute("UPDATE lotes_pago_comisiones SET pdf_ruta = ? WHERE id = ?", [relativePath, batchId]);
  return relativePath;
}

function filterPendingPayablesByMonth(accounts = [], monthInput = "") {
  const match = String(monthInput || "").match(/^(\d{4})-(\d{2})$/);
  if (!match) return accounts;
  const start = new Date(Number(match[1]), Number(match[2]) - 1, 1).getTime();
  const end = new Date(Number(match[1]), Number(match[2]), 1).getTime();
  return accounts.filter((account) => {
    const time = new Date(account.createdAt || account.fecha || account.updatedAt || 0).getTime();
    return Number.isFinite(time) && time >= start && time < end;
  });
}

async function getPendingCommissionPaymentBatchLinks() {
  const [rows] = await pool.execute(
    `SELECT lpi.tipo_origen,
            CASE
              WHEN lpi.tipo_origen = 'OCP' THEN lpi.ocp_id
              WHEN lpi.tipo_origen = 'OCGF' THEN lpi.ocgf_order_id
              ELSE lpi.comision_id
            END AS entity_id,
            lp.id AS batch_id, lp.folio, lp.estado, lp.total, lp.created_at,
            (SELECT COUNT(*) FROM lotes_pago_comisiones_items grouped WHERE grouped.lote_id = lp.id) AS item_count
     FROM lotes_pago_comisiones_items lpi
     INNER JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id
     WHERE lp.estado = 'Pendiente'`
  );
  return new Map(rows.map((row) => {
    const source = String(row.tipo_origen || "OCCOM").toUpperCase();
    const entityId = Number(row.entity_id || 0);
    return [`${source}:${entityId}`, {
      id: Number(row.batch_id),
      folio: row.folio || `OCP general ${row.batch_id}`,
      estado: row.estado || "Pendiente",
      total: Number(row.total || 0),
      itemCount: Number(row.item_count || 0),
      createdAt: row.created_at,
      previewUrl: `/api/commission-payment-batches/${Number(row.batch_id)}/preview`
    }];
  }));
}

async function getCommissionPaymentBatchCandidates(monthInput = "", user = null) {
  // Las OCP pendientes no están ligadas al periodo de las comisiones. Deben
  // coincidir con el universo visible en la tabla principal de Cuentas por pagar.
  const ocpAccounts = filterOwnedRowsForUser(
    await getAccountsPayableList(),
    user,
    "modulo:cuentas-pagar"
  )
    .filter((account) => !account.pagado && !account.lotePagoId && Number(account.saldoRestante || 0) > 0.005)
    .map((account) => ({
      ...account,
      source: "OCP",
      entityId: Number(account.orderId),
      person: account.proveedor || "Sin proveedor",
      supervisor: account.proveedor || "Sin proveedor",
      documento: account.ocp || "",
      monto: Number(account.saldoRestante || 0),
      montoOriginal: Number(account.montoTotal || account.monto || 0)
    }));

  const ocgfAccounts = (shouldRestrictToOwnedBudgets(user) ? [] : await getAccountsPayableFixedExpenseRows())
    .filter((account) => !account.pagado && !account.lotePagoId && Number(account.saldoRestante || 0) > 0.005)
    .map((account) => ({
      ...account,
      source: "OCGF",
      entityId: Number(account.orderId),
      person: account.proveedor || "Sin proveedor",
      supervisor: account.proveedor || "Sin proveedor",
      documento: account.ocgf || "",
      proyecto: account.gasto || "Gasto fijo",
      empresa: account.sucursal || "",
      monto: Number(account.saldoRestante || 0),
      montoOriginal: Number(account.montoTotal || account.monto || 0)
    }));

  let commissionAccounts = [];
  if (canManageCommissions(user)) {
    const rows = await getAccountsPayableCommissionRows();
    const accounts = await filterCommissionAccountsForUser(
      applyCommissionDebtCarryover(rows.map(mapAccountsPayableCommissionRow)),
      user,
      "modulo:comisiones",
      "accion:pagar"
    );
    commissionAccounts = filterCommissionAccountsByMonth(accounts, monthInput)
      .filter((account) => !account.pagado && !account.lotePagoId)
      .map((account) => ({
        ...account,
        source: "OCCOM",
        entityId: Number(account.commissionId),
        person: account.supervisor || "Sin supervisor",
        documento: account.occom || "",
        monto: Math.max(
          Math.round((Number(account.montoOriginal || account.subtotal || 0) - Number(account.adeudoMonto || 0)) * 100) / 100,
          0
        )
      }))
      .filter((account) => Number(account.monto || 0) > 0.005);
  }
  const pendingBatchLinks = await getPendingCommissionPaymentBatchLinks();
  return [...ocpAccounts, ...ocgfAccounts, ...commissionAccounts].map((account) => ({
    ...account,
    existingBatch: pendingBatchLinks.get(`${account.source}:${Number(account.entityId)}`) || null
  }));
}

function getExistingCommissionPaymentBatches(candidates = []) {
  return [...new Map((Array.isArray(candidates) ? candidates : [])
    .filter((candidate) => candidate.existingBatch?.id)
    .map((candidate) => [Number(candidate.existingBatch.id), candidate.existingBatch])).values()]
    .sort((a, b) => Number(b.id) - Number(a.id));
}

async function createCommissionPaymentBatchDraft({ selections, mode = "persona", user = null, monthInput = "" }) {
  const requested = Array.isArray(selections) ? selections : [];
  const uniqueSelections = [...new Map(requested.map((item) => {
    const requestedSource = String(item?.source || "").toUpperCase();
    const source = ["OCP", "OCGF", "OCCOM"].includes(requestedSource) ? requestedSource : "OCCOM";
    const id = Number(item?.id ?? item?.entityId);
    return [`${source}:${id}`, { source, id }];
  }).filter(([, item]) => Number.isInteger(item.id) && item.id > 0)).values()];
  if (uniqueSelections.length < 2) throw new Error("Selecciona al menos dos pagos para crear una OCP general.");
  if (uniqueSelections.length > 200) throw new Error("Una OCP general puede contener como máximo 200 pagos.");

  const groupingMode = mode === "proyecto" ? "proyecto" : "persona";
  const candidates = await getCommissionPaymentBatchCandidates(monthInput, user);
  const byId = new Map(candidates.map((account) => [`${account.source}:${Number(account.entityId)}`, account]));
  const selected = uniqueSelections.map((item) => byId.get(`${item.source}:${item.id}`));
  if (selected.some((account) => !account)) {
    throw new Error("Uno o más pagos ya no están disponibles para crear la OCP general.");
  }
  const linkedAccount = selected.find((account) => account.existingBatch?.id);
  if (linkedAccount) {
    const error = new Error(`${linkedAccount.documento || "El pago"} ya pertenece a la OCP general ${linkedAccount.existingBatch.folio}.`);
    error.code = "PAYMENT_BATCH_EXISTS";
    error.batch = linkedAccount.existingBatch;
    throw error;
  }

  const cuentaIds = [];
  for (const account of selected) {
    const cuentaId = account.source === "OCP"
      ? await ensureAccountsPayableRecord(account.entityId, user?.id || null)
      : account.source === "OCGF"
        ? await ensureAccountsPayableRecordForOcgf(account.entityId, user?.id || null)
        : await ensureAccountsPayableRecordForCommission(account.entityId, user?.id || null);
    if (!cuentaId) throw new Error(`No se pudo preparar ${account.documento || account.entityId}.`);
    cuentaIds.push(Number(cuentaId));
  }

  const connection = await pool.getConnection();
  let lockAcquired = false;
  let batchId = null;
  try {
    const [lockRows] = await connection.query("SELECT GET_LOCK('dalvo_payment_batch', 10) AS acquired");
    lockAcquired = Number(lockRows[0]?.acquired || 0) === 1;
    if (!lockAcquired) throw new Error("No se pudo reservar el folio de la OCP general.");
    await connection.beginTransaction();
    const folio = await generateCommissionPaymentBatchFolio(connection);
    const [batchInsert] = await connection.execute(
      `INSERT INTO lotes_pago_comisiones
        (folio, estado, modo_agrupacion, total, fecha_pago, usuario_id)
       VALUES (?, 'Pendiente', ?, 0, ?, ?)`,
      [folio, groupingMode, businessDateOnly(), user?.id || null]
    );
    batchId = Number(batchInsert.insertId);
    let total = 0;

    for (let index = 0; index < selected.length; index += 1) {
      const account = selected[index];
      const cuentaId = cuentaIds[index];
      const [existingItems] = await connection.execute(
        account.source === "OCP"
          ? `SELECT lp.id AS batch_id, lp.folio, lp.estado, lp.total
             FROM lotes_pago_comisiones_items lpi
             INNER JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id
             WHERE lpi.ocp_id = ? LIMIT 1`
          : account.source === "OCGF"
            ? `SELECT lp.id AS batch_id, lp.folio, lp.estado, lp.total
               FROM lotes_pago_comisiones_items lpi
               INNER JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id
               WHERE lpi.ocgf_order_id = ? LIMIT 1`
            : `SELECT lp.id AS batch_id, lp.folio, lp.estado, lp.total
               FROM lotes_pago_comisiones_items lpi
               INNER JOIN lotes_pago_comisiones lp ON lp.id = lpi.lote_id
               WHERE lpi.comision_id = ? LIMIT 1`,
        [account.entityId]
      );
      if (existingItems.length) {
        const existing = existingItems[0];
        const error = new Error(`${account.documento || "El pago"} ya pertenece a la OCP general ${existing.folio || existing.batch_id}.`);
        error.code = "PAYMENT_BATCH_EXISTS";
        error.batch = {
          id: Number(existing.batch_id),
          folio: existing.folio || `OCP general ${existing.batch_id}`,
          estado: existing.estado || "Pendiente",
          total: Number(existing.total || 0),
          previewUrl: `/api/commission-payment-batches/${Number(existing.batch_id)}/preview`
        };
        throw error;
      }
      const financial = await getAccountsPayableFinancialSummary(cuentaId, connection);
      if (!financial || financial.remaining <= 0.005) throw new Error(`${account.documento || "El pago"} ya está pagado.`);
      const amount = Math.round(Number(financial.remaining || 0) * 100) / 100;
      await connection.execute(
        `INSERT INTO lotes_pago_comisiones_items
          (lote_id, cuenta_id, tipo_origen, ocp_id, ocgf_order_id, comision_id, movimiento_id, supervisor_id, supervisor_nombre,
           empresa, proyecto, folio_presupuesto, folio_occom, monto_bruto, adeudo_monto, monto_pagado)
         VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          batchId,
          cuentaId,
          account.source,
          account.source === "OCP" ? account.entityId : null,
          account.source === "OCGF" ? account.entityId : null,
          account.source === "OCCOM" ? account.entityId : null,
          account.source === "OCCOM" ? account.supervisorId || null : null,
          account.person || account.supervisor || account.proveedor || "Sin persona",
          account.empresa || "",
          account.proyecto || account.gasto || "",
          account.folio || "",
          account.documento || account.occom || account.ocp || account.ocgf || "",
          Number(account.montoOriginal || account.subtotal || 0),
          Number(account.adeudoMonto || 0),
          amount
        ]
      );
      total = Math.round((total + amount) * 100) / 100;
    }
    await connection.execute("UPDATE lotes_pago_comisiones SET total = ? WHERE id = ?", [total, batchId]);
    await connection.commit();
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    throw error;
  } finally {
    if (lockAcquired) {
      try { await connection.query("SELECT RELEASE_LOCK('dalvo_payment_batch')"); } catch (_releaseError) {}
    }
    connection.release();
  }

  try { await generateCommissionPaymentBatchPdf(batchId); } catch (error) { logServerError(`commission-batch-draft-pdf-${batchId}`, error); }
  return getCommissionPaymentBatch(batchId);
}

async function payCommissionPaymentBatch(batchId, user = null) {
  const connection = await pool.getConnection();
  const cuentaIds = [];
  try {
    await connection.beginTransaction();
    const [batchRows] = await connection.execute(
      "SELECT id, folio, estado FROM lotes_pago_comisiones WHERE id = ? FOR UPDATE",
      [batchId]
    );
    if (!batchRows.length) throw new Error("OCP general no encontrada.");
    const batchRow = batchRows[0];
    if (String(batchRow.estado || "").toLowerCase() === "pagado") {
      await connection.commit();
      return getCommissionPaymentBatch(batchId);
    }
    const [items] = await connection.execute(
      `SELECT id, cuenta_id, tipo_origen, ocp_id, ocgf_order_id, comision_id, monto_pagado
       FROM lotes_pago_comisiones_items WHERE lote_id = ? ORDER BY id FOR UPDATE`,
      [batchId]
    );
    if (items.length < 2) throw new Error("La OCP general no contiene pagos suficientes.");
    let total = 0;
    for (let index = 0; index < items.length; index += 1) {
      const item = items[index];
      const financial = await getAccountsPayableFinancialSummary(Number(item.cuenta_id), connection);
      if (!financial || financial.remaining <= 0.005) throw new Error("Una cuenta incluida ya no tiene saldo pendiente.");
      const amount = Math.round(Number(financial.remaining || 0) * 100) / 100;
      const movementFolio = `${batchRow.folio}-${String(index + 1).padStart(2, "0")}`;
      const source = String(item.tipo_origen || (item.ocp_id ? "OCP" : item.ocgf_order_id ? "OCGF" : "OCCOM"));
      const [movementInsert] = await connection.execute(
        `INSERT INTO ordenes_pago
          (cuenta_id, tipo_origen, ocp_id, ocgf_orden_id, folio, monto,
           tipo_movimiento, estado_movimiento, fecha_aplicacion, metodo_pago,
           referencia, observaciones, usuario_id)
         VALUES (?, ?, ?, ?, ?, ?, 'Pago completo', 'Aplicado', ?, '', ?, ?, ?)`,
        [
          item.cuenta_id,
          source,
          source === "OCP" ? item.ocp_id : null,
          source === "OCGF" ? item.ocgf_order_id : null,
          movementFolio,
          amount,
          businessDateOnly(),
          batchRow.folio,
          `Pago incluido en la OCP general ${batchRow.folio}`,
          user?.id || null
        ]
      );
      await connection.execute(
        "UPDATE lotes_pago_comisiones_items SET movimiento_id = ?, monto_pagado = ? WHERE id = ?",
        [movementInsert.insertId, amount, item.id]
      );
      await connection.execute(
        `UPDATE cuentas_por_pagar
         SET estado = 'Pago completo', pendiente = 'Sin pendientes', fecha_pago = ?, pagado = 1,
             estado_registro = 'Cerrada', estatus_pago = 'Pagada', updated_at = CURRENT_TIMESTAMP
         WHERE id = ?`,
        [businessDateOnly(), item.cuenta_id]
      );
      cuentaIds.push(Number(item.cuenta_id));
      total = Math.round((total + amount) * 100) / 100;
    }
    await connection.execute(
      "UPDATE lotes_pago_comisiones SET estado = 'Pagado', total = ?, fecha_pago = ?, pdf_ruta = '' WHERE id = ?",
      [total, businessDateOnly(), batchId]
    );
    await connection.commit();
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    throw error;
  } finally {
    connection.release();
  }
  for (const cuentaId of cuentaIds) {
    try { await refreshAccountsPayableStatus(cuentaId); } catch (error) { logServerError(`commission-batch-pay-refresh-${cuentaId}`, error); }
  }
  try { await generateCommissionPaymentBatchPdf(batchId); } catch (error) { logServerError(`commission-batch-paid-pdf-${batchId}`, error); }
  return getCommissionPaymentBatch(batchId);
}

async function createCommissionPaymentBatch({ selections, commissionIds, mode = "persona", user = null, monthInput = "" }) {
  const requested = Array.isArray(selections) && selections.length
    ? selections
    : (Array.isArray(commissionIds) ? commissionIds : []).map((id) => ({ source: "OCCOM", id }));
  const uniqueSelections = [...new Map(requested.map((item) => {
    const requestedSource = String(item?.source || "").toUpperCase();
    const source = ["OCP", "OCGF", "OCCOM"].includes(requestedSource) ? requestedSource : "OCCOM";
    const id = Number(item?.id ?? item?.entityId);
    return [`${source}:${id}`, { source, id }];
  }).filter(([, item]) => Number.isInteger(item.id) && item.id > 0)).values()];
  if (uniqueSelections.length < 2) throw new Error("Selecciona al menos dos pagos para crear un lote.");
  if (uniqueSelections.length > 200) throw new Error("Un lote puede contener como máximo 200 pagos.");
  const groupingMode = mode === "proyecto" ? "proyecto" : "persona";
  const candidates = await getCommissionPaymentBatchCandidates(monthInput, user);
  const byId = new Map(candidates.map((account) => [`${account.source}:${Number(account.entityId)}`, account]));
  const selected = uniqueSelections.map((item) => byId.get(`${item.source}:${item.id}`));
  if (selected.some((account) => !account)) {
    throw new Error("Uno o más pagos ya fueron registrados, cambiaron de periodo o no están disponibles para este usuario.");
  }

  const cuentaIds = [];
  for (const account of selected) {
    const cuentaId = account.source === "OCP"
      ? await ensureAccountsPayableRecord(account.entityId, user?.id || null)
      : account.source === "OCGF"
        ? await ensureAccountsPayableRecordForOcgf(account.entityId, user?.id || null)
        : await ensureAccountsPayableRecordForCommission(account.entityId, user?.id || null);
    if (!cuentaId) throw new Error(`No se pudo preparar el pago ${account.documento || account.entityId}.`);
    cuentaIds.push(Number(cuentaId));
  }

  const connection = await pool.getConnection();
  let lockAcquired = false;
  let batchId = null;
  try {
    const [lockRows] = await connection.query("SELECT GET_LOCK('dalvo_payment_batch', 10) AS acquired");
    lockAcquired = Number(lockRows[0]?.acquired || 0) === 1;
    if (!lockAcquired) throw new Error("No se pudo reservar el folio del lote de pago.");
    await connection.beginTransaction();
    const folio = await generateCommissionPaymentBatchFolio(connection);
    const [batchInsert] = await connection.execute(
      `INSERT INTO lotes_pago_comisiones
        (folio, estado, modo_agrupacion, total, fecha_pago, usuario_id)
       VALUES (?, 'Pagado', ?, 0, ?, ?)`,
      [folio, groupingMode, businessDateOnly(), user?.id || null]
    );
    batchId = Number(batchInsert.insertId);
    let total = 0;

    for (let index = 0; index < selected.length; index += 1) {
      const account = selected[index];
      const cuentaId = cuentaIds[index];
      const [accountRows] = await connection.execute(
        "SELECT id FROM cuentas_por_pagar WHERE id = ? FOR UPDATE",
        [cuentaId]
      );
      if (!accountRows.length) throw new Error("Una cuenta por pagar dejó de estar disponible.");
      const [existingItems] = await connection.execute(
        account.source === "OCP"
          ? "SELECT lote_id FROM lotes_pago_comisiones_items WHERE ocp_id = ? LIMIT 1"
          : account.source === "OCGF"
            ? "SELECT lote_id FROM lotes_pago_comisiones_items WHERE ocgf_order_id = ? LIMIT 1"
            : "SELECT lote_id FROM lotes_pago_comisiones_items WHERE comision_id = ? LIMIT 1",
        [account.entityId]
      );
      if (existingItems.length) throw new Error(`${account.documento || "El pago"} ya pertenece a otro lote.`);
      const financial = await getAccountsPayableFinancialSummary(cuentaId, connection);
      if (!financial || financial.remaining <= 0.005) throw new Error(`${account.documento || "El pago"} ya está pagado.`);
      const amount = Math.round(Number(financial.remaining || 0) * 100) / 100;
      const movementFolio = `${folio}-${String(index + 1).padStart(2, "0")}`;
      const [movementInsert] = await connection.execute(
        `INSERT INTO ordenes_pago
          (cuenta_id, tipo_origen, ocp_id, ocgf_orden_id, folio, monto,
           tipo_movimiento, estado_movimiento, fecha_aplicacion, metodo_pago,
           referencia, observaciones, usuario_id)
         VALUES (?, ?, ?, ?, ?, ?, 'Pago completo', 'Aplicado', ?, '', ?, ?, ?)`,
        [cuentaId, account.source, account.source === "OCP" ? account.entityId : null, account.source === "OCGF" ? account.entityId : null, movementFolio, amount, businessDateOnly(), folio, `Pago incluido en el lote ${folio}`, user?.id || null]
      );
      await connection.execute(
        `INSERT INTO lotes_pago_comisiones_items
          (lote_id, cuenta_id, tipo_origen, ocp_id, ocgf_order_id, comision_id, movimiento_id, supervisor_id, supervisor_nombre,
           empresa, proyecto, folio_presupuesto, folio_occom, monto_bruto, adeudo_monto, monto_pagado)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          batchId,
          cuentaId,
          account.source,
          account.source === "OCP" ? account.entityId : null,
          account.source === "OCGF" ? account.entityId : null,
          account.source === "OCCOM" ? account.entityId : null,
          movementInsert.insertId,
          account.source === "OCCOM" ? account.supervisorId || null : null,
          account.person || account.supervisor || account.proveedor || "Sin persona",
          account.empresa || "",
          account.proyecto || "",
          account.folio || "",
          account.documento || account.occom || account.ocp || "",
          Number(account.montoOriginal || account.subtotal || 0),
          Number(account.adeudoMonto || 0),
          amount
        ]
      );
      await connection.execute(
        `UPDATE cuentas_por_pagar
         SET estado = 'Pago completo', pendiente = 'Sin pendientes', fecha_pago = ?, pagado = 1,
             estado_registro = 'Cerrada', estatus_pago = 'Pagada', updated_at = CURRENT_TIMESTAMP
         WHERE id = ?`,
        [businessDateOnly(), cuentaId]
      );
      total = Math.round((total + amount) * 100) / 100;
    }
    await connection.execute("UPDATE lotes_pago_comisiones SET total = ? WHERE id = ?", [total, batchId]);
    await connection.commit();
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    throw error;
  } finally {
    if (lockAcquired) {
      try { await connection.query("SELECT RELEASE_LOCK('dalvo_payment_batch')"); } catch (_releaseError) {}
    }
    connection.release();
  }

  for (const cuentaId of cuentaIds) {
    try { await refreshAccountsPayableStatus(cuentaId); } catch (error) { logServerError(`commission-batch-refresh-${cuentaId}`, error); }
  }
  try { await generateCommissionPaymentBatchPdf(batchId); } catch (error) { logServerError(`commission-batch-pdf-${batchId}`, error); }
  return getCommissionPaymentBatch(batchId);
}

function receivableBatchPdfRelativePath(batch = {}) {
  const safeFolio = String(batch.folio || `cobro_${batch.id || Date.now()}`).replace(/[^a-zA-Z0-9._-]/g, "_");
  return path.join("uploads", "lotes_cobro_clientes", `${safeFolio}.pdf`).replace(/\\/g, "/");
}

async function generateReceivableBatchFolio(connection = pool) {
  const yearSuffix = String(businessDateOnly() || new Date().getFullYear()).slice(2, 4);
  const prefix = `COBG${yearSuffix}`;
  const [rows] = await connection.execute(
    `SELECT MAX(CAST(SUBSTRING(folio, ?) AS UNSIGNED)) AS last_number
     FROM lotes_cobro_clientes WHERE folio LIKE ?`,
    [prefix.length + 1, `${prefix}%`]
  );
  return `${prefix}${String(Number(rows[0]?.last_number || 0) + 1).padStart(4, "0")}`;
}

async function getReceivableBatch(batchId, connection = pool) {
  const [batchRows] = await connection.execute(
    `SELECT id, folio, estado, empresa, intermediario, referencia_externa, porcentaje_descuento,
            monto_original, descuento_monto, monto_cobrar, fecha_cobro, pdf_ruta, observaciones,
            usuario_id, created_at, updated_at
     FROM lotes_cobro_clientes WHERE id = ? LIMIT 1`,
    [batchId]
  );
  if (!batchRows.length) return null;
  const [items] = await connection.execute(
    `SELECT id, lote_id, cuenta_id, cotizacion_cliente_id, presupuesto_id, folio_cotizacion,
            folio_presupuesto, po_cliente, proyecto, monto_original, porcentaje_descuento,
            descuento_monto, ajuste_redondeo, monto_cobrar, pago_id, created_at
     FROM lotes_cobro_clientes_items WHERE lote_id = ? ORDER BY id`,
    [batchId]
  );
  const [files] = await connection.execute(
    `SELECT id, lote_id, item_id, tipo, nombre, ruta, usuario_id, created_at
     FROM lotes_cobro_clientes_archivos WHERE lote_id = ? ORDER BY id DESC`,
    [batchId]
  );
  const quoteIds = [...new Set(items.map((item) => Number(item.cotizacion_cliente_id || 0)).filter(Boolean))];
  let quoteParts = [];
  if (quoteIds.length) {
    const placeholders = quoteIds.map(() => "?").join(",");
    const [partRows] = await connection.execute(
      `SELECT id, cotizacion_id, cantidad, unidad_medida, descripcion, precio, subtotal
       FROM cotizacion_cliente_partidas
       WHERE cotizacion_id IN (${placeholders})
       ORDER BY cotizacion_id, id`,
      quoteIds
    );
    quoteParts = partRows;
  }
  const row = batchRows[0];
  const netSubtotal = Number(row.monto_cobrar || 0);
  const iva = roundMoneyServer(netSubtotal * 0.16);
  return {
    id: Number(row.id),
    folio: row.folio || "",
    estado: row.estado || "Pendiente",
    empresa: row.empresa || "",
    intermediario: row.intermediario || "",
    referenciaExterna: row.referencia_externa || "",
    porcentajeDescuento: Number(row.porcentaje_descuento || 0),
    montoOriginal: Number(row.monto_original || 0),
    descuentoMonto: Number(row.descuento_monto || 0),
    montoCobrar: Number(row.monto_cobrar || 0),
    iva,
    totalConIva: roundMoneyServer(netSubtotal + iva),
    fechaCobro: row.fecha_cobro,
    observaciones: row.observaciones || "",
    pdfRuta: row.pdf_ruta || "",
    pdfUrl: `/api/accounts-receivable-batches/${Number(row.id)}/pdf`,
    previewUrl: `/api/accounts-receivable-batches/${Number(row.id)}/preview`,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    items: items.map((item) => ({
      id: Number(item.id),
      cuentaId: Number(item.cuenta_id),
      quoteId: Number(item.cotizacion_cliente_id),
      presupuestoId: Number(item.presupuesto_id),
      quoteFolio: item.folio_cotizacion || "",
      folio: item.folio_presupuesto || "",
      po: item.po_cliente || "",
      proyecto: item.proyecto || "",
      montoOriginal: Number(item.monto_original || 0),
      porcentajeDescuento: Number(item.porcentaje_descuento || 0),
      descuentoMonto: Number(item.descuento_monto || 0),
      ajusteRedondeo: Number(item.ajuste_redondeo || 0),
      montoCobrar: Number(item.monto_cobrar || 0),
      pagoId: Number(item.pago_id || 0) || null,
      partidas: quoteParts
        .filter((part) => Number(part.cotizacion_id) === Number(item.cotizacion_cliente_id))
        .map((part) => ({
          id: Number(part.id),
          cantidad: Number(part.cantidad || 0),
          unidadMedida: part.unidad_medida || "",
          descripcion: part.descripcion || "",
          precio: Number(part.precio || 0),
          subtotal: Number(part.subtotal || 0)
        }))
    })),
    files: files.map((file) => ({
      id: Number(file.id),
      itemId: Number(file.item_id || 0) || null,
      tipo: file.tipo || "Comprobante de pago",
      nombre: file.nombre || "",
      url: file.ruta ? `/${String(file.ruta).replace(/\\/g, "/")}` : "",
      downloadUrl: `/api/accounts-receivable-batch-files/${Number(file.id)}/download`,
      createdAt: file.created_at
    }))
  };
}

async function generateReceivableBatchPdf(batchId) {
  const batch = await getReceivableBatch(batchId);
  if (!batch) throw new Error("Cobro general no encontrado.");
  const relativePath = receivableBatchPdfRelativePath(batch);
  const absolutePath = path.join(__dirname, relativePath);
  await fs.promises.mkdir(path.dirname(absolutePath), { recursive: true });
  await new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: "LETTER", margin: 36, bufferPages: true, info: { Title: `Cotizacion consolidada ${batch.folio}`, Author: "DALVO SOLUTIONS SA DE CV" } });
    const stream = fs.createWriteStream(absolutePath);
    stream.on("finish", resolve);
    stream.on("error", reject);
    doc.on("error", reject);
    doc.pipe(stream);
    const batchState = normalizeWorkflowValue(batch.estado);
    const collected = batchState === "completado";
    const paymentReceived = batchState === "pendiente complemento" || batchState === "cobrado";
    if (fs.existsSync(DALVO_QUOTE_LOGO)) {
      doc.image(DALVO_QUOTE_LOGO, 36, 30, { fit: [150, 78], align: "left", valign: "center" });
    }
    doc.fillColor("#071225").font("Helvetica-Bold").fontSize(17).text("Cotización consolidada", 250, 42, { width: 306, align: "right" });
    doc.fontSize(11).text(batch.folio, 300, 68, { width: 256, align: "right" });
    const stateLabel = collected
      ? "COMPLETADO"
      : paymentReceived ? "PAGO RECIBIDO · FALTA COMPLEMENTO"
        : batchState === "parcial" ? "PAGO PARCIAL" : "PENDIENTE DE COBRO";
    doc.font("Helvetica").fontSize(9).text(`${stateLabel} · ${formatDateOnly(batch.fechaCobro || batch.createdAt)}`, 270, 86, { width: 286, align: "right" });
    doc.moveTo(36, 118).lineTo(556, 118).strokeColor("#0f84aa").lineWidth(1.5).stroke();
    doc.font("Helvetica-Bold").fontSize(10).fillColor("#071225").text("Cliente", 36, 138);
    doc.font("Helvetica").text(batch.empresa || "Sin empresa", 36, 154, { width: 240 });
    doc.font("Helvetica-Bold").text("Pagador / intermediario", 316, 138, { width: 240, align: "right" });
    doc.font("Helvetica").text(batch.intermediario || batch.empresa || "Sin intermediario", 316, 154, { width: 240, align: "right" });
    doc.font("Helvetica-Bold").text("Referencia OC / PO", 36, 180);
    doc.font("Helvetica").text(batch.referenciaExterna || "Sin referencia", 36, 196, { width: 240 });
    doc.font("Helvetica-Bold").text("Descuento", 316, 180, { width: 240, align: "right" });
    doc.font("Helvetica").text(`${batch.porcentajeDescuento.toFixed(2)}%`, 316, 196, { width: 240, align: "right" });
    let y = 232;
    const drawHead = () => {
      doc.rect(36, y, 520, 23).fill("#273142");
      doc.fillColor("#fff").font("Helvetica-Bold").fontSize(7);
      doc.text("Folio / serie", 43, y + 8, { width: 80 });
      doc.text("Cant.", 127, y + 8, { width: 38, align: "right" });
      doc.text("U.M.", 169, y + 8, { width: 40 });
      doc.text("Descripción", 213, y + 8, { width: 190 });
      doc.text("Precio", 407, y + 8, { width: 68, align: "right" });
      doc.text("Subtotal", 479, y + 8, { width: 70, align: "right" });
      y += 23;
    };
    drawHead();
    for (const item of batch.items) {
      if (y + 30 > 690) { doc.addPage(); y = 72; drawHead(); }
      doc.rect(36, y, 520, 27).fill("#edf7fa");
      doc.fillColor("#071225").font("Helvetica-Bold").fontSize(7.5);
      doc.text(`${item.folio || item.quoteFolio || "Proyecto"} · ${item.proyecto || "Sin proyecto"}`, 43, y + 6, { width: 360 });
      doc.text(`Neto: ${formatCurrencyServer(item.montoCobrar)}`, 409, y + 6, { width: 140, align: "right" });
      y += 27;
      const parts = item.partidas?.length ? item.partidas : [{ cantidad: 1, unidadMedida: "P", descripcion: item.proyecto || "Proyecto", precio: item.montoOriginal, subtotal: item.montoOriginal }];
      for (const part of parts) {
        const rowHeight = Math.max(28, doc.heightOfString(part.descripcion || "Sin descripción", { width: 190 }) + 12);
        if (y + rowHeight > 690) { doc.addPage(); y = 72; drawHead(); }
        doc.rect(36, y, 520, rowHeight).strokeColor("#dbe4ea").lineWidth(0.5).stroke();
        doc.fillColor("#071225").font("Helvetica").fontSize(7.2);
        doc.text(item.quoteFolio || item.folio || "—", 43, y + 7, { width: 80, lineBreak: false });
        doc.text(Number(part.cantidad || 0).toFixed(2), 127, y + 7, { width: 38, align: "right" });
        doc.text(part.unidadMedida || "", 169, y + 7, { width: 40 });
        doc.text(part.descripcion || "Sin descripción", 213, y + 7, { width: 190 });
        doc.text(formatCurrencyServer(part.precio || 0), 407, y + 7, { width: 68, align: "right" });
        doc.text(formatCurrencyServer(part.subtotal || 0), 479, y + 7, { width: 70, align: "right" });
        y += rowHeight;
      }
    }
    if (y + 105 > 690) { doc.addPage(); y = 72; }
    y += 18;
    doc.font("Helvetica").fontSize(9).fillColor("#071225").text(`Monto original: ${formatCurrencyServer(batch.montoOriginal)}`, 336, y, { width: 220, align: "right" });
    doc.text(`Descuento: ${formatCurrencyServer(batch.descuentoMonto)}`, 336, y + 16, { width: 220, align: "right" });
    doc.text(`Subtotal neto: ${formatCurrencyServer(batch.montoCobrar)}`, 336, y + 32, { width: 220, align: "right" });
    doc.text(`IVA 16%: ${formatCurrencyServer(batch.iva)}`, 336, y + 48, { width: 220, align: "right" });
    doc.font("Helvetica-Bold").fontSize(13).text(`TOTAL: ${formatCurrencyServer(batch.totalConIva)}`, 296, y + 70, { width: 260, align: "right" });
    const pageRange = doc.bufferedPageRange();
    for (let index = 0; index < pageRange.count; index += 1) { doc.switchToPage(pageRange.start + index); drawQuoteFooter(doc, index + 1, pageRange.count); }
    doc.end();
  });
  await pool.execute("UPDATE lotes_cobro_clientes SET pdf_ruta = ? WHERE id = ?", [relativePath, batchId]);
  return relativePath;
}

async function getReceivableBatchCandidates(user = null, accountsInput = null) {
  const accounts = Array.isArray(accountsInput)
    ? accountsInput
    : filterOwnedRowsForUser(await getAccountsReceivableList(), user, "modulo:cuentas-cobrar");
  return accounts
    .filter((item) => isReceivablePending(item) && Number(item.saldoCobrar ?? item.monto ?? 0) > 0.004 && !item.pagosRegistrados)
    .map((item) => ({
      quoteId: Number(item.quoteId),
      cuentaId: Number(item.cuentaId),
      presupuestoId: Number(item.presupuestoId),
      empresa: item.empresa || "",
      clienteUsuario: item.clienteUsuario || "",
      folio: item.folio || "",
      po: item.po || "",
      proyecto: item.proyecto || "",
      quoteFolio: item.quoteFolio || "",
      montoOriginal: Number(item.montoOriginal ?? item.monto ?? 0),
      saldoCobrar: Number(item.saldoCobrar ?? item.monto ?? 0),
      existingBatch: item.cobroAgrupado ? {
        ...item.cobroAgrupado,
        previewUrl: `/api/accounts-receivable-batches/${Number(item.cobroAgrupado.id)}/preview`
      } : null
    }));
}

function getExistingReceivableBatches(candidates = []) {
  const rows = candidates
    .map((item) => ({ item, batch: item.existingBatch || item.cobroAgrupado || null }))
    .filter(({ batch }) => batch?.id && normalizeWorkflowValue(batch.estado) !== "completado");
  return [...new Map(rows.map(({ batch }) => [
    Number(batch.id),
    {
      ...batch,
      itemCount: rows.filter((row) => Number(row.batch?.id) === Number(batch.id)).length
    }
  ])).values()];
}

async function createReceivableBatchDraft({ quoteIds = [], percentage = 0, authorizedTotal = null, intermediary = "", externalReference = "", observations = "", user = null }) {
  const ids = [...new Set((Array.isArray(quoteIds) ? quoteIds : []).map(Number).filter((id) => Number.isInteger(id) && id > 0))];
  if (ids.length < 2) throw new Error("Selecciona al menos dos cuentas para crear un cobro general.");
  if (ids.length > 200) throw new Error("Un cobro general puede contener como máximo 200 cuentas.");
  const discountPercentage = Number(percentage || 0);
  if (!Number.isFinite(discountPercentage) || discountPercentage < 0 || discountPercentage >= 100) throw new Error("Ingresa un descuento entre 0% y 99.99%.");
  const candidates = await getReceivableBatchCandidates(user);
  const byId = new Map(candidates.map((item) => [Number(item.quoteId), item]));
  const selected = ids.map((id) => byId.get(id));
  if (selected.some((item) => !item || item.existingBatch?.id)) throw new Error("Una o más cuentas ya no están disponibles o pertenecen a otro cobro general.");
  for (const item of selected) {
    if (!(await canAccessBudget(user, item.presupuestoId, "modulo:cuentas-cobrar", "accion:facturar"))) {
      throw new Error("No tienes permiso de cobranza para uno o más proyectos seleccionados.");
    }
  }
  const companies = [...new Set(selected.map((item) => normalizeSearchText(item.empresa || "")))];
  if (companies.length !== 1) throw new Error("Todos los proyectos seleccionados deben pertenecer a la misma empresa.");
  const originalTotal = roundMoneyServer(selected.reduce((sum, item) => sum + Number(item.saldoCobrar || 0), 0));
  const automaticNets = selected.map((item) => roundMoneyServer(Number(item.saldoCobrar || 0) * (1 - discountPercentage / 100)));
  const automaticTotal = roundMoneyServer(automaticNets.reduce((sum, value) => sum + value, 0));
  const requestedAuthorized = authorizedTotal === null || authorizedTotal === undefined || String(authorizedTotal).trim() === "" ? automaticTotal : roundMoneyServer(authorizedTotal);
  if (!(requestedAuthorized > 0) || requestedAuthorized > originalTotal + 0.004) throw new Error("El total autorizado debe ser mayor a cero y no puede superar el monto original.");
  const allocationAdjustment = roundMoneyServer(requestedAuthorized - automaticTotal);
  automaticNets[automaticNets.length - 1] = roundMoneyServer(automaticNets[automaticNets.length - 1] + allocationAdjustment);
  if (automaticNets.some((value) => value < 0)) throw new Error("El ajuste del total autorizado produce un importe inválido.");

  const connection = await pool.getConnection();
  let lockAcquired = false;
  let batchId = null;
  try {
    const [lockRows] = await connection.query("SELECT GET_LOCK('dalvo_receivable_batch', 10) AS acquired");
    lockAcquired = Number(lockRows[0]?.acquired || 0) === 1;
    if (!lockAcquired) throw new Error("No se pudo reservar el folio del cobro general.");
    await connection.beginTransaction();
    const folio = await generateReceivableBatchFolio(connection);
    const [insert] = await connection.execute(
      `INSERT INTO lotes_cobro_clientes
        (folio, estado, empresa, intermediario, referencia_externa, porcentaje_descuento,
         monto_original, descuento_monto, monto_cobrar, observaciones, usuario_id)
       VALUES (?, 'Pendiente', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [folio, selected[0].empresa || "", String(intermediary || "").trim(), String(externalReference || "").trim(), discountPercentage,
       originalTotal, roundMoneyServer(originalTotal - requestedAuthorized), requestedAuthorized, String(observations || "").trim(), user?.id || null]
    );
    batchId = Number(insert.insertId);
    for (let index = 0; index < selected.length; index += 1) {
      const item = selected[index];
      const gross = roundMoneyServer(item.saldoCobrar || 0);
      const net = automaticNets[index];
      const automaticNet = roundMoneyServer(gross * (1 - discountPercentage / 100));
      await connection.execute(
        `INSERT INTO lotes_cobro_clientes_items
          (lote_id, cuenta_id, cotizacion_cliente_id, presupuesto_id, folio_cotizacion,
           folio_presupuesto, po_cliente, proyecto, monto_original, porcentaje_descuento,
           descuento_monto, ajuste_redondeo, monto_cobrar)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [batchId, item.cuentaId, item.quoteId, item.presupuestoId, item.quoteFolio || "", item.folio || "", item.po || "", item.proyecto || "",
         gross, discountPercentage, roundMoneyServer(gross - net), roundMoneyServer(net - automaticNet), net]
      );
      await connection.execute("UPDATE cuentas_por_cobrar SET monto = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?", [net, item.cuentaId]);
    }
    await connection.commit();
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    if (error?.code === "ER_DUP_ENTRY") throw new Error("Una de las cuentas seleccionadas ya pertenece a otro cobro general.");
    throw error;
  } finally {
    if (lockAcquired) { try { await connection.query("SELECT RELEASE_LOCK('dalvo_receivable_batch')"); } catch (_releaseError) {} }
    connection.release();
  }
  try { await generateReceivableBatchPdf(batchId); } catch (error) { logServerError(`receivable-batch-pdf-${batchId}`, error); }
  return getReceivableBatch(batchId);
}

async function canAccessReceivableBatch(user, batch = null, operationPermission = "") {
  if (!batch || !Array.isArray(batch.items) || !batch.items.length) return false;
  for (const item of batch.items) {
    if (!(await canAccessBudget(user, item.presupuestoId, "modulo:cuentas-cobrar", operationPermission))) return false;
  }
  return true;
}

async function createReceivableAccountDocumentCopy({ sourcePath, originalName, cuentaId, tipo, batchFileId = null, userId = null, connection = pool }) {
  const safeBase = normalizeQuoteFileName(path.basename(originalName || sourcePath || "documento"));
  const storedName = `lote-${Date.now()}-${crypto.randomBytes(5).toString("hex")}-${safeBase}`;
  const absoluteTarget = path.join(ACCOUNTS_RECEIVABLE_UPLOAD_DIR, storedName);
  await fs.promises.copyFile(path.resolve(__dirname, sourcePath), absoluteTarget);
  const relativeTarget = path.relative(__dirname, absoluteTarget).replace(/\\/g, "/");
  try {
    const [result] = await connection.execute(
      `INSERT INTO cuentas_por_cobrar_archivos
        (cuenta_id, tipo, nombre, ruta, usuario_id, lote_cobro_archivo_id)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [cuentaId, tipo, originalName || safeBase, relativeTarget, userId || null, batchFileId || null]
    );
    return { archivoId: Number(result.insertId), relativePath: relativeTarget };
  } catch (error) {
    unlinkStoredFile(relativeTarget, ACCOUNTS_RECEIVABLE_UPLOAD_DIR);
    throw error;
  }
}

async function linkReceivableInvoiceDocument({ cuentaId, archivoId, userId = null, connection = pool }) {
  let facturacionId = null;
  const [pendingBilling] = await connection.execute(
    "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado = 'Solicitada' ORDER BY id ASC LIMIT 1",
    [cuentaId]
  );
  if (pendingBilling.length) {
    facturacionId = Number(pendingBilling[0].id);
    await connection.execute("UPDATE cuentas_por_cobrar_facturacion SET estado = 'Facturada', updated_at = NOW() WHERE id = ?", [facturacionId]);
  } else {
    const [accountRows] = await connection.execute("SELECT monto FROM cuentas_por_cobrar WHERE id = ? LIMIT 1", [cuentaId]);
    const total = Number(accountRows[0]?.monto || 0);
    const billingSummary = await getAccountsReceivableBillingSummary(cuentaId, total, connection);
    if (billingSummary.remaining > 0.004) {
      const [billingInsert] = await connection.execute(
        `INSERT INTO cuentas_por_cobrar_facturacion (cuenta_id, monto, estado, observaciones, usuario_id)
         VALUES (?, ?, 'Facturada', 'Factura general de cobro consolidado', ?)`,
        [cuentaId, billingSummary.remaining, userId || null]
      );
      facturacionId = Number(billingInsert.insertId);
    } else {
      const [lastBilled] = await connection.execute(
        "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado IN ('Facturada','Pagada') ORDER BY id DESC LIMIT 1",
        [cuentaId]
      );
      facturacionId = Number(lastBilled[0]?.id || 0) || null;
    }
  }
  if (facturacionId) await connection.execute("UPDATE cuentas_por_cobrar_archivos SET facturacion_id = ? WHERE id = ?", [facturacionId, archivoId]);
  return facturacionId;
}

async function getReceivableBatchPaymentBase(relativePath, batch, outstandingTotal) {
  const xml = await readXmlFile(relativePath);
  if (!xml) return { amount: outstandingTotal, fechaPago: null, referencia: "" };
  const parsed = extractPaymentDetailsFromXmlContent(xml);
  let ratio = batch.totalConIva > 0 ? Number(batch.montoCobrar || 0) / Number(batch.totalConIva || 0) : (1 / 1.16);
  const knownInvoiceUuids = new Set();
  for (const item of batch.items || []) {
    const invoices = await getAccountsReceivableInvoiceDocuments(item.cuentaId);
    invoices.forEach((invoice) => knownInvoiceUuids.add(invoice.uuid));
    const matched = invoices.find((invoice) => invoice.total > 0 && invoice.subtotal > 0 && parsed.documents.some((document) => document.uuid === invoice.uuid));
    if (matched) { ratio = matched.subtotal / matched.total; break; }
  }
  const matchedDocuments = parsed.documents.filter((document) => knownInvoiceUuids.has(document.uuid));
  const relevantDocuments = matchedDocuments.length ? matchedDocuments : parsed.documents;
  const paidWithTax = roundMoneyServer(relevantDocuments.reduce((sum, document) => sum + Number(document.paid || 0), 0));
  if (!(paidWithTax > 0)) return { amount: outstandingTotal, fechaPago: parsed.fechaPago, referencia: parsed.referencia };
  return {
    amount: Math.min(outstandingTotal, roundMoneyServer(paidWithTax * ratio)),
    fechaPago: parsed.fechaPago,
    referencia: parsed.referencia
  };
}

async function refreshReceivableBatchCollectionState(batchId) {
  const batch = await getReceivableBatch(batchId);
  if (!batch) return null;
  let paidTotal = 0;
  for (const item of batch.items) {
    const summary = await getAccountsReceivablePaymentSummary(item.cuentaId, item.montoCobrar);
    paidTotal += summary.paid;
  }
  const roundedPaid = roundMoneyServer(paidTotal);
  const fullyPaid = roundedPaid + 0.004 >= Number(batch.montoCobrar || 0);
  let hasAllComplements = false;
  if (fullyPaid && batch.items.length) {
    const [complementRows] = await pool.execute(
      `SELECT COUNT(*) AS completed_items
       FROM lotes_cobro_clientes_items item
       WHERE item.lote_id = ?
         AND EXISTS (
           SELECT 1
           FROM cuentas_por_cobrar_archivos archivo
           WHERE archivo.cuenta_id = item.cuenta_id
             AND archivo.tipo = 'Complemento de pago'
         )`,
      [batchId]
    );
    hasAllComplements = Number(complementRows[0]?.completed_items || 0) === batch.items.length;
  }
  const state = fullyPaid
    ? (hasAllComplements ? "Completado" : "Pendiente complemento")
    : roundedPaid > 0.004 ? "Parcial" : "Pendiente";
  await pool.execute(
    "UPDATE lotes_cobro_clientes SET estado = ?, fecha_cobro = ?, pdf_ruta = '' WHERE id = ?",
    [state, fullyPaid ? (batch.fechaCobro || businessDateOnly()) : null, batchId]
  );
  try { await generateReceivableBatchPdf(batchId); } catch (error) { logServerError(`receivable-batch-payment-pdf-${batchId}`, error); }
  return getReceivableBatch(batchId);
}

async function refreshReceivableBatchForAccount(cuentaId) {
  const [rows] = await pool.execute(
    "SELECT lote_id FROM lotes_cobro_clientes_items WHERE cuenta_id = ? LIMIT 1",
    [cuentaId]
  );
  const batchId = Number(rows[0]?.lote_id || 0);
  return batchId ? refreshReceivableBatchCollectionState(batchId) : null;
}

async function distributeReceivableBatchPayment({ batch, targets, accountDocuments, relativePath, fileName, userId = null }) {
  const connection = await pool.getConnection();
  const outstandingByItem = [];
  try {
    for (const item of targets) {
      const summary = await getAccountsReceivablePaymentSummary(item.cuentaId, item.montoCobrar, connection);
      if (summary.remaining > 0.004) outstandingByItem.push({ item, remaining: summary.remaining });
    }
    const outstandingTotal = roundMoneyServer(outstandingByItem.reduce((sum, entry) => sum + entry.remaining, 0));
    if (outstandingTotal <= 0.004) return;
    const payment = await getReceivableBatchPaymentBase(relativePath, batch, outstandingTotal);
    if (!(payment.amount > 0.004)) return;

    await connection.beginTransaction();
    let allocated = 0;
    for (let index = 0; index < outstandingByItem.length; index += 1) {
      const entry = outstandingByItem[index];
      const isLast = index === outstandingByItem.length - 1;
      const proportional = isLast
        ? roundMoneyServer(payment.amount - allocated)
        : roundMoneyServer(payment.amount * (entry.remaining / outstandingTotal));
      const amount = Math.min(entry.remaining, Math.max(0, proportional));
      if (amount <= 0.004) continue;
      const document = accountDocuments.get(Number(entry.item.id));
      if (!document?.archivoId) throw new Error("No se pudo ligar el comprobante a una de las cuentas.");
      const [billingRows] = await connection.execute(
        "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado IN ('Facturada','Pagada') ORDER BY id ASC LIMIT 1",
        [entry.item.cuentaId]
      );
      const facturacionId = Number(billingRows[0]?.id || 0) || null;
      const [insert] = await connection.execute(
        `INSERT INTO cuentas_por_cobrar_pagos
          (cuenta_id, archivo_id, facturacion_id, monto, fecha_pago, referencia, usuario_id)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [entry.item.cuentaId, document.archivoId, facturacionId, amount, payment.fechaPago || null,
         payment.referencia || fileName || batch.folio, userId || null]
      );
      await connection.execute("UPDATE lotes_cobro_clientes_items SET pago_id = ? WHERE id = ?", [insert.insertId, entry.item.id]);
      allocated = roundMoneyServer(allocated + amount);
    }
    await connection.commit();
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    throw error;
  } finally {
    connection.release();
  }
}

async function registerReceivableBatchDocument({ batch, batchFileId = null, itemId = null, tipo, relativePath, fileName, userId = null }) {
  const targets = itemId ? batch.items.filter((item) => Number(item.id) === Number(itemId)) : batch.items;
  if (!targets.length) throw new Error("No hay proyectos disponibles para ligar el documento.");
  const accountDocuments = new Map();
  for (const item of targets) {
    const document = await createReceivableAccountDocumentCopy({ sourcePath: relativePath, originalName: fileName, cuentaId: item.cuentaId, tipo, batchFileId, userId });
    accountDocuments.set(Number(item.id), document);
    if (tipo === "Factura") await linkReceivableInvoiceDocument({ cuentaId: item.cuentaId, archivoId: document.archivoId, userId });
  }
  if (tipo === "Comprobante de pago") {
    await distributeReceivableBatchPayment({ batch, targets, accountDocuments, relativePath, fileName, userId });
  }
  for (const item of targets) {
    try { await refreshAccountsReceivableStatus(item.cuentaId); } catch (error) { logServerError(`receivable-batch-refresh-${item.cuentaId}`, error); }
  }
  return refreshReceivableBatchCollectionState(batch.id);
}

