function paymentOrderPdfRelativePath(order) {
  return path
    .join("uploads", "ordenes_pago", `${normalizeQuoteFileName(order.folio || `op_${order.id}`)}.pdf`)
    .replace(/\\/g, "/");
}

async function generatePaymentOrderFolio(connection = pool) {
  const yearSuffix = String(businessDateOnly() || new Date().getFullYear()).slice(2, 4);
  const prefix = `OP${yearSuffix}`;
  const [rows] = await connection.execute(
    `SELECT MAX(CAST(SUBSTRING(folio, ?) AS UNSIGNED)) AS last_number
     FROM ordenes_pago
     WHERE folio LIKE ?`,
    [prefix.length + 1, `${prefix}%`]
  );
  const nextNumber = Number(rows[0]?.last_number || 0) + 1;
  return `${prefix}${String(nextNumber).padStart(4, "0")}`;
}

async function getPaymentOrdersByAccount(cuentaId, totalInput = null) {
  if (!cuentaId) return [];
  const [rows] = await pool.execute(
    `SELECT id, cuenta_id, tipo_origen, ocp_id, ocgf_orden_id, folio, monto,
            tipo_movimiento, estado_movimiento, fecha_aplicacion, metodo_pago,
            referencia, observaciones, cancelado_at, pdf_ruta, usuario_id,
            created_at, updated_at
     FROM ordenes_pago
     WHERE cuenta_id = ?
     ORDER BY id ASC`,
    [cuentaId]
  );

  let total = Number(totalInput);
  if (!Number.isFinite(total)) {
    const financial = await getAccountsPayableFinancialSummary(cuentaId);
    total = Number(financial?.total || 0);
  }
  total = Math.max(0, Math.round(total * 100) / 100);

  let runningBalance = total;
  const mapped = rows.map((row) => {
    const amount = Math.max(0, Math.round(Number(row.monto || 0) * 100) / 100);
    const isApplied = String(row.estado_movimiento || "") === "Aplicado";
    const saldoAnterior = runningBalance;
    const saldoPosterior = isApplied
      ? Math.max(0, Math.round((runningBalance - amount) * 100) / 100)
      : runningBalance;
    if (isApplied) runningBalance = saldoPosterior;
    return {
      id: row.id,
      cuentaId: row.cuenta_id,
      source: row.tipo_origen || "OCP",
      orderId: row.tipo_origen === "OCGF" ? row.ocgf_orden_id : row.ocp_id,
      folio: row.folio || "",
      monto: amount,
      tipoMovimiento: row.tipo_movimiento || "Abono",
      estadoMovimiento: row.estado_movimiento || "Pendiente",
      saldoAnterior,
      saldoPosterior,
      fechaAplicacion: row.fecha_aplicacion,
      metodoPago: row.metodo_pago || "",
      referencia: row.referencia || "",
      observaciones: row.observaciones || "",
      canceladoAt: row.cancelado_at,
      pdfRuta: row.pdf_ruta || "",
      pdfUrl: row.pdf_ruta ? `/${String(row.pdf_ruta).replace(/\\/g, "/")}` : "",
      usuarioId: row.usuario_id || null,
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  });
  return mapped.reverse();
}

async function getPaymentOrderById(paymentOrderId) {
  const [rows] = await pool.execute(
    `SELECT id, cuenta_id, tipo_origen, ocp_id, ocgf_orden_id, folio, monto,
            tipo_movimiento, estado_movimiento, fecha_aplicacion, metodo_pago,
            referencia, observaciones, cancelado_at, pdf_ruta, usuario_id,
            created_at, updated_at
     FROM ordenes_pago
     WHERE id = ?
     LIMIT 1`,
    [paymentOrderId]
  );
  const row = rows[0];
  if (!row) return null;
  return {
    id: row.id,
    cuentaId: row.cuenta_id,
    source: row.tipo_origen || "OCP",
    ocpId: row.ocp_id || null,
    ocgfOrderId: row.ocgf_orden_id || null,
    folio: row.folio || "",
    monto: Number(row.monto || 0),
    tipoMovimiento: row.tipo_movimiento || "Abono",
    estadoMovimiento: row.estado_movimiento || "Pendiente",
    fechaAplicacion: row.fecha_aplicacion,
    metodoPago: row.metodo_pago || "",
    referencia: row.referencia || "",
    observaciones: row.observaciones || "",
    canceladoAt: row.cancelado_at,
    pdfRuta: row.pdf_ruta || "",
    pdfUrl: row.pdf_ruta ? `/${String(row.pdf_ruta).replace(/\\/g, "/")}` : "",
    usuarioId: row.usuario_id || null,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

async function getPaymentOrderPdfData(paymentOrderId) {
  const paymentOrder = await getPaymentOrderById(paymentOrderId);
  if (!paymentOrder) return null;

  const isOcgf = paymentOrder.source === "OCGF";
  const order = isOcgf
    ? await getFixedExpenseOrderPdfData(paymentOrder.ocgfOrderId)
    : await getSupplierOrderPreviewData(paymentOrder.ocpId);
  if (!order) return null;

  const accountRows = isOcgf
    ? await getAccountsPayableFixedExpenseRows(paymentOrder.ocgfOrderId)
    : (await getAccountsPayableBaseRows(paymentOrder.ocpId)).map(mapAccountsPayableRow);
  const account = accountRows[0] || {};
  const providerName =
    order.provider?.empresa ||
    order.expense?.proveedorNombre ||
    order.items?.find((item) => item.proveedorNombre)?.proveedorNombre ||
    account.proveedor ||
    "Proveedor";
  const providerContact = [order.provider?.telefono, order.provider?.correo].filter(Boolean).join(" | ");
  const bankData = [
    providerName,
    order.provider?.banco ? `Banco: ${order.provider.banco}` : "",
    order.provider?.cuenta ? `Cuenta: ${order.provider.cuenta}` : "",
    order.provider?.clabe ? `CLABE: ${order.provider.clabe}` : ""
  ]
    .filter(Boolean)
    .join(" | ");
  const items = (order.items || []).map((item) => ({
    cantidad: Number(item.cantidad || 0),
    descripcion: item.descripcion || "",
    precioUnitario: Number(item.precioUnitario || 0),
    total: Number(item.total || 0)
  }));

  return {
    paymentOrder,
    isOcgf,
    order,
    account,
    providerName,
    providerContact,
    paymentTerms: order.provider?.condicionesPago || "Contado",
    bankData,
    items
  };
}

async function generatePaymentOrderPdf(paymentOrderId) {
  const data = await getPaymentOrderPdfData(paymentOrderId);
  if (!data) throw new Error("Orden de pago no encontrada.");

  const { paymentOrder, isOcgf, order, account, providerName, providerContact, paymentTerms, bankData, items } = data;
  const relativePath = paymentOrderPdfRelativePath(paymentOrder);
  const absolutePath = path.join(__dirname, relativePath);
  await fs.promises.mkdir(path.dirname(absolutePath), { recursive: true });

  await new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: "LETTER",
      margin: 30,
      bufferPages: true,
      info: {
        Title: `Orden de pago ${paymentOrder.folio}`,
        Author: "DALVO SOLUTIONS SA DE CV"
      }
    });
    const stream = fs.createWriteStream(absolutePath);
    stream.on("finish", resolve);
    stream.on("error", reject);
    doc.on("error", reject);
    doc.pipe(stream);

    const shortDate = new Intl.DateTimeFormat("es-MX", {
      day: "numeric",
      month: "numeric",
      year: "numeric"
    }).format(new Date(paymentOrder.createdAt || new Date()));
    const orderFolio = isOcgf ? account.ocgf || order.folio : account.ocp || order.folio;
    const originFolio = isOcgf ? account.gasto || order.expense?.gasto || "" : account.dlv || order.budget?.folio || "";

    if (fs.existsSync(DALVO_QUOTE_LOGO)) {
      doc.image(DALVO_QUOTE_LOGO, 52, 38, { width: 170 });
    }

    doc.fillColor("#000").font("Helvetica-Bold").fontSize(13).text("Orden de pago", 360, 30, {
      width: 190,
      align: "right"
    });
    doc.fontSize(10).text(providerName.toUpperCase(), 300, 48, { width: 250, align: "right" });
    doc.font("Helvetica").fontSize(8).text(`Folio ${paymentOrder.folio}`, 390, 82, {
      width: 160,
      align: "right"
    });
    doc.text(`Fecha: ${shortDate}`, 390, 96, { width: 160, align: "right" });

    doc.font("Helvetica-Bold").fontSize(10).text("DATOS DE LA ORDEN", 32, 145, { underline: true });
    doc.fontSize(8).text("Empresa emisora", 32, 176);
    doc.font("Helvetica").fontSize(8).text("DALVO SOLUTIONS SA DE CV", 32, 191);
    doc.text("RFC: DSO250131KZ9", 32, 204);
    doc.text(isOcgf ? `Gasto fijo: ${originFolio || orderFolio}` : `Folio origen: ${originFolio || orderFolio}`, 32, 217);
    doc.text(`${isOcgf ? "OCGF" : "OCP"}: ${orderFolio || ""}`, 32, 230);

    doc.font("Helvetica-Bold").text("Proveedor", 350, 176, { width: 200, align: "right" });
    doc.font("Helvetica").text(`Nombre: ${providerName}`, 350, 191, { width: 200, align: "right" });
    doc.text(`Contacto: ${providerContact || "N/A"}`, 350, 204, { width: 200, align: "right" });
    doc.text(`Condiciones de pago: ${paymentTerms || "Contado"}`, 350, 230, {
      width: 200,
      align: "right"
    });

    doc.font("Helvetica-Bold").fontSize(10).text("DATOS BANCARIOS", 32, 270, { underline: true });
    doc.font("Helvetica").fontSize(7.5).text(bankData || "Sin datos bancarios capturados", 32, 289, {
      width: 515
    });

    doc.font("Helvetica-Bold").fontSize(10).text("DETALLE DE PRODUCTOS A PAGAR", 32, 330, {
      underline: true
    });
    let y = 354;
    doc.rect(32, y, 515, 18).fill("#273142");
    doc.fillColor("#fff").font("Helvetica-Bold").fontSize(6.8);
    doc.text("Cantidad", 38, y + 6, { width: 58 });
    doc.text("Descripción", 100, y + 6, { width: 265 });
    doc.text("Precio", 370, y + 6, { width: 76, align: "right" });
    doc.text("Subtotal", 464, y + 6, { width: 76, align: "right" });
    y += 18;

    doc.fillColor("#071225").font("Helvetica").fontSize(7);
    for (const item of items) {
      const height = Math.max(19, doc.heightOfString(item.descripcion || "", { width: 255 }) + 9);
      if (y + height > 690) {
        doc.addPage();
        y = 48;
      }
      doc.rect(32, y, 515, height).strokeColor("#dbe4ea").lineWidth(0.5).stroke();
      doc.text(Number(item.cantidad || 0).toFixed(0), 38, y + 6, { width: 58 });
      doc.text(item.descripcion || "", 100, y + 6, { width: 255 });
      doc.text(formatCurrencyServer(item.precioUnitario || 0), 370, y + 6, { width: 76, align: "right" });
      doc.text(formatCurrencyServer(item.total || 0), 464, y + 6, { width: 76, align: "right" });
      y += height;
    }

    y += 18;
    doc.fillColor("#071225").font("Helvetica-Bold").fontSize(10);
    doc.text(`Monto autorizado a pagar con IVA: ${formatCurrencyServer(paymentOrder.monto)}`, 292, y, {
      width: 255,
      align: "right"
    });
    doc.font("Helvetica-Bold").fontSize(9).text(`Folio ${paymentOrder.folio}`, 145, y, { width: 140, align: "center" });

    const range = doc.bufferedPageRange();
    for (let i = range.start; i < range.start + range.count; i += 1) {
      doc.switchToPage(i);
      drawQuoteFooter(doc, i + 1 - range.start, range.count);
    }
    doc.end();
  });

  await pool.execute("UPDATE ordenes_pago SET pdf_ruta = ? WHERE id = ?", [relativePath, paymentOrderId]);
  return relativePath;
}

