app.get("/api/commissions/budget-by-folio", requireAuth, async (req, res) => {
  if (!canManageCommissions(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes acceso al módulo de comisiones." });
  }
  const folio = String(req.query.folio || "").trim();
  if (!folio) return res.status(400).json({ ok: false, message: "Captura el folio del presupuesto." });

  try {
    let budget = await getBudgetByFolioForManualCommission(folio, req.session.user);
    if (!budget) return res.status(404).json({ ok: false, message: "No se encontró un presupuesto con ese folio." });

    // La comisión extraordinaria se calcula sobre PVP2: la última versión de la
    // cotización al cliente, sin IVA y después del descuento comercial de esa cotización.
    const pvp2 = await getLatestClientQuotePvp2(budget.id);
    if (!pvp2 || Number(pvp2.monto || 0) <= 0) {
      return res.status(409).json({
        ok: false,
        message: "Este proyecto todavía no tiene una cotización cliente versionada con monto válido para calcular la comisión extraordinaria."
      });
    }

    // PVP1 se conserva como referencia financiera: costo depurado × factor de venta.
    try {
      budget = (await getBudgetWithDedupedCostTotals(budget.id)) || budget;
    } catch (_costError) {
      // Si el histórico no permite recalcular, conservamos el presupuesto recuperado.
    }
    const pvp1 = Number(budget.precioVenta || 0) || calculateBudgetSalePriceServer(budget);

    res.json({
      ok: true,
      budget: {
        presupuestoId: budget.id,
        supervisorId: budget.ownerId || null,
        supervisorNombre: budget.owner || "Sin supervisor",
        nombreProyecto: budget.tituloProyecto || budget.folio || "",
        descripcionProyecto: budget.folio || "",
        empresa: budget.empresa || "",
        folioPresupuesto: budget.folio || "",
        montoProyecto: Number(pvp2.monto || 0),
        porcentajeComision: 0,
        montoComision: 0,
        montoComisionBase: 0,
        presupuestoAdicional: 0,
        montoComisionMenosPa: 0,
        manualCommission: true,
        pvp1,
        pvp2Version: Number(pvp2.version || 0),
        pvp2Folio: pvp2.folio || ""
      }
    });
  } catch (error) {
    logServerError("commissions-budget-by-folio", error);
    res.status(500).json({
      ok: false,
      message: `No se pudo cargar el presupuesto para comisión extraordinaria. Detalle: ${error.sqlMessage || error.message || "sin detalle"}`
    });
  }
});

app.post("/api/commissions", requireAuth, async (req, res) => {
  if (!canManageCommissions(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para generar comisiones." });
  }

  const presupuestoId = Number(req.body.presupuestoId || 0);
  const isManualCommission = Boolean(req.body.manualCommission);
  const commissionItems = Array.isArray(req.body.items)
    ? req.body.items
    : [{ supervisorId: req.body.supervisorId, montoComision: req.body.montoComision }];
  const normalizedItems = commissionItems
    .map((item) => ({
      supervisorId: Number(item?.supervisorId || 0),
      nombreManual: String(item?.nombreManual || item?.supervisorNombre || "").trim(),
      descuento: 0,
      porcentajeComision: Number(item?.porcentajeComision || 0),
      porcentajeDistribucion: Number(item?.porcentajeDistribucion || 0),
      montoComision: Math.round(Number(item?.montoComision || 0) * 100) / 100
    }))
    .filter((item) => (item.supervisorId || item.nombreManual) && !Number.isNaN(item.montoComision) && Math.abs(item.montoComision) > 0.009);
  if (!presupuestoId || !normalizedItems.length) {
    return res.status(400).json({ ok: false, message: "Selecciona presupuesto, persona y monto de comisión válido." });
  }
  if (!(await canAccessBudget(
    req.session.user,
    presupuestoId,
    "modulo:comisiones",
    "accion:generar-comisiones"
  ))) {
    return res.status(403).json({
      ok: false,
      message: "No tienes permiso para generar comisiones de esta sucursal."
    });
  }
  const userAssignedIds = normalizedItems.map((item) => item.supervisorId).filter(Boolean);
  if (new Set(userAssignedIds).size !== userAssignedIds.length) {
    return res.status(400).json({ ok: false, message: "No puedes asignar la misma comisión dos veces al mismo supervisor." });
  }

  let connection;
  let committed = false;
  try {
    await ensureCommissionTables();
    connection = await pool.getConnection();
    await connection.beginTransaction();

    let budget = isManualCommission
      ? await getBudgetByIdForManualCommission(presupuestoId)
      : await getBudgetById(presupuestoId);
    if (!budget) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    }
    // Toda comisión usa el mismo costo depurado que el Resumen Financiero.
    // Esto evita inflar PVP1 cuando existen filas históricas idénticas duplicadas.
    try {
      budget = (await getBudgetWithDedupedCostTotals(budget.id)) || budget;
    } catch (_costError) {
      // Conservamos compatibilidad con históricos incompletos.
    }

    let manualPvp2 = null;
    if (isManualCommission) {
      manualPvp2 = await getLatestClientQuotePvp2(budget.id, connection);
      if (!manualPvp2 || Number(manualPvp2.monto || 0) <= 0) {
        await connection.rollback();
        return res.status(409).json({
          ok: false,
          message: "La comisión extraordinaria requiere una última cotización cliente (PVP2) con monto válido."
        });
      }
      const invalidManualRate = normalizedItems.find(
        (item) => !Number.isFinite(Number(item.porcentajeComision)) || Number(item.porcentajeComision) <= 0 || Number(item.porcentajeComision) > 5
      );
      if (invalidManualRate) {
        await connection.rollback();
        return res.status(400).json({
          ok: false,
          message: "La comisión extraordinaria debe ser mayor a 0% y no puede exceder el 5% del PVP2."
        });
      }
    }

    const commissionPaymentDateMap = await getCommissionBudgetPaymentDateMap([budget.id]);
    if (!isManualCommission && !commissionPaymentDateMap.has(Number(budget.id))) {
      await connection.rollback();
      return res.status(400).json({ ok: false, message: "La comisión solo se puede generar cuando el proyecto tiene complemento de pago cargado." });
    }

    const supervisorIds = [...new Set(normalizedItems.map((item) => item.supervisorId).filter(Boolean))];
    let supervisorRows = [];
    if (supervisorIds.length) {
      const placeholders = supervisorIds.map(() => "?").join(",");
      [supervisorRows] = await connection.execute(
        `SELECT
            u.user_id AS id,
            COALESCE(NULLIF(CONCAT_WS(' ', u.nombre, u.apellido), ''), u.usuario) AS nombre,
            COALESCE(u.comision_supervisor, 0) AS comision_supervisor
          FROM usuarios u
          INNER JOIN roles r ON r.id = u.rol_id
          WHERE u.user_id IN (${placeholders}) AND LOWER(r.nombre) IN ('supervisor', 'superadmin')`,
        supervisorIds
      );
    }
    const supervisorMap = new Map(supervisorRows.map((row) => [Number(row.id), row]));
    const missingSupervisor = normalizedItems.find((item) => item.supervisorId && !supervisorMap.has(Number(item.supervisorId)));
    if (missingSupervisor) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Supervisor no encontrado." });
    }
    if (!isManualCommission && supervisorIds.length) {
      const placeholders = supervisorIds.map(() => "?").join(",");
      const [existingSupervisorCommissions] = await connection.execute(
        `SELECT supervisor_id, folio
           FROM comisiones
          WHERE presupuesto_id = ?
            AND supervisor_id IN (${placeholders})
            AND COALESCE(supervisor_nombre_manual, '') = ''
            AND LOWER(COALESCE(estatus, '')) NOT IN (
              'cancelada', 'cancelado', 'eliminada', 'eliminado', 'rechazada', 'rechazado', 'no aprobada', 'no aprobado'
            )
          LIMIT 1`,
        [presupuestoId, ...supervisorIds]
      );
      if (existingSupervisorCommissions.length) {
        await connection.rollback();
        return res.status(400).json({
          ok: false,
          message: "Ya existe una OCCOM activa para ese supervisor en este presupuesto. Elimina la anterior antes de generar otra."
        });
      }
    }

    const montoProyecto = isManualCommission
      ? Number(manualPvp2?.monto || 0)
      : Number(budget.precioVenta || 0) || calculateBudgetSalePriceServer(budget);
    const descripcionProyecto = budget.folio || "";
    const createdFolios = [];
    const createdCommissionIds = [];
    const ownerSupervisor = supervisorMap.get(Number(budget.ownerId || 0)) || null;
    const commissionAmountForItem = (item) => isManualCommission
      ? roundMoneyServer(montoProyecto * (Number(item.porcentajeComision || 0) / 100))
      : roundMoneyServer(item.montoComision || 0);
    const requestedTotal = roundMoneyServer(normalizedItems.reduce((sum, item) => sum + commissionAmountForItem(item), 0));
    const baseAvailable = isManualCommission
      ? requestedTotal
      : await getCommissionAvailableForBudget(budget, ownerSupervisor);
    const remainingAvailable = Math.max(0, baseAvailable);
    const distributionTotal = normalizedItems.reduce((sum, item) => sum + Number(item.porcentajeDistribucion || 0), 0);
    if (!isManualCommission && distributionTotal > 100.01) {
      await connection.rollback();
      return res.status(400).json({ ok: false, message: "El porcentaje asignado no puede exceder el 100%." });
    }
    if (!isManualCommission && requestedTotal > remainingAvailable + 0.01) {
      await connection.rollback();
      return res.status(400).json({
        ok: false,
        message: `La comisión excede el disponible (${formatCurrencyServer(remainingAvailable)}).`
      });
    }

    for (const item of normalizedItems) {
      const supervisor = supervisorMap.get(Number(item.supervisorId));
      const porcentajeComision = isManualCommission
        ? Number(item.porcentajeComision || 0)
        : Number(supervisor.comision_supervisor || 0);
      const montoComisionCalculado = commissionAmountForItem(item);
      if (isManualCommission && montoComisionCalculado > roundMoneyServer(montoProyecto * 0.05) + 0.01) {
        await connection.rollback();
        return res.status(400).json({ ok: false, message: "La comisión extraordinaria no puede exceder el 5% del PVP2." });
      }
      const folio = await generateCommissionFolio(connection, budget, createdFolios);
      createdFolios.push(folio);
      const [insertResult] = await connection.execute(
        `INSERT INTO comisiones
          (presupuesto_id, supervisor_id, supervisor_nombre_manual, folio, nombre_proyecto, descripcion_proyecto, empresa,
           monto_proyecto, porcentaje_comision, porcentaje_distribucion, descuento, monto_comision, estatus, usuario_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          presupuestoId,
          item.supervisorId || null,
          item.supervisorId ? "" : item.nombreManual,
          folio,
          budget.tituloProyecto || budget.folio || "",
          descripcionProyecto,
          budget.empresa || "",
          montoProyecto,
          porcentajeComision,
          item.porcentajeDistribucion || 100,
          item.descuento || 0,
          montoComisionCalculado,
          "Aprobada",
          req.session.user?.id || null
        ]
      );
      createdCommissionIds.push(Number(insertResult.insertId || 0));
    }
    await connection.commit();
    committed = true;
    const payableErrors = [];
    for (const commissionId of createdCommissionIds.filter(Boolean)) {
      try {
        await ensureAccountsPayableRecordForCommission(commissionId, req.session.user?.id || null);
      } catch (payableError) {
        payableErrors.push(commissionId);
        logServerError(`commissions-create-payable:${commissionId}`, payableError);
      }
    }
    res.status(201).json({
      ok: true,
      folio: createdFolios[0] || "",
      folios: createdFolios,
      createdCommissionIds,
      payableWarning: payableErrors.length
        ? "La comisión se generó, pero cuentas por pagar se sincronizará al abrir el módulo."
        : ""
    });
  } catch (error) {
    if (connection && !committed) await connection.rollback();
    logServerError("commissions-create", error);
    const message = error.code === "ER_DUP_ENTRY" ? "Ya existe una comisión con ese folio." : "No se pudo generar la comisión.";
    res.status(500).json({ ok: false, message });
  } finally {
    connection?.release();
  }
});

app.delete("/api/commissions/:commissionId", requireAuth, requireDeletePermission, async (req, res) => {
  const commissionId = Number(req.params.commissionId || 0);
  if (!commissionId) return res.status(400).json({ ok: false, message: "OCCOM inválida." });

  let connection;
  try {
    await ensureCommissionTables();
    await ensureAccountsPayableTables();
    connection = await pool.getConnection();
    await connection.beginTransaction();
    const [rows] = await connection.execute(
      `SELECT c.id, COALESCE(cp.pagado, 0) AS pagado
       FROM comisiones c
       LEFT JOIN cuentas_por_pagar cp
         ON cp.comision_id = c.id
        AND cp.tipo_origen = 'OCCOM'
       WHERE c.id = ?
       LIMIT 1
       FOR UPDATE`,
      [commissionId]
    );
    if (!rows.length) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "OCCOM no encontrada." });
    }
    if (Boolean(rows[0].pagado)) {
      await connection.rollback();
      return res.status(409).json({
        ok: false,
        message: "No se puede eliminar una OCCOM que ya fue pagada."
      });
    }
    await detachLegacyCommissionCreditApplication(
      connection,
      commissionId,
      req.session.user?.id || null
    );
    await connection.execute(
      `DELETE FROM cuentas_por_pagar_archivos
       WHERE cuenta_id IN (
         SELECT id FROM cuentas_por_pagar WHERE tipo_origen = 'OCCOM' AND comision_id = ?
       )`,
      [commissionId]
    );
    await connection.execute(
      `DELETE FROM ordenes_pago
       WHERE cuenta_id IN (
         SELECT id FROM cuentas_por_pagar WHERE tipo_origen = 'OCCOM' AND comision_id = ?
       )`,
      [commissionId]
    );
    await connection.execute("DELETE FROM cuentas_por_pagar WHERE tipo_origen = 'OCCOM' AND comision_id = ?", [commissionId]);
    await connection.execute("DELETE FROM comisiones WHERE id = ?", [commissionId]);
    await connection.commit();
    const data = await getCommissionsPayload(req.session.user, "");
    res.json({ ok: true, ...data });
  } catch (error) {
    if (connection) await connection.rollback();
    logServerError("commissions-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar la OCCOM." });
  } finally {
    if (connection) connection.release();
  }
});

app.post("/api/commissions/:commissionId/approve", requireAuth, async (req, res) => {
  if (!canApproveCommissions(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para aprobar comisiones." });
  }
  const commissionId = Number(req.params.commissionId);
  if (!commissionId) return res.status(400).json({ ok: false, message: "OCCOM inválida." });

  try {
    await ensureCommissionTables();
    await ensureAccountsPayableTables();
    const [rows] = await pool.execute("SELECT id FROM comisiones WHERE id = ? LIMIT 1", [commissionId]);
    if (!rows.length) return res.status(404).json({ ok: false, message: "OCCOM no encontrada." });
    await pool.execute("UPDATE comisiones SET estatus = 'Aprobada', updated_at = CURRENT_TIMESTAMP WHERE id = ?", [commissionId]);
    await ensureAccountsPayableRecordForCommission(commissionId, req.session.user?.id || null);
    const data = await getCommissionsPayload(req.session.user, "");
    res.json({ ok: true, ...data });
  } catch (error) {
    logServerError("commissions-approve", error);
    res.status(500).json({ ok: false, message: "No se pudo aprobar la OCCOM." });
  }
});

app.post("/api/commissions/:commissionId/reject", requireAuth, async (req, res) => {
  if (!canApproveCommissions(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para rechazar comisiones." });
  }
  const commissionId = Number(req.params.commissionId);
  if (!commissionId) return res.status(400).json({ ok: false, message: "OCCOM inválida." });

  try {
    await ensureCommissionTables();
    const [result] = await pool.execute(
      "UPDATE comisiones SET estatus = 'No aprobada', updated_at = CURRENT_TIMESTAMP WHERE id = ?",
      [commissionId]
    );
    if (!result.affectedRows) return res.status(404).json({ ok: false, message: "OCCOM no encontrada." });
    const data = await getCommissionsPayload(req.session.user, "");
    res.json({ ok: true, ...data });
  } catch (error) {
    logServerError("commissions-reject", error);
    res.status(500).json({ ok: false, message: "No se pudo rechazar la OCCOM." });
  }
});

