app.post(
  "/api/budgets/shared-client-po",
  requireAuth,
  uploadBudgetFile.single("poArchivo"),
  async (req, res) => {
    const relativePath = req.file ? path.relative(__dirname, req.file.path).replace(/\\/g, "/") : "";
    const fileName = req.file?.originalname || "";
    const connection = await pool.getConnection();
    let transactionStarted = false;
    let committed = false;

    try {
      await ensureBudgetTables();
      await ensureAccountsReceivableTables();

      let rawBudgetIds = req.body.budgetIds;
      if (typeof rawBudgetIds === "string") {
        try {
          rawBudgetIds = JSON.parse(rawBudgetIds);
        } catch {
          rawBudgetIds = rawBudgetIds.split(",");
        }
      }
      const budgetIds = [...new Set((Array.isArray(rawBudgetIds) ? rawBudgetIds : [])
        .map((value) => Number(value || 0))
        .filter(Boolean))];
      const numeroPo = String(req.body.numeroPo || (fileName ? path.parse(fileName).name : "")).trim();
      const montoTotal = roundMoneyServer(req.body.montoTotal || 0);

      if (budgetIds.length < 2) {
        const error = new Error("Selecciona al menos dos presupuestos para compartir la PO.");
        error.statusCode = 400;
        throw error;
      }
      if (!req.file) {
        const error = new Error("Selecciona el archivo de la PO compartida.");
        error.statusCode = 400;
        throw error;
      }
      if (!numeroPo) {
        const error = new Error("Captura el numero de la PO.");
        error.statusCode = 400;
        throw error;
      }
      if (montoTotal <= 0) {
        const error = new Error("Captura el monto total de la PO.");
        error.statusCode = 400;
        throw error;
      }

      if (!canManageClientPo(req.session.user || {})) {
        for (const budgetId of budgetIds) {
          if (!(await canAccessBudget(req.session.user, budgetId, "modulo:presupuesto", "accion:subir-archivos"))) {
            const error = new Error("No tienes acceso para administrar la PO de uno o mas presupuestos seleccionados.");
            error.statusCode = 403;
            throw error;
          }
        }
      }

      await connection.beginTransaction();
      transactionStarted = true;
      const placeholders = budgetIds.map(() => "?").join(",");
      const [budgets] = await connection.execute(
        `SELECT id, empresa, folio, titulo_proyecto, po, estado, estatus
         FROM presupuestos
         WHERE id IN (${placeholders})
         ORDER BY id
         FOR UPDATE`,
        budgetIds
      );
      if (budgets.length !== budgetIds.length) {
        const error = new Error("Uno o mas presupuestos seleccionados ya no existen.");
        error.statusCode = 404;
        throw error;
      }

      const companyKeys = new Set(budgets.map((budget) => normalizeWorkflowValue(budget.empresa)));
      if (companyKeys.size !== 1) {
        const error = new Error("Todos los presupuestos de una PO compartida deben pertenecer a la misma empresa.");
        error.statusCode = 409;
        throw error;
      }
      const closedBudget = budgets.find((budget) => isBudgetWorkflowClosed(budget));
      if (closedBudget) {
        const error = new Error(`${closedBudget.folio} esta cerrado y no puede recibir una PO.`);
        error.statusCode = 409;
        throw error;
      }

      const [activePoRows] = await connection.execute(
        `SELECT presupuesto_id
         FROM presupuesto_po_cliente
         WHERE presupuesto_id IN (${placeholders})
           AND COALESCE(estado_documento, 'Activo') = 'Activo'
           AND deleted_at IS NULL`,
        budgetIds
      );
      const activePoBudgetIds = new Set(activePoRows.map((row) => Number(row.presupuesto_id)));
      const budgetWithPo = budgets.find((budget) => activePoBudgetIds.has(Number(budget.id)) || String(budget.po || "").trim());
      if (budgetWithPo) {
        const error = new Error(`${budgetWithPo.folio} ya tiene una PO activa. Quitala antes de asignar una PO compartida.`);
        error.statusCode = 409;
        throw error;
      }

      const assignments = [];
      for (const budget of budgets) {
        const quoteId = await getLatestApprovedClientQuoteIdByBudget(budget.id, connection);
        if (!quoteId) {
          const error = new Error(`${budget.folio} no tiene una cotizacion de cliente aprobada.`);
          error.statusCode = 409;
          throw error;
        }
        const totals = await getClientQuoteTotalWithTax(quoteId, connection);
        assignments.push({
          budgetId: Number(budget.id),
          quoteId,
          folio: budget.folio || "",
          monto: roundMoneyServer(totals.subtotal || 0)
        });
      }
      const calculatedTotal = roundMoneyServer(assignments.reduce((sum, assignment) => sum + assignment.monto, 0));
      if (Math.abs(calculatedTotal - montoTotal) > 0.05) {
        const error = new Error(
          `El monto de la PO (${formatCurrencyServer(montoTotal)}) no coincide con las cotizaciones seleccionadas (${formatCurrencyServer(calculatedTotal)}).`
        );
        error.statusCode = 409;
        error.details = { montoPo: montoTotal, montoCotizaciones: calculatedTotal };
        throw error;
      }

      const [duplicatePoRows] = await connection.execute(
        `SELECT id
         FROM po_cliente_compartidas
         WHERE LOWER(TRIM(numero_po)) = LOWER(TRIM(?))
           AND estado = 'Activa'
         LIMIT 1`,
        [numeroPo]
      );
      if (duplicatePoRows.length) {
        const error = new Error(`La PO ${numeroPo} ya esta asignada como PO compartida.`);
        error.statusCode = 409;
        throw error;
      }

      const [sharedResult] = await connection.execute(
        `INSERT INTO po_cliente_compartidas
          (numero_po, monto_total, empresa, nombre, ruta, estado, usuario_id)
         VALUES (?, ?, ?, ?, ?, 'Activa', ?)`,
        [numeroPo, montoTotal, budgets[0].empresa || "", fileName, relativePath, req.session.user?.id || null]
      );
      const sharedPoId = Number(sharedResult.insertId);

      for (const assignment of assignments) {
        await connection.execute(
          `INSERT INTO presupuesto_po_cliente
            (presupuesto_id, po_compartida_id, numero_po, sin_po, nombre, ruta, monto_asignado, estado_documento, usuario_id)
           VALUES (?, ?, ?, 0, ?, ?, ?, 'Activo', ?)`,
          [
            assignment.budgetId,
            sharedPoId,
            numeroPo,
            fileName,
            relativePath,
            assignment.monto,
            req.session.user?.id || null
          ]
        );
        await connection.execute(
          `UPDATE presupuestos
           SET po = ?, estado = 'En proceso', updated_at = NOW()
           WHERE id = ?`,
          [numeroPo, assignment.budgetId]
        );
      }

      await connection.commit();
      committed = true;

      const accountIds = [];
      const syncWarnings = [];
      for (const assignment of assignments) {
        try {
          const accountId = await ensureAccountsReceivableRecord(assignment.quoteId, req.session.user?.id || null);
          if (accountId) accountIds.push(Number(accountId));
          else syncWarnings.push(`${assignment.folio}: no se pudo crear la CxC.`);
        } catch (syncError) {
          logServerError("shared-client-po-receivable-sync", syncError);
          syncWarnings.push(`${assignment.folio}: no se pudo crear la CxC.`);
        }
      }

      res.status(201).json({
        ok: true,
        sharedPo: {
          id: sharedPoId,
          numeroPo,
          montoTotal,
          empresa: budgets[0].empresa || "",
          nombre: fileName,
          url: relativePath ? `/${relativePath}` : "",
          projects: assignments
        },
        accountIds,
        warnings: syncWarnings
      });
    } catch (error) {
      if (transactionStarted && !committed) await connection.rollback();
      if (!committed && relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
      logServerError("shared-client-po-save", error);
      res.status(error.statusCode || 500).json({
        ok: false,
        message: error.message || "No se pudo guardar la PO compartida.",
        ...(error.details || {})
      });
    } finally {
      connection.release();
    }
  }
);

app.use("/api/budgets/:id", requireAuth, requireBudgetAccess);

function normalizeExcelHeader(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "");
}

function getExcelValue(row, names) {
  for (const name of names) {
    if (row[name] !== undefined && row[name] !== null) return row[name];
  }
  return "";
}

app.get("/api/budgets/materials-template", requireAuth, (_req, res) => {
  const workbook = XLSX.utils.book_new();
  const worksheet = XLSX.utils.aoa_to_sheet([
    ["Descripción", "Cantidad", "Unidad", "Costo"],
    ["Tornillo hexagonal 1/2", 100, "PZA", 12.5]
  ]);
  XLSX.utils.book_append_sheet(workbook, worksheet, "Materiales");
  const buffer = XLSX.write(workbook, { type: "buffer", bookType: "xlsx" });

  res.setHeader(
    "Content-Type",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
  );
  res.setHeader("Content-Disposition", 'attachment; filename="plantilla-materiales.xlsx"');
  res.send(buffer);
});

app.post(
  "/api/budgets/import-materials-excel",
  requireAuth,
  uploadExcelFile.single("archivo"),
  async (req, res) => {
    if (!req.file) {
      return res.status(400).json({ ok: false, message: "Selecciona un archivo Excel." });
    }

    try {
      const workbook = XLSX.read(req.file.buffer, { type: "buffer" });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });

      const materiales = rows
        .map((row) => {
          const normalizedRow = {};
          for (const [key, value] of Object.entries(row)) {
            normalizedRow[normalizeExcelHeader(key)] = value;
          }

          return {
            descripcion: String(
              getExcelValue(normalizedRow, ["descripcion", "description", "material"])
            ).trim(),
            cantidad: Number(getExcelValue(normalizedRow, ["cantidad", "cant", "qty"]) || 0),
            unidad: String(getExcelValue(normalizedRow, ["unidad", "unit", "um"])).trim(),
            costo: Number(getExcelValue(normalizedRow, ["costo", "cost", "precio"]) || 0)
          };
        })
        .filter((row) => row.descripcion);

      res.json({ ok: true, materiales });
    } catch (error) {
      logServerError("materials-excel-import", error);
      res.status(400).json({ ok: false, message: "No se pudo leer el archivo Excel." });
    }
  }
);

async function insertBudgetCosts(connection, budgetId, budget) {
  const cleanCosts = cleanBudgetCosts(budget);

  for (const row of cleanCosts.equipos) {
    await connection.execute(
      `INSERT INTO presupuesto_costos_equipos
        (presupuesto_id, item_precio_id, item, cantidad_equipos, cantidad_um, unidad_medida,
         costo_unitario, flete, subtotal)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        budgetId,
        row.itemPrecioId,
        row.item,
        row.cantidadEquipos,
        row.cantidadUm,
        row.unidadMedida,
        row.costoUnitario,
        row.flete,
        row.subtotal
      ]
    );
  }

  for (const row of cleanCosts.contratistas) {
    await connection.execute(
      `INSERT INTO presupuesto_costos_contratistas
        (presupuesto_id, descripcion, cantidad, costo, subtotal)
       VALUES (?, ?, ?, ?, ?)`,
      [budgetId, row.descripcion, row.cantidad, row.costo, row.subtotal]
    );
  }

  for (const row of cleanCosts.manoObra) {
    await connection.execute(
      `INSERT INTO presupuesto_costos_mano_obra
        (presupuesto_id, item_precio_id, descripcion, personas, horas, horas_total,
         costo_hora, comidas, costo_comida, subtotal)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        budgetId,
        row.itemPrecioId,
        row.descripcion,
        row.personas,
        row.horas,
        row.horasTotal,
        row.costoHora,
        row.comidas,
        row.costoComida,
        row.subtotal
      ]
    );
  }

  for (const row of cleanCosts.materiales) {
    await connection.execute(
      `INSERT INTO presupuesto_costos_materiales
        (presupuesto_id, descripcion, cantidad, unidad, costo, subtotal)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [budgetId, row.descripcion, row.cantidad, row.unidad, row.costo, row.subtotal]
    );
  }
}

app.post("/api/budgets", requireAuth, async (req, res) => {
  const parsed = parseBudgetPayload(req.body);
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });

  const budget = parsed.payload;
  if (budget.folioManual && !isSuperAdminSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "Solo superadmin puede capturar folio manual." });
  }
  const connection = await pool.getConnection();

  try {
    await connection.beginTransaction();
    const contact = await resolveBudgetContactSelection(connection, budget.clienteId, budget.sucursalId);
    if (!contact) {
      await connection.rollback();
      return res.status(400).json({
        ok: false,
        message: "El cliente / usuario no pertenece a la ubicación seleccionada. Actualiza los catálogos e inténtalo de nuevo."
      });
    }
    budget.empresa = String(contact.empresa || "").trim();
    budget.sucursalId = Number(contact.sucursal_id || 0) || null;
    budget.sucursal = normalizeClientBranchLabel(contact.sucursal || "");
    budget.clienteUsuario = String(contact.nombre || "").trim();
    const responsibleId = await resolveBudgetResponsibleId(
      connection,
      budget.responsableId,
      req.session.user || {},
      req.session.user?.id || null
    );
    if (!responsibleId) {
      await connection.rollback();
      return res.status(400).json({ ok: false, message: "Selecciona un responsable interno activo." });
    }
    const folio = budget.folioManual ? budget.folio : await generateBudgetFolio(connection, budget.empresa);

    const [result] = await connection.execute(
      `INSERT INTO presupuestos
        (cliente_id, empresa_id, sucursal_id, empresa, sucursal, cliente_usuario, area, titulo_proyecto, folio, folio_manual, sin_garantia, estado, estatus, usuario_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        budget.clienteId,
        Number(contact.empresa_id || 0) || null,
        budget.sucursalId,
        budget.empresa,
        budget.sucursal,
        budget.clienteUsuario,
        budget.area,
        budget.tituloProyecto,
        folio,
        budget.folioManual ? 1 : 0,
        budget.sinGarantia ? 1 : 0,
        "Abierta",
        "En espera de aprobación",
        responsibleId
      ]
    );

    const budgetId = result.insertId;
    await insertBudgetCosts(connection, budgetId, budget);

    await connection.commit();
    res.status(201).json({ ok: true, budgetId, folio });
  } catch (error) {
    await connection.rollback();
    logServerError("budgets-create", error);
    const message = error.code === "ER_DUP_ENTRY" ? "Ese folio ya existe." : "No se pudo crear el presupuesto.";
    res.status(error.code === "ER_DUP_ENTRY" ? 409 : 500).json({ ok: false, message });
  } finally {
    connection.release();
  }
});

app.put("/api/budgets/:id", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  const parsed = parseBudgetPayload(req.body, { allowLegacyBranch: true });
  if (parsed.error) return res.status(400).json({ ok: false, message: parsed.error });

  const budget = parsed.payload;
  const connection = await pool.getConnection();

  try {
    await connection.beginTransaction();
    const [existingRows] = await connection.execute(
      `SELECT id, folio, folio_manual, estatus, estado, usuario_id,
              cliente_id, sucursal_id, empresa, sucursal, cliente_usuario
       FROM presupuestos
       WHERE id = ?
       FOR UPDATE`,
      [budgetId]
    );
    const existing = existingRows[0];
    if (!existing) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    }
    if (existing.estado === "Cerrada") {
      await connection.rollback();
      return res.status(409).json({
        ok: false,
        message: "No puedes editar presupuestos cerrados."
      });
    }
    if (shouldRestrictToOwnedBudgets(req.session.user || {}) && (await budgetHasApprovedClientQuote(budgetId, connection))) {
      await connection.rollback();
      return res.status(403).json({
        ok: false,
        message: "La cotización ya fue aprobada. Solicita al administrador cualquier ajuste de costos."
      });
    }

    if (budget.folioManual && !isSuperAdminSession(req.session.user)) {
      await connection.rollback();
      return res.status(403).json({ ok: false, message: "Solo superadmin puede capturar folio manual." });
    }

    if (!budget.sucursalId) {
      const repairedBranch = await resolveLegacyCompanyBranch(
        connection,
        budget.empresa || existing.empresa,
        budget.sucursal || existing.sucursal
      );
      if (repairedBranch) {
        budget.sucursalId = Number(repairedBranch.id);
        budget.sucursal = repairedBranch.nombre;
      }
    }

    const contact = await resolveBudgetContactSelection(
      connection,
      budget.clienteId || existing.cliente_id,
      budget.sucursalId,
      { allowLegacyRepair: true }
    );
    if (!contact) {
      await connection.rollback();
      return res.status(400).json({
        ok: false,
        message: "El cliente / usuario no pertenece a la ubicación seleccionada. Selecciona una sucursal activa y vuelve a guardar."
      });
    }
    budget.clienteId = Number(contact.id || budget.clienteId || existing.cliente_id || 0) || null;
    budget.empresa = String(contact.empresa || "").trim();
    budget.sucursalId = Number(contact.sucursal_id || 0) || null;
    budget.sucursal = normalizeClientBranchLabel(contact.sucursal || "");
    budget.clienteUsuario = String(contact.nombre || "").trim();
    const responsibleId = await resolveBudgetResponsibleId(
      connection,
      budget.responsableId,
      req.session.user || {},
      existing.usuario_id
    );
    if (!responsibleId) {
      await connection.rollback();
      return res.status(400).json({ ok: false, message: "Selecciona un responsable interno activo." });
    }

    const canUseManualFolio = isSuperAdminSession(req.session.user);
    const folio = canUseManualFolio ? budget.folio || existing.folio : existing.folio;
    const folioManual = canUseManualFolio ? (budget.folioManual ? 1 : 0) : Number(existing.folio_manual || 0);
    await connection.execute(
      `UPDATE presupuestos
       SET cliente_id = ?, empresa_id = ?, sucursal_id = ?, empresa = ?, sucursal = ?, cliente_usuario = ?, area = ?,
           titulo_proyecto = ?, folio = ?, folio_manual = ?, sin_garantia = ?, estatus = ?, usuario_id = ?
       WHERE id = ?`,
      [
        budget.clienteId,
        Number(contact.empresa_id || 0) || null,
        budget.sucursalId,
        budget.empresa,
        budget.sucursal,
        budget.clienteUsuario,
        budget.area,
        budget.tituloProyecto,
        folio,
        folioManual,
        budget.sinGarantia ? 1 : 0,
        "En espera de aprobación",
        responsibleId,
        budgetId
      ]
    );

    await connection.execute("DELETE FROM presupuesto_costos_equipos WHERE presupuesto_id = ?", [budgetId]);
    await connection.execute("DELETE FROM presupuesto_costos_contratistas WHERE presupuesto_id = ?", [budgetId]);
    await connection.execute("DELETE FROM presupuesto_costos_mano_obra WHERE presupuesto_id = ?", [budgetId]);
    await connection.execute("DELETE FROM presupuesto_costos_materiales WHERE presupuesto_id = ?", [budgetId]);
    await insertBudgetCosts(connection, budgetId, budget);

    await connection.commit();
    res.json({ ok: true, budgetId, folio });
  } catch (error) {
    await connection.rollback();
    logServerError("budgets-update", error);
    const message = error.code === "ER_DUP_ENTRY" ? "Ese folio ya existe." : "No se pudo actualizar el presupuesto.";
    res.status(error.code === "ER_DUP_ENTRY" ? 409 : 500).json({ ok: false, message });
  } finally {
    connection.release();
  }
});

async function getBudgetDeletionLock(budgetId, executor = pool) {
  const [budgetRows] = await executor.execute(
    "SELECT estado, estatus, po FROM presupuestos WHERE id = ? LIMIT 1",
    [budgetId]
  );
  if (!budgetRows.length) return { locked: false, reason: "" };

  const [documentRows] = await executor.execute(
    `SELECT
       EXISTS(
         SELECT 1 FROM cotizaciones_cliente q
         WHERE q.presupuesto_id = ? AND q.tipo = 'version'
         LIMIT 1
       ) AS has_quote,
       EXISTS(
         SELECT 1 FROM presupuesto_po_cliente po
         WHERE po.presupuesto_id = ?
           AND (po.sin_po = 1 OR NULLIF(TRIM(po.numero_po), '') IS NOT NULL OR NULLIF(TRIM(po.ruta), '') IS NOT NULL)
         LIMIT 1
       ) AS has_client_po,
       EXISTS(
         SELECT 1 FROM ocp_proveedor ocp
         WHERE ocp.presupuesto_id = ? AND ocp.tipo = 'version'
           AND LOWER(TRIM(COALESCE(ocp.estatus, ''))) NOT LIKE 'cancel%'
         LIMIT 1
       ) AS has_supplier_order`,
    [budgetId, budgetId, budgetId]
  );
  const budget = budgetRows[0] || {};
  const documents = documentRows[0] || {};
  const status = normalizeAccessRole(`${budget.estado || ""} ${budget.estatus || ""}`);
  const accepted = /aprob|en proceso|cerrad/.test(status) || Boolean(documents.has_client_po) || Boolean(documents.has_supplier_order);
  const generated = Boolean(documents.has_quote) || Boolean(documents.has_client_po) || Boolean(documents.has_supplier_order) || Boolean(String(budget.po || "").trim());
  return {
    locked: accepted && generated,
    reason: accepted && generated
      ? "El proyecto ya fue aceptado y tiene documentos generados; se protege para conservar su trazabilidad."
      : ""
  };
}

app.get("/api/budgets/:id", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  try {
    await ensureBudgetTables();
    await ensureAccountsReceivableTables();
    const budget = await getBudgetWithDedupedCostTotals(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    const costs = await getBudgetCosts(budgetId);
    const files = await getBudgetFiles(budgetId);
    const transfers = await getBudgetTransfers(budgetId);
    const additionals = await getBudgetAdditionals(budgetId);
    const availableBlocks = await getSupplierOrderAvailableBlocksServer(budgetId);
    const deletionLock = await getBudgetDeletionLock(budgetId);
    const totalAdicional = additionals.reduce((sum, row) => sum + Number(row.monto || 0), 0);
    applyBudgetCostTotals(budget, costs);
    budget.totalAdicional = totalAdicional;
    budget.totalProyecto += totalAdicional;
    res.json({ ok: true, budget, costs, files, transfers, additionals, availableBlocks, deletionLock });
  } catch (error) {
    logServerError("budget-detail", error);
    res.status(500).json({ ok: false, message: "No se pudo cargar el presupuesto." });
  }
});

app.post("/api/budgets/:id/transfers", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  const origen = normalizeBudgetBlock(req.body.origen);
  const destino = normalizeBudgetBlock(req.body.destino);
  const monto = Number(req.body.monto || 0);

  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });
  if (!BUDGET_BLOCKS.has(origen) || !BUDGET_BLOCKS.has(destino)) {
    return res.status(400).json({ ok: false, message: "Selecciona bloques validos." });
  }
  if (origen === destino) {
    return res.status(400).json({ ok: false, message: "El origen y destino deben ser diferentes." });
  }
  if (monto <= 0) return res.status(400).json({ ok: false, message: "Captura un monto mayor a cero." });

  try {
    // Las instalaciones antiguas ya tenían la tabla, pero no necesariamente
    // las columnas monto/created_at. Completar el esquema antes de transferir.
    await ensureBudgetTables();
    const budget = await getBudgetWithDedupedCostTotals(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    const available = await getSupplierOrderAvailableBlocksServer(budgetId);
    if (monto > Number(available?.[origen] || 0) + 0.005) {
      return res.status(400).json({
        ok: false,
        message: `No hay presupuesto disponible suficiente en ${getBudgetBlockLabelServer(origen)}. Disponible: ${formatCurrencyServer(available?.[origen] || 0)}.`
      });
    }
    await pool.execute(
      `INSERT INTO presupuesto_transferencias (presupuesto_id, origen, destino, monto, usuario_id)
       VALUES (?, ?, ?, ?, ?)`,
      [budgetId, origen, destino, monto, req.session.user?.id || null]
    );
    await touchBudgetUpdatedAt(budgetId);
    res.status(201).json({ ok: true });
  } catch (error) {
    logServerError("budget-transfer", error);
    const legacySchemaError = ["ER_NO_DEFAULT_FOR_FIELD", "ER_NO_REFERENCED_ROW_2", "ER_ROW_IS_REFERENCED_2"].includes(error.code);
    res.status(500).json({
      ok: false,
      code: error.code || "BUDGET_TRANSFER_ERROR",
      message: legacySchemaError
        ? "La tabla histórica de transferencias no pudo actualizarse. Reinicia la aplicación y vuelve a intentarlo."
        : "No se pudo transferir el presupuesto. Revisa el registro del servidor con la clave budget-transfer."
    });
  }
});

