app.patch("/api/budgets/:id/financial", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  const isAdmin =
    String(req.session.user?.username || "").toLowerCase() === "superadmin" ||
    String(req.session.user?.role || "").toLowerCase() === "superadmin";
  const fields = [];
  const values = [];

  if (Object.prototype.hasOwnProperty.call(req.body, "sinGarantia")) {
    fields.push("sin_garantia = ?");
    values.push(req.body.sinGarantia ? 1 : 0);
  }

  if (Object.prototype.hasOwnProperty.call(req.body, "valorVenta")) {
    if (!isAdmin) return res.status(403).json({ ok: false, message: "Solo superadmin puede cambiar el valor de venta." });
    const value = Number(req.body.valorVenta || 0);
    if (value < 0) return res.status(400).json({ ok: false, message: "El valor de venta no puede ser negativo." });
    fields.push("valor_venta_override = ?");
    values.push(value);
  }

  if (Object.prototype.hasOwnProperty.call(req.body, "comisionSupervisor")) {
    if (!isAdmin) return res.status(403).json({ ok: false, message: "Solo superadmin puede cambiar la comisión." });
    const value = Number(req.body.comisionSupervisor || 0);
    if (value < 0 || value > 100) {
      return res.status(400).json({ ok: false, message: "La comisión debe estar entre 0 y 100." });
    }
    fields.push("comision_supervisor_override = ?");
    values.push(value);
  }

  if (!fields.length) return res.status(400).json({ ok: false, message: "No hay cambios para guardar." });

  try {
    values.push(budgetId);
    const [result] = await pool.execute(`UPDATE presupuestos SET ${fields.join(", ")} WHERE id = ?`, values);
    if (!result.affectedRows) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    res.json({ ok: true });
  } catch (error) {
    logServerError("budget-financial-update", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar el resumen financiero." });
  }
});

