app.post("/api/budgets/:id/client-quote/draft", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  const items = parseClientQuoteRows(req.body.items);
  const terminos = String(req.body.terminos || CLIENT_QUOTE_DEFAULT_TERMS).trim() || CLIENT_QUOTE_DEFAULT_TERMS;
  const descuentoMonto = normalizeClientQuoteDiscount(req.body.descuentoMonto, getClientQuoteItemsSubtotal(items));
  const draftId = Number(req.body.borradorId || req.body.draftId || 0);
  const connection = await pool.getConnection();

  try {
    const budget = await getBudgetById(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    if (!canUseClientQuoteModule(budget)) {
      return res.status(409).json({ ok: false, message: "La cotización cliente se habilita al aprobar el presupuesto." });
    }
    const amountError = validateClientQuoteAmount(budget, items, req.session.user, descuentoMonto);
    if (amountError) return res.status(400).json({ ok: false, message: amountError });

    await connection.beginTransaction();
    let quoteId = 0;
    if (draftId) {
      const [existing] = await connection.execute(
        "SELECT id FROM cotizaciones_cliente WHERE id = ? AND presupuesto_id = ? AND tipo = 'borrador' LIMIT 1",
        [draftId, budgetId]
      );
      quoteId = Number(existing[0]?.id || 0);
    }
    if (quoteId) {
      await connection.execute(
        "UPDATE cotizaciones_cliente SET terminos = ?, descuento_monto = ?, usuario_id = ?, updated_at = NOW() WHERE id = ?",
        [terminos, descuentoMonto, req.session.user?.id || null, quoteId]
      );
    } else {
      const [result] = await connection.execute(
        `INSERT INTO cotizaciones_cliente (presupuesto_id, tipo, folio, version, terminos, descuento_monto, usuario_id)
         VALUES (?, 'borrador', '', 0, ?, ?, ?)`,
        [budgetId, terminos, descuentoMonto, req.session.user?.id || null]
      );
      quoteId = result.insertId;
    }

    await replaceClientQuoteRows(connection, quoteId, items);
    await touchBudgetUpdatedAt(budgetId, connection);
    await connection.commit();
    const draft = await getClientQuoteById(quoteId);
    const drafts = await getClientQuoteDrafts(budgetId);
    res.json({ ok: true, draft, drafts });
  } catch (error) {
    await connection.rollback();
    logServerError("client-quote-draft", error);
    res.status(500).json({ ok: false, message: "No se pudo guardar el borrador." });
  } finally {
    connection.release();
  }
});

app.post("/api/budgets/:id/client-quote/versions", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  const items = parseClientQuoteRows(req.body.items);
  const terminos = String(req.body.terminos || CLIENT_QUOTE_DEFAULT_TERMS).trim() || CLIENT_QUOTE_DEFAULT_TERMS;
  const descuentoMonto = normalizeClientQuoteDiscount(req.body.descuentoMonto, getClientQuoteItemsSubtotal(items));
  const draftId = Number(req.body.borradorId || req.body.draftId || 0);
  if (!items.length) return res.status(400).json({ ok: false, message: "Agrega al menos una partida." });

  const connection = await pool.getConnection();
  try {
    const budget = await getBudgetById(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    if (!canUseClientQuoteModule(budget)) {
      return res.status(409).json({ ok: false, message: "La cotización cliente se habilita al aprobar el presupuesto." });
    }
    const amountError = validateClientQuoteAmount(budget, items, req.session.user, descuentoMonto);
    if (amountError) return res.status(400).json({ ok: false, message: amountError });

    await connection.beginTransaction();
    const [versionRows] = await connection.execute(
      "SELECT COALESCE(MAX(version), 0) AS last_version FROM cotizaciones_cliente WHERE presupuesto_id = ? AND tipo = 'version'",
      [budgetId]
    );
    const version = Number(versionRows[0]?.last_version || 0) + 1;
    const folio = `${clientQuoteBaseFromBudgetFolio(budget.folio)}-${version}`;
    const [result] = await connection.execute(
      `INSERT INTO cotizaciones_cliente
        (presupuesto_id, tipo, folio, version, estatus, terminos, descuento_monto, usuario_id, aprobada_at)
       VALUES (?, 'version', ?, ?, 'Aprobada', ?, ?, ?, NOW())`,
      [budgetId, folio, version, terminos, descuentoMonto, req.session.user?.id || null]
    );
    await replaceClientQuoteRows(connection, result.insertId, items);
    if (draftId) await deleteClientQuoteDraft(connection, budgetId, draftId);
    await touchBudgetUpdatedAt(budgetId, connection);
    await connection.commit();
    const quote = await getClientQuoteById(result.insertId);
    const versions = await getClientQuoteVersions(budgetId);
    res.status(201).json({ ok: true, quote, versions });
  } catch (error) {
    await connection.rollback();
    logServerError("client-quote-version", error);
    res.status(500).json({ ok: false, message: "No se pudo guardar la versión." });
  } finally {
    connection.release();
  }
});

app.put("/api/budgets/:id/client-quote/versions/:quoteId", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  const quoteId = Number(req.params.quoteId);
  if (!budgetId || !quoteId) return res.status(400).json({ ok: false, message: "Cotización invalida." });

  const items = parseClientQuoteRows(req.body.items);
  const terminos = String(req.body.terminos || CLIENT_QUOTE_DEFAULT_TERMS).trim() || CLIENT_QUOTE_DEFAULT_TERMS;
  const descuentoMonto = normalizeClientQuoteDiscount(req.body.descuentoMonto, getClientQuoteItemsSubtotal(items));
  const draftId = Number(req.body.borradorId || req.body.draftId || 0);
  if (!items.length) return res.status(400).json({ ok: false, message: "Agrega al menos una partida." });

  const connection = await pool.getConnection();
  try {
    const budget = await getBudgetById(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    if (!canUseClientQuoteModule(budget)) {
      return res.status(409).json({ ok: false, message: "La cotización cliente se habilita al aprobar el presupuesto." });
    }
    const amountError = validateClientQuoteAmount(budget, items, req.session.user, descuentoMonto);
    if (amountError) return res.status(400).json({ ok: false, message: amountError });

    const [existing] = await connection.execute(
      "SELECT id, estatus FROM cotizaciones_cliente WHERE id = ? AND presupuesto_id = ? AND tipo = 'version' LIMIT 1",
      [quoteId, budgetId]
    );
    if (!existing.length) return res.status(404).json({ ok: false, message: "Versión no encontrada." });
    if (String(existing[0].estatus || "").toLowerCase().includes("cancel")) {
      return res.status(409).json({ ok: false, message: "No se puede editar una cotización cancelada." });
    }

    await connection.beginTransaction();
    await connection.execute(
      "UPDATE cotizaciones_cliente SET estatus = 'Cancelada', updated_at = NOW() WHERE id = ?",
      [quoteId]
    );

    const [versionRows] = await connection.execute(
      "SELECT COALESCE(MAX(version), 0) AS last_version FROM cotizaciones_cliente WHERE presupuesto_id = ? AND tipo = 'version'",
      [budgetId]
    );
    const version = Number(versionRows[0]?.last_version || 0) + 1;
    const folio = `${clientQuoteBaseFromBudgetFolio(budget.folio)}-${version}`;
    const [result] = await connection.execute(
      `INSERT INTO cotizaciones_cliente
        (presupuesto_id, tipo, folio, version, estatus, terminos, descuento_monto, usuario_id, aprobada_at)
       VALUES (?, 'version', ?, ?, 'Aprobada', ?, ?, ?, NOW())`,
      [budgetId, folio, version, terminos, descuentoMonto, req.session.user?.id || null]
    );
    const newQuoteId = result.insertId;
    await replaceClientQuoteRows(connection, newQuoteId, items);
    await connection.execute(
      `UPDATE cuentas_por_cobrar
       SET cotizacion_cliente_id = ?, monto = ?, updated_at = NOW()
       WHERE cotizacion_cliente_id = ?`,
      [newQuoteId, Math.max(getClientQuoteItemsSubtotal(items) - descuentoMonto, 0), quoteId]
    );
    if (draftId) await deleteClientQuoteDraft(connection, budgetId, draftId);
    await touchBudgetUpdatedAt(budgetId, connection);
    await connection.commit();
    const quote = await getClientQuoteById(newQuoteId);
    const versions = await getClientQuoteVersions(budgetId);
    res.status(201).json({ ok: true, quote, versions, cancelledQuoteId: quoteId });
  } catch (error) {
    await connection.rollback();
    logServerError("client-quote-version-update", error);
    res.status(500).json({ ok: false, message: "No se pudo generar la nueva versión." });
  } finally {
    connection.release();
  }
});

