app.delete("/api/client-quotes/:quoteId", requireAuth, requireDeletePermission, async (req, res) => {
  const quoteId = Number(req.params.quoteId);
  if (!quoteId) return res.status(400).json({ ok: false, message: "Cotización invalida." });

  const connection = await pool.getConnection();
  try {
    const quote = await getClientQuoteById(quoteId);
    if (!quote || quote.tipo !== "version") {
      return res.status(404).json({ ok: false, message: "Cotización no encontrada." });
    }

    const filesToUnlink = [];
    if (quote.pdfRuta) filesToUnlink.push({ ruta: quote.pdfRuta, root: CLIENT_QUOTE_PDF_DIR });

    const [receivableFiles] = await connection.execute(
      `SELECT a.ruta
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
       WHERE c.cotizacion_cliente_id = ?`,
      [quoteId]
    );
    filesToUnlink.push(...receivableFiles.map((row) => ({ ruta: row.ruta, root: ACCOUNTS_RECEIVABLE_UPLOAD_DIR })));

    await connection.beginTransaction();
    await connection.execute(
      `DELETE a
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar c ON c.id = a.cuenta_id
       WHERE c.cotizacion_cliente_id = ?`,
      [quoteId]
    );
    await connection.execute("DELETE FROM cuentas_por_cobrar WHERE cotizacion_cliente_id = ?", [quoteId]);
    await connection.execute("DELETE FROM cotizacion_cliente_partidas WHERE cotizacion_id = ?", [quoteId]);
    await connection.execute("DELETE FROM cotizaciones_cliente WHERE id = ?", [quoteId]);
    await touchBudgetUpdatedAt(quote.presupuestoId, connection);
    await connection.commit();

    filesToUnlink.forEach((file) => unlinkStoredFile(file.ruta, file.root));
    res.json({ ok: true });
  } catch (error) {
    await connection.rollback();
    logServerError("client-quote-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar la cotización." });
  } finally {
    connection.release();
  }
});

app.get("/api/client-quotes/:quoteId/download", requireAuth, async (req, res) => {
  const quoteId = Number(req.params.quoteId);
  if (!quoteId) return res.status(400).json({ ok: false, message: "Cotización invalida." });

  try {
    let quote = await getClientQuoteById(quoteId);
    if (!quote || quote.estatus !== "Aprobada") {
      return res.status(404).json({ ok: false, message: "PDF no disponible." });
    }
    let pdfRuta = quote.pdfRuta || "";
    let absolutePath = pdfRuta ? path.resolve(__dirname, pdfRuta) : "";
    if (!pdfRuta || !fs.existsSync(absolutePath)) {
      pdfRuta = await generateClientQuotePdf(quoteId);
      quote = await getClientQuoteById(quoteId);
      absolutePath = path.resolve(__dirname, pdfRuta || quote?.pdfRuta || "");
    }
    const allowedRoot = path.resolve(CLIENT_QUOTE_PDF_DIR);
    if (!absolutePath.startsWith(allowedRoot)) {
      return res.status(400).json({ ok: false, message: "Ruta de PDF invalida." });
    }
    res.download(absolutePath, `${clientQuotePdfFileBase(quote)}.pdf`);
  } catch (error) {
    logServerError("client-quote-download", error);
    res.status(500).json({ ok: false, message: "No se pudo descargar el PDF." });
  }
});

