app.post("/api/accounts-receivable/:quoteId/cancel-bill", requireAuth, async (req, res) => {
  const quoteId = Number(req.params.quoteId);
  if (!quoteId) return res.status(400).json({ ok: false, message: "Cotización invalida." });

  try {
    await ensureAccountsReceivableTables();
    const detail = await getAccountsReceivableDetail(quoteId);
    if (!detail) return res.status(404).json({ ok: false, message: "Cuenta por cobrar no encontrada." });
    if (!(await canAccessBudget(req.session.user, detail.account?.presupuestoId, "modulo:cuentas-cobrar", "accion:facturar"))) {
      return res.status(403).json({ ok: false, message: "No tienes acceso a esta cuenta por cobrar." });
    }

    const cuentaId = await ensureAccountsReceivableRecord(quoteId, req.session.user?.id || null);
    if (!cuentaId) return res.status(404).json({ ok: false, message: "Cotización aprobada no encontrada." });

    const [pendingMovements] = await pool.execute(
      "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado = 'Solicitada' ORDER BY id DESC LIMIT 1",
      [cuentaId]
    );
    if (pendingMovements.length) {
      await pool.execute(
        "UPDATE cuentas_por_cobrar_facturacion SET estado = 'Cancelada', updated_at = NOW() WHERE id = ?",
        [pendingMovements[0].id]
      );
      await refreshAccountsReceivableStatus(cuentaId);
    } else {
      const files = await getAccountsReceivableFilesByQuote(quoteId);
      if (files.some((file) => file.tipo === "Factura")) {
        return res.status(409).json({ ok: false, message: "No hay una parcialidad pendiente que se pueda cancelar." });
      }
      await pool.execute(
        "UPDATE cuentas_por_cobrar SET estado = 'En proceso', pendiente = 'En proceso', updated_at = NOW() WHERE id = ?",
        [cuentaId]
      );
    }

    const updatedDetail = await getAccountsReceivableDetail(quoteId);
    res.json({ ok: true, ...updatedDetail });
  } catch (error) {
    logServerError("accounts-receivable-cancel-bill", error);
    res.status(500).json({ ok: false, message: "No se pudo cancelar la solicitud de factura." });
  }
});

app.patch("/api/accounts-receivable/billing-movements/:movementId/cancel", requireAuth, async (req, res) => {
  const movementId = Number(req.params.movementId);
  if (!movementId) return res.status(400).json({ ok: false, message: "Parcialidad inválida." });
  try {
    await ensureAccountsReceivableTables();
    const [rows] = await pool.execute(
      `SELECT f.cuenta_id, f.estado, p.id AS presupuesto_id, p.usuario_id AS owner_id
       FROM cuentas_por_cobrar_facturacion f
       INNER JOIN cuentas_por_cobrar cx ON cx.id = f.cuenta_id
       INNER JOIN cotizaciones_cliente q ON q.id = cx.cotizacion_cliente_id
       INNER JOIN presupuestos p ON p.id = q.presupuesto_id
       WHERE f.id = ?
       LIMIT 1`,
      [movementId]
    );
    if (!rows.length) return res.status(404).json({ ok: false, message: "Parcialidad no encontrada." });
    if (!(await canAccessBudget(req.session.user, rows[0].presupuesto_id, "modulo:cuentas-cobrar", "accion:editar"))) {
      return res.status(403).json({ ok: false, message: "No tienes acceso a esta cuenta por cobrar." });
    }
    if (normalizeWorkflowValue(rows[0].estado) !== "solicitada") {
      return res.status(409).json({ ok: false, message: "Solo se pueden cancelar parcialidades que aún no tienen factura." });
    }
    await pool.execute("UPDATE cuentas_por_cobrar_facturacion SET estado = 'Cancelada', updated_at = NOW() WHERE id = ?", [movementId]);
    await refreshAccountsReceivableStatus(rows[0].cuenta_id);
    res.json({ ok: true });
  } catch (error) {
    logServerError("accounts-receivable-billing-cancel", error);
    res.status(500).json({ ok: false, message: "No se pudo cancelar la parcialidad." });
  }
});

app.post(
  "/api/accounts-receivable/:quoteId/files",
  requireAuth,
  uploadAccountsReceivableFile.single("archivo"),
  async (req, res) => {
    const quoteId = Number(req.params.quoteId);
    if (!quoteId) return res.status(400).json({ ok: false, message: "Cotización invalida." });

    const tipo = String(req.body.tipo || "").trim();
    if (!req.file) {
      return res.status(400).json({ ok: false, message: "Selecciona un archivo para cargar." });
    }

    const relativePath = path.relative(__dirname, req.file.path).replace(/\\/g, "/");
    const fileName = req.file.originalname || "";

    try {
      await ensureAccountsReceivableTables();
      const baseRows = await getAccountsReceivableBaseRows(quoteId);
      const sourceRow = baseRows[0];
      if (!sourceRow) {
        unlinkStoredFile(relativePath, ACCOUNTS_RECEIVABLE_UPLOAD_DIR);
        return res.status(404).json({ ok: false, message: "Cotización aprobada no encontrada." });
      }
      if (!(await canAccessBudget(req.session.user, sourceRow.presupuesto_id, "modulo:cuentas-cobrar", "accion:subir-archivos"))) {
        unlinkStoredFile(relativePath, ACCOUNTS_RECEIVABLE_UPLOAD_DIR);
        return res.status(403).json({ ok: false, message: "No tienes acceso a esta cuenta por cobrar." });
      }
      const fileTypes = getAccountsReceivableFileTypes(sourceRow.empresa || "");
      if (!fileTypes.includes(tipo)) {
        unlinkStoredFile(relativePath, ACCOUNTS_RECEIVABLE_UPLOAD_DIR);
        return res.status(400).json({ ok: false, message: "Selecciona el tipo de archivo." });
      }

      const cuentaId = await ensureAccountsReceivableRecord(quoteId, req.session.user?.id || null);
      if (!cuentaId) return res.status(404).json({ ok: false, message: "Cotización aprobada no encontrada." });

      const [fileInsert] = await pool.execute(
        `INSERT INTO cuentas_por_cobrar_archivos
          (cuenta_id, tipo, nombre, ruta, usuario_id)
         VALUES (?, ?, ?, ?, ?)`,
        [cuentaId, tipo, fileName, relativePath, req.session.user?.id || null]
      );
      const archivoId = Number(fileInsert.insertId || 0);
      if (tipo === "Factura") {
        let facturacionId = null;
        const [pendingBilling] = await pool.execute(
          "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado = 'Solicitada' ORDER BY id ASC LIMIT 1",
          [cuentaId]
        );
        if (pendingBilling.length) {
          facturacionId = Number(pendingBilling[0].id);
          await pool.execute(
            "UPDATE cuentas_por_cobrar_facturacion SET estado = 'Facturada', updated_at = NOW() WHERE id = ?",
            [facturacionId]
          );
        } else {
          const [accountAmountRows] = await pool.execute("SELECT monto FROM cuentas_por_cobrar WHERE id = ? LIMIT 1", [cuentaId]);
          const summary = await getAccountsReceivableBillingSummary(cuentaId, Number(accountAmountRows[0]?.monto || 0));
          if (summary.remaining > 0.004) {
            const [billingInsert] = await pool.execute(
              `INSERT INTO cuentas_por_cobrar_facturacion (cuenta_id, monto, estado, observaciones, usuario_id)
               VALUES (?, ?, 'Facturada', 'Factura cargada sin solicitud previa', ?)`,
              [cuentaId, summary.remaining, req.session.user?.id || null]
            );
            facturacionId = Number(billingInsert.insertId || 0);
          } else {
            const [lastBilled] = await pool.execute(
              "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado IN ('Facturada','Pagada') ORDER BY id DESC LIMIT 1",
              [cuentaId]
            );
            facturacionId = Number(lastBilled[0]?.id || 0) || null;
          }
        }
        if (archivoId && facturacionId) {
          await pool.execute("UPDATE cuentas_por_cobrar_archivos SET facturacion_id = ? WHERE id = ?", [facturacionId, archivoId]);
        }
      }
      if (tipo === "Comprobante de pago" && archivoId) {
        await registerAccountsReceivablePaymentFromProof({
          cuentaId,
          archivoId,
          relativePath,
          fileName,
          userId: req.session.user?.id || null
        });
      }
      await refreshAccountsReceivableStatus(cuentaId);
      await refreshReceivableBatchForAccount(cuentaId);

      const detail = await getAccountsReceivableDetail(quoteId);
      res.status(201).json({ ok: true, message: `${tipo} cargado correctamente.`, ...detail });
    } catch (error) {
      logServerError("accounts-receivable-file-upload", error);
      res.status(500).json({ ok: false, message: "No se pudo cargar el archivo de cobranza." });
    }
  }
);

app.delete("/api/accounts-receivable-files/:fileId", requireAuth, async (req, res) => {
  const fileId = Number(req.params.fileId);
  if (!fileId) return res.status(400).json({ ok: false, message: "Archivo inválido." });

  try {
    await ensureAccountsReceivableTables();
    const [rows] = await pool.execute(
      `SELECT a.cuenta_id, a.tipo, a.ruta, a.facturacion_id, p.id AS presupuesto_id
       FROM cuentas_por_cobrar_archivos a
       INNER JOIN cuentas_por_cobrar cx ON cx.id = a.cuenta_id
       INNER JOIN cotizaciones_cliente q ON q.id = cx.cotizacion_cliente_id
       INNER JOIN presupuestos p ON p.id = q.presupuesto_id
       WHERE a.id = ?
       LIMIT 1`,
      [fileId]
    );
    if (!rows.length) return res.status(404).json({ ok: false, message: "Archivo no encontrado." });
    if (!(await canAccessBudget(
      req.session.user,
      rows[0].presupuesto_id,
      "modulo:cuentas-cobrar",
      "accion:eliminar-archivos"
    ))) {
      return res.status(403).json({ ok: false, message: "No tienes permiso para eliminar este archivo de cobranza." });
    }
    if (rows[0].tipo === "Comprobante de pago") {
      const [paymentRows] = await pool.execute(
        "SELECT id, facturacion_id FROM cuentas_por_cobrar_pagos WHERE archivo_id = ? LIMIT 1",
        [fileId]
      );
      if (paymentRows.length) {
        const facturacionId = Number(paymentRows[0].facturacion_id || 0);
        await pool.execute("DELETE FROM cuentas_por_cobrar_pagos WHERE id = ?", [paymentRows[0].id]);
        if (facturacionId) {
          await pool.execute("UPDATE cuentas_por_cobrar_facturacion SET estado = 'Facturada', updated_at = NOW() WHERE id = ?", [facturacionId]);
        }
      }
    }
    await pool.execute("DELETE FROM cuentas_por_cobrar_archivos WHERE id = ?", [fileId]);
    if (rows[0].tipo === "Factura") {
      const [lastBilled] = rows[0].facturacion_id
        ? [[{ id: rows[0].facturacion_id }]]
        : await pool.execute(
            "SELECT id FROM cuentas_por_cobrar_facturacion WHERE cuenta_id = ? AND estado = 'Facturada' ORDER BY id DESC LIMIT 1",
            [rows[0].cuenta_id]
          );
      if (lastBilled.length) {
        const [linkedPayments] = await pool.execute(
          "SELECT COUNT(*) AS total FROM cuentas_por_cobrar_pagos WHERE facturacion_id = ?",
          [lastBilled[0].id]
        );
        if (Number(linkedPayments[0]?.total || 0) === 0) {
          await pool.execute(
            "UPDATE cuentas_por_cobrar_facturacion SET estado = 'Solicitada', updated_at = NOW() WHERE id = ?",
            [lastBilled[0].id]
          );
        }
      }
    }
    await refreshAccountsReceivableStatus(rows[0].cuenta_id);
    await refreshReceivableBatchForAccount(rows[0].cuenta_id);
    unlinkStoredFile(rows[0].ruta, ACCOUNTS_RECEIVABLE_UPLOAD_DIR);
    res.json({ ok: true });
  } catch (error) {
    logServerError("accounts-receivable-file-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar el archivo de cobranza." });
  }
});

