app.post(
  "/api/accounts-receivable-batches/:batchId/files",
  requireAuth,
  requireCollectionPermission,
  uploadReceivableBatchFile.array("archivo", 20),
  async (req, res) => {
    const batchId = Number(req.params.batchId);
    const files = Array.isArray(req.files) ? req.files : [];
    if (!batchId || !files.length) return res.status(400).json({ ok: false, message: "Selecciona al menos un archivo." });
    try {
      await ensureAccountsReceivableTables();
      const batch = await getReceivableBatch(batchId);
      if (!batch) throw new Error("Cobro general no encontrado.");
      if (!(await canAccessReceivableBatch(req.session.user, batch, "accion:facturar"))) {
        for (const file of files) unlinkStoredFile(path.relative(__dirname, file.path).replace(/\\/g, "/"), RECEIVABLE_BATCH_UPLOAD_DIR);
        return res.status(403).json({ ok: false, message: "No tienes permiso para adjuntar archivos a este cobro general." });
      }
      const itemId = Number(req.body.itemId || 0) || null;
      if (itemId && !batch.items.some((item) => Number(item.id) === itemId)) throw new Error("El proyecto no pertenece a este cobro general.");
      const tipo = String(req.body.tipo || "Comprobante de pago").trim() || "Comprobante de pago";
      const allowedTypes = getAccountsReceivableFileTypes(batch.empresa || "");
      if (!allowedTypes.includes(tipo)) throw new Error("Selecciona un tipo de documento válido para la cuenta por cobrar.");
      for (const file of files) {
        const relativePath = path.relative(__dirname, file.path).replace(/\\/g, "/");
        const [batchFileInsert] = await pool.execute(
          `INSERT INTO lotes_cobro_clientes_archivos (lote_id, item_id, tipo, nombre, ruta, usuario_id)
           VALUES (?, ?, ?, ?, ?, ?)`,
          [batchId, itemId, tipo, file.originalname || "", relativePath, req.session.user?.id || null]
        );
        await registerReceivableBatchDocument({
          batch,
          batchFileId: Number(batchFileInsert.insertId || 0) || null,
          itemId,
          tipo,
          relativePath,
          fileName: file.originalname || "",
          userId: req.session.user?.id || null
        });
      }
      res.status(201).json({
        ok: true,
        message: tipo === "Comprobante de pago"
          ? "Pago registrado. El cobro queda pendiente hasta cargar el complemento."
          : tipo === "Complemento de pago"
            ? "Complemento ligado a todos los proyectos. Cobro consolidado completado."
            : `${tipo} ligado a todos los proyectos seleccionados.`,
        batch: await getReceivableBatch(batchId)
      });
    } catch (error) {
      for (const file of files) unlinkStoredFile(path.relative(__dirname, file.path).replace(/\\/g, "/"), RECEIVABLE_BATCH_UPLOAD_DIR);
      logServerError("accounts-receivable-batch-files", error);
      res.status(400).json({ ok: false, message: error.message || "No se pudieron guardar los comprobantes." });
    }
  }
);

