app.delete("/api/accounts-receivable-batch-files/:fileId", requireAuth, requireCollectionPermission, async (req, res) => {
  const fileId = Number(req.params.fileId);
  if (!fileId) return res.status(400).json({ ok: false, message: "Archivo inválido." });
  try {
    await ensureAccountsReceivableTables();
    const [sourceRows] = await pool.execute(
      `SELECT id, lote_id, item_id, tipo, nombre, ruta, created_at
       FROM lotes_cobro_clientes_archivos WHERE id = ? LIMIT 1`,
      [fileId]
    );
    if (!sourceRows.length) return res.status(404).json({ ok: false, message: "Archivo no encontrado." });
    const source = sourceRows[0];
    const batch = await getReceivableBatch(source.lote_id);
    if (!batch) return res.status(404).json({ ok: false, message: "Cobro consolidado no encontrado." });
    if (!(await canAccessReceivableBatch(req.session.user, batch, "accion:facturar"))) {
      return res.status(403).json({ ok: false, message: "No tienes permiso para eliminar este documento." });
    }

    const connection = await pool.getConnection();
    const accountPaths = [];
    const accountIds = new Set();
    try {
      await connection.beginTransaction();
      const [locked] = await connection.execute(
        "SELECT id FROM lotes_cobro_clientes_archivos WHERE id = ? FOR UPDATE",
        [fileId]
      );
      if (!locked.length) throw new Error("El archivo ya fue eliminado.");
      const [replicas] = await connection.execute(
        `SELECT DISTINCT archivo.id, archivo.cuenta_id, archivo.tipo, archivo.ruta, archivo.facturacion_id
         FROM cuentas_por_cobrar_archivos archivo
         INNER JOIN lotes_cobro_clientes_items item ON item.cuenta_id = archivo.cuenta_id
         WHERE item.lote_id = ?
           AND (
             archivo.lote_cobro_archivo_id = ?
             OR (
               archivo.lote_cobro_archivo_id IS NULL
               AND archivo.tipo = ?
               AND archivo.nombre = ?
               AND ABS(TIMESTAMPDIFF(SECOND, ?, archivo.created_at)) <= 300
             )
           )`,
        [source.lote_id, fileId, source.tipo, source.nombre, source.created_at]
      );

      for (const replica of replicas) {
        const [payments] = await connection.execute(
          "SELECT id, facturacion_id FROM cuentas_por_cobrar_pagos WHERE archivo_id = ?",
          [replica.id]
        );
        await connection.execute("DELETE FROM cuentas_por_cobrar_pagos WHERE archivo_id = ?", [replica.id]);
        await connection.execute("DELETE FROM cuentas_por_cobrar_archivos WHERE id = ?", [replica.id]);
        const billingIds = [...new Set([replica.facturacion_id, ...payments.map((payment) => payment.facturacion_id)].map(Number).filter(Boolean))];
        for (const billingId of billingIds) {
          const [remainingDocuments] = await connection.execute(
            "SELECT COUNT(*) AS total FROM cuentas_por_cobrar_archivos WHERE facturacion_id = ?",
            [billingId]
          );
          const [billingPayments] = await connection.execute(
            "SELECT COALESCE(SUM(monto), 0) AS total FROM cuentas_por_cobrar_pagos WHERE facturacion_id = ?",
            [billingId]
          );
          const [billingRows] = await connection.execute("SELECT monto FROM cuentas_por_cobrar_facturacion WHERE id = ? LIMIT 1", [billingId]);
          if (!Number(remainingDocuments[0]?.total || 0) && !Number(billingPayments[0]?.total || 0)) {
            await connection.execute("DELETE FROM cuentas_por_cobrar_facturacion WHERE id = ?", [billingId]);
          } else if (billingRows.length) {
            const paid = Number(billingPayments[0]?.total || 0);
            const amount = Number(billingRows[0]?.monto || 0);
            await connection.execute(
              "UPDATE cuentas_por_cobrar_facturacion SET estado = ?, updated_at = NOW() WHERE id = ?",
              [paid + 0.004 >= amount ? "Pagada" : "Facturada", billingId]
            );
          }
        }
        accountPaths.push(String(replica.ruta || ""));
        accountIds.add(Number(replica.cuenta_id));
      }
      await connection.execute("DELETE FROM lotes_cobro_clientes_archivos WHERE id = ?", [fileId]);
      await connection.commit();
    } catch (error) {
      try { await connection.rollback(); } catch (_rollbackError) {}
      throw error;
    } finally {
      connection.release();
    }

    accountPaths.filter(Boolean).forEach((relativePath) => unlinkStoredFile(relativePath, ACCOUNTS_RECEIVABLE_UPLOAD_DIR));
    unlinkStoredFile(source.ruta, RECEIVABLE_BATCH_UPLOAD_DIR);
    for (const accountId of accountIds) {
      try { await refreshAccountsReceivableStatus(accountId); } catch (error) { logServerError(`receivable-batch-file-refresh-${accountId}`, error); }
    }
    const updatedBatch = await refreshReceivableBatchCollectionState(source.lote_id);
    res.json({ ok: true, message: `${source.tipo || "Documento"} eliminado del cobro y de sus proyectos.`, batch: updatedBatch });
  } catch (error) {
    logServerError("accounts-receivable-batch-file-delete", error);
    res.status(409).json({ ok: false, message: error.message || "No se pudo eliminar el documento general." });
  }
});

app.delete("/api/accounts-receivable-batches/:batchId", requireAuth, requireCollectionPermission, async (req, res) => {
  const batchId = Number(req.params.batchId);
  if (!batchId) return res.status(400).json({ ok: false, message: "Cobro general inválido." });
  try {
    await ensureAccountsReceivableTables();
    const current = await getReceivableBatch(batchId);
    if (!current) return res.status(404).json({ ok: false, message: "Cobro general no encontrado." });
    if (!(await canAccessReceivableBatch(req.session.user, current, "accion:facturar"))) {
      return res.status(403).json({ ok: false, message: "No tienes permiso para cancelar este cobro general." });
    }
  } catch (error) {
    logServerError("accounts-receivable-batch-cancel-access", error);
    return res.status(500).json({ ok: false, message: "No se pudo validar el acceso al cobro general." });
  }
  const connection = await pool.getConnection();
  let pdfPath = "";
  let storedFiles = [];
  try {
    await connection.beginTransaction();
    const [batches] = await connection.execute("SELECT id, estado, pdf_ruta FROM lotes_cobro_clientes WHERE id = ? FOR UPDATE", [batchId]);
    if (!batches.length || normalizeWorkflowValue(batches[0].estado) !== "pendiente") throw new Error("El cobro general ya fue cobrado o no existe.");
    pdfPath = String(batches[0].pdf_ruta || "");
    const [items] = await connection.execute("SELECT cuenta_id, monto_original FROM lotes_cobro_clientes_items WHERE lote_id = ?", [batchId]);
    const [files] = await connection.execute("SELECT ruta FROM lotes_cobro_clientes_archivos WHERE lote_id = ?", [batchId]);
    if (files.length) throw new Error(`El cobro general todavía tiene ${files.length} documento${files.length === 1 ? "" : "s"}. Elimínalo${files.length === 1 ? "" : "s"} desde \"Documentos del cobro\" antes de cancelarlo.`);
    storedFiles = files.map((file) => String(file.ruta || "")).filter(Boolean);
    for (const item of items) await connection.execute("UPDATE cuentas_por_cobrar SET monto = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?", [item.monto_original, item.cuenta_id]);
    await connection.execute("DELETE FROM lotes_cobro_clientes WHERE id = ?", [batchId]);
    await connection.commit();
    [...storedFiles, pdfPath].filter(Boolean).forEach((relativePath) => unlinkStoredFile(relativePath, RECEIVABLE_BATCH_UPLOAD_DIR));
    res.json({ ok: true, message: "Cobro general pendiente cancelado." });
  } catch (error) {
    try { await connection.rollback(); } catch (_rollbackError) {}
    logServerError("accounts-receivable-batch-cancel", error);
    res.status(409).json({ ok: false, message: error.message || "No se pudo cancelar el cobro general." });
  } finally { connection.release(); }
});

