app.patch("/api/payment-orders/:paymentOrderId/status", requireAuth, async (req, res) => {
  const paymentOrderId = Number(req.params.paymentOrderId);
  const estadoMovimiento = String(req.body.estadoMovimiento || "").trim();
  if (!paymentOrderId || !PAYMENT_MOVEMENT_STATUSES.includes(estadoMovimiento)) {
    return res.status(400).json({ ok: false, message: "Movimiento o estado inválido." });
  }

  const connection = await pool.getConnection();
  let cuentaId = null;
  try {
    await ensureAccountsPayableTables();
    await connection.beginTransaction();
    const [movementRows] = await connection.execute(
      `SELECT id, cuenta_id, monto, estado_movimiento
       FROM ordenes_pago
       WHERE id = ?
       FOR UPDATE`,
      [paymentOrderId]
    );
    const movement = movementRows[0];
    if (!movement) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Movimiento no encontrado." });
    }
    cuentaId = Number(movement.cuenta_id || 0);
    const [accountRows] = await connection.execute(
      "SELECT id FROM cuentas_por_pagar WHERE id = ? FOR UPDATE",
      [cuentaId]
    );
    if (!accountRows.length) {
      await connection.rollback();
      return res.status(404).json({ ok: false, message: "Cuenta por pagar no encontrada." });
    }

    if (estadoMovimiento === "Aplicado" && movement.estado_movimiento !== "Aplicado") {
      const financial = await getAccountsPayableFinancialSummary(cuentaId, connection);
      if (Number(movement.monto || 0) > financial.remaining + 0.005) {
        await connection.rollback();
        return res.status(400).json({
          ok: false,
          message: `El movimiento excede el saldo restante de ${formatCurrencyServer(financial.remaining)}.`
        });
      }
    }

    await connection.execute(
      `UPDATE ordenes_pago
       SET estado_movimiento = ?,
           fecha_aplicacion = CASE WHEN ? = 'Aplicado' THEN COALESCE(fecha_aplicacion, ?) ELSE NULL END,
           cancelado_at = CASE WHEN ? = 'Cancelado' THEN CURRENT_TIMESTAMP ELSE NULL END,
           updated_at = CURRENT_TIMESTAMP
       WHERE id = ?`,
      [estadoMovimiento, estadoMovimiento, businessDateOnly(), estadoMovimiento, paymentOrderId]
    );
    await connection.commit();
  } catch (error) {
    try {
      await connection.rollback();
    } catch (_rollbackError) {
      // Sin acción adicional.
    }
    logServerError("payment-order-status-update", error);
    return res.status(500).json({ ok: false, message: "No se pudo actualizar el movimiento." });
  } finally {
    connection.release();
  }

  try {
    const financial = await refreshAccountsPayableStatus(cuentaId);
    return res.json({ ok: true, financial });
  } catch (error) {
    logServerError("payment-order-status-refresh", error);
    return res.status(500).json({ ok: false, message: "El movimiento se actualizó, pero no se pudo recalcular la cuenta." });
  }
});

