app.post(
  "/api/accounts-payable/ocgf/:orderId/files",
  requireAuth,
  uploadAccountsPayableFile.array("archivo", 10),
  async (req, res) => {
    const orderId = Number(req.params.orderId);
    if (!orderId) return res.status(400).json({ ok: false, message: "OCGF inválida." });

    const tipo = String(req.body.tipo || "").trim();
    const uploadedFiles = getAccountsPayableUploadedFiles(req);
    if (!ACCOUNTS_PAYABLE_FILE_TYPES.includes(tipo)) {
      cleanupAccountsPayableUploadedFiles(uploadedFiles);
      return res.status(400).json({ ok: false, message: "Selecciona el tipo de archivo." });
    }
    if (!uploadedFiles.length) {
      return res.status(400).json({ ok: false, message: "Selecciona un archivo para cargar." });
    }

    try {
      await ensureAccountsPayableTables();
      await ensureFixedExpensePurchaseTables();
      const cuentaId = await ensureAccountsPayableRecordForOcgf(orderId, req.session.user?.id || null);
      if (!cuentaId) {
        cleanupAccountsPayableUploadedFiles(uploadedFiles);
        return res.status(404).json({ ok: false, message: "OCGF aprobada no encontrada." });
      }

      for (const file of uploadedFiles) {
        const relativePath = path.relative(__dirname, file.path).replace(/\\/g, "/");
        await pool.execute(
          `INSERT INTO cuentas_por_pagar_archivos
            (cuenta_id, tipo, nombre, ruta, usuario_id)
           VALUES (?, ?, ?, ?, ?)`,
          [cuentaId, tipo, file.originalname || "", relativePath, req.session.user?.id || null]
        );
      }
      await refreshAccountsPayableStatus(cuentaId);

      const detail = await getAccountsPayableFixedExpenseDetail(orderId);
      res.status(201).json({ ok: true, ...detail });
    } catch (error) {
      cleanupAccountsPayableUploadedFiles(uploadedFiles);
      logServerError("accounts-payable-ocgf-file-upload", error);
      res.status(500).json({ ok: false, message: "No se pudo cargar el archivo de pago OCGF." });
    }
  }
);

