app.delete("/api/commission-payment-batches/:batchId", requireAuth, requirePaymentPermission, async (req, res) => {
  const batchId = Number(req.params.batchId);
  if (!batchId) return res.status(400).json({ ok: false, message: "OCP general inválida." });
  try {
    const [batchRows] = await pool.execute(
      "SELECT id, pdf_ruta FROM lotes_pago_comisiones WHERE id = ? AND estado = 'Pendiente' LIMIT 1",
      [batchId]
    );
    if (!batchRows.length) return res.status(409).json({ ok: false, message: "La OCP general ya fue pagada o no existe." });
    const [result] = await pool.execute(
      "DELETE FROM lotes_pago_comisiones WHERE id = ? AND estado = 'Pendiente'",
      [batchId]
    );
    if (!result.affectedRows) return res.status(409).json({ ok: false, message: "La OCP general ya fue pagada o no existe." });
    const relativePdfPath = String(batchRows[0].pdf_ruta || "").trim();
    if (relativePdfPath) {
      const pdfDirectory = path.resolve(COMMISSION_PAYMENT_BATCH_PDF_DIR);
      const pdfPath = path.resolve(__dirname, relativePdfPath);
      if (pdfPath.startsWith(`${pdfDirectory}${path.sep}`)) {
        try { await fs.promises.unlink(pdfPath); } catch (error) {
          if (error.code !== "ENOENT") logServerError(`commission-payment-batch-cancel-pdf-${batchId}`, error);
        }
      }
    }
    res.json({ ok: true, message: "OCP general pendiente cancelada." });
  } catch (error) {
    logServerError("commission-payment-batch-cancel", error);
    res.status(500).json({ ok: false, message: "No se pudo cancelar la OCP general." });
  }
});

