app.post(
  "/api/accounts-payable/:orderId/files",
  requireAuth,
  uploadAccountsPayableFile.array("archivo", 10),
  async (req, res) => {
    const orderId = Number(req.params.orderId);
    if (!orderId) return res.status(400).json({ ok: false, message: "OCP invalida." });

    const tipo = String(req.body.tipo || "").trim();
    const uploadedFiles = getAccountsPayableUploadedFiles(req);
    if (!ACCOUNTS_PAYABLE_FILE_TYPES.includes(tipo)) {
      cleanupAccountsPayableUploadedFiles(uploadedFiles);
      return res.status(400).json({ ok: false, message: "Selecciona el tipo de archivo." });
    }
    if (!uploadedFiles.length) {
      return res.status(400).json({ ok: false, message: "Selecciona un archivo para cargar." });
    }

    try {
      await ensureAccountsPayableTables();
      if (!(await canAccessSupplierOrder(req.session.user, orderId, "modulo:cuentas-pagar", "accion:subir-archivos"))) {
        cleanupAccountsPayableUploadedFiles(uploadedFiles);
        return res.status(403).json({ ok: false, message: "No tienes acceso a esta cuenta por pagar." });
      }
      const cuentaId = await ensureAccountsPayableRecord(orderId, req.session.user?.id || null);
      if (!cuentaId) {
        cleanupAccountsPayableUploadedFiles(uploadedFiles);
        return res.status(404).json({ ok: false, message: "OCP aprobada no encontrada." });
      }

      for (const file of uploadedFiles) {
        const relativePath = path.relative(__dirname, file.path).replace(/\\/g, "/");
        await pool.execute(
          `INSERT INTO cuentas_por_pagar_archivos
            (cuenta_id, tipo, nombre, ruta, usuario_id)
           VALUES (?, ?, ?, ?, ?)`,
          [cuentaId, tipo, file.originalname || "", relativePath, req.session.user?.id || null]
        );
      }
      await refreshAccountsPayableStatus(cuentaId);

      const detail = await getAccountsPayableDetail(orderId);
      res.status(201).json({ ok: true, ...detail });
    } catch (error) {
      cleanupAccountsPayableUploadedFiles(uploadedFiles);
      logServerError("accounts-payable-file-upload", error);
      res.status(500).json({ ok: false, message: "No se pudo cargar el archivo de pago." });
    }
  }
);

app.get("/api/budgets/:id/purchase-flow", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  try {
    const budget = await getBudgetWithDedupedCostTotals(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    const [clientPo, providers, costParts, draft, versions, files, budgetFiles, transfers, additionals] = await Promise.all([
      getClientPoByBudget(budgetId),
      getProviders("", { limit: null }),
      getSupplierOrderCostParts(budgetId),
      getSupplierOrderDraft(budgetId),
      getSupplierOrderVersions(budgetId),
      getSupplierOrderFiles(budgetId),
      getBudgetFiles(budgetId),
      getBudgetTransfers(budgetId),
      getBudgetAdditionals(budgetId)
    ]);
    const availableBlocks = await getSupplierOrderAvailableBlocksServer(budgetId);
    const reassignments = await getExpenseReassignmentHistory(
      "OCP",
      versions.map((order) => order.id),
      pool,
      { type: "PROYECTO", id: budgetId }
    );
    const totalAdicional = additionals.reduce((sum, row) => sum + Number(row.monto || 0), 0);
    budget.totalAdicional = totalAdicional;
    budget.totalProyecto += totalAdicional;
    res.json({
      ok: true,
      budget,
      clientPo,
      providers,
      costParts,
      draft,
      versions,
      files,
      budgetFiles,
      transfers,
      additionals,
      reassignments,
      availableBlocks,
      purchasesEnabled: Boolean(clientPo && (clientPo.sinPo || clientPo.numeroPo || clientPo.ruta))
    });
  } catch (error) {
    logServerError("purchase-flow-load", error);
    res.status(500).json({ ok: false, message: "No se pudo cargar el flujo de compras." });
  }
});

function formatPendingParts(pendingCounts) {
  const labels = {
    equipos: "Equipos",
    manoObra: "Mano de obra",
    materiales: "Materiales"
  };
  return Object.entries(pendingCounts)
    .filter(([, count]) => Number(count || 0) > 0)
    .map(([block, count]) => `${labels[block] || block} ${count}`)
    .join(", ");
}

function normalizeSearchText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/(?<=\d),(?=\d)/g, "")
    .toLowerCase();
}


function getServerSearchTerms(value) {
  return normalizeSearchText(value)
    .replace(/[^a-z0-9ñ]+/gi, " ")
    .split(/\s+/)
    .map((term) => term.trim())
    .filter(Boolean);
}

function matchesAllServerSearchTerms(value, query) {
  const terms = getServerSearchTerms(query);
  if (!terms.length) return true;
  const haystack = normalizeSearchText(value);
  return terms.every((term) => haystack.includes(term));
}

function buildMoneySearchTermsServer(...values) {
  return values
    .flat()
    .filter((value) => value !== null && value !== undefined && value !== "")
    .flatMap((value) => {
      const number = Number(value || 0);
      if (!Number.isFinite(number)) return [String(value)];
      const fixed = number.toFixed(2);
      const formatted = formatCurrencyServer(number);
      return [String(value), fixed, fixed.replace(".", ""), formatted, formatted.replace(/(?<=\d),(?=\d)/g, "")];
    })
    .join(" ");
}

function purchaseMatchesSearch(item, search) {
  if (!search) return true;
  return normalizeSearchText(Object.values(item).join(" ")).includes(search);
}

app.get("/api/purchases", requireAuth, async (req, res) => {
  try {
    const search = normalizeSearchText(req.query.search || "");
    const ownerConditions = [];
    const ownerValues = [];
    appendBudgetOwnerCondition(ownerConditions, ownerValues, req.session.user, "p", "modulo:compras");
    const ownerWhere = ownerConditions.length ? `AND ${ownerConditions.join(" AND ")}` : "";
    const [poRows] = await pool.execute(
      `SELECT
          p.id,
          p.empresa,
          p.folio,
          p.po,
          p.sucursal,
          p.cliente_usuario,
          p.area,
          p.titulo_proyecto,
          p.created_at,
          p.updated_at,
          po.numero_po,
          po.nombre AS po_nombre,
          (SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', fa.tipo, fa.nombre) ORDER BY fa.nombre SEPARATOR ' ')
           FROM ocp_proveedor_archivos fa
           WHERE fa.presupuesto_id = p.id AND (fa.ocp_id IS NULL OR fa.ocp_id = 0)) AS archivos_nombres,
          po.sin_po
       FROM presupuestos p
       LEFT JOIN presupuesto_po_cliente po ON po.id = (
         SELECT po_actual.id
         FROM presupuesto_po_cliente po_actual
         WHERE po_actual.presupuesto_id = p.id
           AND COALESCE(po_actual.estado_documento, 'Activo') = 'Activo'
           AND po_actual.deleted_at IS NULL
         ORDER BY po_actual.id DESC
         LIMIT 1
       )
       WHERE p.estado <> 'Cerrada'
         AND (
           NULLIF(p.po, '') IS NOT NULL
           OR po.sin_po = 1
           OR NULLIF(po.numero_po, '') IS NOT NULL
           OR NULLIF(po.ruta, '') IS NOT NULL
         )
       ${ownerWhere}
       ORDER BY p.id DESC`,
      ownerValues
    );

    const pending = [];
    for (const row of poRows) {
      const costParts = await getSupplierOrderCostParts(row.id);
      const baseCounts = {
        equipos: costParts.equipos.length,
        manoObra: costParts.manoObra.length,
        materiales: costParts.materiales.length
      };
      const [usedRows] = await pool.execute(
        `SELECT presupuesto_bloque, COUNT(*) AS total
         FROM ocp_proveedor_partidas op
         INNER JOIN ocp_proveedor o ON o.id = op.ocp_id
         WHERE o.presupuesto_id = ? AND o.tipo = 'version' AND o.estatus <> 'Cancelada'
         GROUP BY presupuesto_bloque`,
        [row.id]
      );
      const usedCounts = usedRows.reduce((acc, item) => {
        acc[normalizeBudgetBlock(item.presupuesto_bloque)] = Number(item.total || 0);
        return acc;
      }, {});
      const pendingCounts = {
        equipos: Math.max(0, baseCounts.equipos - Number(usedCounts.equipos || 0)),
        manoObra: Math.max(0, baseCounts.manoObra - Number(usedCounts.manoObra || 0)),
        materiales: Math.max(0, baseCounts.materiales - Number(usedCounts.materiales || 0))
      };
      const pendingText = formatPendingParts(pendingCounts);
      if (pendingText) {
        const costSearch = Object.values(costParts)
          .flat()
          .map((part) =>
            [
              part.descripcion,
              part.item,
              part.nombre,
              part.unidad,
              part.um,
              part.tipo,
              part.presupuesto
            ].join(" ")
          )
          .join(" ");
        const item = {
          budgetId: row.id,
          empresa: row.empresa || "",
          dlv: row.folio || "",
          po: row.sin_po ? "Sin PO" : row.numero_po || row.po || "",
          proyecto: row.titulo_proyecto || "",
          partidasPendientes: pendingText,
          pendingCounts,
          estatus: "OCP Pendientes de crear",
          archivosNombres: row.archivos_nombres || "",
          createdAt: row.created_at,
          updatedAt: row.updated_at,
          searchText: [
            row.empresa,
            row.folio,
            row.po,
            row.numero_po,
            row.sucursal,
            row.cliente_usuario,
            row.area,
            row.titulo_proyecto,
            row.po_nombre,
            row.archivos_nombres,
            pendingText,
            costSearch,
            "OCP Pendientes de crear"
          ].join(" ")
        };
        if (purchaseMatchesSearch(item, search)) pending.push(item);
      }
    }

    const [createdRows] = await pool.execute(
      `SELECT
          o.id,
          o.presupuesto_id,
          o.folio,
          o.estatus,
          o.retencion_activa,
          o.retencion_monto,
          o.created_at,
          o.updated_at,
          COALESCE(NULLIF(CONCAT_WS(' ', creator.nombre, creator.apellido), ''), creator.usuario, '') AS owner_nombre,
          COALESCE(NULLIF(CONCAT_WS(' ', updater.nombre, updater.apellido), ''), updater.usuario, '') AS updated_by_nombre,
          p.empresa,
          p.folio AS dlv,
          p.po,
          p.sucursal,
          p.cliente_usuario,
          p.area,
          p.titulo_proyecto,
          po.numero_po,
          po.nombre AS po_nombre,
          po.sin_po,
          GROUP_CONCAT(DISTINCT op.proveedor_nombre ORDER BY op.proveedor_nombre SEPARATOR ', ') AS proveedores,
          GROUP_CONCAT(DISTINCT op.descripcion ORDER BY op.descripcion SEPARATOR ' ') AS partidas,
          GROUP_CONCAT(DISTINCT op.presupuesto_bloque ORDER BY op.presupuesto_bloque SEPARATOR ' ') AS bloques,
          (SELECT GROUP_CONCAT(DISTINCT CONCAT_WS(' ', fa.tipo, fa.nombre) ORDER BY fa.nombre SEPARATOR ' ')
           FROM ocp_proveedor_archivos fa
           WHERE fa.ocp_id = o.id OR (fa.ocp_id IS NULL AND fa.presupuesto_id = o.presupuesto_id)) AS archivos_nombres,
          COALESCE(SUM(op.total), 0) AS subtotal_ocp
       FROM ocp_proveedor o
       INNER JOIN presupuestos p ON p.id = o.presupuesto_id
       LEFT JOIN usuarios creator ON creator.user_id = o.usuario_id
       LEFT JOIN usuarios updater ON updater.user_id = COALESCE(o.updated_by_user_id, o.usuario_id)
       LEFT JOIN presupuesto_po_cliente po ON po.id = (
         SELECT po_actual.id
         FROM presupuesto_po_cliente po_actual
         WHERE po_actual.presupuesto_id = p.id
           AND COALESCE(po_actual.estado_documento, 'Activo') = 'Activo'
           AND po_actual.deleted_at IS NULL
         ORDER BY po_actual.id DESC
         LIMIT 1
       )
       LEFT JOIN ocp_proveedor_partidas op ON op.ocp_id = o.id
       WHERE o.tipo = 'version'
       ${ownerWhere}
       GROUP BY
         o.id, o.presupuesto_id, o.folio, o.estatus, o.retencion_activa, o.retencion_monto, o.created_at, o.updated_at,
         creator.nombre, creator.apellido, creator.usuario, updater.nombre, updater.apellido, updater.usuario,
         p.empresa, p.folio, p.po, p.sucursal, p.cliente_usuario, p.area, p.titulo_proyecto,
         po.numero_po, po.nombre, po.sin_po
       ORDER BY o.id DESC`,
      ownerValues
    );

    const created = createdRows
      .map((row) => {
        const normalizedStatus = normalizeWorkflowValue(row.estatus);
        const estatus =
        normalizedStatus.startsWith("aprobad")
          ? "OCP Aprobada"
          : normalizedStatus.includes("cancel")
            ? "OCP Cancelada"
            : "OCP pendiente de aprobar";
        const subtotal = Number(row.subtotal_ocp || 0);
        const retention = row.retencion_activa ? Number(row.retencion_monto || 0) : 0;
        const monto = Math.max(0, subtotal * 1.16 - retention);
        return {
          orderId: row.id,
          budgetId: row.presupuesto_id,
          empresa: row.empresa || "",
          dlv: row.dlv || "",
          ocp: row.folio || "",
          proveedor: row.proveedores || "Sin proveedor",
          proyecto: row.titulo_proyecto || "",
          createdAt: row.created_at,
          updatedAt: row.updated_at,
          owner: row.owner_nombre || "Sin dato",
          updatedBy: row.updated_by_nombre || row.owner_nombre || "Sin dato",
          monto,
          estatus,
          archivosNombres: row.archivos_nombres || "",
          searchText: [
            row.empresa,
            row.dlv,
            row.folio,
            row.po,
            row.sin_po ? "Sin PO" : row.numero_po,
            row.sucursal,
            row.cliente_usuario,
            row.area,
            row.titulo_proyecto,
            row.proveedores,
            row.partidas,
            row.bloques,
            row.po_nombre,
            row.archivos_nombres,
            row.owner_nombre,
            row.updated_by_nombre,
            monto,
            buildMoneySearchTermsServer(monto, subtotal, retention),
            estatus
          ].join(" ")
        };
      })
      .filter((item) => purchaseMatchesSearch(item, search));

    res.json({ ok: true, pending, created });
  } catch (error) {
    logServerError("purchases-list", error);
    res.status(500).json({ ok: false, message: "No se pudieron cargar las compras." });
  }
});

app.get("/api/purchases/open-by-folio", requireAuth, async (req, res) => {
  const folio = String(req.query.folio || "").trim();
  if (!folio) return res.status(400).json({ ok: false, message: "Ingresa el folio del presupuesto." });

  try {
    const ownerConditions = [];
    const ownerValues = [];
    appendBudgetOwnerCondition(ownerConditions, ownerValues, req.session.user, "p", "modulo:compras");
    const ownerWhere = ownerConditions.length ? `AND ${ownerConditions.join(" AND ")}` : "";
    const [rows] = await pool.execute(
      `SELECT p.id, p.folio, p.estado
       FROM presupuestos p
       WHERE LOWER(TRIM(p.folio)) = LOWER(TRIM(?))
         ${ownerWhere}
       LIMIT 1`,
      [folio, ...ownerValues]
    );
    const row = rows[0];
    if (!row) return res.status(404).json({ ok: false, message: "No encontré un presupuesto con ese folio." });
    const budget = await getBudgetById(row.id);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    if (normalizeWorkflowValue(budget.estado).includes("cerrad")) {
      return res.status(409).json({
        ok: false,
        message: "Este presupuesto está cerrado. Solo superadmin puede reabrirlo para generar nuevas compras."
      });
    }

    const clientPo = await getClientPoByBudget(budget.id);
    if (!clientPo || (!clientPo.sinPo && !clientPo.numeroPo && !clientPo.ruta)) {
      return res.status(409).json({ ok: false, message: "Este presupuesto aún no tiene PO o confirmación Sin PO." });
    }

    const available = await getSupplierOrderAvailableBlocksServer(budget.id);
    const availableTotal = Object.values(available || {}).reduce((sum, value) => sum + Number(value || 0), 0);
    if (availableTotal <= 0.005) {
      return res.status(409).json({
        ok: false,
        message: "No cuenta con presupuesto disponible este folio. Consulta con el administrador."
      });
    }

    res.json({ ok: true, budgetId: budget.id, budget, available });
  } catch (error) {
    logServerError("purchase-open-by-folio", error);
    res.status(500).json({ ok: false, message: "No se pudo validar el folio para compras." });
  }
});

app.post(
  "/api/budgets/:id/client-po",
  requireAuth,
  requireClientPoManager,
  uploadBudgetFile.single("poArchivo"),
  async (req, res) => {
    const budgetId = Number(req.params.id);
    if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

    const requestedSinPo =
      String(req.body.sinPo || "").toLowerCase() === "true" || req.body.sinPo === "1";
    // Un archivo seleccionado siempre representa una PO real. Esto también
    // protege a clientes anteriores que enviaban el archivo con "Sin PO"
    // todavía marcado en el formulario.
    const sinPo = requestedSinPo && !req.file;
    if (!sinPo && !req.file) {
      return res.status(400).json({ ok: false, message: "Carga la PO o marca Sin PO." });
    }

    const relativePath = req.file ? path.relative(__dirname, req.file.path).replace(/\\/g, "/") : "";
    const fileName = req.file?.originalname || "";
    const numeroPo = req.file ? path.parse(fileName).name.trim() : "";
    const connection = await pool.getConnection();
    const filesToUnlink = [];
    let transactionStarted = false;
    let committed = false;

    try {
      const budget = await getBudgetById(budgetId);
      if (!budget) {
        if (relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
        return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
      }
      if (isBudgetWorkflowClosed(budget)) {
        if (relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
        return res.status(409).json({
          ok: false,
          message: "No se puede cargar PO en un presupuesto cerrado."
        });
      }
      const quoteId = await getLatestClientQuoteIdForPoByBudget(budgetId, connection);
      if (!quoteId) {
        if (relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
        return res.status(409).json({
          ok: false,
          message: "Primero genera una cotización del cliente vigente."
        });
      }

      const [currentPoRows] = await connection.execute(
        `SELECT id, sin_po, po_compartida_id
         FROM presupuesto_po_cliente
         WHERE presupuesto_id = ?
           AND COALESCE(estado_documento, 'Activo') = 'Activo'
           AND deleted_at IS NULL
         ORDER BY id DESC
         LIMIT 1`,
        [budgetId]
      );
      // Confirmar nuevamente el mismo estado "Sin PO" es una operación
      // idempotente: no debe crear otra versión del historial.
      if (sinPo && Number(currentPoRows[0]?.sin_po || 0) === 1) {
        if (relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
        const clientPo = await getClientPoByBudget(budgetId);
        return res.json({ ok: true, clientPo, unchanged: true });
      }

      await connection.beginTransaction();
      transactionStarted = true;
      await connection.execute(
        `UPDATE presupuesto_po_cliente
         SET estado_documento = 'Reemplazada', reemplazada_at = NOW(), reemplazada_by = ?, updated_at = NOW()
         WHERE presupuesto_id = ? AND COALESCE(estado_documento, 'Activo') = 'Activo' AND deleted_at IS NULL`,
        [req.session.user?.id || null, budgetId]
      );
      const storedPoNumber = sinPo ? `SIN-PO-${budgetId}` : numeroPo;
      const [newPoResult] = await connection.execute(
        `INSERT INTO presupuesto_po_cliente
          (presupuesto_id, numero_po, sin_po, nombre, ruta, estado_documento, usuario_id)
         VALUES (?, ?, ?, ?, ?, 'Activo', ?)`,
        [budgetId, storedPoNumber, sinPo ? 1 : 0, fileName, relativePath, req.session.user?.id || null]
      );
      await connection.execute(
        `UPDATE presupuesto_po_cliente
         SET reemplazada_por_id = ?
         WHERE presupuesto_id = ? AND estado_documento = 'Reemplazada' AND reemplazada_por_id IS NULL`,
        [newPoResult.insertId, budgetId]
      );
      const previousSharedPoId = Number(currentPoRows[0]?.po_compartida_id || 0);
      if (previousSharedPoId) {
        const [activeMembers] = await connection.execute(
          `SELECT COUNT(*) AS total
           FROM presupuesto_po_cliente
           WHERE po_compartida_id = ?
             AND COALESCE(estado_documento, 'Activo') = 'Activo'
             AND deleted_at IS NULL`,
          [previousSharedPoId]
        );
        if (Number(activeMembers[0]?.total || 0) === 0) {
          const [sharedRows] = await connection.execute(
            "SELECT ruta FROM po_cliente_compartidas WHERE id = ? LIMIT 1",
            [previousSharedPoId]
          );
          if (sharedRows[0]?.ruta) filesToUnlink.push(sharedRows[0].ruta);
          await connection.execute(
            "UPDATE po_cliente_compartidas SET estado = 'Cancelada', updated_at = NOW() WHERE id = ?",
            [previousSharedPoId]
          );
        }
      }
      await connection.execute("UPDATE presupuestos SET po = ?, estado = ? WHERE id = ?", [
        sinPo ? "Sin PO" : numeroPo,
        "En proceso",
        budgetId
      ]);
      await connection.commit();
      committed = true;
      filesToUnlink.forEach((storedPath) => unlinkStoredFile(storedPath, BUDGET_UPLOAD_DIR));

      try {
        const cuentaId = await ensureAccountsReceivableRecord(quoteId, req.session.user?.id || null);
        if (cuentaId) {
          const [accountRows] = await pool.execute("SELECT pendiente FROM cuentas_por_cobrar WHERE id = ? LIMIT 1", [
            cuentaId
          ]);
          const currentPending = normalizeWorkflowValue(accountRows[0]?.pendiente || "");
          if (!currentPending || currentPending.includes("creacion de factura")) {
            await pool.execute(
              "UPDATE cuentas_por_cobrar SET estado = 'En proceso', pendiente = 'En proceso', updated_at = NOW() WHERE id = ?",
              [cuentaId]
            );
          }
        } else {
          logServerError("client-po-receivable-sync", new Error("No se pudo crear la cuenta por cobrar."));
        }
      } catch (syncError) {
        logServerError("client-po-receivable-sync", syncError);
      }

      const clientPo = await getClientPoByBudget(budgetId);
      res.status(201).json({ ok: true, clientPo });
    } catch (error) {
      if (transactionStarted && !committed) await connection.rollback();
      if (!committed && relativePath) unlinkStoredFile(relativePath, BUDGET_UPLOAD_DIR);
      logServerError("client-po-save", error);
      res.status(500).json({ ok: false, message: "No se pudo guardar la PO del cliente." });
    } finally {
      connection.release();
    }
  }
);

app.post("/api/budgets/:id/bill", requireAuth, requireClientPoManager, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  try {
    await ensureAccountsReceivableTables();
    const budget = await getBudgetById(budgetId);
    if (!budget) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });
    if (isBudgetWorkflowClosed(budget)) {
      return res.status(409).json({
        ok: false,
        message: "No se puede mandar a facturar un presupuesto cerrado."
      });
    }

    const clientPo = await getClientPoByBudget(budgetId);
    if (!clientPo && !budget.hasClientPo) {
      return res.status(409).json({ ok: false, message: "Carga la PO o marca Sin PO antes de facturar." });
    }

    const quoteId = await getLatestClientQuoteIdForPoByBudget(budgetId);
    if (!quoteId) {
      return res.status(409).json({ ok: false, message: "Primero genera una cotización del cliente vigente." });
    }

    const detail = await getAccountsReceivableDetail(quoteId);
    if (!detail) return res.status(404).json({ ok: false, message: "No se pudo preparar la cuenta por cobrar." });
    if (!(await canAccessBudget(req.session.user, detail.account?.presupuestoId, "modulo:cuentas-cobrar", "accion:facturar"))) {
      return res.status(403).json({ ok: false, message: "No tienes acceso a este presupuesto." });
    }

    const cuentaId = await ensureAccountsReceivableRecord(quoteId, req.session.user?.id || null);
    if (!cuentaId) return res.status(404).json({ ok: false, message: "No se pudo crear la cuenta por cobrar." });

    await createAccountsReceivableBillingMovement({
      cuentaId,
      monto: req.body?.monto,
      observaciones: req.body?.observaciones || "",
      userId: req.session.user?.id || null
    });

    const updatedDetail = await getAccountsReceivableDetail(quoteId);
    res.json({ ok: true, message: "Parcialidad enviada a Cuentas por cobrar correctamente.", ...updatedDetail });
  } catch (error) {
    logServerError("budget-bill", error);
    res.status(error.statusCode || 500).json({ ok: false, message: error.message || "No se pudo mandar el presupuesto a facturar." });
  }
});

