app.post(
  "/api/budgets/:id/files",
  requireAuth,
  uploadBudgetFile.single("archivo"),
  async (req, res) => {
    const budgetId = Number(req.params.id);
    if (!budgetId || !req.file) {
      return res.status(400).json({ ok: false, message: "Selecciona un archivo valido." });
    }

    const relativePath = path.relative(__dirname, req.file.path).replace(/\\/g, "/");
    const tipo = String(req.body.tipo || "Cotización proveedor").trim() || "Cotización proveedor";

    try {
      const [result] = await pool.execute(
        `INSERT INTO presupuesto_archivos (presupuesto_id, tipo, nombre, ruta, usuario_id)
         VALUES (?, ?, ?, ?, ?)`,
        [budgetId, tipo, req.file.originalname, relativePath, req.session.user?.id || null]
      );
      await touchBudgetUpdatedAt(budgetId);

      res.status(201).json({ ok: true, fileId: result.insertId });
    } catch (error) {
      logServerError("budget-file-upload", error);
      res.status(500).json({ ok: false, message: "No se pudo guardar el archivo." });
    }
  }
);

app.delete("/api/budget-files/:fileId", requireAuth, requireDeletePermission, async (req, res) => {
  const fileId = Number(req.params.fileId);
  if (!fileId) return res.status(400).json({ ok: false, message: "Archivo inválido." });

  try {
    const [rows] = await pool.execute("SELECT presupuesto_id, ruta FROM presupuesto_archivos WHERE id = ? LIMIT 1", [fileId]);
    if (!rows.length) return res.status(404).json({ ok: false, message: "Archivo no encontrado." });
    await pool.execute("DELETE FROM presupuesto_archivos WHERE id = ?", [fileId]);
    await touchBudgetUpdatedAt(rows[0].presupuesto_id);
    unlinkStoredFile(rows[0].ruta, BUDGET_UPLOAD_DIR);
    res.json({ ok: true });
  } catch (error) {
    logServerError("budget-file-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar el archivo." });
  }
});

app.patch("/api/budgets/:id/status", requireAuth, async (req, res) => {
  const budgetId = Number(req.params.id);
  const action = String(req.body.action || "").trim();
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  const statuses = {
    approve: "Aprobado",
    reject: "No aprobado",
    close: "Cerrada",
    reopen: "Aprobado"
  };
  const nextStatus = statuses[action];
  if (!nextStatus) return res.status(400).json({ ok: false, message: "Accion invalida." });
  if (["approve", "reject"].includes(action) && !canApproveWithSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "No tienes permisos para aprobar." });
  }
  if (["close", "reopen"].includes(action) && !isSuperAdminSession(req.session.user)) {
    return res.status(403).json({ ok: false, message: "Solo superadmin puede cerrar o reabrir presupuestos." });
  }

  try {
    const [budgetRows] = await pool.execute("SELECT id, estado, po FROM presupuestos WHERE id = ? LIMIT 1", [budgetId]);
    if (!budgetRows.length) return res.status(404).json({ ok: false, message: "Presupuesto no encontrado." });

    const [poRows] = await pool.execute(
      `SELECT 1
       FROM presupuesto_po_cliente
       WHERE presupuesto_id = ?
         AND (sin_po = 1 OR NULLIF(numero_po, '') IS NOT NULL OR NULLIF(ruta, '') IS NOT NULL)
       LIMIT 1`,
      [budgetId]
    );
    const hasPo = poRows.length > 0 || Boolean(String(budgetRows[0]?.po || "").trim());
    const nextState = action === "close" ? "Cerrada" : hasPo ? "En proceso" : "Abierta";
    const workflowStatus =
      action === "reopen"
        ? await resolveBudgetWorkflowStatus({
            id: budgetId,
            estado: nextState,
            estatus: "Aprobado",
            has_client_po: hasPo ? 1 : 0
          })
        : nextStatus;
    await pool.execute("UPDATE presupuestos SET estado = ?, estatus = ? WHERE id = ?", [
      nextState,
      workflowStatus,
      budgetId
    ]);
    res.json({ ok: true });
  } catch (error) {
    logServerError("budget-status", error);
    res.status(500).json({ ok: false, message: "No se pudo actualizar el presupuesto." });
  }
});

app.delete("/api/budgets/:id", requireAuth, requireSuperAdmin, async (req, res) => {
  const budgetId = Number(req.params.id);
  if (!budgetId) return res.status(400).json({ ok: false, message: "Presupuesto invalido." });

  try {
    await ensureBudgetTables();
    await ensureAccountsReceivableTables();
  } catch (error) {
    logServerError("budget-delete-prepare", error);
    return res.status(500).json({ ok: false, message: "No se pudo preparar la eliminación del presupuesto." });
  }

  const connection = await pool.getConnection();
  try {
    await connection.beginTransaction();
    const [files] = await connection.execute("SELECT ruta FROM presupuesto_archivos WHERE presupuesto_id = ?", [
      budgetId
    ]);
    await connection.execute("DELETE FROM presupuestos WHERE id = ?", [budgetId]);
    await connection.commit();

    for (const file of files) {
      const absolutePath = path.join(__dirname, file.ruta);
      if (absolutePath.startsWith(BUDGET_UPLOAD_DIR)) {
        fs.promises.unlink(absolutePath).catch(() => {});
      }
    }

    res.json({ ok: true });
  } catch (error) {
    await connection.rollback();
    logServerError("budget-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar el presupuesto." });
  } finally {
    connection.release();
  }
});

app.delete("/api/users/:id", requireAuth, requireSuperAdmin, async (req, res) => {
  const userId = Number(req.params.id);
  if (!userId) return res.status(400).json({ ok: false, message: "Usuario invalido." });
  if (userId === Number(req.session.user?.id)) {
    return res.status(400).json({ ok: false, message: "No puedes eliminar tu propio usuario." });
  }

  try {
    const [result] = await pool.execute("DELETE FROM usuarios WHERE user_id = ?", [userId]);
    if (!result.affectedRows) {
      return res.status(404).json({ ok: false, message: "Usuario no encontrado." });
    }

    res.json({ ok: true });
  } catch (error) {
    logServerError("users-delete", error);
    res.status(500).json({ ok: false, message: "No se pudo eliminar el usuario." });
  }
});

