app.post("/api/auth/login", checkLoginLimit, async (req, res) => {
  const username = String(req.body.username || "").trim();
  const password = String(req.body.password || "");

  if (!username || !password) {
    return res.status(400).json({ ok: false, message: "Ingresa usuario y contrasena." });
  }

  try {
    const authConfig = await getAuthTable();
    const [rows] = await pool.execute(
      `SELECT *
       FROM ${escapeId(authConfig.table)}
       WHERE ${escapeId(authConfig.userColumn)} = ?
       LIMIT 1`,
      [username]
    );

    const userRow = rows[0];
    if (!userRow) {
      recordLoginFailure(req, username);
      return res.status(401).json({ ok: false, message: "Usuario o contrasena incorrectos." });
    }

    if (authConfig.activeColumn && !isActive(userRow[authConfig.activeColumn])) {
      return res.status(403).json({ ok: false, message: "El usuario esta inactivo." });
    }

    const passwordOk = await comparePassword(password, userRow[authConfig.passwordColumn]);
    if (!passwordOk) {
      recordLoginFailure(req, username);
      return res.status(401).json({ ok: false, message: "Usuario o contrasena incorrectos." });
    }

    clearLoginFailures(req, username);
    req.session.user = publicUser(userRow, authConfig);
    req.session.user.role = await resolveSessionRole(userRow, authConfig);
    await hydrateSessionBranchAccess(req.session.user);
    return res.json({ ok: true, user: req.session.user });
  } catch (error) {
    logServerError("login", error);
    return res.status(500).json({
      ok: false,
      message: "No se pudo conectar con la base de datos. Revisa la configuracion de MySQL."
    });
  }
});

app.post("/api/auth/logout", requireAuth, (req, res) => {
  req.session.destroy(() => {
    res.clearCookie("dalvo.sid");
    res.json({ ok: true });
  });
});

app.use((error, _req, res, next) => {
  if (!error) return next();
  if (error instanceof multer.MulterError) {
    const message =
      error.code === "LIMIT_FILE_SIZE"
        ? "El archivo excede el limite de 100 MB."
        : `No se pudo cargar el archivo (${error.code}).`;
    return res.status(400).json({ ok: false, message });
  }
  return next(error);
});

app.get("*", (_req, res) => {
  res.sendFile(path.join(__dirname, "index.html"));
});

function startServer(port, attemptsLeft = 5) {
  const server = app.listen(port, LISTEN_HOST, () => {
    logServerInfo("listen", `Dalvo System listo en http://${LISTEN_HOST}:${port}`);
  });

  server.on("error", (error) => {
    logServerError("listen", error);
    if (!IS_PRODUCTION && error.code === "EADDRINUSE" && attemptsLeft > 0) {
      const nextPort = port + 1;
      console.warn(`El puerto ${port} esta en uso. Intentando con ${nextPort}.`);
      startServer(nextPort, attemptsLeft - 1);
      return;
    }

    throw error;
  });
}

async function bootstrap({ startHttpServer = true } = {}) {
  try {
    if (IS_PRODUCTION && (!process.env.SESSION_SECRET || SESSION_SECRET.length < 32 || SESSION_SECRET === "dalvo-system-local-session")) {
      throw new Error("SESSION_SECRET debe configurarse con una llave segura antes de iniciar en producción.");
    }
    await ensureSecurityTables();
    await ensureCoreBusinessTables();
    await ensureFixedExpensesTable();
    await ensureFixedExpensePurchaseTables();
    await ensureExpenseReassignmentTables();
    await ensureAccountsPayableTables();
    await ensureBudgetTables();
    await ensureClientBranchAndAssignmentTables();
    await ensureCommissionTables();
    await migrateLegacyV1Data();
    await generateDueFixedExpenseOrders();
    const fixedExpenseTimer = setInterval(() => {
      generateDueFixedExpenseOrders().catch((error) => logServerError("fixed-expense-auto-schedule", error));
    }, 60 * 60 * 1000);
    fixedExpenseTimer.unref?.();
    if (startHttpServer) startServer(PORT);
    logServerInfo("bootstrap", "Inicializacion de base de datos completada.");
  } catch (error) {
    logServerError("bootstrap", error);
    process.exit(1);
  }
}

if (IS_PRODUCTION) {
  // Hostinger/LiteSpeed espera que la aplicacion llame listen() casi de inmediato.
  // Levantamos HTTP primero y completamos la preparacion de BD en segundo plano.
  startServer(PORT);
  bootstrap({ startHttpServer: false });
} else if (require.main === module) {
  bootstrap();
}

module.exports = { app, bootstrap, startServer, buildStructuredExportWorkbook, renderStructuredExportPdf };
